INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51959, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マーケティング", "is_correct": true, "explanation": "お店の品を知ってもらう工夫を指し、文脈に合う。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「お店の地震を考える」では意味が合わない。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、お店について考える内容として意味が合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "形は合うが、「お店の夕焼けを考える」では意味が合わない。"}], "explanations": {"マーケティング": "お店の品を知ってもらう工夫を指し、文脈に合う。", "地震": "形は合うが、「お店の地震を考える」では意味が合わない。", "台風": "形は合うが、お店について考える内容として意味が合わない。", "夕焼け": "形は合うが、「お店の夕焼けを考える」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "マーケティング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "マーケティングを飲んで、お客さんが増えた。", "explanation": "マーケティングは活動であり、飲めないので、「飲む」との組み合わせが誤り。"}, {"text": "お店のマーケティングが川で泳いでいる。", "explanation": "マーケティングは生き物ではないので、泳ぐ主語として誤り。"}, {"text": "マーケティングの靴を履いて店に行った。", "explanation": "マーケティングは物ではないので、靴を修飾する使い方は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51959, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マーケティング", "is_correct": true, "explanation": "店のことで友達に相談する内容として自然に合う。"}, {"text": "虹", "is_correct": false, "explanation": "形は合うが、「店の虹について相談」では意味が合わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "形は合うが、店について相談する内容として意味が合わない。"}, {"text": "星座", "is_correct": false, "explanation": "形は合うが、「店の星座」では意味が合わない。"}], "explanations": {"マーケティング": "店のことで友達に相談する内容として自然に合う。", "虹": "形は合うが、「店の虹について相談」では意味が合わない。", "昼寝": "形は合うが、店について相談する内容として意味が合わない。", "星座": "形は合うが、「店の星座」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "マーケティング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商店街のマーケティングを食べて、お腹がいっぱいになった。", "explanation": "マーケティングは活動で食べ物ではないので、「食べる」の目的語として誤り。"}, {"text": "商店街のマーケティングを着て、みんなで出かけた。", "explanation": "マーケティングは服ではないので、「着る」の目的語として誤り。"}, {"text": "マーケティングは商店街の屋根の上に生えている。", "explanation": "マーケティングは植物や物ではないので、「生える」の主語として誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51959, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私はお店のマーケティングが考えます。", "corrected_sentence": "私はお店のマーケティングを考えます。", "error_description": "「考える」の対象は「を」で示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51959, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マーケティングで本を読んで、ポスターを作ってみた。", "corrected_sentence": "マーケティングの本を読んで、ポスターを作ってみた。", "error_description": "「本」を修飾する形は「マーケティングの本」。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
