INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51960, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「できる」の対象を示す助詞として自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「できる」の対象には使えない。"}, {"text": "と", "is_correct": false, "explanation": "「マーケティングとできれば」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「マーケティングのできれば」は文法的に誤り。"}], "correct_answer": "が", "explanations": {"が": "「できる」の対象を示す助詞として自然。", "へ": "「へ」は方向を示し、「できる」の対象には使えない。", "と": "「マーケティングとできれば」は文として成り立たない。", "の": "「マーケティングのできれば」は文法的に誤り。"}, "error_tags": {"へ": "direction", "と": "wrong_case", "の": "wrong_case"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51960, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "商品やサービスを売るために、市場調査や広告、販売促進などを行う一連の活動。", "primary_collocate": null, "pronunciation": "まーけてぃんぐ", "ipa": "maːketʲiŋɡɯ", "syllable_count": 6, "sentences": [{"text": "成功の鍵は、商品の魅力を伝える写真の工夫と、ターゲット層に届けるマーケティングです。", "target_word": "マーケティング", "complexity_tier": "T6", "furigana": "成功[せいこう]の鍵[かぎ]は、商品[しょうひん]の魅力[みりょく]を伝[つた]える写真[しゃしん]の工夫[くふう]と、ターゲット層[そう]に届[とど]けるマーケティングです。", "sentence_source": "mined"}, {"text": "マーケティングを勉強します。", "target_word": "マーケティング", "complexity_tier": "T2", "furigana": "マーケティングを勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "兄はマーケティングの仕事です。", "target_word": "マーケティング", "complexity_tier": "T2", "furigana": "兄[あに]はマーケティングの仕事[しごと]です。", "sentence_source": "generated"}, {"text": "マーケティングは難しいです。", "target_word": "マーケティング", "complexity_tier": "T2", "furigana": "マーケティングは難[むずか]しいです。", "sentence_source": "generated"}, {"text": "新しい商品のマーケティングを考えている。", "target_word": "マーケティング", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]のマーケティングを考[かんが]えている。", "sentence_source": "generated"}, {"text": "マーケティングを学んで、仕事に生かしたい。", "target_word": "マーケティング", "complexity_tier": "T3", "furigana": "マーケティングを学[まな]んで、仕事[しごと]に生[い]かしたい。", "sentence_source": "generated"}, {"text": "SNSを使ったマーケティングが人気だ。", "target_word": "マーケティング", "complexity_tier": "T3", "furigana": "SNSを使[つか]ったマーケティングが人気[にんき]だ。", "sentence_source": "generated"}, {"text": "効果的なマーケティングができれば、売り上げは伸びる。", "target_word": "マーケティング", "complexity_tier": "T4", "furigana": "効果的[こうかてき]なマーケティングができれば、売[う]り上[あ]げは伸[の]びる。", "sentence_source": "generated"}, {"text": "市場を調べずにマーケティングをしても、成功しにくい。", "target_word": "マーケティング", "complexity_tier": "T4", "furigana": "市場[しじょう]を調[しら]べずにマーケティングをしても、成功[せいこう]しにくい。", "sentence_source": "generated"}, {"text": "彼女はマーケティングの専門家として働いている。", "target_word": "マーケティング", "complexity_tier": "T4", "furigana": "彼女[かのじょ]はマーケティングの専門家[せんもんか]として働[はたら]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マーケター", "label": "派生"}, {"form": "マーケティング戦略", "label": "派生"}, {"form": "デジタルマーケティング", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 商品を売るための調査や広告活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51960, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マーケティング", "is_correct": true, "explanation": "商品を届けるための活動を指し、文脈に合う。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「届ける地震」では意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「ターゲット層に届ける天気」では意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、商品の魅力を伝える文脈で意味が合わない。"}], "explanations": {"マーケティング": "商品を届けるための活動を指し、文脈に合う。", "地震": "形は合うが、「届ける地震」では意味が合わない。", "天気": "形は合うが、「ターゲット層に届ける天気」では意味が合わない。", "季節": "形は合うが、商品の魅力を伝える文脈で意味が合わない。"}, "sentence_index": 0, "correct_answer": "マーケティング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、私はマーケティングを飲みました。", "explanation": "マーケティングは活動であり、飲むものではないので、目的語として使い方が誤り。"}, {"text": "マーケティングは公園の前に立っています。", "explanation": "マーケティングは抽象的な活動なので、場所に立つ物のようには使えない。"}, {"text": "母はマーケティングで髪を切りました。", "explanation": "マーケティングは道具ではないので、「髪を切る手段」として使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51960, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マーケティング", "is_correct": true, "explanation": "SNSを使った販売促進の活動として自然に合う。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、「SNSを使った台風」では意味が合わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "形は合うが、「SNSを使った昼寝」では意味が合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "形は合うが、「SNSを使った渋滞が人気」では意味が合わない。"}], "explanations": {"マーケティング": "SNSを使った販売促進の活動として自然に合う。", "台風": "形は合うが、「SNSを使った台風」では意味が合わない。", "昼寝": "形は合うが、「SNSを使った昼寝」では意味が合わない。", "渋滞": "形は合うが、「SNSを使った渋滞が人気」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "マーケティング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟はマーケティングを着て学校へ行った。", "explanation": "マーケティングは服ではないので、「着る」の目的語にするのは誤り。"}, {"text": "マーケティングが空を飛んでいる。", "explanation": "マーケティングは活動であり、空を飛ぶ物ではないので主語として不適切。"}, {"text": "私はマーケティングの山に登った。", "explanation": "マーケティングは場所ではないので、「山」を修飾する使い方は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51960, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい店のマーケティングへ考えています。", "corrected_sentence": "新しい店のマーケティングを考えています。", "error_description": "「考える」の対象を示す助詞は「を」で、「へ」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
