INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51961, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「獲得する」の対象を示す助詞として自然。"}, {"text": "の", "is_correct": false, "explanation": "「賞品の獲得しました」は文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「賞品に獲得しました」は対象の示し方として誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、獲得の対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "「獲得する」の対象を示す助詞として自然。", "の": "「賞品の獲得しました」は文法的に成り立たない。", "に": "「賞品に獲得しました」は対象の示し方として誤り。", "へ": "「へ」は方向を示し、獲得の対象には使えない。"}, "error_tags": {"の": "wrong_case", "に": "wrong_case", "へ": "direction"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喪失", "is_correct": true, "explanation": "手に入れる獲得に対し、失う意味の反対語。"}, {"text": "入手", "is_correct": false, "explanation": "手に入れる意味で、獲得の類義語。"}, {"text": "取得", "is_correct": false, "explanation": "手に入れる意味で、獲得の類義語。"}, {"text": "確保", "is_correct": false, "explanation": "手に入れて保つ意味で、反対語ではない。"}], "correct_answer": "喪失", "explanations": {"喪失": "手に入れる獲得に対し、失う意味の反対語。", "入手": "手に入れる意味で、獲得の類義語。", "取得": "手に入れる意味で、獲得の類義語。", "確保": "手に入れて保つ意味で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
