INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51961, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ほしいものを、がんばって手に入れること。", "primary_collocate": null, "pronunciation": "かくとく", "ipa": "kakɯtokɯ", "syllable_count": 4, "sentences": [{"text": "一位を獲得した。", "target_word": "獲得", "complexity_tier": "T1", "furigana": "一位[いちい]を獲得[かくとく]した。", "sentence_source": "generated"}, {"text": "切符を獲得したい。", "target_word": "獲得", "complexity_tier": "T1", "furigana": "切符[きっぷ]を獲得[かくとく]したい。", "sentence_source": "generated"}, {"text": "弟はゲームで賞品を獲得しました。", "target_word": "獲得", "complexity_tier": "T2", "furigana": "弟[おとうと]はゲームで賞品[しょうひん]を獲得[かくとく]しました。", "sentence_source": "generated"}, {"text": "獲得するのは、思ったより難しい。", "target_word": "獲得", "complexity_tier": "T3", "furigana": "獲得[かくとく]するのは、思[おも]ったより難[むずか]しい。", "sentence_source": "generated"}, {"text": "毎日練習して、レギュラーの座を獲得した。", "target_word": "獲得", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]して、レギュラーの座[ざ]を獲得[かくとく]した。", "sentence_source": "generated"}, {"text": "獲得できた時は、とてもうれしかった。", "target_word": "獲得", "complexity_tier": "T3", "furigana": "獲得[かくとく]できた時[とき]は、とてもうれしかった。", "sentence_source": "generated"}, {"text": "ついに夢だった留学の権利を獲得できた。", "target_word": "獲得", "complexity_tier": "T3", "furigana": "ついに夢[ゆめ]だった留学[りゅうがく]の権利[けんり]を獲得[かくとく]できた。", "sentence_source": "generated"}, {"text": "獲得した人だけが、この景品をもらえる。", "target_word": "獲得", "complexity_tier": "T3", "furigana": "獲得[かくとく]した人[ひと]だけが、この景品[けいひん]をもらえる。", "sentence_source": "generated"}, {"text": "もっと早く練習していれば、メダルを獲得できたのに。", "target_word": "獲得", "complexity_tier": "T4", "furigana": "もっと早[はや]く練習[れんしゅう]していれば、メダルを獲得[かくとく]できたのに。", "sentence_source": "generated"}, {"text": "彼女が獲得したトロフィーは、棚に飾られている。", "target_word": "獲得", "complexity_tier": "T4", "furigana": "彼女[かのじょ]が獲得[かくとく]したトロフィーは、棚[たな]に飾[かざ]られている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲得する", "label": "活用"}, {"form": "獲得した", "label": "活用"}, {"form": "獲得できる", "label": "活用"}, {"form": "獲得数", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ほしいものを頑張って手に入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51961, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "獲得", "is_correct": true, "explanation": "一位を手に入れる意味で、文脈に合う。"}, {"text": "破壊", "is_correct": false, "explanation": "形は合うが、「一位を破壊した」では意味が合わない。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが、「一位を運転した」では意味が合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "形は合うが、「一位を掃除した」では意味が合わない。"}], "explanations": {"獲得": "一位を手に入れる意味で、文脈に合う。", "破壊": "形は合うが、「一位を破壊した」では意味が合わない。", "運転": "形は合うが、「一位を運転した」では意味が合わない。", "掃除": "形は合うが、「一位を掃除した」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "獲得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事な切符を落として、獲得してしまった。", "explanation": "獲得は手に入れることなので、物を失う場面に使うのは誤り。"}, {"text": "獲得を飲むのは、思ったより難しい。", "explanation": "獲得は行為であり飲み物ではないので、「飲む」の目的語として誤り。"}, {"text": "弟は獲得で学校へ行った。", "explanation": "獲得は乗り物ではないので、手段を表す「で」と組み合わせるのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51961, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "獲得", "is_correct": true, "explanation": "留学の権利を手に入れる意味で、文脈に合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、「留学の権利を洗濯」では意味が合わない。"}, {"text": "料理", "is_correct": false, "explanation": "形は合うが、「権利を料理できた」では意味が合わない。"}, {"text": "修理", "is_correct": false, "explanation": "形は合うが、夢だった権利に対して意味が合わない。"}], "explanations": {"獲得": "留学の権利を手に入れる意味で、文脈に合う。", "洗濯": "形は合うが、「留学の権利を洗濯」では意味が合わない。", "料理": "形は合うが、「権利を料理できた」では意味が合わない。", "修理": "形は合うが、夢だった権利に対して意味が合わない。"}, "sentence_index": 6, "correct_answer": "獲得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は獲得の上に座って休んだ。", "explanation": "獲得は行為で物ではないので、座る場所として使うのは誤り。"}, {"text": "彼女は獲得を着て、パーティーに出かけた。", "explanation": "獲得は服ではないので、「着る」の目的語として誤り。"}, {"text": "獲得が庭できれいな花を咲かせている。", "explanation": "獲得は行為で植物ではないので、「花を咲かせる」の主語として誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
