INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51962, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "努力や行動によって、自分のものにすること。手に入れること。", "primary_collocate": null, "pronunciation": "かくとく", "ipa": "kakɯtokɯ", "syllable_count": 4, "sentences": [{"text": "誰に何を求めているか分析し、適切な言葉で発信することで、小さくても確実なファンを獲得できます。", "target_word": "獲得", "complexity_tier": "T6", "furigana": "誰[だれ]に何[なに]を求[もと]めているか分析[ぶんせき]し、適切[てきせつ]な言葉[ことば]で発信[はっしん]することで、小[ちい]さくても確実[かくじつ]なファンを獲得[かくとく]できます。", "sentence_source": "mined"}, {"text": "票を獲得する。", "target_word": "獲得", "complexity_tier": "T1", "furigana": "票[ひょう]を獲得[かくとく]する。", "sentence_source": "generated"}, {"text": "彼女は金メダルを獲得しました。", "target_word": "獲得", "complexity_tier": "T2", "furigana": "彼女[かのじょ]は金[きん]メダルを獲得[かくとく]しました。", "sentence_source": "generated"}, {"text": "獲得は簡単ではありません。", "target_word": "獲得", "complexity_tier": "T2", "furigana": "獲得[かくとく]は簡単[かんたん]ではありません。", "sentence_source": "generated"}, {"text": "客を獲得するために、安く売っている。", "target_word": "獲得", "complexity_tier": "T3", "furigana": "客[きゃく]を獲得[かくとく]するために、安[やす]く売[う]っている。", "sentence_source": "generated"}, {"text": "努力して獲得した自信は、簡単には消えない。", "target_word": "獲得", "complexity_tier": "T3", "furigana": "努力[どりょく]して獲得[かくとく]した自信[じしん]は、簡単[かんたん]には消[き]えない。", "sentence_source": "generated"}, {"text": "新しい技術の獲得が、会社の目標になった。", "target_word": "獲得", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]の獲得[かくとく]が、会社[かいしゃ]の目標[もくひょう]になった。", "sentence_source": "generated"}, {"text": "支持を獲得できれば、選挙に勝てるだろう。", "target_word": "獲得", "complexity_tier": "T4", "furigana": "支持[しじ]を獲得[かくとく]できれば、選挙[せんきょ]に勝[か]てるだろう。", "sentence_source": "generated"}, {"text": "彼らによって獲得された権利は、今も守られている。", "target_word": "獲得", "complexity_tier": "T4", "furigana": "彼[かれ]らによって獲得[かくとく]された権利[けんり]は、今[いま]も守[まも]られている。", "sentence_source": "generated"}, {"text": "試合に勝って、ポイントを獲得した。", "target_word": "獲得", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]って、ポイントを獲得[かくとく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲得する", "label": "活用"}, {"form": "獲得した", "label": "活用"}, {"form": "獲得できる", "label": "活用"}, {"form": "獲得数", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 努力や行動で自分のものにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51962, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "獲得", "is_correct": true, "explanation": "ファンを手に入れる意味で、文脈に合う。"}, {"text": "破壊", "is_correct": false, "explanation": "形は合うが、ファンを増やす文脈では意味が合わない。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが、「ファンを運転できる」では意味が合わない。"}, {"text": "紛失", "is_correct": false, "explanation": "形は合うが、発信して得る成果の文脈では意味が合わない。"}], "explanations": {"獲得": "ファンを手に入れる意味で、文脈に合う。", "破壊": "形は合うが、ファンを増やす文脈では意味が合わない。", "運転": "形は合うが、「ファンを運転できる」では意味が合わない。", "紛失": "形は合うが、発信して得る成果の文脈では意味が合わない。"}, "sentence_index": 0, "correct_answer": "獲得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "財布を落として、千円を獲得しました。", "explanation": "獲得は手に入れることなので、お金を失う場面に使うのは誤り。"}, {"text": "朝ごはんに獲得を食べました。", "explanation": "獲得は行為であり食べ物ではないので、「食べる」の目的語として誤り。"}, {"text": "雨が獲得して、傘をさしました。", "explanation": "獲得は人が努力して手に入れる行為なので、雨を主語にするのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51962, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "獲得", "is_correct": true, "explanation": "新しい技術を手に入れることが目標になる、という意味で合う。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「技術の地震」では意味が合わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "形は合うが、会社の目標として意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「新しい技術の天気」では意味が合わない。"}], "explanations": {"獲得": "新しい技術を手に入れることが目標になる、という意味で合う。", "地震": "形は合うが、「技術の地震」では意味が合わない。", "昼寝": "形は合うが、会社の目標として意味が合わない。", "天気": "形は合うが、「新しい技術の天気」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "獲得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "犬が公園で獲得を走っている。", "explanation": "獲得は動作の場所や道ではないので、「走る」の対象にするのは誤り。"}, {"text": "獲得が机の上で気持ちよさそうに寝ている。", "explanation": "獲得は行為で生き物ではないので、「寝る」の主語として誤り。"}, {"text": "窓を獲得して、部屋を涼しくした。", "explanation": "獲得は手に入れる意味で、「窓を開ける」の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51962, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は大会で優勝して、金メダルに獲得しました。", "corrected_sentence": "彼は大会で優勝して、金メダルを獲得しました。", "error_description": "獲得の対象は「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
