INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51963, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「事業をする」と、「する」の目的語を示す正しい助詞です。"}, {"text": "が", "is_correct": false, "explanation": "「母は…事業がしています」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「事業へしています」は文として成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「事業のしています」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「事業をする」と、「する」の目的語を示す正しい助詞です。", "が": "「母は…事業がしています」は文として成り立ちません。", "へ": "「事業へしています」は文として成り立ちません。", "の": "「事業のしています」は文として成り立ちません。"}, "error_tags": {"が": "subject_marker_misuse", "へ": "direction_misuse", "の": "possessive_misuse"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51963, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「事業を大きくする」と、目的語を示す正しい助詞です。"}, {"text": "の", "is_correct": false, "explanation": "「事業の大きくしたければ」は文として成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「事業に大きくしたければ」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「事業へ大きくしたければ」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「事業を大きくする」と、目的語を示す正しい助詞です。", "の": "「事業の大きくしたければ」は文として成り立ちません。", "に": "「事業に大きくしたければ」は文として成り立ちません。", "へ": "「事業へ大きくしたければ」は文として成り立ちません。"}, "error_tags": {"の": "possessive_misuse", "に": "target_marker_misuse", "へ": "direction_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51963, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人がお金をかせぐためにするしごとや、やること。", "primary_collocate": null, "pronunciation": "じぎょう", "ipa": "d͡ʑiɡʲoː", "syllable_count": 3, "sentences": [{"text": "事業で稼ぐ。", "target_word": "事業", "complexity_tier": "T1", "furigana": "事業(じぎょう)で稼(かせ)ぐ。", "sentence_source": "generated"}, {"text": "事業は順調だ。", "target_word": "事業", "complexity_tier": "T1", "furigana": "事業(じぎょう)は順調(じゅんちょう)だ。", "sentence_source": "generated"}, {"text": "母は小さな事業をしています。", "target_word": "事業", "complexity_tier": "T2", "furigana": "母(はは)は小(ちい)さな事業(じぎょう)をしています。", "sentence_source": "generated"}, {"text": "事業の話を聞きます。", "target_word": "事業", "complexity_tier": "T2", "furigana": "事業(じぎょう)の話(はなし)を聞(き)きます。", "sentence_source": "generated"}, {"text": "友達と二人で事業を始めて、三年になる。", "target_word": "事業", "complexity_tier": "T3", "furigana": "友達(ともだち)と二人(ふたり)で事業(じぎょう)を始(はじ)めて、三年(さんねん)になる。", "sentence_source": "generated"}, {"text": "事業にはお金と時間が必要だ。", "target_word": "事業", "complexity_tier": "T3", "furigana": "事業(じぎょう)にはお金(かね)と時間(じかん)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "事業が失敗して、彼は借金を背負った。", "target_word": "事業", "complexity_tier": "T3", "furigana": "事業(じぎょう)が失敗(しっぱい)して、彼(かれ)は借金(しゃっきん)を背負(せお)った。", "sentence_source": "generated"}, {"text": "事業を大きくしたければ、人を育てることが大切だ。", "target_word": "事業", "complexity_tier": "T4", "furigana": "事業(じぎょう)を大(おお)きくしたければ、人(ひと)を育(そだ)てることが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "祖父が作った事業を、私が受け継ぐことになった。", "target_word": "事業", "complexity_tier": "T4", "furigana": "祖父(そふ)が作(つく)った事業(じぎょう)を、私(わたし)が受(う)け継(つ)ぐことになった。", "sentence_source": "generated"}, {"text": "新しい事業を始める前に、市場を調べ、資金の計画を立てておくべきだ。", "target_word": "事業", "complexity_tier": "T5", "furigana": "新(あたら)しい事業(じぎょう)を始(はじ)める前(まえ)に、市場(しじょう)を調(しら)べ、資金(しきん)の計画(けいかく)を立(た)てておくべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事業者", "label": "派生"}, {"form": "事業所", "label": "派生"}, {"form": "事業主", "label": "派生"}, {"form": "事業化", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | お金を稼ぐためにする仕事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51963, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事業", "is_correct": true, "explanation": "「事業」(じぎょう)が聞こえた語で、正解です。"}, {"text": "企業", "is_correct": false, "explanation": "「きぎょう」は最初の一拍が「き」で、「じ」と違います。"}, {"text": "偉業", "is_correct": false, "explanation": "「いぎょう」は最初の一拍が「い」で、「じ」と違います。"}, {"text": "始業", "is_correct": false, "explanation": "「しぎょう」は清音の「し」で、濁音の「じ」と違います。"}, {"text": "作業", "is_correct": false, "explanation": "「さぎょう」は最初の一拍が「さ」で、「じ」と違います。"}], "explanations": {"事業": "「事業」(じぎょう)が聞こえた語で、正解です。", "企業": "「きぎょう」は最初の一拍が「き」で、「じ」と違います。", "偉業": "「いぎょう」は最初の一拍が「い」で、「じ」と違います。", "始業": "「しぎょう」は清音の「し」で、濁音の「じ」と違います。", "作業": "「さぎょう」は最初の一拍が「さ」で、「じ」と違います。"}, "sentence_index": null, "correct_answer": "事業"}, "level_3": {"options": [{"text": "事業", "is_correct": true, "explanation": "お金をかせぐための仕事という意味に合います。"}, {"text": "眠気", "is_correct": false, "explanation": "形は合うが、眠気でお金を稼ぐことはなく、意味が合いません。"}, {"text": "夕焼け", "is_correct": false, "explanation": "形は合うが、夕焼けでお金を稼ぐことはできず、意味が合いません。"}, {"text": "湯気", "is_correct": false, "explanation": "形は合うが、湯気で稼ぐという文は意味が合いません。"}], "explanations": {"事業": "お金をかせぐための仕事という意味に合います。", "眠気": "形は合うが、眠気でお金を稼ぐことはなく、意味が合いません。", "夕焼け": "形は合うが、夕焼けでお金を稼ぐことはできず、意味が合いません。", "湯気": "形は合うが、湯気で稼ぐという文は意味が合いません。"}, "sentence_index": 0, "correct_answer": "事業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事業を履いて、学校へ行きます。", "explanation": "「事業」は仕事のことで、履き物ではないので「履く」とは使えません。"}, {"text": "夕方、空に大きな事業が見えました。", "explanation": "「事業」は抽象的な活動で、空に見える物ではありません。"}, {"text": "朝から事業が痛くて、病院に行った。", "explanation": "「事業」は体の部位ではないので、「痛い」とは結びつきません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51963, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事業", "is_correct": true, "explanation": "「事業」(じぎょう)が聞こえた語で、正解です。"}, {"text": "自供", "is_correct": false, "explanation": "「じきょう」は二拍目が清音の「きょ」で、濁音の「ぎょ」と違います。"}, {"text": "持病", "is_correct": false, "explanation": "「じびょう」は二拍目が「びょ」で、「ぎょ」と違います。"}, {"text": "辞表", "is_correct": false, "explanation": "「じひょう」は二拍目が「ひょ」で、「ぎょ」と違います。"}, {"text": "次長", "is_correct": false, "explanation": "「じちょう」は二拍目が「ちょ」で、「ぎょ」と違います。"}], "explanations": {"事業": "「事業」(じぎょう)が聞こえた語で、正解です。", "自供": "「じきょう」は二拍目が清音の「きょ」で、濁音の「ぎょ」と違います。", "持病": "「じびょう」は二拍目が「びょ」で、「ぎょ」と違います。", "辞表": "「じひょう」は二拍目が「ひょ」で、「ぎょ」と違います。", "次長": "「じちょう」は二拍目が「ちょ」で、「ぎょ」と違います。"}, "sentence_index": null, "correct_answer": "事業"}, "level_3": {"options": [{"text": "事業", "is_correct": true, "explanation": "失敗して借金を背負う原因として、仕事の意味に合います。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、景色が失敗するとは言えず、意味が合いません。"}, {"text": "夕日", "is_correct": false, "explanation": "形は合うが、夕日が失敗して借金になるのは意味が合いません。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、果物が失敗するとは言えず、意味が合いません。"}], "explanations": {"事業": "失敗して借金を背負う原因として、仕事の意味に合います。", "景色": "形は合うが、景色が失敗するとは言えず、意味が合いません。", "夕日": "形は合うが、夕日が失敗して借金になるのは意味が合いません。", "果物": "形は合うが、果物が失敗するとは言えず、意味が合いません。"}, "sentence_index": 6, "correct_answer": "事業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事業を飲みながら本を読んだ。", "explanation": "「事業」は飲み物ではないので、「飲む」の目的語になりません。"}, {"text": "昨夜は事業が光っていて、とてもきれいだった。", "explanation": "「事業」は光る物ではなく、星のように「光る」とは使えません。"}, {"text": "彼は事業で髪を切ってもらった。", "explanation": "「事業」は道具ではないので、「髪を切る」手段として使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51963, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は小さな事業に経営しています。", "corrected_sentence": "姉は小さな事業を経営しています。", "error_description": "「経営する」の目的語になる「事業」には、「に」ではなく「を」を使います。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51963, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達と二人で事業を割って、三年になる。", "corrected_sentence": "友達と二人で事業を始めて、三年になる。", "error_description": "「事業」には「割る」ではなく「始める」を使います。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51964, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「事業の終了」と、事業を終了の修飾語にする正しい助詞です。"}, {"text": "が", "is_correct": false, "explanation": "「事業が終了ではなく」は文として成り立ちません。"}, {"text": "を", "is_correct": false, "explanation": "「事業を終了ではなく」は文として成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「事業に終了ではなく」は文として成り立ちません。"}], "correct_answer": "の", "explanations": {"の": "「事業の終了」と、事業を終了の修飾語にする正しい助詞です。", "が": "「事業が終了ではなく」は文として成り立ちません。", "を": "「事業を終了ではなく」は文として成り立ちません。", "に": "「事業に終了ではなく」は文として成り立ちません。"}, "error_tags": {"が": "subject_marker_misuse", "を": "object_marker_misuse", "に": "target_marker_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51964, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「事業が軌道に乗る」と、事業を主語にする正しい助詞です。"}, {"text": "を", "is_correct": false, "explanation": "「乗れば」は自動詞なので、「事業を」では文になりません。"}, {"text": "へ", "is_correct": false, "explanation": "「事業へ軌道に乗れば」は文として成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「事業に軌道に乗れば」は文として成り立ちません。"}], "correct_answer": "が", "explanations": {"が": "「事業が軌道に乗る」と、事業を主語にする正しい助詞です。", "を": "「乗れば」は自動詞なので、「事業を」では文になりません。", "へ": "「事業へ軌道に乗れば」は文として成り立ちません。", "に": "「事業に軌道に乗れば」は文として成り立ちません。"}, "error_tags": {"を": "object_marker_misuse", "へ": "direction_misuse", "に": "target_marker_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51964, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "利益を得る目的で行う経済活動や、特定の目的を持って行う仕事や計画。", "primary_collocate": null, "pronunciation": "じぎょう", "ipa": "d͡ʑiɡʲoː", "syllable_count": 3, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "事業", "complexity_tier": "T6", "furigana": "初期段階(しょきだんかい)では、投資家(とうしか)からの資金調達(しきんちょうたつ)を通(つう)じて事業(じぎょう)の基盤(きばん)を固(かた)め、市場(しじょう)での急速(きゅうそく)な成長(せいちょう)を目指(めざ)す。", "sentence_source": "mined"}, {"text": "これは事業の終了ではなく、資本の循環と新たな創造への移行を意味する重要なプロセスだ。", "target_word": "事業", "complexity_tier": "T6", "furigana": "これは事業(じぎょう)の終了(しゅうりょう)ではなく、資本(しほん)の循環(じゅんかん)と新(あら)たな創造(そうぞう)への移行(いこう)を意味(いみ)する重要(じゅうよう)なプロセスだ。", "sentence_source": "mined"}, {"text": "事業を始める。", "target_word": "事業", "complexity_tier": "T1", "furigana": "事業(じぎょう)を始(はじ)める。", "sentence_source": "generated"}, {"text": "父は事業をしています。", "target_word": "事業", "complexity_tier": "T2", "furigana": "父(ちち)は事業(じぎょう)をしています。", "sentence_source": "generated"}, {"text": "この事業は成功しました。", "target_word": "事業", "complexity_tier": "T2", "furigana": "この事業(じぎょう)は成功(せいこう)しました。", "sentence_source": "generated"}, {"text": "兄は新しい事業を立ち上げて、忙しそうだ。", "target_word": "事業", "complexity_tier": "T3", "furigana": "兄(あに)は新(あたら)しい事業(じぎょう)を立(た)ち上(あ)げて、忙(いそが)しそうだ。", "sentence_source": "generated"}, {"text": "国の事業に、多くの人が協力した。", "target_word": "事業", "complexity_tier": "T3", "furigana": "国(くに)の事業(じぎょう)に、多(おお)くの人(ひと)が協力(きょうりょく)した。", "sentence_source": "generated"}, {"text": "事業が軌道に乗れば、雇う人を増やすつもりだ。", "target_word": "事業", "complexity_tier": "T4", "furigana": "事業(じぎょう)が軌道(きどう)に乗(の)れば、雇(やと)う人(ひと)を増(ふ)やすつもりだ。", "sentence_source": "generated"}, {"text": "資金が足りず、事業を続けられなくなった。", "target_word": "事業", "complexity_tier": "T4", "furigana": "資金(しきん)が足(た)りず、事業(じぎょう)を続(つづ)けられなくなった。", "sentence_source": "generated"}, {"text": "地域の人々の暮らしを支えるために、市は新しい事業を計画している。", "target_word": "事業", "complexity_tier": "T5", "furigana": "地域(ちいき)の人々(ひとびと)の暮(く)らしを支(ささ)えるために、市(し)は新(あたら)しい事業(じぎょう)を計画(けいかく)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事業者", "label": "派生"}, {"form": "事業所", "label": "派生"}, {"form": "事業主", "label": "派生"}, {"form": "事業化", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 利益を得る目的で行う経済活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51964, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事業", "is_correct": true, "explanation": "「事業」(じぎょう)が聞こえた語で、正解です。"}, {"text": "企業", "is_correct": false, "explanation": "「きぎょう」は最初の一拍が「き」で、「じ」と違います。"}, {"text": "偉業", "is_correct": false, "explanation": "「いぎょう」は最初の一拍が「い」で、「じ」と違います。"}, {"text": "始業", "is_correct": false, "explanation": "「しぎょう」は清音の「し」で、濁音の「じ」と違います。"}, {"text": "作業", "is_correct": false, "explanation": "「さぎょう」は最初の一拍が「さ」で、「じ」と違います。"}], "explanations": {"事業": "「事業」(じぎょう)が聞こえた語で、正解です。", "企業": "「きぎょう」は最初の一拍が「き」で、「じ」と違います。", "偉業": "「いぎょう」は最初の一拍が「い」で、「じ」と違います。", "始業": "「しぎょう」は清音の「し」で、濁音の「じ」と違います。", "作業": "「さぎょう」は最初の一拍が「さ」で、「じ」と違います。"}, "sentence_index": null, "correct_answer": "事業"}, "level_3": {"options": [{"text": "事業", "is_correct": true, "explanation": "資金調達を通じて基盤を固め、成長を目指す対象として意味が合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気は資金調達で基盤を固めて成長させるものではなく、意味が合いません。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、果物は市場での成長を目指す基盤を持たず、意味が合いません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節は投資家の資金で基盤を固めるものではなく、意味が合いません。"}], "explanations": {"事業": "資金調達を通じて基盤を固め、成長を目指す対象として意味が合います。", "天気": "形は合うが、天気は資金調達で基盤を固めて成長させるものではなく、意味が合いません。", "果物": "形は合うが、果物は市場での成長を目指す基盤を持たず、意味が合いません。", "季節": "形は合うが、季節は投資家の資金で基盤を固めるものではなく、意味が合いません。"}, "sentence_index": 0, "correct_answer": "事業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日は事業が降っていて、傘が必要だった。", "explanation": "「事業」は仕事や経済活動で、雨のように「降る」ものではありません。"}, {"text": "父は毎朝、事業を食べてから会社に行きます。", "explanation": "「事業」は抽象的な活動なので、「食べる」の目的語にはなりません。"}, {"text": "この事業は赤くて、とてもやわらかいです。", "explanation": "「事業」は色や手触りを持つ物ではないため、「赤い」「やわらかい」とは使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51964, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事業", "is_correct": true, "explanation": "「事業」(じぎょう)が聞こえた語で、正解です。"}, {"text": "自供", "is_correct": false, "explanation": "「じきょう」は二拍目が清音の「きょ」で、濁音の「ぎょ」と違います。"}, {"text": "持病", "is_correct": false, "explanation": "「じびょう」は二拍目が「びょ」で、「ぎょ」と違います。"}, {"text": "辞表", "is_correct": false, "explanation": "「じひょう」は二拍目が「ひょ」で、「ぎょ」と違います。"}, {"text": "次長", "is_correct": false, "explanation": "「じちょう」は二拍目が「ちょ」で、「ぎょ」と違います。"}], "explanations": {"事業": "「事業」(じぎょう)が聞こえた語で、正解です。", "自供": "「じきょう」は二拍目が清音の「きょ」で、濁音の「ぎょ」と違います。", "持病": "「じびょう」は二拍目が「びょ」で、「ぎょ」と違います。", "辞表": "「じひょう」は二拍目が「ひょ」で、「ぎょ」と違います。", "次長": "「じちょう」は二拍目が「ちょ」で、「ぎょ」と違います。"}, "sentence_index": null, "correct_answer": "事業"}, "level_3": {"options": [{"text": "事業", "is_correct": true, "explanation": "国が行う仕事や計画に多くの人が協力した、という意味に合います。"}, {"text": "眠気", "is_correct": false, "explanation": "形は合うが、眠気に協力することはなく、意味が合いません。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、景色に人が協力するとは言えず、意味が合いません。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、果物に多くの人が協力するのは意味が合いません。"}], "explanations": {"事業": "国が行う仕事や計画に多くの人が協力した、という意味に合います。", "眠気": "形は合うが、眠気に協力することはなく、意味が合いません。", "景色": "形は合うが、景色に人が協力するとは言えず、意味が合いません。", "果物": "形は合うが、果物に多くの人が協力するのは意味が合いません。"}, "sentence_index": 6, "correct_answer": "事業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は昨日、公園で事業に乗って遊びました。", "explanation": "「事業」は乗り物ではないので、「乗る」とは結びつきません。"}, {"text": "テーブルの上に事業が三つ置いてあります。", "explanation": "「事業」は置ける物ではなく、物のように数えて置くことはできません。"}, {"text": "彼女は事業を着て、パーティーに出かけた。", "explanation": "「事業」は衣服ではないので、「着る」の目的語になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUD