INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51964, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は新しい事業を建てるために、銀行から資金を借りた。", "corrected_sentence": "彼は新しい事業を起こすために、銀行から資金を借りた。", "error_description": "「事業」には「建てる」ではなく「起こす」を使います。「建てる」は建物に使う動詞です。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51964, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は地域のために新しい事業が計画している。", "corrected_sentence": "市は地域のために新しい事業を計画している。", "error_description": "「計画する」の目的語になる「事業」には、「が」ではなく「を」を使います。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51965, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「泥を固める」と、目的語を示す正しい助詞です。"}, {"text": "が", "is_correct": false, "explanation": "「泥が固めて皿を作ります」は他動詞と合わず、文になりません。"}, {"text": "へ", "is_correct": false, "explanation": "「泥へ固めて」は文として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「泥と固めて」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「泥を固める」と、目的語を示す正しい助詞です。", "が": "「泥が固めて皿を作ります」は他動詞と合わず、文になりません。", "へ": "「泥へ固めて」は文として成り立ちません。", "と": "「泥と固めて」は文として成り立ちません。"}, "error_tags": {"が": "subject_marker_misuse", "へ": "direction_misuse", "と": "comitative_misuse"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "溶かす", "is_correct": true, "explanation": "固い物を液体に近い状態にする意味で、「固める」の反対です。"}, {"text": "切る", "is_correct": false, "explanation": "刃物で分ける意味で、反対ではありません。"}, {"text": "洗う", "is_correct": false, "explanation": "水で汚れを落とす意味で、反対ではありません。"}, {"text": "混ぜる", "is_correct": false, "explanation": "合わせる意味で、「固める」の反対ではありません。"}], "correct_answer": "溶かす", "explanations": {"溶かす": "固い物を液体に近い状態にする意味で、「固める」の反対です。", "切る": "刃物で分ける意味で、反対ではありません。", "洗う": "水で汚れを落とす意味で、反対ではありません。", "混ぜる": "合わせる意味で、「固める」の反対ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51965, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「粘土を固める」と、目的語を示す正しい助詞です。"}, {"text": "が", "is_correct": false, "explanation": "「粘土が手で固めると」は他動詞と合わず、文になりません。"}, {"text": "に", "is_correct": false, "explanation": "「粘土に手で固めると」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「粘土へ手で固めると」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「粘土を固める」と、目的語を示す正しい助詞です。", "が": "「粘土が手で固めると」は他動詞と合わず、文になりません。", "に": "「粘土に手で固めると」は文として成り立ちません。", "へ": "「粘土へ手で固めると」は文として成り立ちません。"}, "error_tags": {"が": "subject_marker_misuse", "に": "target_marker_misuse", "へ": "direction_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "崩す", "is_correct": true, "explanation": "かたくまとまった物を壊す意味で、「固める」の反対です。"}, {"text": "並べる", "is_correct": false, "explanation": "順に置く意味で、反対ではありません。"}, {"text": "拾う", "is_correct": false, "explanation": "手に取る意味で、反対ではありません。"}, {"text": "渡す", "is_correct": false, "explanation": "向こうへ移す意味で、「固める」とは無関係です。"}], "correct_answer": "崩す", "explanations": {"崩す": "かたくまとまった物を壊す意味で、「固める」の反対です。", "並べる": "順に置く意味で、反対ではありません。", "拾う": "手に取る意味で、反対ではありません。", "渡す": "向こうへ移す意味で、「固める」とは無関係です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51965, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものをかたくしたり、しっかりしたものにすること。", "primary_collocate": null, "pronunciation": "かためる", "ipa": "katame̞ɾɯ", "syllable_count": 4, "sentences": [{"text": "砂を固める。", "target_word": "固める", "complexity_tier": "T1", "furigana": "砂(すな)を固(かた)める。", "sentence_source": "generated"}, {"text": "手で固めた。", "target_word": "固めた", "complexity_tier": "T1", "furigana": "手(て)で固(かた)めた。", "sentence_source": "generated"}, {"text": "泥を固めて皿を作ります。", "target_word": "固めて", "complexity_tier": "T2", "furigana": "泥(どろ)を固(かた)めて皿(さら)を作(つく)ります。", "sentence_source": "generated"}, {"text": "ゼリーを冷やして固めます。", "target_word": "固めます", "complexity_tier": "T2", "furigana": "ゼリーを冷(ひ)やして固(かた)めます。", "sentence_source": "generated"}, {"text": "ご飯を丸く固めて、おにぎりを作った。", "target_word": "固めて", "complexity_tier": "T3", "furigana": "ご飯(はん)を丸(まる)く固(かた)めて、おにぎりを作(つく)った。", "sentence_source": "generated"}, {"text": "地面を固めて、その上に家を建てる。", "target_word": "固めて", "complexity_tier": "T3", "furigana": "地面(じめん)を固(かた)めて、その上(うえ)に家(いえ)を建(た)てる。", "sentence_source": "generated"}, {"text": "チョコレートを冷蔵庫で固める。", "target_word": "固める", "complexity_tier": "T3", "furigana": "チョコレートを冷蔵庫(れいぞうこ)で固(かた)める。", "sentence_source": "generated"}, {"text": "粘土を手で固めると、丸い玉になる。", "target_word": "固める", "complexity_tier": "T4", "furigana": "粘土(ねんど)を手(て)で固(かた)めると、丸(まる)い玉(たま)になる。", "sentence_source": "generated"}, {"text": "雪を手でぎゅっと固めて、雪玉を作った。", "target_word": "固めて", "complexity_tier": "T4", "furigana": "雪(ゆき)を手(て)でぎゅっと固(かた)めて、雪玉(ゆきだま)を作(つく)った。", "sentence_source": "generated"}, {"text": "工事の前に、道を固める作業をしないと、雨でくずれてしまう。", "target_word": "固める", "complexity_tier": "T5", "furigana": "工事(こうじ)の前(まえ)に、道(みち)を固(かた)める作業(さぎょう)をしないと、雨(あめ)でくずれてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "固めて", "label": "活用"}, {"form": "固めた", "label": "活用"}, {"form": "固めない", "label": "活用"}, {"form": "固まる", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | ものをかたくしっかりさせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51965, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "固める", "is_correct": true, "explanation": "「固める」(かためる)が聞こえた語で、正解です。"}, {"text": "偏る", "is_correct": false, "explanation": "「かたよる」は三拍目が「よ」で、「め」と違います。"}, {"text": "掠める", "is_correct": false, "explanation": "「かすめる」は二拍目が「す」で、「た」と違います。"}, {"text": "絡める", "is_correct": false, "explanation": "「からめる」は二拍目が「ら」で、「た」と違います。"}], "explanations": {"固める": "「固める」(かためる)が聞こえた語で、正解です。", "偏る": "「かたよる」は三拍目が「よ」で、「め」と違います。", "掠める": "「かすめる」は二拍目が「す」で、「た」と違います。", "絡める": "「からめる」は二拍目が「ら」で、「た」と違います。"}, "sentence_index": null, "correct_answer": "固める"}, "level_3": {"options": [{"text": "固める", "is_correct": true, "explanation": "砂をかたくしっかりさせる、という意味に合います。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが、砂は食べ物ではなく、意味が合いません。"}, {"text": "飲む", "is_correct": false, "explanation": "形は合うが、砂は飲むものではなく、意味が合いません。"}, {"text": "着る", "is_correct": false, "explanation": "形は合うが、砂は着るものではなく、意味が合いません。"}], "explanations": {"固める": "砂をかたくしっかりさせる、という意味に合います。", "食べる": "形は合うが、砂は食べ物ではなく、意味が合いません。", "飲む": "形は合うが、砂は飲むものではなく、意味が合いません。", "着る": "形は合うが、砂は着るものではなく、意味が合いません。"}, "sentence_index": 0, "correct_answer": "固める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達の名前を忘れて固めました。", "explanation": "「名前」は形のある物ではなく、「固める」の対象になりません。"}, {"text": "窓を開けて、部屋の空気を固めます。", "explanation": "「空気」は普通かたくできないので、この文脈で「固める」は不自然です。"}, {"text": "毎晩、日記を固めてから寝ます。", "explanation": "「日記」は書くもので、かたくする対象ではないため「固める」は不自然です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51965, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "固める", "is_correct": true, "explanation": "「固める」(かためる)が聞こえた語で、正解です。"}, {"text": "偏る", "is_correct": false, "explanation": "「かたよる」は三拍目が「よ」で、「め」と違います。"}, {"text": "象る", "is_correct": false, "explanation": "「かたどる」は三拍目が「ど」で、「め」と違います。"}, {"text": "屈める", "is_correct": false, "explanation": "「かがめる」は二拍目が「が」で、「た」と違います。"}], "explanations": {"固める": "「固める」(かためる)が聞こえた語で、正解です。", "偏る": "「かたよる」は三拍目が「よ」で、「め」と違います。", "象る": "「かたどる」は三拍目が「ど」で、「め」と違います。", "屈める": "「かがめる」は二拍目が「が」で、「た」と違います。"}, "sentence_index": null, "correct_answer": "固める"}, "level_3": {"options": [{"text": "固める", "is_correct": true, "explanation": "チョコレートを冷やしてかたくする、という意味に合います。"}, {"text": "読む", "is_correct": false, "explanation": "形は合うが、チョコレートは読むものではなく、意味が合いません。"}, {"text": "着る", "is_correct": false, "explanation": "形は合うが、チョコレートは着るものではなく、意味が合いません。"}, {"text": "聞く", "is_correct": false, "explanation": "形は合うが、チョコレートは聞くものではなく、意味が合いません。"}], "explanations": {"固める": "チョコレートを冷やしてかたくする、という意味に合います。", "読む": "形は合うが、チョコレートは読むものではなく、意味が合いません。", "着る": "形は合うが、チョコレートは着るものではなく、意味が合いません。", "聞く": "形は合うが、チョコレートは聞くものではなく、意味が合いません。"}, "sentence_index": 6, "correct_answer": "固める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "犬が公園で楽しそうに風を固めている。", "explanation": "「風」はかたくできないので、「固める」の対象になりません。"}, {"text": "彼は夕方、手紙を固めてから出かけた。", "explanation": "「手紙」は普通かたくするものではなく、ここでの使い方は不自然です。"}, {"text": "電車の中で、大きな声を固めて話した。", "explanation": "「声」は形がないので、かたくする意味の「固める」は使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51965, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母はゼリーを冷蔵庫で固まった。", "corrected_sentence": "母はゼリーを冷蔵庫で固めた。", "error_description": "「ゼリーを」を受けるのは他動詞「固める」で、自動詞の「固まる」は使えません。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "固めた", "is_correct": true, "explanation": "「手で固めた。」と過去を表して文を終える形で、正解です。"}, {"text": "固めれば", "is_correct": false, "explanation": "仮定形では「手で固めれば。」と文が完結しません。"}, {"text": "固め", "is_correct": false, "explanation": "連用形では「手で固め。」と文が終わりません。"}, {"text": "固めず", "is_correct": false, "explanation": "「手で固めず。」は否定の連用で、文末としては不自然で、過去の意味も出ません。"}], "correct_form": "固めた", "base_form": "固める", "form_label": "た形", "sentence_index": 1, "explanations": {"固めた": "「手で固めた。」と過去を表して文を終える形で、正解です。", "固めれば": "仮定形では「手で固めれば。」と文が完結しません。", "固め": "連用形では「手で固め。」と文が終わりません。", "固めず": "「手で固めず。」は否定の連用で、文末としては不自然で、過去の意味も出ません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51965, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は庭の土が固めて、その上に小屋を建てた。", "corrected_sentence": "父は庭の土を固めて、その上に小屋を建てた。", "error_description": "他動詞「固める」の目的語「土」には、「が」ではなく「を」を使います。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "固める", "is_correct": true, "explanation": "「固めると、丸い玉になる」と、条件を表す「と」の前に置く辞書形で、正解です。"}, {"text": "固めた", "is_correct": false, "explanation": "「固めたと」では引用になり、この文の条件の意味になりません。"}, {"text": "固めれば", "is_correct": false, "explanation": "「固めればと」は「と」と続かず、文になりません。"}, {"text": "固めて", "is_correct": false, "explanation": "「固めてと」は「と」と続かず、文になりません。"}], "correct_form": "固める", "base_form": "固める", "form_label": "辞書形", "sentence_index": 7, "explanations": {"固める": "「固めると、丸い玉になる」と、条件を表す「と」の前に置く辞書形で、正解です。", "固めた": "「固めたと」では引用になり、この文の条件の意味になりません。", "固めれば": "「固めればと」は「と」と続かず、文になりません。", "固めて": "「固めてと」は「と」と続かず、文になりません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51966, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「基盤を固める」と、目的語を示す正しい助詞です。"}, {"text": "が", "is_correct": false, "explanation": "「基盤が固め」は他動詞と合わず、文になりません。"}, {"text": "に", "is_correct": false, "explanation": "「基盤に固め」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「基盤へ固め」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「基盤を固める」と、目的語を示す正しい助詞です。", "が": "「基盤が固め」は他動詞と合わず、文になりません。", "に": "「基盤に固め」は文として成り立ちません。", "へ": "「基盤へ固め」は文として成り立ちません。"}, "error_tags": {"が": "subject_marker_misuse", "に": "target_marker_misuse", "へ": "direction_misuse"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "崩す", "is_correct": true, "explanation": "しっかりした状態を壊す意味で、「固める」の反対です。"}, {"text": "調べる", "is_correct": false, "explanation": "確かめる意味で、「固める」の反対ではありません。"}, {"text": "守る", "is_correct": false, "explanation": "守り支える意味で、反対ではありません。"}, {"text": "運ぶ", "is_correct": false, "explanation": "移動させる意味で、「固める」とは無関係です。"}], "correct_answer": "崩す", "explanations": {"崩す": "しっかりした状態を壊す意味で、「固める」の反対です。", "調べる": "確かめる意味で、「固める」の反対ではありません。", "守る": "守り支える意味で、反対ではありません。", "運ぶ": "移動させる意味で、「固める」とは無関係です。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51966, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「証拠を固める」と、目的語を示す正しい助詞です。"}, {"text": "が", "is_correct": false, "explanation": "「証拠が固めれば」は他動詞と合わず、文になりません。"}, {"text": "に", "is_correct": false, "explanation": "「証拠に固めれば」は文として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「証拠と固めれば」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「証拠を固める」と、目的語を示す正しい助詞です。", "が": "「証拠が固めれば」は他動詞と合わず、文になりません。", "に": "「証拠に固めれば」は文として成り立ちません。", "と": "「証拠と固めれば」は文として成り立ちません。"}, "error_tags": {"が": "subject_marker_misuse", "に": "target_marker_misuse", "と": "comitative_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩める", "is_correct": true, "explanation": "しっかりさせず、ゆるくする意味で、「固める」の反対です。"}, {"text": "進める", "is_correct": false, "explanation": "前へ進ませる意味で、反対ではありません。"}, {"text": "集める", "is_correct": false, "explanation": "寄せ集める意味で、反対ではありません。"}, {"text": "数える", "is_correct": false, "explanation": "数を調べる意味で、「固める」とは無関係です。"}], "correct_answer": "緩める", "explanations": {"緩める": "しっかりさせず、ゆるくする意味で、「固める」の反対です。", "進める": "前へ進ませる意味で、反対ではありません。", "集める": "寄せ集める意味で、反対ではありません。", "数える": "数を調べる意味で、「固める」とは無関係です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51966, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事をしっかりとした状態にする。安定させる。また、形を変えにくくする。", "primary_collocate": null, "pronunciation": "かためる", "ipa": "katame̞ɾɯ", "syllable_count": 4, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "固め", "complexity_tier": "T6", "furigana": "初期段階(しょきだんかい)では、投資家(とうしか)からの資金調達(しきんちょうたつ)を通(つう)じて事業(じぎょう)の基盤(きばん)を固(かた)め、市場(しじょう)での急速(きゅうそく)な成長(せいちょう)を目指(めざ)す。", "sentence_source": "mined"}, {"text": "基礎を固める。", "target_word": "固める", "complexity_tier": "T1", "furigana": "基礎(きそ)を固(かた)める。", "sentence_source": "generated"}, {"text": "決意を固めた。", "target_word": "固めた", "complexity_tier": "T1", "furigana": "決意(けつい)を固(かた)めた。", "sentence_source": "generated"}, {"text": "まず足元を固めます。", "target_word": "固めます", "complexity_tier": "T2", "furigana": "まず足元(あしもと)を固(かた)めます。", "sentence_source": "generated"}, {"text": "守りを固めました。", "target_word": "固めました", "complexity_tier": "T2", "furigana": "守(まも)りを固(かた)めました。", "sentence_source": "generated"}, {"text": "会議の前に、計画の内容を固めておく。", "target_word": "固めて", "complexity_tier": "T3", "furigana": "会議(かいぎ)の前(まえ)に、計画(けいかく)の内容(ないよう)を固(かた)めておく。", "sentence_source": "generated"}, {"text": "新しい社長は、会社の体制を固めて、改革を始めた。", "target_word": "固めて", "complexity_tier": "T3", "furigana": "新(あたら)しい社長(しゃちょう)は、会社(かいしゃ)の体制(たいせい)を固(かた)めて、改革(かいかく)を始(はじ)めた。", "sentence_source": "generated"}, {"text": "証拠を固めれば、相手も認めるだろう。", "target_word": "固めれば", "complexity_tier": "T4", "furigana": "証拠(しょうこ)を固(かた)めれば、相手(あいて)も認(みと)めるだろう。", "sentence_source": "generated"}, {"text": "彼は留学する決心を固めたが、親には言えなかった。", "target_word": "固めた", "complexity_tier": "T4", "furigana": "彼(かれ)は留学(りゅうがく)する決心(けっしん)を固(かた)めたが、親(おや)には言(い)えなかった。", "sentence_source": "generated"}, {"text": "選手たちは試合に向けて、守備の連携を固める練習を何度も繰り返した。", "target_word": "固める", "complexity_tier": "T5", "furigana": "選手(せんしゅ)たちは試合(しあい)に向(む)けて、守備(しゅび)の連携(れんけい)を固(かた)める練習(れんしゅう)を何度(なんど)も繰(く)り返(かえ)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "固めて", "label": "活用"}, {"form": "固めた", "label": "活用"}, {"form": "固めない", "label": "活用"}, {"form": "固まる", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物事をしっかり安定した状態にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51966, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "固める", "is_correct": true, "explanation": "「固める」(かためる)が聞こえた語で、正解です。"}, {"text": "偏る", "is_correct": false, "explanation": "「かたよる」は三拍目が「よ」で、「め」と違います。"}, {"text": "掠める", "is_correct": false, "explanation": "「かすめる」は二拍目が「す」で、「た」と違います。"}, {"text": "絡める", "is_correct": false, "explanation": "「からめる」は二拍目が「ら」で、「た」と違います。"}], "explanations": {"固める": "「固める」(かためる)が聞こえた語で、正解です。", "偏る": "「かたよる」は三拍目が「よ」で、「め」と違います。", "掠める": "「かすめる」は二拍目が「す」で、「た」と違います。", "絡める": "「からめる」は二拍目が「ら」で、「た」と違います。"}, "sentence_index": null, "correct_answer": "固める"}, "level_3": {"options": [{"text": "固め", "is_correct": true, "explanation": "基盤をしっかり安定させて成長を目指す、という意味に合います。"}, {"text": "壊し", "is_correct": false, "explanation": "形は合うが、基盤を壊して成長を目指すのは意味が合いません。"}, {"text": "洗い", "is_correct": false, "explanation": "形は合うが、事業の基盤を洗うという意味は合いません。"}, {"text": "折り", "is_correct": false, "explanation": "形は合うが、事業の基盤を折るという意味は合いません。"}], "explanations": {"固め": "基盤をしっかり安定させて成長を目指す、という意味に合います。", "壊し": "形は合うが、基盤を壊して成長を目指すのは意味が合いません。", "洗い": "形は合うが、事業の基盤を洗うという意味は合いません。", "折り": "形は合うが、事業の基盤を折るという意味は合いません。"}, "sentence_index": 0, "correct_answer": "固め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝七時に目を固めます。", "explanation": "「固める」は物をかたくしたり安定させたりすることで、「目」には使えません。"}, {"text": "歌を大きな声で固めます。", "explanation": "「歌」は形のある物ではなく、「固める」の目的語になりません。"}, {"text": "友達の名前を固めて呼びました。", "explanation": "「名前を固める」では、安定させるという意味になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51966, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "固める", "is_correct": true, "explanation": "「固める」(かためる)が聞こえた語で、正解です。"}, {"text": "偏る", "is_correct": false, "explanation": "「かたよる」は三拍目が「よ」で、「め」と違います。"}, {"text": "象る", "is_correct": false, "explanation": "「かたどる」は三拍目が「ど」で、「め」と違います。"}, {"text": "屈める", "is_correct": false, "explanation": "「かがめる」は二拍目が「が」で、「た」と違います。"}], "explanations": {"固める": "「固める」(かためる)が聞こえた語で、正解です。", "偏る": "「かたよる」は三拍目が「よ」で、「め」と違います。", "象る": "「かたどる」は三拍目が「ど」で、「め」と違います。", "屈める": "「かがめる」は二拍目が「が」で、「た」と違います。"}, "sentence_index": null, "correct_answer": "固める"}, "level_3": {"options": [{"text": "固めて", "is_correct": true, "explanation": "会社の体制をしっかり安定させてから改革を始める、という意味に合います。"}, {"text": "折って", "is_correct": false, "explanation": "形は合うが、体制を折るという意味は成り立ちません。"}, {"text": "焼いて", "is_correct": false, "explanation": "形は合うが、体制を焼くという意味は成り立ちません。"}, {"text": "運んで", "is_correct": false, "explanation": "形は合うが、体制を運ぶという意味は成り立ちません。"}], "explanations": {"固めて": "会社の体制をしっかり安定させてから改革を始める、という意味に合います。", "折って": "形は合うが、体制を折るという意味は成り立ちません。", "焼いて": "形は合うが、体制を焼くという意味は成り立ちません。", "運んで": "形は合うが、体制を運ぶという意味は成り立ちません。"}, "sentence_index": 6, "correct_answer": "固めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大声で歌を固める練習をした。", "explanation": "「歌」は形のある物ではないので、「固める」の目的語になりません。"}, {"text": "テレビを固めてから寝た。", "explanation": "「テレビ」には「固める」の意味が当てはまらず、使い方が不自然です。"}, {"text": "昨日の天気は一日中固めていた。", "explanation": "「固める」は他動詞で、天気の状態を表すことはできません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX