INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51966, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は転職する覚悟が固めて、会社に伝えた。", "corrected_sentence": "兄は転職する覚悟を固めて、会社に伝えた。", "error_description": "他動詞「固める」の目的語「覚悟」には、「が」ではなく「を」を使います。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "固める", "is_correct": true, "explanation": "「基礎を固める。」と文を終える終止形で、正解です。"}, {"text": "固めて", "is_correct": false, "explanation": "て形は文が途中で終わってしまい、この位置に合いません。"}, {"text": "固めれば", "is_correct": false, "explanation": "仮定形では「基礎を固めれば。」と文が完結しません。"}, {"text": "固め", "is_correct": false, "explanation": "連用形では「基礎を固め。」と文が終わりません。"}], "correct_form": "固める", "base_form": "固める", "form_label": "終止形", "sentence_index": 1, "explanations": {"固める": "「基礎を固める。」と文を終える終止形で、正解です。", "固めて": "て形は文が途中で終わってしまい、この位置に合いません。", "固めれば": "仮定形では「基礎を固めれば。」と文が完結しません。", "固め": "連用形では「基礎を固め。」と文が終わりません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51966, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察は犯人の証拠を固まって、逮捕した。", "corrected_sentence": "警察は犯人の証拠を固めて、逮捕した。", "error_description": "「証拠を」を受ける他動詞は「固める」で、自動詞の「固まる」は使えません。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "固めれば", "is_correct": true, "explanation": "「ば」で条件を表す仮定形で、「相手も認めるだろう」に自然に続きます。"}, {"text": "固める", "is_correct": false, "explanation": "辞書形では「固める、相手も…」となり、条件の意味が出ません。"}, {"text": "固めた", "is_correct": false, "explanation": "た形では「固めた、相手も認めるだろう」と文がつながりません。"}, {"text": "固めます", "is_correct": false, "explanation": "ます形では「固めます、相手も…」と文がつながりません。"}], "correct_form": "固めれば", "base_form": "固める", "form_label": "仮定形", "sentence_index": 7, "explanations": {"固めれば": "「ば」で条件を表す仮定形で、「相手も認めるだろう」に自然に続きます。", "固める": "辞書形では「固める、相手も…」となり、条件の意味が出ません。", "固めた": "た形では「固めた、相手も認めるだろう」と文がつながりません。", "固めます": "ます形では「固めます、相手も…」と文がつながりません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
