INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51967, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものが十分に育って、しっかりとした状態になること。", "primary_collocate": null, "pronunciation": "せいじゅく", "ipa": "seːdʑɯkɯ", "syllable_count": 4, "sentences": [{"text": "トマトが赤く成熟して、収穫の時期になった。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "この魚は、三年で成熟する。", "target_word": "成熟", "complexity_tier": "T2", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "成熟した果実は、甘い香りがする。", "target_word": "成熟", "complexity_tier": "T2", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "ぶどうが、ゆっくり成熟している。", "target_word": "成熟", "complexity_tier": "T2", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "稲が成熟すると、穂が重く垂れ下がる。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "体が成熟するまで、この薬は使えない。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "木の実の成熟には、十分な日光が必要だ。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "成熟したカエルは、池の外で暮らす。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "動物は、成熟すると子どもを産めるようになる。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "この貝は、二年で成熟して卵を産む。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}], "morphological_forms": [{"form": "成熟する", "label": "活用"}, {"form": "成熟した", "label": "活用"}, {"form": "成熟度", "label": "派生"}, {"form": "成熟期", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 生き物や実が十分に育つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a797ebe1-5b97-4e78-8db1-e79629926289') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51967, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成熟", "is_correct": true, "explanation": "せいじゅく。聞こえた語そのものです。"}, {"text": "制約", "is_correct": false, "explanation": "せいやく。「じゅ」が「や」に変わった別の語です。"}, {"text": "静粛", "is_correct": false, "explanation": "せいしゅく。「じゅ」が「しゅ」に変わった別の語です。"}, {"text": "清純", "is_correct": false, "explanation": "せいじゅん。「く」が「ん」に変わった別の語です。"}, {"text": "正確", "is_correct": false, "explanation": "せいかく。「じゅ」が「か」に変わった別の語です。"}], "explanations": {"成熟": "せいじゅく。聞こえた語そのものです。", "制約": "せいやく。「じゅ」が「や」に変わった別の語です。", "静粛": "せいしゅく。「じゅ」が「しゅ」に変わった別の語です。", "清純": "せいじゅん。「く」が「ん」に変わった別の語です。", "正確": "せいかく。「じゅ」が「か」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "成熟"}, "level_3": {"options": [{"text": "成熟", "is_correct": true, "explanation": "トマトが十分に育つ意味で、収穫の時期と合います。"}, {"text": "到着", "is_correct": false, "explanation": "形は合うが意味が合わない。トマトが赤く到着するとは言えません。"}, {"text": "欠席", "is_correct": false, "explanation": "形は合うが意味が合わない。トマトが赤く欠席するとは言えません。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが意味が合わない。トマトが赤く出発するとは言えません。"}], "explanations": {"成熟": "トマトが十分に育つ意味で、収穫の時期と合います。", "到着": "形は合うが意味が合わない。トマトが赤く到着するとは言えません。", "欠席": "形は合うが意味が合わない。トマトが赤く欠席するとは言えません。", "出発": "形は合うが意味が合わない。トマトが赤く出発するとは言えません。"}, "sentence_index": 0, "correct_answer": "成熟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "氷がゆっくり成熟して、水になった。", "explanation": "「成熟」を「溶ける」の意味で使っており、誤りです。"}, {"text": "彼は毎朝、公園を成熟している。", "explanation": "「成熟」を「散歩する」の意味で使っており、誤りです。"}, {"text": "電車が遅れて、駅で一時間も成熟している。", "explanation": "「成熟」を「待つ」の意味で使っており、誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
