INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51968, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未熟", "is_correct": true, "explanation": "十分に発達していないことで、「成熟」の反対です。"}, {"text": "円熟", "is_correct": false, "explanation": "十分に熟達することで、「成熟」に近い意味です。"}, {"text": "旅行", "is_correct": false, "explanation": "旅をすることで、反対の関係ではありません。"}, {"text": "約束", "is_correct": false, "explanation": "取り決めることで、反対の関係ではありません。"}], "correct_answer": "未熟", "explanations": {"未熟": "十分に発達していないことで、「成熟」の反対です。", "円熟": "十分に熟達することで、「成熟」に近い意味です。", "旅行": "旅をすることで、反対の関係ではありません。", "約束": "取り決めることで、反対の関係ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51968, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事が十分に発達して、安定した状態に達すること。", "primary_collocate": null, "pronunciation": "せいじゅく", "ipa": "seːdʑɯkɯ", "syllable_count": 4, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "成熟", "complexity_tier": "T6", "furigana": "せいじゅく", "sentence_source": "mined"}, {"text": "この市場は、すでに成熟した段階に入っている。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "社会が成熟するにつれて、人々の考え方も変わる。", "target_word": "成熟", "complexity_tier": "T4", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "成熟した民主主義には、多様な意見を認める力がある。", "target_word": "成熟", "complexity_tier": "T4", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "産業の成熟とともに、新しい競争が生まれた。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "彼の技術は、長い経験を経て成熟した。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "組織の成熟には、長い時間と多くの経験が必要だ。", "target_word": "成熟", "complexity_tier": "T3", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "この国の経済は成熟しており、急な成長は期待できない。", "target_word": "成熟", "complexity_tier": "T4", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "成熟したチームは、問題が起きても落ち着いて対応する。", "target_word": "成熟", "complexity_tier": "T4", "furigana": "せいじゅく", "sentence_source": "generated"}, {"text": "ファンの文化が成熟して、質の高い作品が増えた。", "target_word": "成熟", "complexity_tier": "T4", "furigana": "せいじゅく", "sentence_source": "generated"}], "morphological_forms": [{"form": "成熟する", "label": "活用"}, {"form": "成熟した", "label": "活用"}, {"form": "成熟度", "label": "派生"}, {"form": "成熟期", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が十分発達し安定すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: エグジット (Zipf 1.27)']::text[], 'a797ebe1-5b97-4e78-8db1-e79629926289') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51968, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成熟", "is_correct": true, "explanation": "せいじゅく。聞こえた語そのものです。"}, {"text": "制約", "is_correct": false, "explanation": "せいやく。「じゅ」が「や」に変わった別の語です。"}, {"text": "静粛", "is_correct": false, "explanation": "せいしゅく。「じゅ」が「しゅ」に変わった別の語です。"}, {"text": "清純", "is_correct": false, "explanation": "せいじゅん。「く」が「ん」に変わった別の語です。"}, {"text": "正確", "is_correct": false, "explanation": "せいかく。「じゅ」が「か」に変わった別の語です。"}], "explanations": {"成熟": "せいじゅく。聞こえた語そのものです。", "制約": "せいやく。「じゅ」が「や」に変わった別の語です。", "静粛": "せいしゅく。「じゅ」が「しゅ」に変わった別の語です。", "清純": "せいじゅん。「く」が「ん」に変わった別の語です。", "正確": "せいかく。「じゅ」が「か」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "成熟"}, "level_3": {"options": [{"text": "成熟", "is_correct": true, "explanation": "企業が十分に発達して安定する意味で、文脈に合います。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが意味が合わない。企業が出発すると出口戦略は選びません。"}, {"text": "反省", "is_correct": false, "explanation": "形は合うが意味が合わない。企業が反省すると出口戦略へ続きません。"}, {"text": "到着", "is_correct": false, "explanation": "形は合うが意味が合わない。企業が到着するとは言えません。"}], "explanations": {"成熟": "企業が十分に発達して安定する意味で、文脈に合います。", "出発": "形は合うが意味が合わない。企業が出発すると出口戦略は選びません。", "反省": "形は合うが意味が合わない。企業が反省すると出口戦略へ続きません。", "到着": "形は合うが意味が合わない。企業が到着するとは言えません。"}, "sentence_index": 0, "correct_answer": "成熟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝から何も食べていないので、おなかが成熟した。", "explanation": "「成熟」を「空腹になる」の意味で使っており、誤りです。"}, {"text": "毎朝、駅まで自転車で成熟している。", "explanation": "「成熟」を「通う」の意味で使っており、誤りです。"}, {"text": "この机は成熟が重いので、一人では運べない。", "explanation": "「成熟」を「重さ」の意味で使っており、誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51968, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成熟", "is_correct": true, "explanation": "せいじゅく。聞こえた語そのものです。"}, {"text": "声楽", "is_correct": false, "explanation": "せいがく。「じゅ」が「が」に変わった別の語です。"}, {"text": "聖職", "is_correct": false, "explanation": "せいしょく。「じゅ」が「しょ」に変わった別の語です。"}, {"text": "生息", "is_correct": false, "explanation": "せいそく。「じゅ」が「そ」に変わった別の語です。"}, {"text": "精読", "is_correct": false, "explanation": "せいどく。「じゅ」が「ど」に変わった別の語です。"}], "explanations": {"成熟": "せいじゅく。聞こえた語そのものです。", "声楽": "せいがく。「じゅ」が「が」に変わった別の語です。", "聖職": "せいしょく。「じゅ」が「しょ」に変わった別の語です。", "生息": "せいそく。「じゅ」が「そ」に変わった別の語です。", "精読": "せいどく。「じゅ」が「ど」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "成熟"}, "level_3": {"options": [{"text": "成熟", "is_correct": true, "explanation": "十分に発達するには時間と経験が要る、という意味で合います。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが意味が合わない。洗濯に長い時間と多くの経験は必要ありません。"}, {"text": "挨拶", "is_correct": false, "explanation": "形は合うが意味が合わない。挨拶に長い時間と経験は必要ありません。"}, {"text": "停電", "is_correct": false, "explanation": "形は合うが意味が合わない。停電に経験は必要ありません。"}], "explanations": {"成熟": "十分に発達するには時間と経験が要る、という意味で合います。", "洗濯": "形は合うが意味が合わない。洗濯に長い時間と多くの経験は必要ありません。", "挨拶": "形は合うが意味が合わない。挨拶に長い時間と経験は必要ありません。", "停電": "形は合うが意味が合わない。停電に経験は必要ありません。"}, "sentence_index": 6, "correct_answer": "成熟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅で友達を成熟して、一緒に出発した。", "explanation": "「成熟」を「待つ」の意味で使っており、誤りです。"}, {"text": "雨が強くて、試合が成熟された。", "explanation": "「成熟」を「中止する」の意味で使っており、誤りです。"}, {"text": "暑い日は、アイスが成熟して手についた。", "explanation": "「成熟」を「溶ける」の意味で使っており、誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version,