INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51968, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この業界はすでに成熟を達しており、成長は遅い。", "corrected_sentence": "この業界はすでに成熟に達しており、成長は遅い。", "error_description": "「達する」は「成熟に」と「に」を取ります。「を」は誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51968, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の判断力は、経験とともに成熟になった。", "corrected_sentence": "彼の判断力は、経験とともに成熟した。", "error_description": "「成熟」は「する」と結びつきます。「成熟になる」は誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51970, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「支払う」の目的語を表す「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「対価が支払う」は他動詞の目的語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「対価へ支払う」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「対価と支払う」は目的語として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「支払う」の目的語を表す「を」が正しい。", "が": "「対価が支払う」は他動詞の目的語として成り立たない。", "へ": "「へ」は方向を表し、「対価へ支払う」は成り立たない。", "と": "「対価と支払う」は目的語として成り立たない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51970, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51970, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするために支払う代償や、その見返りとして得られる利益。特に、投資や取引において、相手に提供する金銭や価値。", "primary_collocate": null, "pronunciation": "たいか", "ipa": "taika", "syllable_count": 3, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "対価", "complexity_tier": "T6", "furigana": "たいか", "sentence_source": "mined"}, {"text": "会社は、社員の働きに見合った対価を支払う。", "target_word": "対価", "complexity_tier": "T3", "furigana": "たいか", "sentence_source": "generated"}, {"text": "サービスの対価として、利用料を受け取る。", "target_word": "対価", "complexity_tier": "T3", "furigana": "たいか", "sentence_source": "generated"}, {"text": "技術を提供する対価に、株式を要求した。", "target_word": "対価", "complexity_tier": "T3", "furigana": "たいか", "sentence_source": "generated"}, {"text": "投資家は、資金の対価として利益を期待する。", "target_word": "対価", "complexity_tier": "T3", "furigana": "たいか", "sentence_source": "generated"}, {"text": "労働の対価が低すぎると、不満が出る。", "target_word": "対価", "complexity_tier": "T3", "furigana": "たいか", "sentence_source": "generated"}, {"text": "対価は、契約を結ぶ前に決めておくべきだ。", "target_word": "対価", "complexity_tier": "T3", "furigana": "たいか", "sentence_source": "generated"}, {"text": "土地を売った対価で、新しい事業を始めた。", "target_word": "対価", "complexity_tier": "T3", "furigana": "たいか", "sentence_source": "generated"}, {"text": "情報の対価として、高額な料金が請求された。", "target_word": "対価", "complexity_tier": "T3", "furigana": "たいか", "sentence_source": "generated"}, {"text": "この取引で、相手は十分な対価を得られなかった。", "target_word": "対価", "complexity_tier": "T4", "furigana": "たいか", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 取引で払う代償や見返り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: エグジット (Zipf 1.27)']::text[], 'a797ebe1-5b97-4e78-8db1-e79629926289') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51970, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "対価", "is_correct": true, "explanation": "見出し語の「たいか」。"}, {"text": "大気", "is_correct": false, "explanation": "「たいき」で、最後の拍が か→き と異なる。"}, {"text": "大河", "is_correct": false, "explanation": "「たいが」で、か→が の清濁だけが異なる。"}, {"text": "太鼓", "is_correct": false, "explanation": "「たいこ」で、最後の拍が か→こ と異なる。"}, {"text": "対話", "is_correct": false, "explanation": "「たいわ」で、最後の拍が か→わ と異なる。"}], "explanations": {"対価": "見出し語の「たいか」。", "大気": "「たいき」で、最後の拍が か→き と異なる。", "大河": "「たいが」で、か→が の清濁だけが異なる。", "太鼓": "「たいこ」で、最後の拍が か→こ と異なる。", "対話": "「たいわ」で、最後の拍が か→わ と異なる。"}, "sentence_index": null, "correct_answer": "対価"}, "level_3": {"options": [{"text": "対価", "is_correct": true, "explanation": "投資の見返りとして得るものを表し、文脈に合う。"}, {"text": "負債", "is_correct": false, "explanation": "形は合うが、負債は「得るために」エグジットを選ぶ見返りという意味に合わない。"}, {"text": "欠点", "is_correct": false, "explanation": "形は合うが、欠点を得るために出口戦略を選ぶという意味が合わない。"}, {"text": "災害", "is_correct": false, "explanation": "形は合うが、災害を投資して得るという意味が合わない。"}], "explanations": {"対価": "投資の見返りとして得るものを表し、文脈に合う。", "負債": "形は合うが、負債は「得るために」エグジットを選ぶ見返りという意味に合わない。", "欠点": "形は合うが、欠点を得るために出口戦略を選ぶという意味が合わない。", "災害": "形は合うが、災害を投資して得るという意味が合わない。"}, "sentence_index": 0, "correct_answer": "対価"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、対価を飲んでから会社に行く。", "explanation": "対価は支払う・得るものであり、「飲む」ものではないので、目的語として誤用。"}, {"text": "今日の天気は対価で、一日中雨が降った。", "explanation": "対価は天気の状態を表す語ではなく、意味を取り違えた誤用。"}, {"text": "雨が降ってきたので、対価をさして歩いた。", "explanation": "対価は傘のような物ではないので、「さす」の目的語にならない誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUD