INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51972, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "他の会社。別の企業。", "primary_collocate": null, "pronunciation": "たしゃ", "ipa": "taɕa", "syllable_count": 2, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "他社", "complexity_tier": "T6", "furigana": "たしゃ", "sentence_source": "mined"}, {"text": "他社の製品と比べて、価格が低い。", "target_word": "他社", "complexity_tier": "T2", "furigana": "たしゃ", "sentence_source": "generated"}, {"text": "当社は、他社にはない技術を持っている。", "target_word": "他社", "complexity_tier": "T3", "furigana": "たしゃ", "sentence_source": "generated"}, {"text": "他社との競争が、年々激しくなっている。", "target_word": "他社", "complexity_tier": "T3", "furigana": "たしゃ", "sentence_source": "generated"}, {"text": "他社に先を越されないよう、開発を急いだ。", "target_word": "他社", "complexity_tier": "T3", "furigana": "たしゃ", "sentence_source": "generated"}, {"text": "他社が新しいサービスを始めたと聞いた。", "target_word": "他社", "complexity_tier": "T3", "furigana": "たしゃ", "sentence_source": "generated"}, {"text": "彼は他社に引き抜かれて、転職した。", "target_word": "他社", "complexity_tier": "T3", "furigana": "たしゃ", "sentence_source": "generated"}, {"text": "他社の動きを調べるのも、重要な仕事だ。", "target_word": "他社", "complexity_tier": "T3", "furigana": "たしゃ", "sentence_source": "generated"}, {"text": "他社と提携すれば、新しい市場に参入できる。", "target_word": "他社", "complexity_tier": "T3", "furigana": "たしゃ", "sentence_source": "generated"}, {"text": "他社より早く、新製品を市場に出した。", "target_word": "他社", "complexity_tier": "T3", "furigana": "たしゃ", "sentence_source": "generated"}], "morphological_forms": [{"form": "他社製", "label": "派生"}, {"form": "他社製品", "label": "派生"}, {"form": "他社比", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 競争相手など別の企業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: エグジット (Zipf 1.27)']::text[], 'a797ebe1-5b97-4e78-8db1-e79629926289') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51972, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "他社", "is_correct": true, "explanation": "見出し語の「たしゃ」。"}, {"text": "医者", "is_correct": false, "explanation": "「いしゃ」で、最初の拍が た→い と異なる。"}, {"text": "貨車", "is_correct": false, "explanation": "「かしゃ」で、最初の拍が た→か と異なる。"}, {"text": "覇者", "is_correct": false, "explanation": "「はしゃ」で、最初の拍が た→は と異なる。"}], "explanations": {"他社": "見出し語の「たしゃ」。", "医者": "「いしゃ」で、最初の拍が た→い と異なる。", "貨車": "「かしゃ」で、最初の拍が た→か と異なる。", "覇者": "「はしゃ」で、最初の拍が た→は と異なる。"}, "sentence_index": null, "correct_answer": "他社"}, "level_3": {"options": [{"text": "他社", "is_correct": true, "explanation": "別の会社による買収という意味で文脈に合う。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、地震による買収という意味が合わない。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、台風による買収という意味が合わない。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが、病気による買収という意味が合わない。"}], "explanations": {"他社": "別の会社による買収という意味で文脈に合う。", "地震": "形は合うが、地震による買収という意味が合わない。", "台風": "形は合うが、台風による買収という意味が合わない。", "病気": "形は合うが、病気による買収という意味が合わない。"}, "sentence_index": 0, "correct_answer": "他社"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他社の気持ちを考えて、やさしく話しかけた。", "explanation": "「他社」は他の会社であり、他の人を表す「他者」の意味で使った誤用。"}, {"text": "この町には、他社が三人住んでいる。", "explanation": "「他社」は会社を指すので、人数を数えて住むという使い方は誤り。"}, {"text": "他社を食べるために、レストランへ行った。", "explanation": "他の会社は食べ物ではないので、「食べる」の対象にならない誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bbf27a8-1ec1-4674-9c90-ba0a306da972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch