INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51973, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「買収の話」で、買収と話をつなぎます。"}, {"text": "を", "is_correct": false, "explanation": "「買収を話を聞きました」は助詞が重なり、非文です。"}, {"text": "へ", "is_correct": false, "explanation": "「買収へ話を聞きました」は意味がつながりません。"}, {"text": "ずつ", "is_correct": false, "explanation": "「買収ずつ」は名詞に付けられず、非文です。"}], "correct_answer": "の", "explanations": {"の": "「買収の話」で、買収と話をつなぎます。", "を": "「買収を話を聞きました」は助詞が重なり、非文です。", "へ": "「買収へ話を聞きました」は意味がつながりません。", "ずつ": "「買収ずつ」は名詞に付けられず、非文です。"}, "error_tags": {"を": "object_marker", "へ": "direction", "ずつ": "distribution"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "売却", "is_correct": true, "explanation": "会社を買い取る買収に対し、売却は手放す側で反対です。"}, {"text": "設立", "is_correct": false, "explanation": "設立は会社を新しく作ることで、買収の反対ではありません。"}, {"text": "経営", "is_correct": false, "explanation": "経営は会社を運営することで、買収の反対ではありません。"}, {"text": "成長", "is_correct": false, "explanation": "成長は大きくなることで、買収の反対ではありません。"}], "correct_answer": "売却", "explanations": {"売却": "会社を買い取る買収に対し、売却は手放す側で反対です。", "設立": "設立は会社を新しく作ることで、買収の反対ではありません。", "経営": "経営は会社を運営することで、買収の反対ではありません。", "成長": "成長は大きくなることで、買収の反対ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
