INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51973, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "会社などをお金で手に入れることです。", "primary_collocate": null, "pronunciation": "ばいしゅう", "ipa": "baiɕɯː", "syllable_count": 4, "sentences": [{"text": "会社を買収した。", "target_word": "買収", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "あの店は買収されました。", "target_word": "買収", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "買収の話を聞きました。", "target_word": "買収", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大きな会社が小さな会社を買収します。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "買収にはたくさんのお金が必要だ。", "target_word": "買収", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "買収のニュースに、みんなが驚いた。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社長は買収を断ることにした。", "target_word": "買収", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "買収が終わって、会社の名前が変わった。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この買収で、会社は二倍の大きさになった。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会社を買収するために、銀行からお金を借りた。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "買収する", "label": "活用"}, {"form": "買収した", "label": "活用"}, {"form": "買収される", "label": "活用"}, {"form": "買収額", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 会社をお金で手に入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_ve