INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51974, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他の会社の株や事業を、お金を払って自分のものにすること。", "primary_collocate": null, "pronunciation": "ばいしゅう", "ipa": "baiɕɯː", "syllable_count": 4, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "買収", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "大手企業が小さな会社を買収する。", "target_word": "買収", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "その買収には百億円かかった。", "target_word": "買収", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "ライバル社に買収されて、社名が変わった。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "買収の発表を受けて、株価が大きく上がった。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼らは敵対的な買収を警戒している。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "買収が成立すれば、二社は一つになる。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "経営陣は買収の条件について話し合った。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "買収された会社の社員は不安を感じた。", "target_word": "買収", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新しい技術を手に入れるため、その会社の買収を決めた。", "target_word": "買収", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "買収する", "label": "活用"}, {"form": "買収した", "label": "活用"}, {"form": "買収される", "label": "活用"}, {"form": "買収額", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 他社を金で買い取り支配下に置くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: エグジット (Zipf 1.27)']::text[], '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51974, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "買収", "is_correct": true, "explanation": "「ばいしゅう」で、会社を買い取る意味の見出し語そのものです。"}, {"text": "回収", "is_correct": false, "explanation": "「かいしゅう」で、最初の音が「ば」ではなく「か」です。"}, {"text": "毎週", "is_correct": false, "explanation": "「まいしゅう」で、最初の音が「ば」ではなく「ま」です。"}, {"text": "賠償", "is_correct": false, "explanation": "「ばいしょう」で、三音目が「しゅ」ではなく「しょ」です。"}], "explanations": {"買収": "「ばいしゅう」で、会社を買い取る意味の見出し語そのものです。", "回収": "「かいしゅう」で、最初の音が「ば」ではなく「か」です。", "毎週": "「まいしゅう」で、最初の音が「ば」ではなく「ま」です。", "賠償": "「ばいしょう」で、三音目が「しゅ」ではなく「しょ」です。"}, "sentence_index": null, "correct_answer": "買収"}, "level_3": {"options": [{"text": "買収", "is_correct": true, "explanation": "他社による買収は株式上場と並ぶ出口戦略なので、意味が合います。"}, {"text": "訴訟", "is_correct": false, "explanation": "形は合うが意味が合わない。訴訟は出口戦略ではありません。"}, {"text": "宣伝", "is_correct": false, "explanation": "形は合うが意味が合わない。宣伝は投資の対価を得る手段ではありません。"}, {"text": "調査", "is_correct": false, "explanation": "形は合うが意味が合わない。調査は株式上場のような出口ではありません。"}], "explanations": {"買収": "他社による買収は株式上場と並ぶ出口戦略なので、意味が合います。", "訴訟": "形は合うが意味が合わない。訴訟は出口戦略ではありません。", "宣伝": "形は合うが意味が合わない。宣伝は投資の対価を得る手段ではありません。", "調査": "形は合うが意味が合わない。調査は株式上場のような出口ではありません。"}, "sentence_index": 0, "correct_answer": "買収"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅の売店で飲み物を買収した。", "explanation": "「買収」は会社や事業を買い取ることで、飲み物を買う意味には使えません。"}, {"text": "母は商店街で新鮮な野菜を買収した。", "explanation": "「買収」を日用品の購入の意味で使っており、会社を買い取る意味から外れています。"}, {"text": "誕生日に、友達へのプレゼントを買収した。", "explanation": "プレゼントは「買収」の対象にならず、「買う」とすべきところを誤用しています。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51974, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "買収", "is_correct": true, "explanation": "「ばいしゅう」で、見出し語そのものです。"}, {"text": "来週", "is_correct": false, "explanation": "「らいしゅう」で、最初の音が「ば」ではなく「ら」です。"}, {"text": "最終", "is_correct": false, "explanation": "「さいしゅう」で、最初の音が「ば」ではなく「さ」です。"}, {"text": "税収", "is_correct": false, "explanation": "「ぜいしゅう」で、最初の音が「ば」ではなく「ぜ」です。"}, {"text": "大衆", "is_correct": false, "explanation": "「たいしゅう」で、最初の音が「ば」ではなく「た」です。"}], "explanations": {"買収": "「ばいしゅう」で、見出し語そのものです。", "来週": "「らいしゅう」で、最初の音が「ば」ではなく「ら」です。", "最終": "「さいしゅう」で、最初の音が「ば」ではなく「さ」です。", "税収": "「ぜいしゅう」で、最初の音が「ば」ではなく「ぜ」です。", "大衆": "「たいしゅう」で、最初の音が「ば」ではなく「た」です。"}, "sentence_index": null, "correct_answer": "買収"}, "level_3": {"options": [{"text": "買収", "is_correct": true, "explanation": "買収が成立すると二つの会社が一つになるので、意味が合います。"}, {"text": "競争", "is_correct": false, "explanation": "形は合うが意味が合わない。競争が成立しても会社は一つになりません。"}, {"text": "輸出", "is_correct": false, "explanation": "形は合うが意味が合わない。輸出が成立しても会社は一つになりません。"}, {"text": "宣伝", "is_correct": false, "explanation": "形は合うが意味が合わない。宣伝が成立しても二社は一つになりません。"}], "explanations": {"買収": "買収が成立すると二つの会社が一つになるので、意味が合います。", "競争": "形は合うが意味が合わない。競争が成立しても会社は一つになりません。", "輸出": "形は合うが意味が合わない。輸出が成立しても会社は一つになりません。", "宣伝": "形は合うが意味が合わない。宣伝が成立しても二社は一つになりません。"}, "sentence_index": 6, "correct_answer": "買収"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この時計は去年、デパートで買収されたものだ。", "explanation": "「買収」は会社を買い取る意味で、時計を買う意味には使えません。"}, {"text": "弟はおこづかいでゲームを買収した。", "explanation": "ゲームの購入に「買収」を使っており、対象が会社や事業ではありません。"}, {"text": "私は雨の日に傘を買収して帰った。", "explanation": "傘は「買収」の対象にならず、「買う」とすべきところの誤用です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EX