INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51975, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しい会社や仕事を始めること。", "primary_collocate": null, "pronunciation": "そうぎょう", "ipa": "soːɡjoː", "syllable_count": 4, "sentences": [{"text": "私は去年、店を創業した。", "target_word": "創業", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "創業の日をお祝いした。", "target_word": "創業", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父は小さな会社を創業した。", "target_word": "創業", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "創業したばかりの店は、お客さんが少ない。", "target_word": "創業", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "創業にはお金と時間が必要だ。", "target_word": "創業", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この会社は十年前に創業された。", "target_word": "創業", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "祖母は、この店を創業したときの話をしてくれた。", "target_word": "創業", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼は二十歳で創業するつもりだ。", "target_word": "創業", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "創業から一年たって、店は人気になった。", "target_word": "創業", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "創業した日のことを、今でも覚えている。", "target_word": "創業", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "創業する", "label": "活用"}, {"form": "創業した", "label": "活用"}, {"form": "創業される", "label": "活用"}, {"form": "創業者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 新しい会社や仕事を始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt