INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51976, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「会社を創業する」で、創業の対象を示します。"}, {"text": "に", "is_correct": false, "explanation": "「会社に創業したとき」は対象を示せず、非文です。"}, {"text": "へ", "is_correct": false, "explanation": "「会社へ創業したとき」は方向の助詞で、非文です。"}, {"text": "と", "is_correct": false, "explanation": "「会社と創業したとき」は意味がつながらず、非文です。"}], "correct_answer": "を", "explanations": {"を": "「会社を創業する」で、創業の対象を示します。", "に": "「会社に創業したとき」は対象を示せず、非文です。", "へ": "「会社へ創業したとき」は方向の助詞で、非文です。", "と": "「会社と創業したとき」は意味がつながらず、非文です。"}, "error_tags": {"に": "target_marker", "へ": "direction", "と": "companion"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "廃業", "is_correct": true, "explanation": "資金を集めて始める創業に対し、廃業は事業をやめることで反対です。"}, {"text": "投資", "is_correct": false, "explanation": "投資はお金を出すことで、創業の反対ではありません。"}, {"text": "販売", "is_correct": false, "explanation": "販売は物を売ることで、創業の反対ではありません。"}, {"text": "会議", "is_correct": false, "explanation": "会議は話し合いのことで、創業の反対ではありません。"}], "correct_answer": "廃業", "explanations": {"廃業": "資金を集めて始める創業に対し、廃業は事業をやめることで反対です。", "投資": "投資はお金を出すことで、創業の反対ではありません。", "販売": "販売は物を売ることで、創業の反対ではありません。", "会議": "会議は話し合いのことで、創業の反対ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51976, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "事業や組織を新しく始めること。", "primary_collocate": null, "pronunciation": "そうぎょう", "ipa": "soːɡjoː", "syllable_count": 4, "sentences": [{"text": "スタートアップは、革新的なアイデアを種として創業される。", "target_word": "創業", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "創業", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "祖父は戦後すぐにこの会社を創業した。", "target_word": "創業", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "創業から百年を迎える老舗だ。", "target_word": "創業", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "創業の理念を大切に守っている。", "target_word": "創業", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼女は大学在学中に創業を決意した。", "target_word": "創業", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "創業して三年で、会社は黒字になった。", "target_word": "創業", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会社を創業したとき、社員は三人だけだった。", "target_word": "創業", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "この店は江戸時代に創業された。", "target_word": "創業", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "創業するには、まず資金を集めなければならない。", "target_word": "創業", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "創業する", "label": "活用"}, {"form": "創業した", "label": "活用"}, {"form": "創業される", "label": "活用"}, {"form": "創業者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 事業や組織を新しく始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: エグジット (Zipf 1.27)']::text[], '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51976, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "創業", "is_correct": true, "explanation": "「そうぎょう」で、見出し語そのものです。"}, {"text": "工業", "is_correct": false, "explanation": "「こうぎょう」で、最初の音が「そ」ではなく「こ」です。"}, {"text": "農業", "is_correct": false, "explanation": "「のうぎょう」で、最初の音が「そ」ではなく「の」です。"}, {"text": "同業", "is_correct": false, "explanation": "「どうぎょう」で、最初の音が「そ」ではなく「ど」です。"}, {"text": "商業", "is_correct": false, "explanation": "「しょうぎょう」で、最初の音が「そ」ではなく「しょ」です。"}], "explanations": {"創業": "「そうぎょう」で、見出し語そのものです。", "工業": "「こうぎょう」で、最初の音が「そ」ではなく「こ」です。", "農業": "「のうぎょう」で、最初の音が「そ」ではなく「の」です。", "同業": "「どうぎょう」で、最初の音が「そ」ではなく「ど」です。", "商業": "「しょうぎょう」で、最初の音が「そ」ではなく「しょ」です。"}, "sentence_index": null, "correct_answer": "創業"}, "level_3": {"options": [{"text": "創業", "is_correct": true, "explanation": "アイデアを種に会社が始められる、という意味に合います。"}, {"text": "輸入", "is_correct": false, "explanation": "形は合うが意味が合わない。スタートアップは輸入されるものではありません。"}, {"text": "翻訳", "is_correct": false, "explanation": "形は合うが意味が合わない。スタートアップは翻訳されるものではありません。"}, {"text": "解散", "is_correct": false, "explanation": "形は合うが意味が合わない。アイデアを種として解散されるとは言えません。"}], "explanations": {"創業": "アイデアを種に会社が始められる、という意味に合います。", "輸入": "形は合うが意味が合わない。スタートアップは輸入されるものではありません。", "翻訳": "形は合うが意味が合わない。スタートアップは翻訳されるものではありません。", "解散": "形は合うが意味が合わない。アイデアを種として解散されるとは言えません。"}, "sentence_index": 0, "correct_answer": "創業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝七時に創業して、学校へ行った。", "explanation": "「創業」は事業を新しく始めることで、一日の活動を始める意味には使えません。"}, {"text": "映画は午後三時に創業する予定です。", "explanation": "映画の開始に「創業」を使っており、「始まる」の意味を取り違えています。"}, {"text": "新しいアパートを創業して、引っ越した。", "explanation": "アパートを借りる意味に「創業」を使っており、事業を始める意味ではないので誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51976, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "創業", "is_correct": true, "explanation": "「そうぎょう」で、見出し語そのものです。"}, {"text": "早朝", "is_correct": false, "explanation": "「そうちょう」で、三音目が「ぎょ」ではなく「ちょ」です。"}, {"text": "総称", "is_correct": false, "explanation": "「そうしょう」で、三音目が「ぎょ」ではなく「しょ」です。"}, {"text": "送料", "is_correct": false, "explanation": "「そうりょう」で、三音目が「ぎょ」ではなく「りょ」です。"}, {"text": "協業", "is_correct": false, "explanation": "「きょうぎょう」で、最初の音が「そ」ではなく「きょ」です。"}], "explanations": {"創業": "「そうぎょう」で、見出し語そのものです。", "早朝": "「そうちょう」で、三音目が「ぎょ」ではなく「ちょ」です。", "総称": "「そうしょう」で、三音目が「ぎょ」ではなく「しょ」です。", "送料": "「そうりょう」で、三音目が「ぎょ」ではなく「りょ」です。", "協業": "「きょうぎょう」で、最初の音が「そ」ではなく「きょ」です。"}, "sentence_index": null, "correct_answer": "創業"}, "level_3": {"options": [{"text": "創業", "is_correct": true, "explanation": "会社を始めて三年で黒字になった、という意味に合います。"}, {"text": "入院", "is_correct": false, "explanation": "形は合うが意味が合わない。入院して三年で会社が黒字になるとは言えません。"}, {"text": "旅行", "is_correct": false, "explanation": "形は合うが意味が合わない。旅行と会社の黒字は結びつきません。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが意味が合わない。運転して三年で会社が黒字になるとは言えません。"}], "explanations": {"創業": "会社を始めて三年で黒字になった、という意味に合います。", "入院": "形は合うが意味が合わない。入院して三年で会社が黒字になるとは言えません。", "旅行": "形は合うが意味が合わない。旅行と会社の黒字は結びつきません。", "運転": "形は合うが意味が合わない。運転して三年で会社が黒字になるとは言えません。"}, "sentence_index": 6, "correct_answer": "創業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝六時に創業して、犬と散歩に出かけた。", "explanation": "「創業」は事業を始めることで、起きて活動を始める意味には使えません。"}, {"text": "会議は十時に創業するので、急いでください。", "explanation": "会議の開始に「創業」を使っており、「始まる」の意味を取り違えています。"}, {"text": "彼は新しい家を創業して、家族と住んでいる。", "explanation": "家を建てる意味に「創業」を使っており、事業を始める意味ではないので誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUD