INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51977, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "会社の一部で、お金を出して買えるものです。", "primary_collocate": null, "pronunciation": "かぶしき", "ipa": "kabɯɕiki", "syllable_count": 4, "sentences": [{"text": "株式を買いました。", "target_word": "株式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "株式は会社の一部だ。", "target_word": "株式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "兄は株式をたくさん持っている。", "target_word": "株式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "株式の値段は毎日変わる。", "target_word": "株式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "この会社の株式を、百株持っている。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "株式を買うと、会社の一部の持ち主になれる。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母は株式の勉強を始めました。", "target_word": "株式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "株式で、お金が増えることも減ることもある。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "株式を売って、新しい車を買った。", "target_word": "株式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "いい会社の株式は、人気があって高い。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "株式会社", "label": "派生"}, {"form": "株式市場", "label": "派生"}, {"form": "株式投資", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 会社の一部で買えるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, 