INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51977, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "株式", "is_correct": true, "explanation": "お金を出して買える会社の一部なので「買いました」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は買えない。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが意味が合わない。昨日は買うものではない。"}, {"text": "雨", "is_correct": false, "explanation": "形は合うが意味が合わない。雨は買えない。"}], "explanations": {"株式": "お金を出して買える会社の一部なので「買いました」に合う。", "天気": "形は合うが意味が合わない。天気は買えない。", "昨日": "形は合うが意味が合わない。昨日は買うものではない。", "雨": "形は合うが意味が合わない。雨は買えない。"}, "sentence_index": 0, "correct_answer": "株式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに株式を食べました。", "explanation": "株式は会社の一部を買う証券で、食べ物ではない。"}, {"text": "株式は雨の日に空から降ってくる。", "explanation": "株式は天気のように降るものではなく、お金を出して買うものである。"}, {"text": "兄は株式の中で泳いでいる。", "explanation": "株式は場所ではないので、「中で泳ぐ」と使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51977, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "株式", "is_correct": true, "explanation": "株式は勉強の対象になるので意味が合う。"}, {"text": "まばたき", "is_correct": false, "explanation": "形は合うが意味が合わない。まばたきは勉強するものではない。"}, {"text": "青空", "is_correct": false, "explanation": "形は合うが意味が合わない。青空の勉強を始めるとは言わない。"}, {"text": "くしゃみ", "is_correct": false, "explanation": "形は合うが意味が合わない。くしゃみの勉強を始めるとは言わない。"}], "explanations": {"株式": "株式は勉強の対象になるので意味が合う。", "まばたき": "形は合うが意味が合わない。まばたきは勉強するものではない。", "青空": "形は合うが意味が合わない。青空の勉強を始めるとは言わない。", "くしゃみ": "形は合うが意味が合わない。くしゃみの勉強を始めるとは言わない。"}, "sentence_index": 6, "correct_answer": "株式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "株式を飲むと、元気になる。", "explanation": "株式は証券で、飲むものではない。"}, {"text": "私の部屋には大きい株式が三つある。", "explanation": "株式を家具のような物として数えており、証券という意味に合わない。"}, {"text": "株式は犬の一部だ。", "explanation": "株式は会社の一部であり、犬の一部ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
