INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51978, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "企業が資金調達のために発行する証券。株主は企業の所有権の一部を持つ。", "primary_collocate": null, "pronunciation": "かぶしき", "ipa": "kabɯɕiki", "syllable_count": 4, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "株式", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "会社は株式を発行して資金を集めた。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "株式の一部を売って、利益を得た。", "target_word": "株式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "株式の価格は朝から大きく動いた。", "target_word": "株式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "彼は多くの株式を保有している。", "target_word": "株式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "株式を持つ人は、会社の所有者の一人になる。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "株式による資金調達には、利点と危険がある。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "親会社が子会社の株式をすべて取得した。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "株式の売買は、証券会社を通して行う。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "配当は、株式の数に応じて支払われる。", "target_word": "株式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "株式会社", "label": "派生"}, {"form": "株式市場", "label": "派生"}, {"form": "株式投資", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 資金調達のために発行する証券", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: エグジット (Zipf 1.27)']::text[], '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51978, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "株式", "is_correct": true, "explanation": "「株式上場」で、企業が出口戦略として選ぶ上場の対象を表すので意味が合う。"}, {"text": "土地", "is_correct": false, "explanation": "形は合うが意味が合わない。「土地上場」という言い方はなく、出口戦略にもならない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は上場の対象にならない。"}, {"text": "料理", "is_correct": false, "explanation": "形は合うが意味が合わない。料理は買収や上場と並ぶ出口戦略ではない。"}], "explanations": {"株式": "「株式上場」で、企業が出口戦略として選ぶ上場の対象を表すので意味が合う。", "土地": "形は合うが意味が合わない。「土地上場」という言い方はなく、出口戦略にもならない。", "天気": "形は合うが意味が合わない。天気は上場の対象にならない。", "料理": "形は合うが意味が合わない。料理は買収や上場と並ぶ出口戦略ではない。"}, "sentence_index": 0, "correct_answer": "株式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は株式を着て会社へ行った。", "explanation": "株式は証券であり、着るものではない。「着る」との組み合わせで誤用している。"}, {"text": "毎朝、公園で株式を散歩させている。", "explanation": "株式を犬のような生き物として扱っており、証券という意味から外れている。"}, {"text": "昼ごはんに株式を食べました。", "explanation": "株式は食べ物ではない。「食べる」と結びつけたため意味が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51978, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "株式", "is_correct": true, "explanation": "株式を発行することが資金調達の方法になるので意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気で資金調達はできない。"}, {"text": "料理", "is_correct": false, "explanation": "形は合うが意味が合わない。料理による資金調達は利点と危険の話にならない。"}, {"text": "睡眠", "is_correct": false, "explanation": "形は合うが意味が合わない。睡眠は資金調達の手段ではない。"}], "explanations": {"株式": "株式を発行することが資金調達の方法になるので意味が合う。", "天気": "形は合うが意味が合わない。天気で資金調達はできない。", "料理": "形は合うが意味が合わない。料理による資金調達は利点と危険の話にならない。", "睡眠": "形は合うが意味が合わない。睡眠は資金調達の手段ではない。"}, "sentence_index": 6, "correct_answer": "株式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "株式を飲むと、会社の所有者になる。", "explanation": "株式は証券で、飲むものではない。「飲む」との組み合わせが誤り。"}, {"text": "この株式は三メートルの高さで、とても重い。", "explanation": "株式を大きく重い物体のように扱っており、証券という意味に合わない。"}, {"text": "株式の天気は、明日は晴れるでしょう。", "explanation": "株式に天気はない。「株式の」と天気を結びつけるのは誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51978, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は株式を飲んで、利益を得た。", "corrected_sentence": "彼女は株式を売って、利益を得た。", "error_description": "「株式を飲む」は不自然。株式は「売る・買う」と使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51978, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "投資家は株式を着て、会社の所有者の一人になった。", "corrected_sentence": "投資家は株式を買って、会社の所有者の一人になった。", "error_description": "「株式を着る」は誤り。所有者になるには株式を「買う」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51979, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「会社の株」で、会社に属する株を表す。"}, {"text": "を", "is_correct": false, "explanation": "「会社を株が買える」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「会社へ株が買える」は文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「会社に株が買える」は文法的に成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「会社の株」で、会社に属する株を表す。", "を": "「会社を株が買える」は文法的に成り立たない。", "へ": "「会社へ株が買える」は文法的に成り立たない。", "に": "「会社に株が買える」は文法的に成り立たない。"}, "error_tags": {"を": "wrong_particle", "へ": "wrong_particle", "に": "wrong_particle"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非上場", "is_correct": true, "explanation": "株をみんなが買えない状態で、上場の反対。"}, {"text": "開店", "is_correct": false, "explanation": "店を開けることで、上場の反対ではない。"}, {"text": "出張", "is_correct": false, "explanation": "仕事で出かけることで、上場の反対ではない。"}, {"text": "引っ越し", "is_correct": false, "explanation": "住む場所を変えることで、上場の反対ではない。"}], "correct_answer": "非上場", "explanations": {"非上場": "株をみんなが買えない状態で、上場の反対。", "開店": "店を開けることで、上場の反対ではない。", "出張": "仕事で出かけることで、上場の反対ではない。", "引っ越し": "住む場所を変えることで、上場の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51979, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「目指す」の目的語を示すので「上場を目指す」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「上場に目指して」は「目指す」の格の取り方に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「上場と目指して」は文法的に成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「上場から目指して」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「目指す」の目的語を示すので「上場を目指す」が正しい。", "に": "「上場に目指して」は「目指す」の格の取り方に合わない。", "と": "「上場と目指して」は文法的に成り立たない。", "から": "「上場から目指して」は文法的に成り立たない。"}, "error_tags": {"に": "wrong_particle", "と": "wrong_particle", "から": "wrong_particle"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上場廃止", "is_correct": true, "explanation": "株を買えなくすることで、上場の反対。"}, {"text": "入社", "is_correct": false, "explanation": "会社に入ることで、上場の反対ではない。"}, {"text": "合格", "is_correct": false, "explanation": "試験に受かることで、上場の反対ではない。"}, {"text": "出発", "is_correct": false, "explanation": "出かけることで、上場の反対ではない。"}], "correct_answer": "上場廃止", "explanations": {"上場廃止": "株を買えなくすることで、上場の反対。", "入社": "会社に入ることで、上場の反対ではない。", "合格": "試験に受かることで、上場の反対ではない。", "出発": "出かけることで、上場の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51979, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "会社の株をみんなが買えるようにすること。", "primary_collocate": null, "pronunciation": "じょうじょう", "ipa": "dʑoːdʑoː", "syllable_count": 4, "sentences": [{"text": "会社が上場した。", "target_word": "上場", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "あの会社は来年、上場する。", "target_word": "上場", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上場すると、だれでも会社の株が買える。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場の日、社長はうれしそうだった。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場のニュースを見て、株を買った人もいる。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場できる会社は、そんなに多くない。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小さな会社が上場して、有名になった。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場を目指して、みんなで働いている。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場した会社の株は、買ったり売ったりできる。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場の準備に、二年かかった。", "target_word": "上場", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "上場する", "label": "活用"}, {"form": "上場した", "label": "活用"}, {"form": "上場企業", "label": "派生"}, {"form": "未上場", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 会社の株をみんなが買えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51979, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上場", "is_correct": true, "explanation": "じょうじょう：音声どおり。"}, {"text": "上昇", "is_correct": false, "explanation": "じょうしょう：三モーラ目の清濁だけが違う。"}, {"text": "症状", "is_correct": false, "explanation": "しょうじょう：一モーラ目の清濁だけが違う。"}, {"text": "条項", "is_correct": false, "explanation": "じょうこう：三モーラ目だけが違う。"}, {"text": "冗長", "is_correct": false, "explanation": "じょうちょう：三モーラ目だけが違う。"}], "explanations": {"上場": "じょうじょう：音声どおり。", "上昇": "じょうしょう：三モーラ目の清濁だけが違う。", "症状": "しょうじょう：一モーラ目の清濁だけが違う。", "条項": "じょうこう：三モーラ目だけが違う。", "冗長": "じょうちょう：三モーラ目だけが違う。"}, "sentence_index": null, "correct_answer": "上場"}, "level_3": {"options": [{"text": "上場", "is_correct": true, "explanation": "会社が株をみんなに買えるようにすることなので「会社が上場した」に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。会社が散歩するとは言わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "形は合うが意味が合わない。会社が昼寝するのは不自然。"}, {"text": "入学", "is_correct": false, "explanation": "形は合うが意味が合わない。会社が入学するのは不自然。"}], "explanations": {"上場": "会社が株をみんなに買えるようにすることなので「会社が上場した」に合う。", "散歩": "形は合うが意味が合わない。会社が散歩するとは言わない。", "昼寝": "形は合うが意味が合わない。会社が昼寝するのは不自然。", "入学": "形は合うが意味が合わない。会社が入学するのは不自然。"}, "sentence_index": 0, "correct_answer": "上場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに上場を食べた。", "explanation": "上場は会社の株を買えるようにすることで、食べ物ではない。"}, {"text": "この上場は三メートルあって、とても重い。", "explanation": "上場は行為であり、長さや重さのある物ではない。"}, {"text": "犬が上場を読んでいる。", "explanation": "上場は読む物ではなく、会社が行うことである。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51979, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "上場", "is_correct": true, "explanation": "じょうじょう：音声どおり。"}, {"text": "工場", "is_correct": false, "explanation": "こうじょう：一モーラ目だけが違う。"}, {"text": "頂上", "is_correct": false, "explanation": "ちょうじょう：一モーラ目だけが違う。"}, {"text": "同情", "is_correct": false, "explanation": "どうじょう：一モーラ目だけが違う。"}, {"text": "状況", "is_correct": false, "explanation": "じょうきょう：三モーラ目だけが違う。"}], "explanations": {"上場": "じょうじょう：音声どおり。", "工場": "こうじょう：一モーラ目だけが違う。", "頂上": "ちょうじょう：一モーラ目だけが違う。", "同情": "どうじょう：一モーラ目だけが違う。", "状況": "じょうきょう：三モーラ目だけが違う。"}, "sentence_index": null, "correct_answer": "上場"}, "level_3": {"options": [{"text": "上場", "is_correct": true, "explanation": "小さな会社が株を買えるようにして有名になった、という流れに合う。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが意味が合わない。会社が結婚するのは不自然。"}, {"text": "入院", "is_correct": false, "explanation": "形は合うが意味が合わない。会社が入院するのは不自然。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが意味が合わない。会社が卒業するのは不自然。"}], "explanations": {"上場": "小さな会社が株を買えるようにして有名になった、という流れに合う。", "結婚": "形は合うが意味が合わない。会社が結婚するのは不自然。", "入院": "形は合うが意味が合わない。会社が入院するのは不自然。", "卒業": "形は合うが意味が合わない。会社が卒業するのは不自然。"}, "sentence_index": 6, "correct_answer": "上場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上場を飲むと、体があたたかくなる。", "explanation": "上場は行為であり、飲み物ではない。"}, {"text": "上場は雨の日に空から落ちてくる。", "explanation": "上場は天気のように降るものではなく、会社が行うことである。"}, {"text": "私は上場の中で泳いでいる。", "explanation": "上場は場所ではないので、「中で泳ぐ」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
