INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51980, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "上場する先の取引所を示すので「取引所に上場する」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「取引所を上場する」は、上場の対象と場所の関係を誤っている。"}, {"text": "と", "is_correct": false, "explanation": "「取引所と上場する」は意味が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「取引所が上場する」だと、取引所自身が上場することになり、文意に合わない。"}], "correct_answer": "に", "explanations": {"に": "上場する先の取引所を示すので「取引所に上場する」が正しい。", "を": "「取引所を上場する」は、上場の対象と場所の関係を誤っている。", "と": "「取引所と上場する」は意味が成り立たない。", "が": "「取引所が上場する」だと、取引所自身が上場することになり、文意に合わない。"}, "error_tags": {"を": "wrong_particle", "と": "wrong_particle", "が": "subject_confusion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上場廃止", "is_correct": true, "explanation": "株式の売買を取引所でできなくすることで、上場の反対。"}, {"text": "増資", "is_correct": false, "explanation": "資本金を増やすことで、上場の反対ではない。"}, {"text": "決算", "is_correct": false, "explanation": "会計の締めの手続きで、上場の反対ではない。"}, {"text": "合併", "is_correct": false, "explanation": "会社どうしが一つになることで、上場の反対ではない。"}], "correct_answer": "上場廃止", "explanations": {"上場廃止": "株式の売買を取引所でできなくすることで、上場の反対。", "増資": "資本金を増やすことで、上場の反対ではない。", "決算": "会計の締めの手続きで、上場の反対ではない。", "合併": "会社どうしが一つになることで、上場の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51980, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「目指す」の目的語を示すので「上場を目指す」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「上場に目指す」は「目指す」の格の取り方に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「上場と目指す」は文法的に成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「上場から目指す」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「目指す」の目的語を示すので「上場を目指す」が正しい。", "に": "「上場に目指す」は「目指す」の格の取り方に合わない。", "と": "「上場と目指す」は文法的に成り立たない。", "から": "「上場から目指す」は文法的に成り立たない。"}, "error_tags": {"に": "wrong_particle", "と": "wrong_particle", "から": "wrong_particle"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上場廃止", "is_correct": true, "explanation": "取引所での株式の売買をできなくすることで、上場の反対。"}, {"text": "配当", "is_correct": false, "explanation": "利益の分配のことで、上場の反対ではない。"}, {"text": "創業", "is_correct": false, "explanation": "会社を始めることで、上場の反対ではない。"}, {"text": "提携", "is_correct": false, "explanation": "会社どうしが協力することで、上場の反対ではない。"}], "correct_answer": "上場廃止", "explanations": {"上場廃止": "取引所での株式の売買をできなくすることで、上場の反対。", "配当": "利益の分配のことで、上場の反対ではない。", "創業": "会社を始めることで、上場の反対ではない。", "提携": "会社どうしが協力することで、上場の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51980, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "企業が株式を証券取引所で売買できるようにすること。", "primary_collocate": null, "pronunciation": "じょうじょう", "ipa": "dʑoːdʑoː", "syllable_count": 4, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "上場", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "その会社は来月、東京証券取引所に上場する。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場により、一般の投資家も株式を売買できるようになる。", "target_word": "上場", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "上場の審査には、厳しい基準が設けられている。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "創業者は上場を機に、経営から退いた。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場して以来、会社の知名度は急速に高まった。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場が承認され、初日の取引が始まった。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上場を目指す企業は、財務の透明性を高める必要がある。", "target_word": "上場", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "上場している会社は、情報を公開する責任を負う。", "target_word": "上場", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "上場前に、社内の体制を整えておくべきだ。", "target_word": "上場", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上場する", "label": "活用"}, {"form": "上場した", "label": "活用"}, {"form": "上場企業", "label": "派生"}, {"form": "未上場", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 株式を取引所で売買可能にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: エグジット (Zipf 1.27)']::text[], '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51980, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上場", "is_correct": true, "explanation": "じょうじょう：音声どおり。"}, {"text": "上昇", "is_correct": false, "explanation": "じょうしょう：三モーラ目の清濁差。"}, {"text": "症状", "is_correct": false, "explanation": "しょうじょう：一モーラ目の清濁差。"}, {"text": "条項", "is_correct": false, "explanation": "じょうこう：三モーラ目のみ異なる。"}, {"text": "冗長", "is_correct": false, "explanation": "じょうちょう：三モーラ目のみ異なる。"}], "explanations": {"上場": "じょうじょう：音声どおり。", "上昇": "じょうしょう：三モーラ目の清濁差。", "症状": "しょうじょう：一モーラ目の清濁差。", "条項": "じょうこう：三モーラ目のみ異なる。", "冗長": "じょうちょう：三モーラ目のみ異なる。"}, "sentence_index": null, "correct_answer": "上場"}, "level_3": {"options": [{"text": "上場", "is_correct": true, "explanation": "「株式上場」は出口戦略の一つなので意味が合う。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。「株式散歩」という言い方はない。"}, {"text": "料理", "is_correct": false, "explanation": "形は合うが意味が合わない。「株式料理」は出口戦略にならない。"}, {"text": "旅行", "is_correct": false, "explanation": "形は合うが意味が合わない。「株式旅行」は買収と並ぶ出口戦略ではない。"}], "explanations": {"上場": "「株式上場」は出口戦略の一つなので意味が合う。", "散歩": "形は合うが意味が合わない。「株式散歩」という言い方はない。", "料理": "形は合うが意味が合わない。「株式料理」は出口戦略にならない。", "旅行": "形は合うが意味が合わない。「株式旅行」は買収と並ぶ出口戦略ではない。"}, "sentence_index": 0, "correct_answer": "上場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、公園で上場をしてから学校へ行く。", "explanation": "上場は株式を売買できるようにする企業の行為で、散歩のような日課ではない。"}, {"text": "この上場は甘くて、とてもおいしい。", "explanation": "上場は食べ物ではないので、味を表す言葉とは結びつかない。"}, {"text": "上場を着て、会社へ出かけた。", "explanation": "上場は行為であり、着る物ではない。「着る」との組み合わせが誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51980, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "上場", "is_correct": true, "explanation": "じょうじょう：音声どおり。"}, {"text": "表情", "is_correct": false, "explanation": "ひょうじょう：一モーラ目のみ異なる。"}, {"text": "道場", "is_correct": false, "explanation": "どうじょう：一モーラ目のみ異なる。"}, {"text": "醸造", "is_correct": false, "explanation": "じょうぞう：三モーラ目のみ異なる。"}, {"text": "状況", "is_correct": false, "explanation": "じょうきょう：三モーラ目のみ異なる。"}], "explanations": {"上場": "じょうじょう：音声どおり。", "表情": "ひょうじょう：一モーラ目のみ異なる。", "道場": "どうじょう：一モーラ目のみ異なる。", "醸造": "じょうぞう：三モーラ目のみ異なる。", "状況": "じょうきょう：三モーラ目のみ異なる。"}, "sentence_index": null, "correct_answer": "上場"}, "level_3": {"options": [{"text": "上場", "is_correct": true, "explanation": "取引所で上場が承認され、取引が始まるという流れに合う。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。散歩は承認されて取引が始まるものではない。"}, {"text": "旅行", "is_correct": false, "explanation": "形は合うが意味が合わない。旅行の承認で初日の取引は始まらない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが意味が合わない。卒業が承認されても取引は始まらない。"}], "explanations": {"上場": "取引所で上場が承認され、取引が始まるという流れに合う。", "散歩": "形は合うが意味が合わない。散歩は承認されて取引が始まるものではない。", "旅行": "形は合うが意味が合わない。旅行の承認で初日の取引は始まらない。", "卒業": "形は合うが意味が合わない。卒業が承認されても取引は始まらない。"}, "sentence_index": 6, "correct_answer": "上場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄は上場を飲んで、元気になった。", "explanation": "上場は行為であり、飲み物ではない。「飲む」との組み合わせが誤り。"}, {"text": "上場の天気は、明日は雨でしょう。", "explanation": "上場に天気はない。「上場の天気」は成り立たない。"}, {"text": "会社が上場に乗って、東京まで行った。", "explanation": "上場は乗り物ではないので、「乗る」と使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
