INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51981, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "会社を売って、お金をもらうことです。", "primary_collocate": null, "pronunciation": "えぐじっと", "ipa": "eɡɯdʑitto", "syllable_count": 5, "sentences": [{"text": "社長はエグジットを考えている。", "target_word": "エグジット", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会社を売るエグジットで、お金をもらった。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "エグジットしたあと、彼は旅行に出かけた。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "エグジットの話を、友だちから聞いた。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "創業者は会社のエグジットに成功した。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "エグジットすれば、大きなお金が手に入る。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彼女は五年でエグジットするつもりだ。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "エグジットを決めた日、社員に話した。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小さな会社でも、エグジットできることがある。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "エグジットのお金で、新しい会社を始めた。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "エグジットする", "label": "活用"}, {"form": "エグジットした", "label": "活用"}, {"form": "エグジット戦略", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 会社を売ってお金をもらうこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51981, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エグジット", "is_correct": true, "explanation": "会社を売ることを社長が考えるという意味で文に合う。"}, {"text": "傘", "is_correct": false, "explanation": "形は合うが、社長が傘を考えているのは意味が合わない。"}, {"text": "皿", "is_correct": false, "explanation": "形は合うが、社長が皿を考えているのは意味が合わない。"}, {"text": "魚", "is_correct": false, "explanation": "形は合うが、社長が魚を考えているのは意味が合わない。"}], "explanations": {"エグジット": "会社を売ることを社長が考えるという意味で文に合う。", "傘": "形は合うが、社長が傘を考えているのは意味が合わない。", "皿": "形は合うが、社長が皿を考えているのは意味が合わない。", "魚": "形は合うが、社長が魚を考えているのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "エグジット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅のエグジットの前で、友だちを待った。", "explanation": "「エグジット」は会社を売ってお金をもらうことで、建物の出口の意味では使えない。"}, {"text": "母にエグジットを作ってもらって、おいしかった。", "explanation": "「エグジット」は料理ではないので、「作る」「おいしい」とは結びつかない。"}, {"text": "会社を買って、新しいエグジットで働き始めた。", "explanation": "「エグジット」は会社を売ることで、働く場所の意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51981, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エグジット", "is_correct": true, "explanation": "会社を売ることを五年でするつもりだという意味で文に合う。"}, {"text": "故障", "is_correct": false, "explanation": "形は合うが、故障するつもりだというのは意味が合わない。"}, {"text": "発芽", "is_correct": false, "explanation": "形は合うが、彼女が発芽するつもりだというのは意味が合わない。"}, {"text": "落下", "is_correct": false, "explanation": "形は合うが、落下するつもりだというのは意味が合わない。"}], "explanations": {"エグジット": "会社を売ることを五年でするつもりだという意味で文に合う。", "故障": "形は合うが、故障するつもりだというのは意味が合わない。", "発芽": "形は合うが、彼女が発芽するつもりだというのは意味が合わない。", "落下": "形は合うが、落下するつもりだというのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "エグジット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エグジットをかばんに入れて、家に帰った。", "explanation": "「エグジット」は会社を売ることで、物ではないのでかばんに入れられない。"}, {"text": "エグジットが痛くて、病院に行った。", "explanation": "「エグジット」は体の部分や症状ではないので、「痛い」とは結びつかない。"}, {"text": "今日は天気がいいので、エグジットを散歩した。", "explanation": "「エグジット」は散歩する場所ではないので、「散歩する」の場所にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
