INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51982, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "投資", "is_correct": true, "explanation": "資金を投じることで、投じた資金を回収するエグジットの反対の関係にある。"}, {"text": "買収", "is_correct": false, "explanation": "エグジットの手段の一つで、反対語ではない。"}, {"text": "配当", "is_correct": false, "explanation": "利益の分配で、反対語ではない。"}, {"text": "清算", "is_correct": false, "explanation": "会社を整理することで、むしろ出口に近い意味。"}], "correct_answer": "投資", "explanations": {"投資": "資金を投じることで、投じた資金を回収するエグジットの反対の関係にある。", "買収": "エグジットの手段の一つで、反対語ではない。", "配当": "利益の分配で、反対語ではない。", "清算": "会社を整理することで、むしろ出口に近い意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51982, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "スタートアップが成長した後、投資家や創業者が投資した資金を回収するために行う、株式公開（IPO）や買収などの出口戦略のこと。", "primary_collocate": null, "pronunciation": "えぐじっと", "ipa": "eɡɯdʑitto", "syllable_count": 5, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "エグジット", "complexity_tier": "T6", "sentence_source": "mined"}, {"text": "投資家は三年後のエグジットを見据えて出資した。", "target_word": "エグジット", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "エグジットには、株式公開と買収の二つの道がある。", "target_word": "エグジット", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "創業者はエグジットで得た資金を、次の事業に投じた。", "target_word": "エグジット", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "エグジットを成功させるには、適切な時期の見極めが欠かせない。", "target_word": "エグジット", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "そのスタートアップは、上場ではなく売却によるエグジットを選んだ。", "target_word": "エグジット", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "エグジットの戦略を、創業時から考えておく。", "target_word": "エグジット", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "エグジットした後も、彼は会社の相談役を務めた。", "target_word": "エグジット", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "出資者がエグジットを急ぐと、経営方針と衝突することがある。", "target_word": "エグジット", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "早期のエグジットは、投資家に大きな利益をもたらした。", "target_word": "エグジット", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "エグジットする", "label": "活用"}, {"form": "エグジットした", "label": "活用"}, {"form": "エグジット戦略", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 投資資金を回収するための出口戦略", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304c4b9c-6a8a-4acd-a330-5d0e647ddb1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51982, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エグジット", "is_correct": true, "explanation": "買収や株式上場を指し、出口戦略と言い換えられるので文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、買収や上場が天気というのは意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、買収や上場が季節というのは意味が合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、買収や上場が野菜というのは意味が合わない。"}], "explanations": {"エグジット": "買収や株式上場を指し、出口戦略と言い換えられるので文に合う。", "天気": "形は合うが、買収や上場が天気というのは意味が合わない。", "季節": "形は合うが、買収や上場が季節というのは意味が合わない。", "野菜": "形は合うが、買収や上場が野菜というのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "エグジット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ビルの非常エグジットから、客が外へ出た。", "explanation": "「エグジット」は資金回収の出口戦略を表し、建物の出口の意味では使えない。"}, {"text": "彼は毎朝エグジットを食べてから会社へ行く。", "explanation": "「エグジット」は食べ物ではないので、「食べる」の目的語にならない。"}, {"text": "投資家は会社を買うために、エグジットを借りた。", "explanation": "「エグジット」は資金を回収する行為で、借りるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51982, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エグジット", "is_correct": true, "explanation": "資金回収の出口戦略を創業時から考えるという意味で文に合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、野菜の戦略を創業時から考えるのは意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気の戦略というのは意味が合わない。"}, {"text": "傘", "is_correct": false, "explanation": "形は合うが、傘の戦略を創業時から考えるのは意味が合わない。"}], "explanations": {"エグジット": "資金回収の出口戦略を創業時から考えるという意味で文に合う。", "野菜": "形は合うが、野菜の戦略を創業時から考えるのは意味が合わない。", "天気": "形は合うが、天気の戦略というのは意味が合わない。", "傘": "形は合うが、傘の戦略を創業時から考えるのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "エグジット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エグジットの天気は、明日も晴れるでしょう。", "explanation": "「エグジット」は天気に関係する語ではなく、場所名のように使うのは誤り。"}, {"text": "創業者は設立時に、エグジットを社員から集めた。", "explanation": "「エグジット」は資金回収の方法で、人から集められるものではない。"}, {"text": "投資家は庭にエグジットを植えて、大きく育てた。", "explanation": "「エグジット」は資金回収の方法で、植えて育てる植物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51982, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "経営陣は買収によるエグジットで見据えている。", "corrected_sentence": "経営陣は買収によるエグジットを見据えている。", "error_description": "「見据える」の目的語を示す助詞は「を」で、「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51982, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "創業者はエグジットを得た資金で、新しい会社を作った。", "corrected_sentence": "創業者はエグジットで得た資金で、新しい会社を作った。", "error_description": "資金の出どころは「エグジットで」得たもので、「を」にすると意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12ec4649-d007-4672-8f3e-1e6890eb9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51983, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "会う場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「会う」は「を」を取らないので成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「出口の会いましょう」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「会う」は「へ」を取らないので成り立たない。"}], "correct_answer": "で", "explanations": {"で": "会う場所を示す。", "を": "「会う」は「を」を取らないので成り立たない。", "の": "「出口の会いましょう」は文として成り立たない。", "へ": "「会う」は「へ」を取らないので成り立たない。"}, "error_tags": {"を": "object", "の": "possession", "へ": "direction"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51983, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "走って到達する地点を示す。"}, {"text": "の", "is_correct": false, "explanation": "「出口の走らなければ」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「出口が走らなければ」は意味が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「出口と走らなければならない」は文として成り立たない。"}], "correct_answer": "まで", "explanations": {"まで": "走って到達する地点を示す。", "の": "「出口の走らなければ」は文として成り立たない。", "が": "「出口が走らなければ」は意味が成り立たない。", "と": "「出口と走らなければならない」は文として成り立たない。"}, "error_tags": {"の": "possession", "が": "subject", "と": "comitative"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51983, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "どこかへ出ていく方法や場所のことです。", "primary_collocate": null, "pronunciation": "でぐち", "ipa": "de̞ɡɯt͡ɕi", "syllable_count": 3, "sentences": [{"text": "出口はあちらだ。", "target_word": "出口", "complexity_tier": "T1", "furigana": "出口(でぐち)はあちらだ。", "sentence_source": "generated"}, {"text": "出口で待つ。", "target_word": "出口", "complexity_tier": "T1", "furigana": "出口(でぐち)で待(ま)つ。", "sentence_source": "generated"}, {"text": "駅の出口で会いましょう。", "target_word": "出口", "complexity_tier": "T2", "furigana": "駅(えき)の出口(でぐち)で会(あ)いましょう。", "sentence_source": "generated"}, {"text": "出口はどこですか。", "target_word": "出口", "complexity_tier": "T2", "furigana": "出口(でぐち)はどこですか。", "sentence_source": "generated"}, {"text": "人が出口に集まっています。", "target_word": "出口", "complexity_tier": "T2", "furigana": "人(ひと)が出口(でぐち)に集(あつ)まっています。", "sentence_source": "generated"}, {"text": "出口を探して、やっと外に出た。", "target_word": "出口", "complexity_tier": "T3", "furigana": "出口(でぐち)を探(さが)して、やっと外(そと)に出(で)た。", "sentence_source": "generated"}, {"text": "地下鉄の出口が三つもあって、迷った。", "target_word": "出口", "complexity_tier": "T3", "furigana": "地下鉄(ちかてつ)の出口(でぐち)が三(みっ)つもあって、迷(まよ)った。", "sentence_source": "generated"}, {"text": "火事のときは、出口まで走らなければならない。", "target_word": "出口", "complexity_tier": "T4", "furigana": "火事(かじ)のときは、出口(でぐち)まで走(はし)らなければならない。", "sentence_source": "generated"}, {"text": "暗い洞窟の出口が見えたとき、ほっとした。", "target_word": "出口", "complexity_tier": "T4", "furigana": "暗(くら)い洞窟(どうくつ)の出口(でぐち)が見(み)えたとき、ほっとした。", "sentence_source": "generated"}, {"text": "映画館では、出口の近くの席に座ると、終わってすぐ外に出られる。", "target_word": "出口", "complexity_tier": "T5", "furigana": "映画館(えいがかん)では、出口(でぐち)の近(ちか)くの席(せき)に座(すわ)ると、終(お)わってすぐ外(そと)に出(で)られる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出口戦略", "label": "派生"}, {"form": "出口調査", "label": "派生"}, {"form": "出口付近", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | どこかへ出ていく場所や方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51983, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出口", "is_correct": true, "explanation": "でぐち。聞こえた語そのもの。"}, {"text": "手口", "is_correct": false, "explanation": "てぐち。「で」と「て」の清濁の一音だけが違う別の語。"}, {"text": "戸口", "is_correct": false, "explanation": "とぐち。最初の一音だけが違う別の語。"}, {"text": "電池", "is_correct": false, "explanation": "でんち。二音目だけが違う別の語。"}], "explanations": {"出口": "でぐち。聞こえた語そのもの。", "手口": "てぐち。「で」と「て」の清濁の一音だけが違う別の語。", "戸口": "とぐち。最初の一音だけが違う別の語。", "電池": "でんち。二音目だけが違う別の語。"}, "sentence_index": null, "correct_answer": "出口"}, "level_3": {"options": [{"text": "出口", "is_correct": true, "explanation": "場所を指して「出口はあちらだ」で意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「あちらだ」と場所を示す意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、方向を示す文として意味が合わない。"}, {"text": "気持ち", "is_correct": false, "explanation": "形は合うが、「あちら」と結びつかず意味が合わない。"}], "explanations": {"出口": "場所を指して「出口はあちらだ」で意味が合う。", "天気": "形は合うが、「あちらだ」と場所を示す意味が合わない。", "季節": "形は合うが、方向を示す文として意味が合わない。", "気持ち": "形は合うが、「あちら」と結びつかず意味が合わない。"}, "sentence_index": 0, "correct_answer": "出口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出口は毎朝、牛乳を飲みます。", "explanation": "「出口」は場所で、人のように飲むことはできない。"}, {"text": "出口を食べて、駅の外に出た。", "explanation": "「出口」は食べ物ではなく、「食べる」と結びつかない。"}, {"text": "出口が泣いているので、先生に伝えた。", "explanation": "「出口」は場所なので、泣くことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51983, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "出口", "is_correct": true, "explanation": "でぐち。聞こえた語そのもの。"}, {"text": "小口", "is_correct": false, "explanation": "こぐち。最初の一音だけが違う別の語。"}, {"text": "丁稚", "is_correct": false, "explanation": "でっち。二音目が促音「っ」で、「ぐ」と違う別の語。"}, {"text": "手口", "is_correct": false, "explanation": "てぐち。「で」と「て」の清濁の一音だけが違う別の語。"}], "explanations": {"出口": "でぐち。聞こえた語そのもの。", "小口": "こぐち。最初の一音だけが違う別の語。", "丁稚": "でっち。二音目が促音「っ」で、「ぐ」と違う別の語。", "手口": "てぐち。「で」と「て」の清濁の一音だけが違う別の語。"}, "sentence_index": null, "correct_answer": "出口"}, "level_3": {"options": [{"text": "出口", "is_correct": true, "explanation": "地下鉄の出口が三つあって迷う、で意味が合う。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、地下鉄の季節が三つあって迷う、は意味が合わない。"}, {"text": "気持ち", "is_correct": false, "explanation": "形は合うが、地下鉄の気持ちが三つある、は意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、地下鉄の天気は意味が合わない。"}], "explanations": {"出口": "地下鉄の出口が三つあって迷う、で意味が合う。", "季節": "形は合うが、地下鉄の季節が三つあって迷う、は意味が合わない。", "気持ち": "形は合うが、地下鉄の気持ちが三つある、は意味が合わない。", "天気": "形は合うが、地下鉄の天気は意味が合わない。"}, "sentence_index": 6, "correct_answer": "出口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出口は昨日、私に手紙を書いた。", "explanation": "「出口」は場所で、手紙を書くことはできない。"}, {"text": "出口を飲みながら、映画を見た。", "explanation": "「出口」は飲み物ではなく、「飲む」と結びつかない。"}, {"text": "出口を三杯もおかわりした。", "explanation": "「出口」は食べ物ではなく、「おかわりする」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
