INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51984, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「決める」の目的語を示す。"}, {"text": "や", "is_correct": false, "explanation": "「出口や先に決める」は後に名詞が続かず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「決める」は方向を表す「へ」を取らない。"}, {"text": "か", "is_correct": false, "explanation": "「か」を入れると文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「決める」の目的語を示す。", "や": "「出口や先に決める」は後に名詞が続かず、文として成り立たない。", "へ": "「決める」は方向を表す「へ」を取らない。", "か": "「か」を入れると文が成り立たない。"}, "error_tags": {"や": "listing", "へ": "direction", "か": "question"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入口", "is_correct": true, "explanation": "投資の入口と出口で対になる反対語。"}, {"text": "利益", "is_correct": false, "explanation": "出口の反対ではなく、出口で得るもの。"}, {"text": "資金", "is_correct": false, "explanation": "反対の関係ではない。"}, {"text": "計画", "is_correct": false, "explanation": "反対の関係ではない。"}], "correct_answer": "入口", "explanations": {"入口": "投資の入口と出口で対になる反対語。", "利益": "出口の反対ではなく、出口で得るもの。", "資金": "反対の関係ではない。", "計画": "反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
