INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51984, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ビジネスなどで、投資した利益を得るために事業から離れる方法や戦略。", "primary_collocate": null, "pronunciation": "でぐち", "ipa": "de̞ɡɯt͡ɕi", "syllable_count": 3, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "出口", "complexity_tier": "T6", "furigana": "やがて企業(きぎょう)が成熟(せいじゅく)すると、創業者(そうぎょうしゃ)や投資家(とうしか)は投資(とうし)した対価(たいか)を得(え)るために、他社(たしゃ)による買収(ばいしゅう)や株式上場(かぶしきじょうじょう)といったエグジット、すなわち出口戦略(でぐちせんりゃく)を選択(せんたく)する。", "sentence_source": "mined"}, {"text": "出口を先に決める。", "target_word": "出口", "complexity_tier": "T1", "furigana": "出口(でぐち)を先(さき)に決(き)める。", "sentence_source": "generated"}, {"text": "投資の出口を考えます。", "target_word": "出口", "complexity_tier": "T2", "furigana": "投資(とうし)の出口(でぐち)を考(かんが)えます。", "sentence_source": "generated"}, {"text": "事業の出口が大切です。", "target_word": "出口", "complexity_tier": "T2", "furigana": "事業(じぎょう)の出口(でぐち)が大切(たいせつ)です。", "sentence_source": "generated"}, {"text": "投資家は出口を決めてから、お金を出す。", "target_word": "出口", "complexity_tier": "T3", "furigana": "投資家(とうしか)は出口(でぐち)を決(き)めてから、お金(かね)を出(だ)す。", "sentence_source": "generated"}, {"text": "出口がない投資は、とても危険だ。", "target_word": "出口", "complexity_tier": "T3", "furigana": "出口(でぐち)がない投資(とうし)は、とても危険(きけん)だ。", "sentence_source": "generated"}, {"text": "もし株式上場できれば、それが出口になる。", "target_word": "出口", "complexity_tier": "T4", "furigana": "もし株式上場(かぶしきじょうじょう)できれば、それが出口(でぐち)になる。", "sentence_source": "generated"}, {"text": "出口を誤ると、せっかくの利益が減ってしまう。", "target_word": "出口", "complexity_tier": "T4", "furigana": "出口(でぐち)を誤(あやま)ると、せっかくの利益(りえき)が減(へ)ってしまう。", "sentence_source": "generated"}, {"text": "創業者は会社を育てる段階から、出口について真剣に話し合っておくべきだ。", "target_word": "出口", "complexity_tier": "T5", "furigana": "創業者(そうぎょうしゃ)は会社(かいしゃ)を育(そだ)てる段階(だんかい)から、出口(でぐち)について真剣(しんけん)に話(はな)し合(あ)っておくべきだ。", "sentence_source": "generated"}, {"text": "ファンドは五年後の出口に向けて、投資先の経営を支援している。", "target_word": "出口", "complexity_tier": "T5", "furigana": "ファンドは五年後(ごねんご)の出口(でぐち)に向(む)けて、投資先(とうしさき)の経営(けいえい)を支援(しえん)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出口戦略", "label": "派生"}, {"form": "出口調査", "label": "派生"}, {"form": "出口付近", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 事業から利益を得て離れる戦略", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: エグジット (Zipf 1.27)']::text[], 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51984, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出口", "is_correct": true, "explanation": "でぐち。聞こえた語そのもの。"}, {"text": "手口", "is_correct": false, "explanation": "てぐち。「で」と「て」の清濁の一音だけが違う別の語。"}, {"text": "戸口", "is_correct": false, "explanation": "とぐち。最初の一音だけが違う別の語。"}, {"text": "電池", "is_correct": false, "explanation": "でんち。二音目「ぐ」と「ん」だけが違う別の語。"}], "explanations": {"出口": "でぐち。聞こえた語そのもの。", "手口": "てぐち。「で」と「て」の清濁の一音だけが違う別の語。", "戸口": "とぐち。最初の一音だけが違う別の語。", "電池": "でんち。二音目「ぐ」と「ん」だけが違う別の語。"}, "sentence_index": null, "correct_answer": "出口"}, "level_3": {"options": [{"text": "出口", "is_correct": true, "explanation": "「エグジット、すなわち出口戦略」で意味が合う。"}, {"text": "営業", "is_correct": false, "explanation": "形は合うが、エグジットを言い換える意味にならない。"}, {"text": "採用", "is_correct": false, "explanation": "形は合うが、投資から離れる戦略という意味が合わない。"}, {"text": "教育", "is_correct": false, "explanation": "形は合うが、買収や上場の説明として意味が合わない。"}], "explanations": {"出口": "「エグジット、すなわち出口戦略」で意味が合う。", "営業": "形は合うが、エグジットを言い換える意味にならない。", "採用": "形は合うが、投資から離れる戦略という意味が合わない。", "教育": "形は合うが、買収や上場の説明として意味が合わない。"}, "sentence_index": 0, "correct_answer": "出口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出口は毎日、投資家と一緒に昼ごはんを食べます。", "explanation": "「出口」を人のように扱っており、事業から離れる戦略という意味に合わない。"}, {"text": "事業の出口を、冷蔵庫で冷やしておきます。", "explanation": "「出口」は抽象的な戦略で、物のように冷やせない。"}, {"text": "投資の出口を着て、会議に出た。", "explanation": "「出口」は衣類ではなく、「着る」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51984, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "出口", "is_correct": true, "explanation": "でぐち。聞こえた語そのもの。"}, {"text": "小口", "is_correct": false, "explanation": "こぐち。最初の一音だけが違う別の語。"}, {"text": "丁稚", "is_correct": false, "explanation": "でっち。二音目が促音「っ」で、「ぐ」と違う別の語。"}, {"text": "手口", "is_correct": false, "explanation": "てぐち。「で」と「て」の清濁の一音だけが違う別の語。"}], "explanations": {"出口": "でぐち。聞こえた語そのもの。", "小口": "こぐち。最初の一音だけが違う別の語。", "丁稚": "でっち。二音目が促音「っ」で、「ぐ」と違う別の語。", "手口": "てぐち。「で」と「て」の清濁の一音だけが違う別の語。"}, "sentence_index": null, "correct_answer": "出口"}, "level_3": {"options": [{"text": "出口", "is_correct": true, "explanation": "上場すれば投資から離れる方法になるので意味が合う。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが、株式上場の結果として意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、上場と天気は意味がつながらない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、文の意味が合わない。"}], "explanations": {"出口": "上場すれば投資から離れる方法になるので意味が合う。", "趣味": "形は合うが、株式上場の結果として意味が合わない。", "天気": "形は合うが、上場と天気は意味がつながらない。", "季節": "形は合うが、文の意味が合わない。"}, "sentence_index": 6, "correct_answer": "出口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ファンドの出口は、昨日から熱が出て休んでいます。", "explanation": "「出口」を人のように扱っており、事業から離れる戦略という意味に合わない。"}, {"text": "出口はとても甘くて、投資家に人気のお菓子です。", "explanation": "「出口」は食べ物ではなく、戦略という意味に合わない。"}, {"text": "出口を歌って、利益を得るために事業を始めた。", "explanation": "「歌う」の対象になれず、「出口」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51984, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "経営者は出口に考えてから、会社を売った。", "corrected_sentence": "経営者は出口を考えてから、会社を売った。", "error_description": "「考える」の目的語になる「出口」には「に」ではなく「を」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
