INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51985, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「終了」と「合図」をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「終了を合図が」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「終了へ合図が」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「終了が合図が鳴りました」は主語が二つになり、文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「終了」と「合図」をつなぐ。", "を": "「終了を合図が」は文として成り立たない。", "へ": "「終了へ合図が」は文として成り立たない。", "が": "「終了が合図が鳴りました」は主語が二つになり、文として成り立たない。"}, "error_tags": {"を": "object", "へ": "direction", "が": "subject"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開始", "is_correct": true, "explanation": "始まることで、終了の反対語。"}, {"text": "合図", "is_correct": false, "explanation": "反対の関係ではない。"}, {"text": "時間", "is_correct": false, "explanation": "反対の関係ではない。"}, {"text": "学校", "is_correct": false, "explanation": "反対の関係ではない。"}], "correct_answer": "開始", "explanations": {"開始": "始まることで、終了の反対語。", "合図": "反対の関係ではない。", "時間": "反対の関係ではない。", "学校": "反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c1eeed-52e0-4ebb-a487-eb23e4bbef62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
