INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51985, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが終わることです。", "primary_collocate": null, "pronunciation": "しゅうりょう", "ipa": "ɕɯːɾjoː", "syllable_count": 4, "sentences": [{"text": "授業が終了した。", "target_word": "終了", "complexity_tier": "T1", "furigana": "授業(じゅぎょう)が終了(しゅうりょう)した。", "sentence_source": "generated"}, {"text": "試合は終了だ。", "target_word": "終了", "complexity_tier": "T1", "furigana": "試合(しあい)は終了(しゅうりょう)だ。", "sentence_source": "generated"}, {"text": "終了の合図が鳴りました。", "target_word": "終了", "complexity_tier": "T2", "furigana": "終了(しゅうりょう)の合図(あいず)が鳴(な)りました。", "sentence_source": "generated"}, {"text": "夏休みが終了します。", "target_word": "終了", "complexity_tier": "T2", "furigana": "夏休(なつやす)みが終了(しゅうりょう)します。", "sentence_source": "generated"}, {"text": "受付は五時に終了して、もう閉まっている。", "target_word": "終了", "complexity_tier": "T3", "furigana": "受付(うけつけ)は五時(ごじ)に終了(しゅうりょう)して、もう閉(し)まっている。", "sentence_source": "generated"}, {"text": "ゲームを終了して、パソコンを閉じた。", "target_word": "終了", "complexity_tier": "T3", "furigana": "ゲームを終了(しゅうりょう)して、パソコンを閉(と)じた。", "sentence_source": "generated"}, {"text": "終了まであと十分しかない。", "target_word": "終了", "complexity_tier": "T3", "furigana": "終了(しゅうりょう)まであと十分(じゅっぷん)しかない。", "sentence_source": "generated"}, {"text": "作業が終了したら、お知らせします。", "target_word": "終了", "complexity_tier": "T4", "furigana": "作業(さぎょう)が終了(しゅうりょう)したら、お知(し)らせします。", "sentence_source": "generated"}, {"text": "終了を知らせるチャイムが、校内に響いた。", "target_word": "終了", "complexity_tier": "T4", "furigana": "終了(しゅうりょう)を知(し)らせるチャイムが、校内(こうない)に響(ひび)いた。", "sentence_source": "generated"}, {"text": "予定していた時間を過ぎても、会議はなかなか終了しなかった。", "target_word": "終了", "complexity_tier": "T5", "furigana": "予定(よてい)していた時間(じかん)を過(す)ぎても、会議(かいぎ)はなかなか終了(しゅうりょう)しなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "終了する", "label": "活用"}, {"form": "終了した", "label": "活用"}, {"form": "終了後", "label": "派生"}, {"form": "終了時", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事や活動が終わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 4 words above tier T1 (max 2): 知らせる (Zipf 3.57), チャイム (Zipf 3.35), 校内 (Zipf 3.38), 響い (Zipf 3.51)']::text[], 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
