INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51986, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "今まで続いていた物事が、そこで終わりになること。", "primary_collocate": null, "pronunciation": "しゅうりょう", "ipa": "ɕɯːɾjoː", "syllable_count": 4, "sentences": [{"text": "これは事業の終了ではなく、資本の循環と新たな創造への移行を意味する重要なプロセスだ。", "target_word": "終了", "complexity_tier": "T6", "furigana": "これは事業(じぎょう)の終了(しゅうりょう)ではなく、資本(しほん)の循環(じゅんかん)と新(あら)たな創造(そうぞう)への移行(いこう)を意味(いみ)する重要(じゅうよう)なプロセスだ。", "sentence_source": "mined"}, {"text": "会議は終了した。", "target_word": "終了", "complexity_tier": "T1", "furigana": "会議(かいぎ)は終了(しゅうりょう)した。", "sentence_source": "generated"}, {"text": "試合は五時に終了します。", "target_word": "終了", "complexity_tier": "T2", "furigana": "試合(しあい)は五時(ごじ)に終了(しゅうりょう)します。", "sentence_source": "generated"}, {"text": "授業の終了を待ちます。", "target_word": "終了", "complexity_tier": "T2", "furigana": "授業(じゅぎょう)の終了(しゅうりょう)を待(ま)ちます。", "sentence_source": "generated"}, {"text": "契約の終了について、説明を受けた。", "target_word": "終了", "complexity_tier": "T3", "furigana": "契約(けいやく)の終了(しゅうりょう)について、説明(せつめい)を受(う)けた。", "sentence_source": "generated"}, {"text": "サービスを終了すると、会社が発表した。", "target_word": "終了", "complexity_tier": "T3", "furigana": "サービスを終了(しゅうりょう)すると、会社(かいしゃ)が発表(はっぴょう)した。", "sentence_source": "generated"}, {"text": "工事が終了したら、すぐ連絡してください。", "target_word": "終了", "complexity_tier": "T4", "furigana": "工事(こうじ)が終了(しゅうりょう)したら、すぐ連絡(れんらく)してください。", "sentence_source": "generated"}, {"text": "事業が終了すれば、社員は別の部署に移る。", "target_word": "終了", "complexity_tier": "T4", "furigana": "事業(じぎょう)が終了(しゅうりょう)すれば、社員(しゃいん)は別(べつ)の部署(ぶしょ)に移(うつ)る。", "sentence_source": "generated"}, {"text": "終了の時間が来ても、会場の人は帰らなかった。", "target_word": "終了", "complexity_tier": "T4", "furigana": "終了(しゅうりょう)の時間(じかん)が来(き)ても、会場(かいじょう)の人(ひと)は帰(かえ)らなかった。", "sentence_source": "generated"}, {"text": "長年続いたこの番組は、来月で終了することが正式に決まった。", "target_word": "終了", "complexity_tier": "T5", "furigana": "長年(ながねん)続(つづ)いたこの番組(ばんぐみ)は、来月(らいげつ)で終了(しゅうりょう)することが正式(せいしき)に決(き)まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "終了する", "label": "活用"}, {"form": "終了した", "label": "活用"}, {"form": "終了後", "label": "派生"}, {"form": "終了時", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 続いていた物事が終わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a500faf0-6d25-4648-b5f5-dd873ded20cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
