INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51987, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」の目的語として「を」が必要で、「テクノロジーを使って」が自然。"}, {"text": "が", "is_correct": false, "explanation": "「使って」の主語にはならず、「古いテクノロジーが使って」では主体が不自然。"}, {"text": "に", "is_correct": false, "explanation": "「テクノロジーに使って」は「使う」と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「使って」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「使う」の目的語として「を」が必要で、「テクノロジーを使って」が自然。", "が": "「使って」の主語にはならず、「古いテクノロジーが使って」では主体が不自然。", "に": "「テクノロジーに使って」は「使う」と結びつかない。", "へ": "「へ」は方向を示すので、「使って」の目的語にはならない。"}, "error_tags": {"が": "主格", "に": "与格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
