INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51987, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものをつくるための、新しいやり方やしくみのこと。", "primary_collocate": null, "pronunciation": "てくのろじー", "ipa": "tekɯnoɾodʑiː", "syllable_count": 6, "sentences": [{"text": "新しいテクノロジーのおかげで、車を安く作れるようになった。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "新[あたら]しいテクノロジーのおかげで、車[くるま]を安[やす]く作[つく]れるようになった。", "sentence_source": "generated"}, {"text": "この工場では、古いテクノロジーを使って、昔と同じ紙を作っている。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、古[ふる]いテクノロジーを使[つか]って、昔[むかし]と同[おな]じ紙[かみ]を作[つく]っている。", "sentence_source": "generated"}, {"text": "その会社は、水をきれいにするテクノロジーを研究している。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は、水[みず]をきれいにするテクノロジーを研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "日本のテクノロジーは、ものづくりの分野で世界に知られている。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "日本[にほん]のテクノロジーは、ものづくりの分野[ぶんや]で世界[せかい]に知[し]られている。", "sentence_source": "generated"}, {"text": "新しいテクノロジーを学ぶために、技術者が海外の工場を見学した。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "新[あたら]しいテクノロジーを学[まな]ぶために、技術者[ぎじゅつしゃ]が海外[かいがい]の工場[こうじょう]を見学[けんがく]した。", "sentence_source": "generated"}, {"text": "このテクノロジーを使えば、ごみから燃料を作ることができる。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "このテクノロジーを使[つか]えば、ごみから燃料[ねんりょう]を作[つく]ることができる。", "sentence_source": "generated"}, {"text": "布を作るテクノロジーが進んで、服がじょうぶで軽くなった。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "布[ぬの]を作[つく]るテクノロジーが進[すす]んで、服[ふく]がじょうぶで軽[かる]くなった。", "sentence_source": "generated"}, {"text": "工場の人は、ものを早く作る新しいテクノロジーを紹介した。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "工場[こうじょう]の人[ひと]は、ものを早[はや]く作[つく]る新[あたら]しいテクノロジーを紹介[しょうかい]した。", "sentence_source": "generated"}, {"text": "昔のテクノロジーでは、こんなに細い糸は作れなかった。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "昔[むかし]のテクノロジーでは、こんなに細[ほそ]い糸[いと]は作[つく]れなかった。", "sentence_source": "generated"}, {"text": "父は、家を建てるテクノロジーの本を読むのが好きだ。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "父[ちち]は、家[いえ]を建[た]てるテクノロジーの本[ほん]を読[よ]むのが好[す]きだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テクノロジー", "label": "基本形"}, {"form": "テクノロジーの", "label": "連体形（の）"}], "register": "平易な書き言葉（常体）", "sense_fingerprint": "ものづくりの新しいやり方やしくみ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51987, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テクノロジー", "is_correct": true, "explanation": "「新しいテクノロジーのおかげで」は、新しい製造の仕組みが車の値段を下げたという意味になり、文に合う。"}, {"text": "友情", "is_correct": false, "explanation": "「新しい友情のおかげで車を安く作れる」は意味が通らない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気のおかげで車を安く作れる」は製造の仕組みと結びつかず、意味が通らない。"}, {"text": "退屈", "is_correct": false, "explanation": "退屈は作り方の改善にならず、文に合わない。"}], "explanations": {"テクノロジー": "「新しいテクノロジーのおかげで」は、新しい製造の仕組みが車の値段を下げたという意味になり、文に合う。", "友情": "「新しい友情のおかげで車を安く作れる」は意味が通らない。", "眠気": "「眠気のおかげで車を安く作れる」は製造の仕組みと結びつかず、意味が通らない。", "退屈": "退屈は作り方の改善にならず、文に合わない。"}, "sentence_index": 0, "correct_answer": "テクノロジー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店はテクノロジーが新鮮で、野菜がおいしい。", "explanation": "ここは〈食材〉の意味。テクノロジーは食材の鮮度を表さないので、野菜の説明には使わない。"}, {"text": "明日のテクノロジーは、晴れのち曇りでしょう。", "explanation": "ここは〈天気〉の意味。テクノロジーは天気の移り変わりを表さないので、予報の文には合わない。"}, {"text": "彼女はテクノロジーが明るく、いつも笑顔だ。", "explanation": "ここは〈性格〉の意味。テクノロジーは人の性質を表さないので、人物の評価には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51987, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テクノロジー", "is_correct": true, "explanation": "「布を作るテクノロジー」は布の製法を指し、進歩の主語として文に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "「布を作る眠気が進んで」は成り立たない。"}, {"text": "寂しさ", "is_correct": false, "explanation": "寂しさが布の製法を進めるとは言えず、文の意味が通らない。"}, {"text": "怒り", "is_correct": false, "explanation": "怒りが布を作る方法を進めるという意味にはならない。"}], "explanations": {"テクノロジー": "「布を作るテクノロジー」は布の製法を指し、進歩の主語として文に合う。", "眠気": "「布を作る眠気が進んで」は成り立たない。", "寂しさ": "寂しさが布の製法を進めるとは言えず、文の意味が通らない。", "怒り": "怒りが布を作る方法を進めるという意味にはならない。"}, "sentence_index": 6, "correct_answer": "テクノロジー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テクノロジーがひどくて、授業中に何度もあくびをした。", "explanation": "ここは〈眠気〉の意味。テクノロジーは体の状態を表さないので、眠くてあくびをする文には使わない。"}, {"text": "彼女はテクノロジーが長くて、腰まで届いている。", "explanation": "ここは〈髪〉の意味。テクノロジーは科学技術の成果なので、髪の長さを表す言葉としては使わない。"}, {"text": "彼女はテクノロジーが大きくて、遠くからでも聞こえる。", "explanation": "ここは〈声〉の意味。テクノロジーは声の大きさを表さないので、人の声の説明には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51987, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工場では、古いテクノロジーに布を織っている。", "corrected_sentence": "この工場では、古いテクノロジーで布を織っている。", "error_description": "「で」は手段を表すので「テクノロジーで布を織る」が自然。「に」は方向や対象を表し、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51987, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工場は、新しいテクノロジーの使って製品を作っている。", "corrected_sentence": "この工場は、新しいテクノロジーを使って製品を作っている。", "error_description": "「使う」は目的語に「を」を取る。「の」は誤りで、「テクノロジーを使って」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51988, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」は目的語に「を」を取り、「テクノロジーを使った」が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すため、「テクノロジーが使った」では使う主体が逆になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「使う」は「に」を取らず、「テクノロジーに使った」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「テクノロジーへ使った」は文として合わない。"}], "correct_answer": "を", "explanations": {"を": "「使う」は目的語に「を」を取り、「テクノロジーを使った」が成り立つ。", "が": "「が」は主語を表すため、「テクノロジーが使った」では使う主体が逆になり不自然。", "に": "「使う」は「に」を取らず、「テクノロジーに使った」は成り立たない。", "へ": "「へ」は方向を表すので、「テクノロジーへ使った」は文として合わない。"}, "error_tags": {"が": "主格", "に": "与格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51988, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「守る」は目的語に「を」を取り、「テクノロジーを守る」が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「守る」は「に」を取らず、「テクノロジーに守る」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表すが、「守る」とは結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「守る」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「守る」は目的語に「を」を取り、「テクノロジーを守る」が成り立つ。", "に": "「守る」は「に」を取らず、「テクノロジーに守る」は不自然。", "と": "「と」は並列や相手を表すが、「守る」とは結びつかない。", "へ": "「へ」は方向を表すので、「守る」の目的語にはならない。"}, "error_tags": {"に": "与格", "と": "共同", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51988, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "科学技術の成果を応用した、実用的な知識や手法の総称。特に、情報処理や電子機器などの分野で用いられる先端的な技術。", "primary_collocate": null, "pronunciation": "てくのろじー", "ipa": "tekɯnoɾodʑiː", "syllable_count": 6, "sentences": [{"text": "ベンチャーキャピタルは、有望なテクノロジーに資金を投じている。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "ベンチャーキャピタルは、有望[ゆうぼう]なテクノロジーに資金[しきん]を投[とう]じている。", "sentence_source": "generated"}, {"text": "最先端のテクノロジーを使った医療機器が、病院に導入された。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "最先端[さいせんたん]のテクノロジーを使[つか]った医療機器[いりょうきき]が、病院[びょういん]に導入[どうにゅう]された。", "sentence_source": "generated"}, {"text": "人工知能のテクノロジーは、この十年で驚くほど進歩した。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "人工知能[じんこうちのう]のテクノロジーは、この十年[じゅうねん]で驚[おどろ]くほど進歩[しんぽ]した。", "sentence_source": "generated"}, {"text": "新しいテクノロジーの開発には、多額の研究費が必要だ。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "新[あたら]しいテクノロジーの開発[かいはつ]には、多額[たがく]の研究費[けんきゅうひ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この会社は独自のテクノロジーで、世界の市場に進出している。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は独自[どくじ]のテクノロジーで、世界[せかい]の市場[しじょう]に進出[しんしゅつ]している。", "sentence_source": "generated"}, {"text": "テクノロジーが発達したおかげで、遠く離れた家族と顔を見て話せる。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "テクノロジーが発達[はったつ]したおかげで、遠[とお]く離[はな]れた家族[かぞく]と顔[かお]を見[み]て話[はな]せる。", "sentence_source": "generated"}, {"text": "テクノロジーに詳しい技術者が、システムの安全性を点検した。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "テクノロジーに詳[くわ]しい技術者[ぎじゅつしゃ]が、システムの安全性[あんぜんせい]を点検[てんけん]した。", "sentence_source": "generated"}, {"text": "高度なテクノロジーを守るため、企業は特許を取得する。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "高度[こうど]なテクノロジーを守[まも]るため、企業[きぎょう]は特許[とっきょ]を取得[しゅとく]する。", "sentence_source": "generated"}, {"text": "電子機器のテクノロジーは、小型化と省電力化を同時に進めている。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "電子機器[でんしきき]のテクノロジーは、小型化[こがたか]と省電力化[しょうでんりょくか]を同時[どうじ]に進[すす]めている。", "sentence_source": "generated"}, {"text": "一方で、テクノロジーの進歩は、仕事のあり方を大きく変えつつある。", "target_word": "テクノロジー", "complexity_tier": "T3", "furigana": "一方[いっぽう]で、テクノロジーの進歩[しんぽ]は、仕事[しごと]のあり方[かた]を大[おお]きく変[か]えつつある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テクノロジー", "label": "基本形"}, {"form": "テクノロジーの", "label": "連体形（の）"}], "register": "書き言葉・やや硬い（常体）", "sense_fingerprint": "情報処理や電子機器など先端分野の実用的な技術", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51988, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テクノロジー", "is_correct": true, "explanation": "「有望なテクノロジー」は資金を投じる対象として文に合う。"}, {"text": "反省", "is_correct": false, "explanation": "「有望な反省に資金を投じる」は成り立たず、文の意味が通らない。"}, {"text": "眠気", "is_correct": false, "explanation": "「有望な眠気に資金を投じる」は意味が通らない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「有望な夕焼けに資金を投じる」は成り立たず、文に合わない。"}], "explanations": {"テクノロジー": "「有望なテクノロジー」は資金を投じる対象として文に合う。", "反省": "「有望な反省に資金を投じる」は成り立たず、文の意味が通らない。", "眠気": "「有望な眠気に資金を投じる」は意味が通らない。", "夕焼け": "「有望な夕焼けに資金を投じる」は成り立たず、文に合わない。"}, "sentence_index": 0, "correct_answer": "テクノロジー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は歴史のテクノロジーが豊富で、どんな質問にも答える。", "explanation": "ここは〈知識〉の意味。テクノロジーは科学技術の成果を指すので、歴史の知識を表す言葉としては合わない。"}, {"text": "あの選手はテクノロジーが高く、最後まで走り続けた。", "explanation": "ここは〈腕前〉の意味。テクノロジーは科学技術の成果を指すので、選手の技術の高さを表す言葉としては合わない。"}, {"text": "このお酒はテクノロジーが強く、一杯で酔ってしまう。", "explanation": "ここは〈度数〉の意味。テクノロジーは科学技術の成果なので、酒のアルコールの強さを表す言葉としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51988, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テクノロジー", "is_correct": true, "explanation": "「テクノロジーに詳しい」は科学技術に通じているという意味で、技術者に合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "「挨拶に詳しい技術者」では、安全性の点検という文脈と結びつかない。"}, {"text": "感傷", "is_correct": false, "explanation": "「感傷に詳しい」は成り立たず、技術者の説明にならない。"}, {"text": "良心", "is_correct": false, "explanation": "「良心に詳しい技術者」は成り立たず、文の意味が通らない。"}], "explanations": {"テクノロジー": "「テクノロジーに詳しい」は科学技術に通じているという意味で、技術者に合う。", "挨拶": "「挨拶に詳しい技術者」では、安全性の点検という文脈と結びつかない。", "感傷": "「感傷に詳しい」は成り立たず、技術者の説明にならない。", "良心": "「良心に詳しい技術者」は成り立たず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "テクノロジー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の演奏を聞いて、テクノロジーが胸にこみ上げた。", "explanation": "ここは〈感動〉の意味。テクノロジーは科学技術の成果を指すので、胸にこみ上げる気持ちには合わない。"}, {"text": "彼はテクノロジーが良くて、宝くじに当たった。", "explanation": "ここは〈運〉の意味。テクノロジーは科学技術の成果なので、運の良し悪しを表す言葉としては使わない。"}, {"text": "このスープはテクノロジーが濃く、ご飯が進む。", "explanation": "ここは〈味〉の意味。テクノロジーは味の濃さを表さないので、スープの味の説明には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51988, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このテクノロジーを、工場の自動化を一気に進めた。", "corrected_sentence": "このテクノロジーが、工場の自動化を一気に進めた。", "error_description": "「進める」の主語はテクノロジーなので「が」が正しい。「を」は目的語の助詞で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51988, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この新しいテクノロジーを、各社が注目している。", "corrected_sentence": "この新しいテクノロジーに、各社が注目している。", "error_description": "「注目する」は「〜に注目する」と「に」を取る。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
