INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51989, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しい会社や仕事を始めることです。", "primary_collocate": null, "pronunciation": "きぎょう", "ipa": "kiɡʲoː", "syllable_count": 3, "sentences": [{"text": "兄は去年、友達と二人で起業した。", "target_word": "起業", "complexity_tier": "T3", "furigana": "兄[あに]は去年[きょねん]、友達[ともだち]と二人[ふたり]で起業[きぎょう]した。", "sentence_source": "generated"}, {"text": "起業するために、姉は毎晩、店の計画を考えている。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]するために、姉[あね]は毎晩[まいばん]、店[みせ]の計画[けいかく]を考[かんが]えている。", "sentence_source": "generated"}, {"text": "私は将来、自分の力で起業したいと思っている。", "target_word": "起業", "complexity_tier": "T3", "furigana": "私[わたし]は将来[しょうらい]、自分[じぶん]の力[ちから]で起業[きぎょう]したいと思[おも]っている。", "sentence_source": "generated"}, {"text": "起業したばかりの会社は、お客さんが少なくて大変だ。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]したばかりの会社[かいしゃ]は、お客[きゃく]さんが少[すく]なくて大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "父は会社を辞めて起業し、パン屋を開いた。", "target_word": "起業", "complexity_tier": "T3", "furigana": "父[ちち]は会社[かいしゃ]を辞[や]めて起業[きぎょう]し、パン屋[や]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "起業の話を聞くために、先輩の会社を訪ねた。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]の話[はなし]を聞[き]くために、先輩[せんぱい]の会社[かいしゃ]を訪[たず]ねた。", "sentence_source": "generated"}, {"text": "起業には勇気がいるので、母は最初反対した。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]には勇気[ゆうき]がいるので、母[はは]は最初[さいしょ]反対[はんたい]した。", "sentence_source": "generated"}, {"text": "彼女は起業して、かわいい雑貨を売る会社を作った。", "target_word": "起業", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は起業[きぎょう]して、かわいい雑貨[ざっか]を売[う]る会社[かいしゃ]を作[つく]った。", "sentence_source": "generated"}, {"text": "起業した人の話を聞く会が、図書館で開かれる。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]した人[ひと]の話[はなし]を聞[き]く会[かい]が、図書館[としょかん]で開[ひら]かれる。", "sentence_source": "generated"}, {"text": "起業を考えているなら、まず仕事の経験を積んだほうがいい。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]を考[かんが]えているなら、まず仕事[しごと]の経験[けいけん]を積[つ]んだほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "起業", "label": "基本形"}, {"form": "起業する", "label": "動詞形（辞書形）"}, {"form": "起業した", "label": "過去形"}, {"form": "起業して", "label": "て形"}], "register": "平易な書き言葉（常体）", "sense_fingerprint": "新しい会社や仕事を始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51989, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起業", "is_correct": true, "explanation": "「二人で起業した」は共同で会社を始めたという意味になり、文に合う。"}, {"text": "停電", "is_correct": false, "explanation": "「二人で停電した」は意味が通らない。"}, {"text": "熱中症", "is_correct": false, "explanation": "「熱中症した」は人の行為として成り立たない。"}, {"text": "不眠", "is_correct": false, "explanation": "「不眠した」は行為として文に合わない。"}], "explanations": {"起業": "「二人で起業した」は共同で会社を始めたという意味になり、文に合う。", "停電": "「二人で停電した」は意味が通らない。", "熱中症": "「熱中症した」は人の行為として成り立たない。", "不眠": "「不眠した」は行為として文に合わない。"}, "sentence_index": 0, "correct_answer": "起業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社は大手の起業として、多くの人に知られている。", "explanation": "ここは〈企業〉の意味。起業は新しく事業を始めることなので、すでに大きく営業している会社を指す言葉としては使わない。"}, {"text": "春に大学へ起業する。", "explanation": "ここは〈入学〉の意味。起業は会社を始めることで、学校に入ることには使わない。"}, {"text": "赤ちゃんは静かに起業している。", "explanation": "ここは〈眠る〉の意味。起業は事業を始めることで、赤ちゃんの睡眠には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51989, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起業", "is_correct": true, "explanation": "「起業には勇気がいる」は新しく事業を始める際の心構えとして文に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩には勇気がいる」は不自然で、反対の理由にならない。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除には勇気がいる」は意味が通らない。"}, {"text": "熟睡", "is_correct": false, "explanation": "「熟睡には勇気がいる」は成り立たない。"}], "explanations": {"起業": "「起業には勇気がいる」は新しく事業を始める際の心構えとして文に合う。", "散歩": "「散歩には勇気がいる」は不自然で、反対の理由にならない。", "掃除": "「掃除には勇気がいる」は意味が通らない。", "熟睡": "「熟睡には勇気がいる」は成り立たない。"}, "sentence_index": 6, "correct_answer": "起業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は毎晩、家族のために起業を作る。", "explanation": "ここは〈料理〉の意味。起業は事業を始めることで、食事を作る行為には使わない。"}, {"text": "毎朝、公園で起業をしている。", "explanation": "ここは〈運動〉の意味。起業は会社を始めることで、体を動かす運動には使わない。"}, {"text": "夏休みに、友達と起業に行く。", "explanation": "ここは〈旅行〉の意味。起業は事業を始めることで、出かける旅行とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51989, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨年、友人は会社を辞めて起業する、今は社長をしている。", "corrected_sentence": "昨年、友人は会社を辞めて起業して、今は社長をしている。", "error_description": "「起業する」で文を切ると「、今は」へ続かない。動作をつなぐ「起業して」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51989, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は大学を出て、すぐに起業を準備を始めた。", "corrected_sentence": "妹は大学を出て、すぐに起業の準備を始めた。", "error_description": "「準備」は「起業の準備」と「の」で結ぶ。「起業を準備」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51990, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「すぐに」は「すぐ」に「に」が付いた副詞句で、「すぐに起業し」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「すぐを起業」は成り立たず、「起業を」も目的語として不自然。"}, {"text": "が", "is_correct": false, "explanation": "「すぐが」は主語にならず、文の流れに合わない。"}, {"text": "で", "is_correct": false, "explanation": "「すぐで起業し」は成り立たず、副詞句として合わない。"}], "correct_answer": "に", "explanations": {"に": "「すぐに」は「すぐ」に「に」が付いた副詞句で、「すぐに起業し」と続く。", "を": "「すぐを起業」は成り立たず、「起業を」も目的語として不自然。", "が": "「すぐが」は主語にならず、文の流れに合わない。", "で": "「すぐで起業し」は成り立たず、副詞句として合わない。"}, "error_tags": {"を": "目的語", "が": "主格", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51990, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「地方で起業する」は場所を表す「で」で、起業する場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「地方を起業する」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「地方が起業する」は主体として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「地方と起業する」は並列にならず、不自然。"}], "correct_answer": "で", "explanations": {"で": "「地方で起業する」は場所を表す「で」で、起業する場所を示す。", "を": "「地方を起業する」は成り立たない。", "が": "「地方が起業する」は主体として不自然。", "と": "「地方と起業する」は並列にならず、不自然。"}, "error_tags": {"を": "目的語", "が": "主格", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51990, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しく事業を始めること。特に、会社を設立して経営を始めること。", "primary_collocate": null, "pronunciation": "きぎょう", "ipa": "kiɡʲoː", "syllable_count": 3, "sentences": [{"text": "不確実性の高い技術課題に挑み、起業を目指す若者を支援する制度が注目されている。", "target_word": "起業", "complexity_tier": "T3", "furigana": "不確実性[ふかくじつせい]の高[たか]い技術課題[ぎじゅつかだい]に挑[いど]み、起業[きぎょう]を目指[めざ]す若者[わかもの]を支援[しえん]する制度[せいど]が注目[ちゅうもく]されている。", "sentence_source": "generated"}, {"text": "大学を卒業してすぐに起業し、小さなソフトウェア会社を設立した。", "target_word": "起業", "complexity_tier": "T3", "furigana": "大学[だいがく]を卒業[そつぎょう]してすぐに起業[きぎょう]し、小[ちい]さなソフトウェア会社[がいしゃ]を設立[せつりつ]した。", "sentence_source": "generated"}, {"text": "起業には資金が必要なので、まず銀行から融資を受けた。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]には資金[しきん]が必要[ひつよう]なので、まず銀行[ぎんこう]から融資[ゆうし]を受[う]けた。", "sentence_source": "generated"}, {"text": "彼女は会社を辞めて起業する決意を固めた。", "target_word": "起業", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は会社[かいしゃ]を辞[や]めて起業[きぎょう]する決意[けつい]を固[かた]めた。", "sentence_source": "generated"}, {"text": "起業した当初は、社員が自分一人しかいなかった。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]した当初[とうしょ]は、社員[しゃいん]が自分[じぶん]一人[ひとり]しかいなかった。", "sentence_source": "generated"}, {"text": "起業の準備として、事業計画書を丁寧に作成した。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]の準備[じゅんび]として、事業計画書[じぎょうけいかくしょ]を丁寧[ていねい]に作成[さくせい]した。", "sentence_source": "generated"}, {"text": "安定した仕事を捨てて起業するのは、大きな危険を伴う。", "target_word": "起業", "complexity_tier": "T3", "furigana": "安定[あんてい]した仕事[しごと]を捨[す]てて起業[きぎょう]するのは、大[おお]きな危険[きけん]を伴[ともな]う。", "sentence_source": "generated"}, {"text": "地方で起業する若者を支援する制度が、市で始まった。", "target_word": "起業", "complexity_tier": "T3", "furigana": "地方[ちほう]で起業[きぎょう]する若者[わかもの]を支援[しえん]する制度[せいど]が、市[し]で始[はじ]まった。", "sentence_source": "generated"}, {"text": "起業に失敗しても、そこから学んだ経験は次の事業に生きる。", "target_word": "起業", "complexity_tier": "T3", "furigana": "起業[きぎょう]に失敗[しっぱい]しても、そこから学[まな]んだ経験[けいけん]は次[つぎ]の事業[じぎょう]に生[い]きる。", "sentence_source": "generated"}, {"text": "彼は祖父の店を継ぐのではなく、自分で起業する道を選んだ。", "target_word": "起業", "complexity_tier": "T3", "furigana": "彼[かれ]は祖父[そふ]の店[みせ]を継[つ]ぐのではなく、自分[じぶん]で起業[きぎょう]する道[みち]を選[えら]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "起業", "label": "基本形"}, {"form": "起業する", "label": "動詞形（辞書形）"}, {"form": "起業した", "label": "過去形"}, {"form": "起業して", "label": "て形"}], "register": "書き言葉・やや硬い（常体）", "sense_fingerprint": "会社を設立して新しく事業を始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51990, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起業", "is_correct": true, "explanation": "「起業を目指す若者」は新しく事業を始めようとする人を指し、文に合う。"}, {"text": "反省", "is_correct": false, "explanation": "「反省を目指す若者」は成り立たず、文の意味が通らない。"}, {"text": "沈黙", "is_correct": false, "explanation": "「沈黙を目指す若者」は意味が通らず、制度の文脈に合わない。"}, {"text": "試練", "is_correct": false, "explanation": "「試練を目指す若者」は不自然で、支援の対象として成り立たない。"}], "explanations": {"起業": "「起業を目指す若者」は新しく事業を始めようとする人を指し、文に合う。", "反省": "「反省を目指す若者」は成り立たず、文の意味が通らない。", "沈黙": "「沈黙を目指す若者」は意味が通らず、制度の文脈に合わない。", "試練": "「試練を目指す若者」は不自然で、支援の対象として成り立たない。"}, "sentence_index": 0, "correct_answer": "起業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの大手の起業は、全国に支店を持っている。", "explanation": "ここは〈企業〉（同音語）の意味。起業は新しく事業を始めることなので、既存の大きな会社を指す文では使えない。"}, {"text": "毎朝六時に起業する。", "explanation": "ここは〈起床〉の意味。起業は事業を始めることで、朝に寝床から起きる動作には合わない。"}, {"text": "警察は男を起業した。", "explanation": "ここは〈起訴〉の意味。起業は会社を始めることで、罪を問う手続きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51990, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起業", "is_correct": true, "explanation": "「起業するのは」は会社を始めることを指し、安定した仕事を捨てる文に合う。"}, {"text": "皿洗い", "is_correct": false, "explanation": "「皿洗いするのは大きな危険を伴う」は意味が通らない。"}, {"text": "昼寝", "is_correct": false, "explanation": "「昼寝するのは危険を伴う」は文脈に合わない。"}, {"text": "立食", "is_correct": false, "explanation": "「立食するのは」は仕事を捨てることと結びつかない。"}], "explanations": {"起業": "「起業するのは」は会社を始めることを指し、安定した仕事を捨てる文に合う。", "皿洗い": "「皿洗いするのは大きな危険を伴う」は意味が通らない。", "昼寝": "「昼寝するのは危険を伴う」は文脈に合わない。", "立食": "「立食するのは」は仕事を捨てることと結びつかない。"}, "sentence_index": 6, "correct_answer": "起業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎日二時間、英語を起業している。", "explanation": "ここは〈勉強〉の意味。起業は事業を始めることで、英語の学習には使わない。"}, {"text": "先生は授業の内容を、ノートに起業した。", "explanation": "ここは〈記録〉の意味。起業は新しく事業を始めることで、文字を書き留める記録には使わない。"}, {"text": "電車は七時に起業した。", "explanation": "ここは〈出発〉の意味。起業は会社を立ち上げることで、乗り物が発つことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51990, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人と話し合って、ついに起業で決めた。", "corrected_sentence": "友人と話し合って、ついに起業を決めた。", "error_description": "「決める」は「〜を決める」と目的語に「を」を取る。「で」は手段を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51990, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は三年前に起業されて、今は社員が十人いる。", "corrected_sentence": "彼は三年前に起業して、今は社員が十人いる。", "error_description": "「起業される」とは言わず、自分で事業を始めた動作は「起業して」で表す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51991, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「マネーを貯める」の「を」。貯める対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「貯める」は「が」の主語を取らず、ここに「が」を入れると文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「マネーへ貯める」は方向として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すが、「マネーと貯める」は文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「マネーを貯める」の「を」。貯める対象を示す。", "が": "「貯める」は「が」の主語を取らず、ここに「が」を入れると文が成り立たない。", "へ": "「へ」は方向を示すが、「マネーへ貯める」は方向として不自然。", "と": "「と」は並列を示すが、「マネーと貯める」は文の意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
