INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51991, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お金のことです。", "primary_collocate": null, "pronunciation": "まねー", "ipa": "maneː", "syllable_count": 3, "sentences": [{"text": "私はマネーの本を読んで、貯金のしかたを学んだ。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "私[わたし]はマネーの本[ほん]を読[よ]んで、貯金[ちょきん]のしかたを学[まな]んだ。", "sentence_source": "generated"}, {"text": "兄はマネーをためて、新しい自転車を買った。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "兄[あに]はマネーをためて、新[あたら]しい自転車[じてんしゃ]を買[か]った。", "sentence_source": "generated"}, {"text": "このゲームでは、マネーを集めると新しい服が買える。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "このゲームでは、マネーを集[あつ]めると新[あたら]しい服[ふく]が買[か]える。", "sentence_source": "generated"}, {"text": "マネーが足りなかったので、ほしい本をあきらめた。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "マネーが足[た]りなかったので、ほしい本[ほん]をあきらめた。", "sentence_source": "generated"}, {"text": "母はマネーの使い方に気をつけて、毎日家計簿をつけている。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "母[はは]はマネーの使[つか]い方[かた]に気[き]をつけて、毎日[まいにち]家計簿[かけいぼ]をつけている。", "sentence_source": "generated"}, {"text": "弟はお祭りで、マネーを全部使ってしまった。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "弟[おとうと]はお祭[まつ]りで、マネーを全部[ぜんぶ]使[つか]ってしまった。", "sentence_source": "generated"}, {"text": "先生は、家計を守るマネーの大切さについて話してくれた。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "先生[せんせい]は、家計[かけい]を守[まも]るマネーの大切[たいせつ]さについて話[はな]してくれた。", "sentence_source": "generated"}, {"text": "マネーの話をするとき、父はいつもまじめな顔になる。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "マネーの話[はなし]をするとき、父[ちち]はいつもまじめな顔[かお]になる。", "sentence_source": "generated"}, {"text": "旅行の前に、銀行で手持ちのマネーを両替した。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]に、銀行[ぎんこう]で手持[ても]ちのマネーを両替[りょうがえ]した。", "sentence_source": "generated"}, {"text": "祖母は、マネーを入れる小さな財布を大切にしている。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、マネーを入[い]れる小[ちい]さな財布[さいふ]を大切[たいせつ]にしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マネー", "label": "基本形"}, {"form": "マネーの", "label": "連体形（の）"}], "register": "平易な書き言葉（常体）", "sense_fingerprint": "お金（日常の買い物や貯金の文脈）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51991, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マネー", "is_correct": true, "explanation": "「マネーの本」はお金についての本。貯金のしかたを学ぶ文脈に合う。"}, {"text": "恐竜", "is_correct": false, "explanation": "「恐竜の本」では貯金のしかたは学べず、文脈が合わない。"}, {"text": "雨", "is_correct": false, "explanation": "「雨の本」を読んで貯金を学ぶのは意味が通らない。"}, {"text": "野菜", "is_correct": false, "explanation": "「野菜の本」では貯金の話にならない。"}], "explanations": {"マネー": "「マネーの本」はお金についての本。貯金のしかたを学ぶ文脈に合う。", "恐竜": "「恐竜の本」では貯金のしかたは学べず、文脈が合わない。", "雨": "「雨の本」を読んで貯金を学ぶのは意味が通らない。", "野菜": "「野菜の本」では貯金の話にならない。"}, "sentence_index": 0, "correct_answer": "マネー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹は姉のマネーをして、同じ服を着た。", "explanation": "ここは〈真似〉（まね）の意味。「姉のまねをする」の代わりに「マネーをする」とは言わない。"}, {"text": "旅行の前に、銀行でマネーを済ませた。", "explanation": "ここは〈両替〉（通貨を交換すること）の意味。マネーは行為ではないので、「済ませる」の対象にならない。"}, {"text": "彼女は合唱部のマネーとして、練習の予定を組んでいる。", "explanation": "ここは〈マネージャー〉（世話や管理をする役）の意味。お金を表すマネーでは役職は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51991, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マネー", "is_correct": true, "explanation": "「マネーの大切さ」はお金の大切さを指す。話の内容として合う。"}, {"text": "窓", "is_correct": false, "explanation": "「窓の大切さ」について話す文脈ではなく、意味が合わない。"}, {"text": "石", "is_correct": false, "explanation": "「石の大切さ」は話の内容として不自然。"}, {"text": "雨", "is_correct": false, "explanation": "「家計を守る雨」は意味が通らず、文脈に合わない。"}], "explanations": {"マネー": "「マネーの大切さ」はお金の大切さを指す。話の内容として合う。", "窓": "「窓の大切さ」について話す文脈ではなく、意味が合わない。", "石": "「石の大切さ」は話の内容として不自然。", "雨": "「家計を守る雨」は意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "マネー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スーパーのレジで、マネーをすませた。", "explanation": "ここは〈支払い〉（代金を払うこと）の意味。マネーは行為ではないので「すませる」の対象にならない。"}, {"text": "毎日同じ食事が続いて、家族の食卓はすっかりマネーになった。", "explanation": "ここは〈マンネリ〉（同じことの繰り返しで新鮮味がないこと）の意味。マネーは「お金」なので、食卓の様子は表せない。"}, {"text": "町の祭りに、子どもたちがマネーをした。", "explanation": "ここは〈寄付〉（お金を差し出す行為）の意味。マネーは行為ではないので「する」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51991, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉はマネーに貯めるために、毎月アルバイトをしている。", "corrected_sentence": "姉はマネーを貯めるために、毎月アルバイトをしている。", "error_description": "「貯める」は目的語を「を」で取る。「に」は誤り。正しくは「マネーを貯める」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51991, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟はお年玉のマネーを食べている。", "corrected_sentence": "弟はお年玉のマネーを貯めている。", "error_description": "お金は「貯める」ものなので「食べる」は誤り。正しくは「マネーを貯めている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
