INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51992, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "商品やサービスの代価として支払われる、お金や貨幣のこと。", "primary_collocate": null, "pronunciation": "まねー", "ipa": "maneː", "syllable_count": 3, "sentences": [{"text": "不確実性の高い技術的課題に挑む起業家に対し、マネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "不確実性[ふかくじつせい]の高[たか]い技術的[ぎじゅつてき]課題[かだい]に挑[いど]む起業家[きぎょうか]に対[たい]し、マネーを供給[きょうきゅう]することで、彼[かれ]らは市場[しじょう]の失敗[しっぱい]を補完[ほかん]し、破壊的[はかいてき]なイノベーションの萌芽[ほうが]を育[はぐく]むのである。", "sentence_source": "generated"}, {"text": "彼は投資で得たマネーを元手に、新しい店を開いた。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "彼[かれ]は投資[とうし]で得[え]たマネーを元手[もとで]に、新[あたら]しい店[みせ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "世界中のマネーが一つの市場に集まり、株価が急に上がった。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "世界中[せかいじゅう]のマネーが一[ひと]つの市場[しじょう]に集[あつ]まり、株価[かぶか]が急[きゅう]に上[あ]がった。", "sentence_source": "generated"}, {"text": "子どものころからマネーについて学ぶ授業が、学校で始まった。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "子[こ]どものころからマネーについて学[まな]ぶ授業[じゅぎょう]が、学校[がっこう]で始[はじ]まった。", "sentence_source": "generated"}, {"text": "海外のマネーが流れ込んだ結果、その国の不動産価格は高騰した。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "海外[かいがい]のマネーが流[なが]れ込[こ]んだ結果[けっか]、その国[くに]の不動産価格[ふどうさんかかく]は高騰[こうとう]した。", "sentence_source": "generated"}, {"text": "彼女はマネーの管理が上手で、毎月きちんと貯金している。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はマネーの管理[かんり]が上手[じょうず]で、毎月[まいつき]きちんと貯金[ちょきん]している。", "sentence_source": "generated"}, {"text": "マネーの使い方を誤ると、家計が苦しくなる。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "マネーの使[つか]い方[かた]を誤[あやま]ると、家計[かけい]が苦[くる]しくなる。", "sentence_source": "generated"}, {"text": "新聞のマネー欄には、株式や為替の最新情報が載っている。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "新聞[しんぶん]のマネー欄[らん]には、株式[かぶしき]や為替[かわせ]の最新情報[さいしんじょうほう]が載[の]っている。", "sentence_source": "generated"}, {"text": "景気が悪くなると、人々はマネーを使わずに貯め込む傾向がある。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなると、人々[ひとびと]はマネーを使[つか]わずに貯[た]め込[こ]む傾向[けいこう]がある。", "sentence_source": "generated"}, {"text": "仕事の報酬として受け取るマネーより、やりがいを重視する人もいる。", "target_word": "マネー", "complexity_tier": "T3", "furigana": "仕事[しごと]の報酬[ほうしゅう]として受[う]け取[と]るマネーより、やりがいを重視[じゅうし]する人[ひと]もいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マネー", "label": "基本形"}, {"form": "マネーの", "label": "連体形（の）"}], "register": "書き言葉・やや硬い（常体）", "sense_fingerprint": "代価として支払われるお金・貨幣（経済や投資の文脈）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: 貯め込む (Zipf 1.65)']::text[], '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51992, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マネー", "is_correct": true, "explanation": "「マネーを供給する」の目的語。資金を起業家に供給する文脈に合う。"}, {"text": "利子", "is_correct": false, "explanation": "利子は貸し借りの対価で、リスクに対して供給される資金ではないので合わない。"}, {"text": "配当", "is_correct": false, "explanation": "配当は株主に分ける利益で、供給される資金の名前ではないので合わない。"}, {"text": "税金", "is_correct": false, "explanation": "税金は国に納めるもので、起業家に供給する対象としては成り立たない。"}], "explanations": {"マネー": "「マネーを供給する」の目的語。資金を起業家に供給する文脈に合う。", "利子": "利子は貸し借りの対価で、リスクに対して供給される資金ではないので合わない。", "配当": "配当は株主に分ける利益で、供給される資金の名前ではないので合わない。", "税金": "税金は国に納めるもので、起業家に供給する対象としては成り立たない。"}, "sentence_index": 0, "correct_answer": "マネー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は先生のマネーをして、クラスの友だちを笑わせた。", "explanation": "ここは〈真似〉（まね）の意味。「先生のまねをする」の代わりに「マネー」は使えない。"}, {"text": "店でお菓子の代金のマネーを済ませて、外に出た。", "explanation": "ここは〈支払い〉（払う行為）の意味。マネーは金銭そのものなので、「済ませる」の対象にならない。"}, {"text": "彼女はチームのマネーとして、選手の予定を管理している。", "explanation": "ここは〈マネージャー〉（管理役）の意味。お金を指す「マネー」では役職は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51992, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マネー", "is_correct": true, "explanation": "「マネーの使い方」は、お金の使い方を指す。文脈に合うのはこの語。"}, {"text": "雨", "is_correct": false, "explanation": "「雨の使い方」では意味が通らず、将来の生活とのつながりもない。"}, {"text": "海", "is_correct": false, "explanation": "「海の使い方を誤る」は文脈に合わない。"}, {"text": "鉄", "is_correct": false, "explanation": "「鉄の使い方を誤ると生活が苦しくなる」は話がつながらない。"}], "explanations": {"マネー": "「マネーの使い方」は、お金の使い方を指す。文脈に合うのはこの語。", "雨": "「雨の使い方」では意味が通らず、将来の生活とのつながりもない。", "海": "「海の使い方を誤る」は文脈に合わない。", "鉄": "「鉄の使い方を誤ると生活が苦しくなる」は話がつながらない。"}, "sentence_index": 6, "correct_answer": "マネー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車の中でマネーが悪い人がいると、周りの人は困る。", "explanation": "ここは〈マナー〉（行儀）の意味。「マネー」（お金）は行儀の良し悪しを表せない。"}, {"text": "やっと借金のマネーが終わって、ほっとした。", "explanation": "ここは〈返済〉（借りた金を返すこと）の意味。マネーは金そのものなので、「終わる」の主語にならない。"}, {"text": "店員はマネー通りに接客した。", "explanation": "ここは〈マニュアル〉（手順書）の意味。マネーは金銭なので、「通り」と組み合わさない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51992, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は資産運用で、マネーに増やした。", "corrected_sentence": "彼は資産運用で、マネーを増やした。", "error_description": "「増やす」は目的語を「を」で取る。「に」は誤り。正しくは「マネーを増やした」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51992, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は一ヶ月でマネーを食べた。", "corrected_sentence": "彼は一ヶ月でマネーを使い切った。", "error_description": "お金は「使い切る」ものなので「食べる」は誤り。正しくは「マネーを使い切った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51997, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成功", "is_correct": true, "explanation": "「失敗」の対義語。うまくいったことを表す。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行は出かける行為で、結果の対義語ではない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、結果の対義語ではない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙を送る仕組みで、結果の対義語ではない。"}], "correct_answer": "成功", "explanations": {"成功": "「失敗」の対義語。うまくいったことを表す。", "旅行": "旅行は出かける行為で、結果の対義語ではない。", "天気": "天気は空模様で、結果の対義語ではない。", "郵便": "郵便は手紙を送る仕組みで、結果の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51997, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成功", "is_correct": true, "explanation": "「失敗」の対義語。うまくいったことを表す。"}, {"text": "反省", "is_correct": false, "explanation": "反省は振り返ることで、結果の反対語ではない。"}, {"text": "研究", "is_correct": false, "explanation": "研究は調べる活動で、結果の対義語ではない。"}, {"text": "指導", "is_correct": false, "explanation": "指導は教えることで、結果の対義語ではない。"}], "correct_answer": "成功", "explanations": {"成功": "「失敗」の対義語。うまくいったことを表す。", "反省": "反省は振り返ることで、結果の反対語ではない。", "研究": "研究は調べる活動で、結果の対義語ではない。", "指導": "指導は教えることで、結果の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51997, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "うまくいかなかったこと。", "primary_collocate": null, "pronunciation": "しっぱい", "ipa": "ɕippai", "syllable_count": 4, "sentences": [{"text": "料理で塩を入れすぎて、失敗してしまった。", "target_word": "失敗", "complexity_tier": "T2", "furigana": "料理[りょうり]で塩[しお]を入[い]れすぎて、失敗[しっぱい]してしまった。", "sentence_source": "generated"}, {"text": "昨日のテストは失敗だった。", "target_word": "失敗", "complexity_tier": "T2", "furigana": "昨日[きのう]のテストは失敗[しっぱい]だった。", "sentence_source": "generated"}, {"text": "失敗しても、もう一度やればいい。", "target_word": "失敗", "complexity_tier": "T2", "furigana": "失敗[しっぱい]しても、もう一度[いちど]やればいい。", "sentence_source": "generated"}, {"text": "友だちの誕生日ケーキづくりは失敗に終わった。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "友[とも]だちの誕生日[たんじょうび]ケーキづくりは失敗[しっぱい]に終[お]わった。", "sentence_source": "generated"}, {"text": "道をまちがえたのは私の失敗です。", "target_word": "失敗", "complexity_tier": "T2", "furigana": "道[みち]をまちがえたのは私[わたし]の失敗[しっぱい]です。", "sentence_source": "generated"}, {"text": "彼は失敗するたびに、少しずつ上手になった。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "彼[かれ]は失敗[しっぱい]するたびに、少[すこ]しずつ上手[じょうず]になった。", "sentence_source": "generated"}, {"text": "初めての写真は失敗ばかりでした。", "target_word": "失敗", "complexity_tier": "T2", "furigana": "初[はじ]めての写真[しゃしん]は失敗[しっぱい]ばかりでした。", "sentence_source": "generated"}, {"text": "弟は料理で失敗して、泣きそうな顔をしている。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "弟[おとうと]は料理[りょうり]で失敗[しっぱい]して、泣[な]きそうな顔[かお]をしている。", "sentence_source": "generated"}, {"text": "失敗を人のせいにしてはいけません。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を人[ひと]のせいにしてはいけません。", "sentence_source": "generated"}, {"text": "この魚の焼き方は失敗だったので、焦げて黒くなった。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "この魚[さかな]の焼[や]き方[かた]は失敗[しっぱい]だったので、焦[こ]げて黒[くろ]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "失敗", "label": "基本形"}, {"form": "失敗する", "label": "サ変動詞・終止形"}, {"form": "失敗した", "label": "過去形"}], "register": "話し言葉（日常・中立）", "sense_fingerprint": "やろうとしたことがうまくいかなかったこと（日常の小さなまちがいや結果）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51997, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失敗", "is_correct": true, "explanation": "塩の入れすぎでうまくいかなかったことを表す。文脈に合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "塩を入れすぎた文脈で挨拶するのは不自然。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は塩を入れすぎたこととつながらない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩してしまった」は塩の入れすぎとつながらず、文脈に合わない。"}], "explanations": {"失敗": "塩の入れすぎでうまくいかなかったことを表す。文脈に合う。", "挨拶": "塩を入れすぎた文脈で挨拶するのは不自然。", "感謝": "感謝は塩を入れすぎたこととつながらない。", "散歩": "「散歩してしまった」は塩の入れすぎとつながらず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "失敗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は前言を失敗した。", "explanation": "ここは〈撤回〉（取り消すこと）の意味。失敗は行為の結果で、言葉を取り消す意味はない。"}, {"text": "彼は朝の電車を失敗した。", "explanation": "ここは〈乗り遅れる〉（乗り物に間に合わず逃すこと）の意味。失敗は結果がうまくいかないことで、乗り物を逃す意味では使わない。"}, {"text": "財布を失敗した。", "explanation": "ここは〈失くす〉（物をなくすこと）の意味。失敗は物をなくすことには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51997, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失敗", "is_correct": true, "explanation": "「失敗ばかり」は、写真がうまく撮れなかったことを表す。"}, {"text": "雨", "is_correct": false, "explanation": "「雨ばかり」では写真の出来を表せず、文脈が合わない。"}, {"text": "紅茶", "is_correct": false, "explanation": "紅茶は写真の出来とつながらず、不自然。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は写真の出来の説明にならない。"}], "explanations": {"失敗": "「失敗ばかり」は、写真がうまく撮れなかったことを表す。", "雨": "「雨ばかり」では写真の出来を表せず、文脈が合わない。", "紅茶": "紅茶は写真の出来とつながらず、不自然。", "眠気": "眠気は写真の出来の説明にならない。"}, "sentence_index": 6, "correct_answer": "失敗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜更かしで、彼は体を失敗した。", "explanation": "ここは〈壊す〉（健康を損なうこと）の意味。失敗は目的を果たせなかった結果で、体の状態には使わない。"}, {"text": "お先に、失敗します。", "explanation": "ここは〈失礼〉（先に帰るときのあいさつ）の意味。失敗は結果がうまくいかないことで、あいさつには使えない。"}, {"text": "彼は先生の申し出を失敗した。", "explanation": "ここは〈承諾〉（引き受けること）の意味。失敗は申し出を受けることではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51997, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉の卵焼き作りは失敗を終わった。", "corrected_sentence": "姉の卵焼き作りは失敗に終わった。", "error_description": "「失敗に終わる」の「に」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51997, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の料理は失敗しけれど、楽しかった。", "corrected_sentence": "昨日の料理は失敗したけれど、楽しかった。", "error_description": "過去形は「失敗した」。「失敗しけれど」は活用の誤り。正しくは「失敗したけれど」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51998, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成功", "is_correct": true, "explanation": "「失敗」の対義語。期待した結果が得られなかった文脈と対になる。"}, {"text": "準備", "is_correct": false, "explanation": "準備は行動の前の段階で、結果の反対語ではない。"}, {"text": "挑戦", "is_correct": false, "explanation": "挑戦は試みること自体で、失敗の反対語ではない。"}, {"text": "理解", "is_correct": false, "explanation": "理解は内容をわかることで、結果の反対語ではない。"}], "correct_answer": "成功", "explanations": {"成功": "「失敗」の対義語。期待した結果が得られなかった文脈と対になる。", "準備": "準備は行動の前の段階で、結果の反対語ではない。", "挑戦": "挑戦は試みること自体で、失敗の反対語ではない。", "理解": "理解は内容をわかることで、結果の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51998, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成功", "is_correct": true, "explanation": "「失敗」の対義語。うまくいったことを表す。"}, {"text": "教育", "is_correct": false, "explanation": "教育は人に教えることで、結果の対義語ではない。"}, {"text": "努力", "is_correct": false, "explanation": "努力は取り組む姿勢で、結果の反対語ではない。"}, {"text": "練習", "is_correct": false, "explanation": "練習は技術を磨く行為で、結果の反対語ではない。"}], "correct_answer": "成功", "explanations": {"成功": "「失敗」の対義語。うまくいったことを表す。", "教育": "教育は人に教えることで、結果の対義語ではない。", "努力": "努力は取り組む姿勢で、結果の反対語ではない。", "練習": "練習は技術を磨く行為で、結果の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51998, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをしようとして、目的を達成できないこと。期待した結果が得られずに終わること。", "primary_collocate": null, "pronunciation": "しっぱい", "ipa": "ɕippai", "syllable_count": 4, "sentences": [{"text": "予算を使いすぎたせいで、今年の旅行計画は失敗した。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "予算[よさん]を使[つか]いすぎたせいで、今年[ことし]の旅行計画[りょこうけいかく]は失敗[しっぱい]した。", "sentence_source": "generated"}, {"text": "新しい事業は準備不足のために失敗に終わった。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "新[あたら]しい事業[じぎょう]は準備不足[じゅんびぶそく]のために失敗[しっぱい]に終[お]わった。", "sentence_source": "generated"}, {"text": "彼は一度の失敗であきらめるような人ではない。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "彼[かれ]は一度[いちど]の失敗[しっぱい]であきらめるような人[ひと]ではない。", "sentence_source": "generated"}, {"text": "期待した結果が出ず、今回の実験は失敗と判断された。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "期待[きたい]した結果[けっか]が出[で]ず、今回[こんかい]の実験[じっけん]は失敗[しっぱい]と判断[はんだん]された。", "sentence_source": "generated"}, {"text": "失敗の原因を丁寧に分析すれば、次の計画に生かせる。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の原因[げんいん]を丁寧[ていねい]に分析[ぶんせき]すれば、次[つぎ]の計画[けいかく]に生[い]かせる。", "sentence_source": "generated"}, {"text": "大きな失敗を恐れて、何も挑戦しないのはもったいない。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "大[おお]きな失敗[しっぱい]を恐[おそ]れて、何[なに]も挑戦[ちょうせん]しないのはもったいない。", "sentence_source": "generated"}, {"text": "値上げ政策は失敗し、客が一気に減ってしまった。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "値上[ねあ]げ政策[せいさく]は失敗[しっぱい]し、客[きゃく]が一気[いっき]に減[へ]ってしまった。", "sentence_source": "generated"}, {"text": "会議では、過去の失敗から学んだ点が共有された。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、過去[かこ]の失敗[しっぱい]から学[まな]んだ点[てん]が共有[きょうゆう]された。", "sentence_source": "generated"}, {"text": "計画が失敗したのは、時間が足りなかったからだ。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "計画[けいかく]が失敗[しっぱい]したのは、時間[じかん]が足[た]りなかったからだ。", "sentence_source": "generated"}, {"text": "失敗は成功のもと、ということわざを先生は教えてくれた。", "target_word": "失敗", "complexity_tier": "T3", "furigana": "失敗[しっぱい]は成功[せいこう]のもと、ということわざを先生[せんせい]は教[おし]えてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "失敗", "label": "基本形"}, {"form": "失敗する", "label": "サ変動詞・終止形"}, {"form": "失敗した", "label": "過去形"}], "register": "書き言葉（やや硬い・中立）", "sense_fingerprint": "目的を達成できず、期待した結果が得られないまま終わること（成功の反対）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51998, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失敗", "is_correct": true, "explanation": "「旅行計画は失敗した」：目的を達成できなかったことを表す。文脈に合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "「旅行計画は挨拶した」は文として成り立たず、文脈に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「旅行計画は季節した」は文として成り立たない。"}, {"text": "感謝", "is_correct": false, "explanation": "「旅行計画は感謝した」は意味が通らない。"}], "explanations": {"失敗": "「旅行計画は失敗した」：目的を達成できなかったことを表す。文脈に合う。", "挨拶": "「旅行計画は挨拶した」は文として成り立たず、文脈に合わない。", "季節": "「旅行計画は季節した」は文として成り立たない。", "感謝": "「旅行計画は感謝した」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "失敗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パスポートの期限が切れて、失敗した。", "explanation": "ここは〈失効〉（効力がなくなること）の意味。失敗は試みの結果がうまくいかないことで、効力が消える意味はない。"}, {"text": "彼は役員の候補を失敗した。", "explanation": "ここは〈辞退〉（自分から断ること）の意味。失敗は結果の不首尾で、自分から断る行為ではない。"}, {"text": "彼は最終電車を失敗した。", "explanation": "ここは〈乗り遅れる〉（乗り物に間に合わず逃すこと）の意味。失敗は目的を果たせなかった結果で、乗り物を逃す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51998, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失敗", "is_correct": true, "explanation": "値上げ政策がうまくいかなかったことを表す。客が減った結果と合う。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は政策の結果とは関係がなく、文脈に合わない。"}, {"text": "遠慮", "is_correct": false, "explanation": "遠慮は控えめにすることで、政策の結果を表せない。"}, {"text": "気絶", "is_correct": false, "explanation": "気絶は意識を失うことで、政策の結果には当てはまらない。"}], "explanations": {"失敗": "値上げ政策がうまくいかなかったことを表す。客が減った結果と合う。", "感謝": "感謝は政策の結果とは関係がなく、文脈に合わない。", "遠慮": "遠慮は控えめにすることで、政策の結果を表せない。", "気絶": "気絶は意識を失うことで、政策の結果には当てはまらない。"}, "sentence_index": 6, "correct_answer": "失敗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体調不良のため、彼は学校を失敗した。", "explanation": "ここは〈欠席〉（休むこと）の意味。失敗は試みの結果がうまくいかないことで、休むことには使えない。"}, {"text": "結果を聞いて、彼は失敗した。", "explanation": "ここは〈失望〉（がっかりすること）の意味。失敗は行為の結果で、感情は表さない。"}, {"text": "暑さで、彼は廊下で失敗した。", "explanation": "ここは〈失神〉（気を失うこと）の意味。失敗は目的を果たせなかったことで、意識を失う意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51998, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その挑戦は準備不足で失敗を終わった。", "corrected_sentence": "その挑戦は準備不足で失敗に終わった。", "error_description": "「失敗に終わる」の「に」が正しい。「失敗を終わった」は誤り（終わるは「に」で結果を示す）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51998, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は実験に失敗ても、落ち込んだ。", "corrected_sentence": "彼は実験に失敗して、落ち込んだ。", "error_description": "「失敗する」の接続形は「失敗して」。「失敗ても」は活用が誤り。正しくは「失敗して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52003, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「エコシステムとは」の「と」。語の定義を示す形で、語を主題として提示する。"}, {"text": "が", "is_correct": false, "explanation": "「エコシステムがは」と続くと成立しない。主語の「が」は「は」と重ねられない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「エコシステムをは」となり、文の形が成り立たない。"}, {"text": "も", "is_correct": false, "explanation": "「エコシステムもは」は成り立たず、「は」と重ねられない。"}], "correct_answer": "と", "explanations": {"と": "「エコシステムとは」の「と」。語の定義を示す形で、語を主題として提示する。", "が": "「エコシステムがは」と続くと成立しない。主語の「が」は「は」と重ねられない。", "を": "目的語の「を」は「エコシステムをは」となり、文の形が成り立たない。", "も": "「エコシステムもは」は成り立たず、「は」と重ねられない。"}, "error_tags": {"が": "主語", "を": "目的語", "も": "並立・強調"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
