INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52003, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いろいろなものがつながって、いっしょにうごくしくみのこと。", "primary_collocate": null, "pronunciation": "えこしすてむ", "ipa": "ekoɕisutemu", "syllable_count": 6, "sentences": [{"text": "池のエコシステムでは、魚も草も水もつながっている。", "target_word": "エコシステム", "complexity_tier": "T2", "furigana": "池[いけ]のエコシステムでは、魚[さかな]も草[くさ]も水[みず]もつながっている。", "sentence_source": "generated"}, {"text": "エコシステムとは、いろいろなものがつながる仕組みのことだ。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "エコシステムとは、いろいろなものがつながる仕組[しく]みのことだ。", "sentence_source": "generated"}, {"text": "森のエコシステムを守るために、木を切りすぎないようにしている。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "森[もり]のエコシステムを守[まも]るために、木[き]を切[き]りすぎないようにしている。", "sentence_source": "generated"}, {"text": "このゲーム会社は、ゲームとグッズが一緒に動くエコシステムを作った。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "このゲーム会社[がいしゃ]は、ゲームとグッズが一緒[いっしょ]に動[うご]くエコシステムを作[つく]った。", "sentence_source": "generated"}, {"text": "虫がいなくなると、畑のエコシステムが変わってしまう。", "target_word": "エコシステム", "complexity_tier": "T2", "furigana": "虫[むし]がいなくなると、畑[はたけ]のエコシステムが変[か]わってしまう。", "sentence_source": "generated"}, {"text": "海のエコシステムについて、小学生が発表した。", "target_word": "エコシステム", "complexity_tier": "T2", "furigana": "海[うみ]のエコシステムについて、小学生[しょうがくせい]が発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "町の店と学校が協力して、小さなエコシステムができた。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "町[まち]の店[みせ]と学校[がっこう]が協力[きょうりょく]して、小[ちい]さなエコシステムができた。", "sentence_source": "generated"}, {"text": "水がよごれたせいで、川のエコシステムがこわれた。", "target_word": "エコシステム", "complexity_tier": "T2", "furigana": "水[みず]がよごれたせいで、川[かわ]のエコシステムがこわれた。", "sentence_source": "generated"}, {"text": "私たちはエコシステムの一部として生きている。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "私[わたし]たちはエコシステムの一部[いちぶ]として生[い]きている。", "sentence_source": "generated"}, {"text": "新しいアプリのエコシステムには、たくさんの人が参加している。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "新[あたら]しいアプリのエコシステムには、たくさんの人[ひと]が参加[さんか]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エコシステム", "label": "基本形"}, {"form": "エコシステムの", "label": "連体修飾（の）"}], "register": "話し言葉（日常・やさしい説明）", "sense_fingerprint": "いろいろなものがつながり、いっしょに動いている仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52003, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エコシステム", "is_correct": true, "explanation": "「池のエコシステム」は、池という場での生き物のつながりを指し、魚・草・水の話と合う。"}, {"text": "時間", "is_correct": false, "explanation": "「池の時間では、魚も草も水もつながっている」は意味が通らない。場所の仕組みを表す語として「時間」は合わない。"}, {"text": "言葉", "is_correct": false, "explanation": "「池の言葉では」は不自然で、生き物のつながりの説明には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「池の天気では」は意味が通らない。魚や草のつながりを示す語として「天気」は当てはまらない。"}], "explanations": {"エコシステム": "「池のエコシステム」は、池という場での生き物のつながりを指し、魚・草・水の話と合う。", "時間": "「池の時間では、魚も草も水もつながっている」は意味が通らない。場所の仕組みを表す語として「時間」は合わない。", "言葉": "「池の言葉では」は不自然で、生き物のつながりの説明には合わない。", "天気": "「池の天気では」は意味が通らない。魚や草のつながりを示す語として「天気」は当てはまらない。"}, "sentence_index": 0, "correct_answer": "エコシステム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎晩、ひとりのエコシステムで静かに過ごしている。", "explanation": "〈生活環境〉の意味。ひとりの暮らしの場には「生活環境」を使う。エコシステムは複数のものがつながって働く仕組みを指すので、ひとりだけの場には合わない。"}, {"text": "この川には、珍しいエコシステムが何匹も泳いでいる。", "explanation": "〈生物〉の意味。エコシステムはつながって動く仕組みで、個々の生き物を数えたり泳がせたりする語ではないので合わない。"}, {"text": "この店はエコシステムをたくさん並べ、客を集めている。", "explanation": "〈商品〉の意味。店に並べるのは商品で、エコシステムは仕組みを表す語なので、陳列の対象としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52003, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エコシステム", "is_correct": true, "explanation": "「小さなエコシステム」は、店と学校が協力してできた小さなつながりの仕組みを指し、文の意味と合う。"}, {"text": "気温", "is_correct": false, "explanation": "「小さな気温ができた」は意味をなさない。協力して生まれたものを表す語として「気温」は合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「小さな体重ができた」は成立しない。協力関係を表す語として「体重」は当てはまらない。"}, {"text": "季節", "is_correct": false, "explanation": "「小さな季節ができた」は不自然で、協力によって生まれた仕組みを表す語としては合わない。"}], "explanations": {"エコシステム": "「小さなエコシステム」は、店と学校が協力してできた小さなつながりの仕組みを指し、文の意味と合う。", "気温": "「小さな気温ができた」は意味をなさない。協力して生まれたものを表す語として「気温」は合わない。", "体重": "「小さな体重ができた」は成立しない。協力関係を表す語として「体重」は当てはまらない。", "季節": "「小さな季節ができた」は不自然で、協力によって生まれた仕組みを表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "エコシステム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女はエコシステムが広く、新しい取引先を次々と見つけた。", "explanation": "〈人脈〉の意味。人との交友関係の広さには「人脈」を使う。エコシステムは仕組みを指すので、人について「広い」とは言わない。"}, {"text": "この会社は毎年、新しいエコシステムを三つ発売している。", "explanation": "〈製品〉の意味。売り出すのは製品で、エコシステムは仕組みを表すので、発売の対象としては合わない。"}, {"text": "大会には、たくさんのエコシステムが参加している。", "explanation": "〈選手〉の意味。大会に参加するのは選手やチームで、エコシステムという仕組みは参加の主体にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52003, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草を刈りすぎたせいで、池のエコシステムを変わってしまった。", "corrected_sentence": "草を刈りすぎたせいで、池のエコシステムが変わってしまった。", "error_description": "「変わる」は自動詞なので、主語のエコシステムには「が」を使う。誤りは「を」で、正しくは「エコシステムが変わってしまった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52003, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域の人たちが協力して、小さなエコシステムが育てている。", "corrected_sentence": "地域の人たちが協力して、小さなエコシステムが育っている。", "error_description": "「育てる」は他動詞で、主語のエコシステムとは合わない。自動詞の「育つ」を使い、正しくは「エコシステムが育っている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52004, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「では」の「で」。森のエコシステムを話題の場面として示す形で、空所に入る。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」は「は」と続けると「がは」となり成立しない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だが、「を」の後に「は」は続かず、この位置では文が成り立たない。"}, {"text": "も", "is_correct": false, "explanation": "「森のエコシステムもは」は成り立たず、「は」と重ねられない。"}], "correct_answer": "で", "explanations": {"で": "「では」の「で」。森のエコシステムを話題の場面として示す形で、空所に入る。", "が": "主語の「が」は「は」と続けると「がは」となり成立しない。", "を": "目的語の「を」だが、「を」の後に「は」は続かず、この位置では文が成り立たない。", "も": "「森のエコシステムもは」は成り立たず、「は」と重ねられない。"}, "error_tags": {"が": "主語", "を": "目的語", "も": "並立・強調"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52004, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「エコシステムを強くする」の「を」。強くする対象を示す目的語。"}, {"text": "が", "is_correct": false, "explanation": "「強くする」は他動詞で目的語が必要なので、主語の「が」は入らず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すが、「エコシステムに強くする」では動詞と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「エコシステムと強くする」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「エコシステムを強くする」の「を」。強くする対象を示す目的語。", "が": "「強くする」は他動詞で目的語が必要なので、主語の「が」は入らず、文が成り立たない。", "に": "「に」は相手や方向を示すが、「エコシステムに強くする」では動詞と合わない。", "と": "「と」は並列や相手を示すが、「エコシステムと強くする」では文が成り立たない。"}, "error_tags": {"が": "主語", "に": "相手・方向", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52004, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある地域や環境で、生物とその周囲の環境が相互に影響し合い、一つのまとまりとして機能するシステム。また、ビジネスやテクノロジーの分野でも、関係する要素が連携して全体を形作る仕組みを指す。", "primary_collocate": null, "pronunciation": "えこしすてむ", "ipa": "ekoɕisutemu", "syllable_count": 6, "sentences": [{"text": "さらに、こうした資金供給メカニズムは、エコシステム全体に好循環をもたらす。", "target_word": "エコシステム", "complexity_tier": "T5", "furigana": "さらに、こうした資金供給[しきんきょうきゅう]メカニズムは、エコシステム全体[ぜんたい]に好循環[こうじゅんかん]をもたらす。", "sentence_source": "mined"}, {"text": "森のエコシステムでは、植物も虫も動物もたがいに支えあっている。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "森[もり]のエコシステムでは、植物[しょくぶつ]も虫[むし]も動物[どうぶつ]もたがいに支[ささ]えあっている。", "sentence_source": "generated"}, {"text": "湖に外来魚が入り、エコシステムのバランスがくずれた。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "湖[みずうみ]に外来魚[がいらいぎょ]が入[はい]り、エコシステムのバランスがくずれた。", "sentence_source": "generated"}, {"text": "この会社はアプリ開発者を集め、独自のエコシステムを築いた。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]はアプリ開発者[かいはつしゃ]を集[あつ]め、独自[どくじ]のエコシステムを築[きず]いた。", "sentence_source": "generated"}, {"text": "川を守る活動は、地域のエコシステムを維持するために欠かせない。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "川[かわ]を守[まも]る活動[かつどう]は、地域[ちいき]のエコシステムを維持[いじ]するために欠[か]かせない。", "sentence_source": "generated"}, {"text": "スマートフォンのエコシステムが広がり、関連商品も増えている。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "スマートフォンのエコシステムが広[ひろ]がり、関連商品[かんれんしょうひん]も増[ふ]えている。", "sentence_source": "generated"}, {"text": "研究者は、サンゴ礁のエコシステムが温暖化の影響を受けていると報告した。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、サンゴ礁[しょう]のエコシステムが温暖化[おんだんか]の影響[えいきょう]を受[う]けていると報告[ほうこく]した。", "sentence_source": "generated"}, {"text": "起業家と投資家が交流する場が、地域のエコシステムを強くする。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "起業家[きぎょうか]と投資家[とうしか]が交流[こうりゅう]する場[ば]が、地域[ちいき]のエコシステムを強[つよ]くする。", "sentence_source": "generated"}, {"text": "海のエコシステムを調べるため、調査船が出発した。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "海[うみ]のエコシステムを調[しら]べるため、調査船[ちょうさせん]が出発[しゅっぱつ]した。", "sentence_source": "generated"}, {"text": "部品メーカーを含むエコシステム全体で、新しい電池の開発を進めている。", "target_word": "エコシステム", "complexity_tier": "T3", "furigana": "部品[ぶひん]メーカーを含[ふく]むエコシステム全体[ぜんたい]で、新[あたら]しい電池[でんち]の開発[かいはつ]を進[すす]めている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エコシステム", "label": "基本形"}, {"form": "エコシステムの", "label": "連体修飾（の）"}], "register": "書き言葉（やや硬い・専門的）", "sense_fingerprint": "生物と環境、またはビジネス・技術の要素が相互に連携してまとまる全体の仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52004, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エコシステム", "is_correct": true, "explanation": "「エコシステム全体」は、資金の流れが業界や地域の仕組み全体に作用することを示し、文の意味と合う。"}, {"text": "時間", "is_correct": false, "explanation": "「時間全体に好循環をもたらす」は意味をなさない。資金供給が作用する対象として「時間」は合わない。"}, {"text": "言葉", "is_correct": false, "explanation": "「言葉全体に好循環をもたらす」は不自然。作用の対象になるのは仕組みや市場で、「言葉」は合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気全体に好循環をもたらす」は意味が通らない。資金供給メカニズムの作用先として「天気」は当てはまらない。"}], "explanations": {"エコシステム": "「エコシステム全体」は、資金の流れが業界や地域の仕組み全体に作用することを示し、文の意味と合う。", "時間": "「時間全体に好循環をもたらす」は意味をなさない。資金供給が作用する対象として「時間」は合わない。", "言葉": "「言葉全体に好循環をもたらす」は不自然。作用の対象になるのは仕組みや市場で、「言葉」は合わない。", "天気": "「天気全体に好循環をもたらす」は意味が通らない。資金供給メカニズムの作用先として「天気」は当てはまらない。"}, "sentence_index": 0, "correct_answer": "エコシステム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この池には、たくさんのエコシステムが泳いでいる。", "explanation": "〈生物〉の意味。エコシステムは生き物と環境がつながる仕組み全体を指すので、個々の生物として泳ぐものには合わない。"}, {"text": "このエコシステムは古くて遅いので、来月入れ替えることになった。", "explanation": "〈情報機器〉の意味。古くて遅いコンピュータ機器や業務ソフトを入れ替える話には「情報機器」を使う。エコシステムは生物や業界のつながりを指すので、入れ替える対象にはならない。"}, {"text": "職人は工房にこもり、ひとりで一つのエコシステムを仕上げている。", "explanation": "〈作品〉を仕上げる文。エコシステムは多くの要素が連携する仕組みを指すので、ひとりで仕上げる対象ではなく合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52004, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エコシステム", "is_correct": true, "explanation": "「サンゴ礁のエコシステム」は、温暖化の影響を受ける生物と環境の全体を指し、報告の内容と合う。"}, {"text": "会議", "is_correct": false, "explanation": "「サンゴ礁の会議が温暖化の影響を受けている」は意味をなさない。サンゴ礁の状態を表す語として「会議」は合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "「サンゴ礁の手紙が温暖化の影響を受けている」は成立しない。自然環境の状態を表す語として合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「サンゴ礁の体重」は意味が通らない。環境の状態を指す語として「体重」は当てはまらない。"}], "explanations": {"エコシステム": "「サンゴ礁のエコシステム」は、温暖化の影響を受ける生物と環境の全体を指し、報告の内容と合う。", "会議": "「サンゴ礁の会議が温暖化の影響を受けている」は意味をなさない。サンゴ礁の状態を表す語として「会議」は合わない。", "手紙": "「サンゴ礁の手紙が温暖化の影響を受けている」は成立しない。自然環境の状態を表す語として合わない。", "体重": "「サンゴ礁の体重」は意味が通らない。環境の状態を指す語として「体重」は当てはまらない。"}, "sentence_index": 6, "correct_answer": "エコシステム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はエコシステムが広く、困った時にいつも助けてもらえる。", "explanation": "〈人脈〉の意味。人の交友関係の広さには「人脈」を使う。エコシステムは仕組み全体を指すので、人について「広い」とは言わない。"}, {"text": "この工場では毎日、新しいエコシステムを生産している。", "explanation": "〈部品〉を生産する文。エコシステムは連携する仕組みを指し、量産して出荷する物ではないので、生産の対象として合わない。"}, {"text": "このエコシステムは社長の指示で動き、判断も早い。", "explanation": "〈組織〉の意味。中心の指示で動く組織と違い、エコシステムは多くの要素がつながって働く仕組みなので、判断して動くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52004, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ダムができてから、川のエコシステムを壊れた。", "corrected_sentence": "ダムができてから、川のエコシステムが壊れた。", "error_description": "「壊れる」は自動詞なので、主語のエコシステムには「が」を使う。誤りは「を」で、正しくは「エコシステムが壊れた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52004, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域では、農家と研究所が協力して、豊かな農業のエコシステムに育てている。", "corrected_sentence": "この地域では、農家と研究所が協力して、豊かな農業のエコシステムを育てている。", "error_description": "「育てる」は他動詞なので目的語に「を」を使う。「に」は誤りで、正しくは「エコシステムを育てている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
