INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52005, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても強い力があること。", "primary_collocate": null, "pronunciation": "きょうりょく", "ipa": "kʲoːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "このライトはとても強力で、遠くまで光が届く。", "target_word": "強力", "complexity_tier": "T2", "furigana": "このライトはとても強力[きょうりょく]で、遠[とお]くまで光[ひかり]が届[とど]く。", "sentence_source": "generated"}, {"text": "強力な風のせいで、傘がこわれてしまった。", "target_word": "強力", "complexity_tier": "T2", "furigana": "強力[きょうりょく]な風[かぜ]のせいで、傘[かさ]がこわれてしまった。", "sentence_source": "generated"}, {"text": "兄は強力なバネを使って、おもちゃを高くとばした。", "target_word": "強力", "complexity_tier": "T3", "furigana": "兄[あに]は強力[きょうりょく]なバネを使[つか]って、おもちゃを高[たか]くとばした。", "sentence_source": "generated"}, {"text": "この掃除機は強力なので、じゅうたんのごみもすぐ取れる。", "target_word": "強力", "complexity_tier": "T3", "furigana": "この掃除機[そうじき]は強力[きょうりょく]なので、じゅうたんのごみもすぐ取[と]れる。", "sentence_source": "generated"}, {"text": "強力な磁石は、鉄のものをぐっと引きつける。", "target_word": "強力", "complexity_tier": "T3", "furigana": "強力[きょうりょく]な磁石[じしゃく]は、鉄[てつ]のものをぐっと引[ひ]きつける。", "sentence_source": "generated"}, {"text": "強力なクレーンが、重い鉄骨を軽々と持ち上げた。", "target_word": "強力", "complexity_tier": "T3", "furigana": "強力[きょうりょく]なクレーンが、重[おも]い鉄骨[てっこつ]を軽々[かるがる]と持[も]ち上[あ]げた。", "sentence_source": "generated"}, {"text": "この虫よけスプレーは強力で、蚊がまったく寄ってこない。", "target_word": "強力", "complexity_tier": "T3", "furigana": "この虫[むし]よけスプレーは強力[きょうりょく]で、蚊[か]がまったく寄[よ]ってこない。", "sentence_source": "generated"}, {"text": "強力なモーターのおかげで、車は坂道を速く登れた。", "target_word": "強力", "complexity_tier": "T3", "furigana": "強力[きょうりょく]なモーターのおかげで、車[くるま]は坂道[さかみち]を速[はや]く登[のぼ]れた。", "sentence_source": "generated"}, {"text": "大きな犬が強力な力で引っぱったので、手が痛かった。", "target_word": "強力", "complexity_tier": "T3", "furigana": "大[おお]きな犬[いぬ]が強力[きょうりょく]な力[ちから]で引[ひ]っぱったので、手[て]が痛[いた]かった。", "sentence_source": "generated"}, {"text": "強力なエンジンを積んだ船が、波をけって進んだ。", "target_word": "強力", "complexity_tier": "T3", "furigana": "強力[きょうりょく]なエンジンを積[つ]んだ船[ふね]が、波[なみ]をけって進[すす]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強力だ", "label": "終止形"}, {"form": "強力な", "label": "連体形"}, {"form": "強力に", "label": "連用形"}, {"form": "強力で", "label": "連用形（で）"}], "register": "話し言葉（日常・中立）", "sense_fingerprint": "物や人の力がとても強いこと（道具・機械・風などの強さ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 引っぱっ (Zipf 2.14)']::text[], '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52005, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強力", "is_correct": true, "explanation": "「とても強力で」は光の強さを示し、遠くまで光が届くという結果と合う。"}, {"text": "静か", "is_correct": false, "explanation": "「とても静かで、遠くまで光が届く」は意味が合わない。光の性質を表す語として「静か」は不適切。"}, {"text": "退屈", "is_correct": false, "explanation": "「とても退屈で、遠くまで光が届く」は意味が通らない。ライトの性能を表す語として合わない。"}, {"text": "不要", "is_correct": false, "explanation": "「不要で、遠くまで光が届く」は意味が矛盾する。光の届く距離とは結びつかない。"}], "explanations": {"強力": "「とても強力で」は光の強さを示し、遠くまで光が届くという結果と合う。", "静か": "「とても静かで、遠くまで光が届く」は意味が合わない。光の性質を表す語として「静か」は不適切。", "退屈": "「とても退屈で、遠くまで光が届く」は意味が通らない。ライトの性能を表す語として合わない。", "不要": "「不要で、遠くまで光が届く」は意味が矛盾する。光の届く距離とは結びつかない。"}, "sentence_index": 0, "correct_answer": "強力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店員さんが強力で、道を丁寧に教えてくれた。", "explanation": "〈親切〉の意味。人の態度の優しさには「親切」を使う。「強力」は力の強さを表すので、人の態度の形容には合わない。"}, {"text": "このクッションは強力で、座ると体が沈む。", "explanation": "〈柔らかい〉の意味。触った感じや沈み込みには「柔らかい」を使う。「強力」は力の強さに用いるので合わない。"}, {"text": "祖父は強力で、いつも口数が少ない。", "explanation": "〈無口〉の意味。話す量の少なさには「無口」を使う。「強力」は力の強さを表すので、性格の形容には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52005, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強力", "is_correct": true, "explanation": "「強力で、蚊がまったく寄ってこない」は、スプレーの効き目の強さを述べ、文の結果と合う。"}, {"text": "平ら", "is_correct": false, "explanation": "「平らで、蚊がまったく寄ってこない」は意味が通らない。効き目を表す語として合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気で、蚊がまったく寄ってこない」は文の論理と合わない。スプレーの性質を表す語ではない。"}, {"text": "厳粛", "is_correct": false, "explanation": "「厳粛で、蚊がまったく寄ってこない」は成立しない。効き目の説明として不自然。"}], "explanations": {"強力": "「強力で、蚊がまったく寄ってこない」は、スプレーの効き目の強さを述べ、文の結果と合う。", "平ら": "「平らで、蚊がまったく寄ってこない」は意味が通らない。効き目を表す語として合わない。", "陽気": "「陽気で、蚊がまったく寄ってこない」は文の論理と合わない。スプレーの性質を表す語ではない。", "厳粛": "「厳粛で、蚊がまったく寄ってこない」は成立しない。効き目の説明として不自然。"}, "sentence_index": 6, "correct_answer": "強力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この浴室は強力で、毎朝気持ちがいい。", "explanation": "〈清潔〉の意味。部屋の汚れのなさには「清潔」を使う。「強力」は力や効果の強さを表すので、浴室の状態の形容には合わない。"}, {"text": "この倉庫は強力で、大型トラックも三台入る。", "explanation": "〈広い〉の意味。空間の大きさには「広い」を使う。「強力」は力の強さを表すので、空間の形容には合わない。"}, {"text": "この布は強力で、夏でも涼しく過ごせる。", "explanation": "〈薄い〉の意味。布の薄さや通気性には「薄い」を使う。「強力」は力の強さに用いるので、布の性質には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52005, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この扇風機は強力くて風を送るので、夏の部屋がすぐに涼しくなる。", "corrected_sentence": "この扇風機は強力な風を送るので、夏の部屋がすぐに涼しくなる。", "error_description": "「強力」は形状詞なので、名詞の前では「な」を使う。「強力くて」は形容詞の活用としても誤り。正しくは「強力な風」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強力な", "is_correct": true, "explanation": "連体形で、名詞「風」を修飾する。この文の形と合う。"}, {"text": "強力だ", "is_correct": false, "explanation": "終止形で、名詞を直接修飾できない。「風」の前には置けない。"}, {"text": "強力に", "is_correct": false, "explanation": "連用形で、名詞「風」を修飾できない。"}, {"text": "強力で", "is_correct": false, "explanation": "連用形で、名詞「風」の前には置けない。"}], "correct_form": "強力な", "base_form": "強力", "form_label": "連体形", "sentence_index": 1, "explanations": {"強力な": "連体形で、名詞「風」を修飾する。この文の形と合う。", "強力だ": "終止形で、名詞を直接修飾できない。「風」の前には置けない。", "強力に": "連用形で、名詞「風」を修飾できない。", "強力で": "連用形で、名詞「風」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52005, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この接着剤は強力ので、割れた陶器もしっかりくっつく。", "corrected_sentence": "この接着剤は強力なので、割れた陶器もしっかりくっつく。", "error_description": "「強力」は形状詞なので、「ので」の前に「な」が必要。「強力ので」は誤りで、正しくは「強力なので」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強力な", "is_correct": true, "explanation": "連体形で、名詞「モーター」を修飾する。この文の形と合う。"}, {"text": "強力に", "is_correct": false, "explanation": "連用形で、名詞「モーター」を修飾できない。"}, {"text": "強力そうだ", "is_correct": false, "explanation": "様子の推測を表す述語形で、名詞の前には置けない。"}, {"text": "強力だろう", "is_correct": false, "explanation": "推量の述語形で、名詞「モーター」を修飾できない。"}], "correct_form": "強力な", "base_form": "強力", "form_label": "連体形", "sentence_index": 7, "explanations": {"強力な": "連体形で、名詞「モーター」を修飾する。この文の形と合う。", "強力に": "連用形で、名詞「モーター」を修飾できない。", "強力そうだ": "様子の推測を表す述語形で、名詞の前には置けない。", "強力だろう": "推量の述語形で、名詞「モーター」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
