INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52006, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "他を押し切るほどの、非常に強い力や効果を持つさま。", "primary_collocate": null, "pronunciation": "きょうりょく", "ipa": "kʲoːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "強力", "complexity_tier": "T5", "furigana": "資金[しきん]のみならず、経営[けいえい]の知見[ちけん]や人的[じんてき]ネットワークが注入[ちゅうにゅう]されることで、個々[ここ]の企業[きぎょう]の成長[せいちょう]が触発[しょくはつ]され、結果[けっか]として社会実装[しゃかいじっそう]を加速[かそく]させ、ひいては経済構造[けいざいこうぞう]の変革[へんかく]を促[うなが]す強力[きょうりょく]な原動力[げんどうりょく]となるのだ。", "sentence_source": "mined"}, {"text": "この薬は強力な効果があり、医師の指示なしに使ってはいけない。", "target_word": "強力", "complexity_tier": "T3", "furigana": "この薬[くすり]は強力[きょうりょく]な効果[こうか]があり、医師[いし]の指示[しじ]なしに使[つか]ってはいけない。", "sentence_source": "generated"}, {"text": "強力な台風が近づいているため、早めに帰宅するよう呼びかけられた。", "target_word": "強力", "complexity_tier": "T3", "furigana": "強力[きょうりょく]な台風[たいふう]が近[ちか]づいているため、早[はや]めに帰宅[きたく]するよう呼[よ]びかけられた。", "sentence_source": "generated"}, {"text": "彼女は強力なリーダーシップでチームをまとめた。", "target_word": "強力", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は強力[きょうりょく]なリーダーシップでチームをまとめた。", "sentence_source": "generated"}, {"text": "新製品は競合他社に対して強力な武器になる。", "target_word": "強力", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]は競合他社[きょうごうたしゃ]に対[たい]して強力[きょうりょく]な武器[ぶき]になる。", "sentence_source": "generated"}, {"text": "強力な宣伝のおかげで、新商品は一週間で売り切れた。", "target_word": "強力", "complexity_tier": "T3", "furigana": "強力[きょうりょく]な宣伝[せんでん]のおかげで、新商品[しんしょうひん]は一週間[いっしゅうかん]で売り切れた。", "sentence_source": "generated"}, {"text": "強力な味方がいたので、交渉は有利に進んだ。", "target_word": "強力", "complexity_tier": "T3", "furigana": "強力[きょうりょく]な味方[みかた]がいたので、交渉[こうしょう]は有利[ゆうり]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "この洗剤は汚れに強力に作用し、一度で油が落ちる。", "target_word": "強力", "complexity_tier": "T3", "furigana": "この洗剤[せんざい]は汚[よご]れに強力[きょうりょく]に作用[さよう]し、一度[いちど]で油[あぶら]が落[お]ちる。", "sentence_source": "generated"}, {"text": "証拠が強力だったため、裁判所は訴えを認めた。", "target_word": "強力", "complexity_tier": "T3", "furigana": "証拠[しょうこ]が強力[きょうりょく]だったため、裁判所[さいばんしょ]は訴[うった]えを認[みと]めた。", "sentence_source": "generated"}, {"text": "強力な対策を取らなければ、被害は広がるだろう。", "target_word": "強力", "complexity_tier": "T3", "furigana": "強力[きょうりょく]な対策[たいさく]を取[と]らなければ、被害[ひがい]は広[ひろ]がるだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強力だ", "label": "終止形"}, {"form": "強力な", "label": "連体形"}, {"form": "強力に", "label": "連用形"}, {"form": "強力で", "label": "連用形（で）"}], "register": "書き言葉（やや硬い）", "sense_fingerprint": "他を圧倒するほど力や効果が非常に強いさま（効果・影響・武器などに使う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 6 words above tier T2 (max 3): 知見 (Zipf 3.42), 人的 (Zipf 3.67), 触発 (Zipf 3.32), ひいては (Zipf 3.24), 変革 (Zipf 3.6), 原動力 (Zipf 3.4)']::text[], '355324e3-e01a-4ed1-889d-ea18f36ee50a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52006, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強力", "is_correct": true, "explanation": "「促す強力な原動力」は、資金や知見が成長を強く動かすことを示し、文の意味と合う。"}, {"text": "静か", "is_correct": false, "explanation": "「促す静かな原動力」は意味が矛盾する。変革を強く促す働きと「静か」は合わない。"}, {"text": "不要", "is_correct": false, "explanation": "「促す不要な原動力」は成立しない。原動力を修飾する語として「不要」は合わない。"}, {"text": "平凡", "is_correct": false, "explanation": "「促す平凡な原動力」は意味が通らない。変革を強く促す文脈では「平凡」は合わない。"}], "explanations": {"強力": "「促す強力な原動力」は、資金や知見が成長を強く動かすことを示し、文の意味と合う。", "静か": "「促す静かな原動力」は意味が矛盾する。変革を強く促す働きと「静か」は合わない。", "不要": "「促す不要な原動力」は成立しない。原動力を修飾する語として「不要」は合わない。", "平凡": "「促す平凡な原動力」は意味が通らない。変革を強く促す文脈では「平凡」は合わない。"}, "sentence_index": 0, "correct_answer": "強力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は強力で、十人が一度に座れる。", "explanation": "〈広い〉の意味。空間の広さには「広い」を使う。「強力」は力や効果の強さを表すので、部屋の形容には合わない。"}, {"text": "彼女は強力な成績で大学を卒業した。", "explanation": "〈優秀〉の意味。成績の良さには「優秀」を使う。「強力」は力や効果の強さを表すので、成績の形容には合わない。"}, {"text": "この金庫は強力で、表面が鏡のようにつるつるしている。", "explanation": "〈なめらか〉の意味。表面の滑らかさには「なめらか」を使う。「強力」は力や効果の強さに用いるので、表面の形容には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52006, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強力", "is_correct": true, "explanation": "「強力な味方」は、交渉を有利に進めるほど力のある味方を表し、文の意味と合う。"}, {"text": "愉快", "is_correct": false, "explanation": "「愉快な味方」は文脈の交渉の効果と結びつかない。力や効果の強さを示す語ではない。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈な味方」は交渉を有利に進めた理由にならず、文の論理と合わない。"}, {"text": "陰気", "is_correct": false, "explanation": "「陰気な味方」は交渉を有利に進めた結果と結びつかず、文の意味と合わない。"}], "explanations": {"強力": "「強力な味方」は、交渉を有利に進めるほど力のある味方を表し、文の意味と合う。", "愉快": "「愉快な味方」は文脈の交渉の効果と結びつかない。力や効果の強さを示す語ではない。", "退屈": "「退屈な味方」は交渉を有利に進めた理由にならず、文の論理と合わない。", "陰気": "「陰気な味方」は交渉を有利に進めた結果と結びつかず、文の意味と合わない。"}, "sentence_index": 6, "correct_answer": "強力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このお酒は強力で、食事と一緒に楽しむと味がまろやかになる。", "explanation": "〈まろやか〉の意味。味のやわらかさには「まろやか」を使う。「強力」は力や効果の強さを表すので、味の形容には合わない。"}, {"text": "彼は指先が強力で、細かい細工もすいすい進める。", "explanation": "〈器用〉の意味。指先の巧みさには「器用」を使う。「強力」は力や効果の強さに用いるので、指先の器用さには合わない。"}, {"text": "この図書館はとても強力で、勉強に集中できる。", "explanation": "〈静か〉の意味。場所の静けさには「静か」を使う。「強力」は力の強さを表すので、図書館の雰囲気には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52006, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は強力い支援を受けて、計画を一気に進めた。", "corrected_sentence": "彼は強力な支援を受けて、計画を一気に進めた。", "error_description": "「強力」は形状詞なので、名詞の前では「な」を使う。「強力い」は形容詞の活用で誤り。正しくは「強力な支援」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強力な", "is_correct": true, "explanation": "連体形で、名詞「効果」を修飾する。この文の形と合う。"}, {"text": "強力だ", "is_correct": false, "explanation": "終止形で、名詞を直接修飾できない。「効果」の前には置けない。"}, {"text": "強力そうだ", "is_correct": false, "explanation": "様子の推測を表す述語形で、名詞「効果」を直接修飾できない。"}, {"text": "強力だろう", "is_correct": false, "explanation": "推量の述語形で、名詞「効果」を修飾できない。"}], "correct_form": "強力な", "base_form": "強力", "form_label": "連体形", "sentence_index": 1, "explanations": {"強力な": "連体形で、名詞「効果」を修飾する。この文の形と合う。", "強力だ": "終止形で、名詞を直接修飾できない。「効果」の前には置けない。", "強力そうだ": "様子の推測を表す述語形で、名詞「効果」を直接修飾できない。", "強力だろう": "推量の述語形で、名詞「効果」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52006, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は強力だモーターのおかげで、重い鉄材も持ち上げられる。", "corrected_sentence": "この機械は強力なモーターのおかげで、重い鉄材も持ち上げられる。", "error_description": "「強力だ」は述語の形で、名詞「モーター」を修飾できない。連体形「強力な」が必要で、誤りは「だ」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強力に", "is_correct": true, "explanation": "連用形で、動詞「作用し」を修飾する。この文の形と合う。"}, {"text": "強力な", "is_correct": false, "explanation": "連体形で名詞を修飾する形。「汚れに」の後の動詞を修飾できない。"}, {"text": "強力すぎる", "is_correct": false, "explanation": "過剰を表す語形で、この文の作用の仕方を述べる文脈とは合わない。"}, {"text": "強力そうだ", "is_correct": false, "explanation": "様子の推測を表す形で、作用の仕方を述べる文には合わない。"}], "correct_form": "強力に", "base_form": "強力", "form_label": "連用形", "sentence_index": 7, "explanations": {"強力に": "連用形で、動詞「作用し」を修飾する。この文の形と合う。", "強力な": "連体形で名詞を修飾する形。「汚れに」の後の動詞を修飾できない。", "強力すぎる": "過剰を表す語形で、この文の作用の仕方を述べる文脈とは合わない。", "強力そうだ": "様子の推測を表す形で、作用の仕方を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42f22950-5f64-474d-90ee-b5abe96404c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52007, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「注入」は入れるもの（熱い金属）に「を」を取る。「熱い金属を注入して」で正しい。"}, {"text": "に", "is_correct": false, "explanation": "「金属に注入して」は入れる先を示すことになり、入れられる物の金属には合わない。型はすでに「型に」で示されている。"}, {"text": "が", "is_correct": false, "explanation": "「金属が注入して」は金属が主語になり、注入するのは人なので意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「金属と注入して」は並列を表し、入れる物を示せない。"}], "correct_answer": "を", "explanations": {"を": "「注入」は入れるもの（熱い金属）に「を」を取る。「熱い金属を注入して」で正しい。", "に": "「金属に注入して」は入れる先を示すことになり、入れられる物の金属には合わない。型はすでに「型に」で示されている。", "が": "「金属が注入して」は金属が主語になり、注入するのは人なので意味が合わない。", "と": "「金属と注入して」は並列を表し、入れる物を示せない。"}, "error_tags": {"に": "入れる先の重複", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52007, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「注入」は入れるもの（空気）に「を」を取る。「空気を注入した」で正しい。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。空気から注入するという不自然な意味になり、目的語としては合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞に続く。「空気の注入した」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。空気で注入するという意味になり、入れる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「注入」は入れるもの（空気）に「を」を取る。「空気を注入した」で正しい。", "から": "「から」は起点を示す。空気から注入するという不自然な意味になり、目的語としては合わない。", "の": "連体修飾の「の」は名詞に続く。「空気の注入した」では文が成り立たない。", "で": "「で」は手段や場所を示す。空気で注入するという意味になり、入れる対象を示せない。"}, "error_tags": {"から": "起点", "の": "連体修飾", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52007, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを中に入れること。", "primary_collocate": null, "pronunciation": "ちゅうにゅう", "ipa": "tɕɯːɲɯː", "syllable_count": 4, "sentences": [{"text": "看護師は点滴で患者の血管に薬を注入した。", "target_word": "注入", "complexity_tier": "T3", "furigana": "看護師[かんごし]は点滴[てんてき]で患者[かんじゃ]の血管[けっかん]に薬[くすり]を注入[ちゅうにゅう]した。", "sentence_source": "generated"}, {"text": "型に熱い金属を注入して、部品を作る。", "target_word": "注入", "complexity_tier": "T3", "furigana": "型[かた]に熱[あつ]い金属[きんぞく]を注入[ちゅうにゅう]して、部品[ぶひん]を作[つく]る。", "sentence_source": "generated"}, {"text": "車のタンクに燃料を注入する前に、エンジンを止める決まりだ。", "target_word": "注入", "complexity_tier": "T3", "furigana": "車[くるま]のタンクに燃料[ねんりょう]を注入[ちゅうにゅう]する前[まえ]に、エンジンを止[と]める決[き]まりだ。", "sentence_source": "generated"}, {"text": "職人は壁のひび割れに特別な樹脂を注入して、水漏れを防いだ。", "target_word": "注入", "complexity_tier": "T3", "furigana": "職人[しょくにん]は壁[かべ]のひび割[わ]れに特別[とくべつ]な樹脂[じゅし]を注入[ちゅうにゅう]して、水漏[みずも]れを防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "水槽に空気を注入すると、魚が元気に泳ぎ始めた。", "target_word": "注入", "complexity_tier": "T3", "furigana": "水槽[すいそう]に空気[くうき]を注入[ちゅうにゅう]すると、魚[さかな]が元気[げんき]に泳[およ]ぎ始[はじ]めた。", "sentence_source": "generated"}, {"text": "医者は傷の中に消毒液を注入して、きれいに洗った。", "target_word": "注入", "complexity_tier": "T3", "furigana": "医者[いしゃ]は傷[きず]の中[なか]に消毒液[しょうどくえき]を注入[ちゅうにゅう]して、きれいに洗[あら]った。", "sentence_source": "generated"}, {"text": "機械にオイルを注入する作業は、毎朝八時に始まる。", "target_word": "注入", "complexity_tier": "T3", "furigana": "機械[きかい]にオイルを注入[ちゅうにゅう]する作業[さぎょう]は、毎朝[まいあさ]八時[はちじ]に始[はじ]まる。", "sentence_source": "generated"}, {"text": "ポンプでタイヤに空気を注入したのに、すぐにしぼんでしまった。", "target_word": "注入", "complexity_tier": "T3", "furigana": "ポンプでタイヤに空気[くうき]を注入[ちゅうにゅう]したのに、すぐにしぼんでしまった。", "sentence_source": "generated"}, {"text": "実験では、細い管で液体を容器の中に注入した。", "target_word": "注入", "complexity_tier": "T3", "furigana": "実験[じっけん]では、細[ほそ]い管[くだ]で液体[えきたい]を容器[ようき]の中[なか]に注入[ちゅうにゅう]した。", "sentence_source": "generated"}, {"text": "ケーキの中にクリームを注入する機械が、工場で動いている。", "target_word": "注入", "complexity_tier": "T3", "furigana": "ケーキの中[なか]にクリームを注入[ちゅうにゅう]する機械[きかい]が、工場[こうじょう]で動[うご]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "注入する", "label": "基本形（サ変動詞）"}, {"form": "注入した", "label": "過去形"}, {"form": "注入される", "label": "受身形"}, {"form": "注入して", "label": "て形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "液体や気体などを、管や道具を使って物や体の中に入れること（具体的な用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52007, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注入", "is_correct": true, "explanation": "「点滴で血管に薬を注入した」は、管を通じて薬を体内に入れる意味で文に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "採掘は地中から鉱物などを掘り出すこと。薬を体に入れる話には使えない。"}, {"text": "解剖", "is_correct": false, "explanation": "解剖は生物の体を切り開いて調べること。薬を血管に入れる文脈とは逆で合わない。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫は作物などを取り入れること。薬の話には使わず、文の意味が成り立たない。"}], "explanations": {"注入": "「点滴で血管に薬を注入した」は、管を通じて薬を体内に入れる意味で文に合う。", "採掘": "採掘は地中から鉱物などを掘り出すこと。薬を体に入れる話には使えない。", "解剖": "解剖は生物の体を切り開いて調べること。薬を血管に入れる文脈とは逆で合わない。", "収穫": "収穫は作物などを取り入れること。薬の話には使わず、文の意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "注入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁の穴に木のくさびを注入して、柱を固定した。", "explanation": "ここは〈挿入〉の意味。細い物を中へさし入れるのが挿入で、くさびは流し込むものではないので注入は合わない。"}, {"text": "壁の表面に塗料を注入して、きれいにした。", "explanation": "ここは〈塗布〉の意味。表面に薄く塗るのが塗布で、注入は中に流し込むことなので表面には合わない。"}, {"text": "銃に弾を注入して、的を狙った。", "explanation": "ここは〈装填〉の意味。銃などに弾を込めるのが装填で、弾を流し込む注入とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52007, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注入", "is_correct": true, "explanation": "「機械にオイルを注入する作業」で、機械に油を流し込む作業を指し文に合う。"}, {"text": "粉砕", "is_correct": false, "explanation": "粉砕は固いものを細かく砕くこと。オイルには使わず、文の意味が成り立たない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言葉を別の言語に置き換えること。オイルには使えず、文の意味が成り立たない。"}, {"text": "鋳造", "is_correct": false, "explanation": "鋳造は溶かした金属を型に流し込んで作ること。オイルの話には使えず、文の意味に合わない。"}], "explanations": {"注入": "「機械にオイルを注入する作業」で、機械に油を流し込む作業を指し文に合う。", "粉砕": "粉砕は固いものを細かく砕くこと。オイルには使わず、文の意味が成り立たない。", "翻訳": "翻訳は言葉を別の言語に置き換えること。オイルには使えず、文の意味が成り立たない。", "鋳造": "鋳造は溶かした金属を型に流し込んで作ること。オイルの話には使えず、文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "注入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "皿の上に料理を注入する機械が、工場で動いている。", "explanation": "ここは〈盛り付け〉の意味。料理を器に並べるのが盛り付けで、料理は注入の対象にならないので合わない。"}, {"text": "箱の中に部品を注入する機械が、工場で動いている。", "explanation": "ここは〈詰める〉の意味。箱などに物を入れ込むのが詰めるで、固体の部品は流し込むものではないので注入は合わない。"}, {"text": "車にタイヤを注入する機械が、工場で動いている。", "explanation": "ここは〈装着〉の意味。部品を取り付けるのが装着で、タイヤを流し込むとは言わないので注入は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52007, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガソリンスタンドの係員は、車のタンクに燃料が注入する前に、エンジンを止めるよう求めた。", "corrected_sentence": "ガソリンスタンドの係員は、車のタンクに燃料を注入する前に、エンジンを止めるよう求めた。", "error_description": "「注入」は入れるもの（燃料）に「を」を取る。「燃料が注入する」は燃料が主語になり、誤り。正しくは「燃料を注入する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52007, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場では、機械にオイルを注入れる作業を毎朝行う。", "corrected_sentence": "工場では、機械にオイルを注入する作業を毎朝行う。", "error_description": "「注入」はサ変動詞なので「注入する」と活用する。「注入れる」は誤りで、名詞「作業」を修飾するには「注入する作業」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52008, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「注入」は入れるもの（公的資金）に「を」を取る。「公的資金を注入し」で正しい。"}, {"text": "に", "is_correct": false, "explanation": "「資金に注入」は入れる物に「に」を使う形になり、注入の対象を示せない。「銀行に」がすでに入れる先を示している。"}, {"text": "が", "is_correct": false, "explanation": "「資金が注入し」では資金が主語になり、注入するのは政府なので意味が逆になる。"}, {"text": "と", "is_correct": false, "explanation": "「資金と注入し」は並列を表し、注入の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「注入」は入れるもの（公的資金）に「を」を取る。「公的資金を注入し」で正しい。", "に": "「資金に注入」は入れる物に「に」を使う形になり、注入の対象を示せない。「銀行に」がすでに入れる先を示している。", "が": "「資金が注入し」では資金が主語になり、注入するのは政府なので意味が逆になる。", "と": "「資金と注入し」は並列を表し、注入の対象を示せない。"}, "error_tags": {"に": "入れる物への誤用", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52008, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「注入」は入れるもの（発想）に「を」を取る。「新しい発想を注入する」で正しい。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す。「発想より注入する」では、入れる対象を示せず意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞に続く。「発想の注入する」では動詞の文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。発想を出発点に流し込むという不自然な意味になり、目的語としては合わない。"}], "correct_answer": "を", "explanations": {"を": "「注入」は入れるもの（発想）に「を」を取る。「新しい発想を注入する」で正しい。", "より": "「より」は比較を表す。「発想より注入する」では、入れる対象を示せず意味が通らない。", "の": "連体修飾の「の」は名詞に続く。「発想の注入する」では動詞の文として成り立たない。", "から": "「から」は起点を示す。発想を出発点に流し込むという不自然な意味になり、目的語としては合わない。"}, "error_tags": {"より": "比較", "の": "連体修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52008, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物や考えを、別の物の中に流し込んだり、加えたりすること。", "primary_collocate": null, "pronunciation": "ちゅうにゅう", "ipa": "tɕɯːɲɯː", "syllable_count": 4, "sentences": [{"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "注入", "complexity_tier": "T3", "furigana": "資金[しきん]のみならず、経営[けいえい]の知見[ちけん]や人的[じんてき]ネットワークが注入[ちゅうにゅう]されることで、個々[ここ]の企業[きぎょう]の成長[せいちょう]が触発[しょくはつ]され、結果[けっか]として社会[しゃかい]実装[じっそう]を加速[かそく]させ、ひいては経済[けいざい]構造[こうぞう]の変革[へんかく]を促[うなが]す強力[きょうりょく]な原動力[げんどうりょく]となるのだ。", "sentence_source": "mined"}, {"text": "政府は経営が苦しい銀行に公的資金を注入し、倒産を防いだ。", "target_word": "注入", "complexity_tier": "T3", "furigana": "政府[せいふ]は経営[けいえい]が苦[くる]しい銀行[ぎんこう]に公的[こうてき]資金[しきん]を注入[ちゅうにゅう]し、倒産[とうさん]を防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "新しい工場の運営に外部の知見を注入した結果、生産量が二倍になった。", "target_word": "注入", "complexity_tier": "T3", "furigana": "新[あたら]しい工場[こうじょう]の運営[うんえい]に外部[がいぶ]の知見[ちけん]を注入[ちゅうにゅう]した結果[けっか]、生産量[せいさんりょう]が二倍[にばい]になった。", "sentence_source": "generated"}, {"text": "古い組織に若い世代の考えを注入しなければ、会社は変わらない。", "target_word": "注入", "complexity_tier": "T3", "furigana": "古[ふる]い組織[そしき]に若[わか]い世代[せだい]の考[かんが]えを注入[ちゅうにゅう]しなければ、会社[かいしゃ]は変[か]わらない。", "sentence_source": "generated"}, {"text": "監督は選手たちに闘志を注入するため、試合前に短い話をした。", "target_word": "注入", "complexity_tier": "T3", "furigana": "監督[かんとく]は選手[せんしゅ]たちに闘志[とうし]を注入[ちゅうにゅう]するため、試合前[しあいまえ]に短[みじか]い話[はなし]をした。", "sentence_source": "generated"}, {"text": "町の再生には、外から資金を注入するだけでなく、住民の協力も必要だ。", "target_word": "注入", "complexity_tier": "T3", "furigana": "町[まち]の再生[さいせい]には、外[そと]から資金[しきん]を注入[ちゅうにゅう]するだけでなく、住民[じゅうみん]の協力[きょうりょく]も必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "企業への資金注入が遅れたため、新しい事業の開始は来年に延びた。", "target_word": "注入", "complexity_tier": "T3", "furigana": "企業[きぎょう]への資金[しきん]注入[ちゅうにゅう]が遅[おく]れたため、新[あたら]しい事業[じぎょう]の開始[かいし]は来年[らいねん]に延[の]びた。", "sentence_source": "generated"}, {"text": "教育の現場に新しい発想を注入する試みが、各地で始まっている。", "target_word": "注入", "complexity_tier": "T3", "furigana": "教育[きょういく]の現場[げんば]に新[あたら]しい発想[はっそう]を注入[ちゅうにゅう]する試[こころ]みが、各地[かくち]で始[はじ]まっている。", "sentence_source": "generated"}, {"text": "赤字の会社に大量の資金が注入されたが、経営は立ち直らなかった。", "target_word": "注入", "complexity_tier": "T3", "furigana": "赤字[あかじ]の会社[かいしゃ]に大量[たいりょう]の資金[しきん]が注入[ちゅうにゅう]されたが、経営[けいえい]は立[た]ち直[なお]らなかった。", "sentence_source": "generated"}, {"text": "彼女は古い店に新しいアイデアを注入して、客の数を増やした。", "target_word": "注入", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は古[ふる]い店[みせ]に新[あたら]しいアイデアを注入[ちゅうにゅう]して、客[きゃく]の数[かず]を増[ふ]やした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "注入する", "label": "基本形（サ変動詞）"}, {"form": "注入した", "label": "過去形"}, {"form": "注入される", "label": "受身形"}, {"form": "注入して", "label": "て形"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "資金・技術・考えなどを、組織や相手の中に加え入れること（比喩的な用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52008, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注入", "is_correct": true, "explanation": "「〜が注入される」で「知見やネットワークを組織の中に流し込み加える」の意味になり、成長を促すという文の流れに合う。"}, {"text": "撤去", "is_correct": false, "explanation": "撤去は設置されたものを取り除くこと。知見やネットワークを取り除く文になり、成長が触発されるという文脈と逆になる。"}, {"text": "蒸発", "is_correct": false, "explanation": "蒸発は液体などが気体となって消えること。知見やネットワークには使わず、「されることで」の文に意味が通らない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集団や組織を解くこと。知見やネットワークを解散させる文にはならず、加えて成長を促す流れにも合わない。"}], "explanations": {"注入": "「〜が注入される」で「知見やネットワークを組織の中に流し込み加える」の意味になり、成長を促すという文の流れに合う。", "撤去": "撤去は設置されたものを取り除くこと。知見やネットワークを取り除く文になり、成長が触発されるという文脈と逆になる。", "蒸発": "蒸発は液体などが気体となって消えること。知見やネットワークには使わず、「されることで」の文に意味が通らない。", "解散": "解散は集団や組織を解くこと。知見やネットワークを解散させる文にはならず、加えて成長を促す流れにも合わない。"}, "sentence_index": 0, "correct_answer": "注入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大学は地域の住民に、無料で図書を注入して喜ばれている。", "explanation": "ここは〈提供〉の意味。相手に差し出して使ってもらうのが提供で、本を流し込む注入とは言わないので合わない。"}, {"text": "会議の資料に大事な写真を注入して、わかりやすくした。", "explanation": "ここは〈挿入〉の意味。文書の中に別の要素をさし入れるのが挿入で、写真を流し込むとは言わないので注入は合わない。"}, {"text": "彼女の演技に注入が集まった。", "explanation": "ここは〈注目〉の意味。人の関心が一点に集まるのが注目で、注入は中に流し込むことなので「注目が集まる」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52008, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注入", "is_correct": true, "explanation": "「企業への資金注入」で、企業に資金を流し込むことを指し、遅れた話の主語として自然。"}, {"text": "粉砕", "is_correct": false, "explanation": "粉砕は固いものを細かく砕くこと。資金には使えず、文の意味が成り立たない。"}, {"text": "解体", "is_correct": false, "explanation": "解体は組み立てたものをばらすこと。資金には使えず、文の意味が成り立たない。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫は作物などを取り入れること。資金には使わず、文の意味が成り立たない。"}], "explanations": {"注入": "「企業への資金注入」で、企業に資金を流し込むことを指し、遅れた話の主語として自然。", "粉砕": "粉砕は固いものを細かく砕くこと。資金には使えず、文の意味が成り立たない。", "解体": "解体は組み立てたものをばらすこと。資金には使えず、文の意味が成り立たない。", "収穫": "収穫は作物などを取り入れること。資金には使わず、文の意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "注入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は古い店に新しい椅子を注入して、客の数を増やした。", "explanation": "ここは〈設置〉の意味。椅子を据えるのが設置で、注入は中に流し込むことなので椅子には合わない。"}, {"text": "彼女は古い店に新しい看板を注入して、客の数を増やした。", "explanation": "ここは〈取り付け〉の意味。看板を店に据え付けるのが取り付けで、注入は中に流し込むことなので看板には合わない。"}, {"text": "彼女は古い店の棚に商品を注入して、客の数を増やした。", "explanation": "ここは〈詰め込む〉の意味。棚に物を並べ入れるのが詰め込むで、商品を流し込むとは言わないので注入は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52008, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい研究所の設立には、大学から資金に注入するだけでなく、人材の交流も必要だ。", "corrected_sentence": "新しい研究所の設立には、大学から資金を注入するだけでなく、人材の交流も必要だ。", "error_description": "「注入」は入れるもの（資金）に「を」を取る。「資金に注入」は誤りで、正しくは「資金を注入」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52008, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地方の学校に新しい発想を注入れる試みが、各地で始まっている。", "corrected_sentence": "地方の学校に新しい発想を注入する試みが、各地で始まっている。", "error_description": "「注入」はサ変動詞なので、名詞「試み」を修飾するときは「注入する」と活用する。「注入れる」は存在しない誤った形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52009, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "物的", "is_correct": true, "explanation": "「人的」の対義語。人に関することに対して、物に関すること。「人的資源」と「物的資源」の対になる関係。"}, {"text": "公的", "is_correct": false, "explanation": "公的は公に関するさま。人に関わるかどうかの対義語ではなく、この意味では対にならない。"}, {"text": "精神的", "is_correct": false, "explanation": "精神的は心に関するさま。物質的の反対語で、人的とは対にならない。"}, {"text": "芸術的", "is_correct": false, "explanation": "芸術的は芸術の性質を持つさま。人的の対義語ではない。"}], "correct_answer": "物的", "explanations": {"物的": "「人的」の対義語。人に関することに対して、物に関すること。「人的資源」と「物的資源」の対になる関係。", "公的": "公的は公に関するさま。人に関わるかどうかの対義語ではなく、この意味では対にならない。", "精神的": "精神的は心に関するさま。物質的の反対語で、人的とは対にならない。", "芸術的": "芸術的は芸術の性質を持つさま。人的の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52009, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "物的", "is_correct": true, "explanation": "「人的」の対義語。人に関することに対して、物に関すること。「人的資源」と「物的資源」の対になる関係。"}, {"text": "道徳的", "is_correct": false, "explanation": "道徳的は道徳に関するさま。人に関わるかどうかの対義語ではなく、この意味では対にならない。"}, {"text": "経済的", "is_correct": false, "explanation": "経済的はお金や景気に関するさま。人的の対義語とはならない。"}, {"text": "私的", "is_correct": false, "explanation": "私的は個人に関するさま。公的の反対語で、人的の対義語ではない。"}], "correct_answer": "物的", "explanations": {"物的": "「人的」の対義語。人に関することに対して、物に関すること。「人的資源」と「物的資源」の対になる関係。", "道徳的": "道徳的は道徳に関するさま。人に関わるかどうかの対義語ではなく、この意味では対にならない。", "経済的": "経済的はお金や景気に関するさま。人的の対義語とはならない。", "私的": "私的は個人に関するさま。公的の反対語で、人的の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52009, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "人と人とのつながりについてのことです。", "primary_collocate": null, "pronunciation": "じんてき", "ipa": "dʑinteki", "syllable_count": 4, "sentences": [{"text": "彼は人的ネットワークが広いので、仕事の相談先に困らない。", "target_word": "人的", "complexity_tier": "T3", "furigana": "彼[かれ]は人的[じんてき]ネットワークが広[ひろ]いので、仕事[しごと]の相談先[そうだんさき]に困[こま]らない。", "sentence_source": "generated"}, {"text": "転職では、学歴より人的なつながりが役に立つことも多い。", "target_word": "人的", "complexity_tier": "T3", "furigana": "転職[てんしょく]では、学歴[がくれき]より人的[じんてき]なつながりが役[やく]に立[た]つことも多[おお]い。", "sentence_source": "generated"}, {"text": "新しい町では人的な関係がないため、最初は友達ができなかった。", "target_word": "人的", "complexity_tier": "T3", "furigana": "新[あたら]しい町[まち]では人的[じんてき]な関係[かんけい]がないため、最初[さいしょ]は友達[ともだち]ができなかった。", "sentence_source": "generated"}, {"text": "起業するとき、資金より人的ネットワークを作ることを優先した。", "target_word": "人的", "complexity_tier": "T3", "furigana": "起業[きぎょう]するとき、資金[しきん]より人的[じんてき]ネットワークを作[つく]ることを優先[ゆうせん]した。", "sentence_source": "generated"}, {"text": "留学生との交流会は、人的なつながりを広げる良い機会だ。", "target_word": "人的", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]との交流会[こうりゅうかい]は、人的[じんてき]なつながりを広[ひろ]げる良[よ]い機会[きかい]だ。", "sentence_source": "generated"}, {"text": "人的な関係が深い会社なので、急な頼みでも引き受けてくれる。", "target_word": "人的", "complexity_tier": "T3", "furigana": "人的[じんてき]な関係[かんけい]が深[ふか]い会社[かいしゃ]なので、急[きゅう]な頼[たの]みでも引[ひ]き受[う]けてくれる。", "sentence_source": "generated"}, {"text": "人的ネットワークを持つ先輩の紹介で、すぐに仕事が決まった。", "target_word": "人的", "complexity_tier": "T3", "furigana": "人的[じんてき]ネットワークを持[も]つ先輩[せんぱい]の紹介[しょうかい]で、すぐに仕事[しごと]が決[き]まった。", "sentence_source": "generated"}, {"text": "長く同じ町に住む人は、人的なつながりが強い。", "target_word": "人的", "complexity_tier": "T3", "furigana": "長[なが]く同[おな]じ町[まち]に住[す]む人[ひと]は、人的[じんてき]なつながりが強[つよ]い。", "sentence_source": "generated"}, {"text": "この研究会は、研究者同士の人的交流を目的として始まった。", "target_word": "人的", "complexity_tier": "T3", "furigana": "この研究会[けんきゅうかい]は、研究者[けんきゅうしゃ]同士[どうし]の人的[じんてき]交流[こうりゅう]を目的[もくてき]として始[はじ]まった。", "sentence_source": "generated"}, {"text": "人的ネットワークがあっても、日ごろの付き合いがなければ生かせない。", "target_word": "人的", "complexity_tier": "T3", "furigana": "人的[じんてき]ネットワークがあっても、日[ひ]ごろの付[つ]き合[あ]いがなければ生[い]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人的な", "label": "連体形（な）"}, {"form": "人的に", "label": "連用形（に）"}, {"form": "人的だ", "label": "終止形"}, {"form": "人的で", "label": "連用形（で）"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "人と人との関係や人脈に関わるという性質（人的ネットワーク・人的なつながり）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52009, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人的", "is_correct": true, "explanation": "「人的ネットワーク」で、人脈を指し、広いので相談先に困らないという文の意味に合う。"}, {"text": "地質的", "is_correct": false, "explanation": "地質的は土地の成り立ちに関するさま。人脈を修飾しても意味が通らない。"}, {"text": "色彩的", "is_correct": false, "explanation": "色彩的は色の配置や性質に関するさま。ネットワークに使うと意味が通らない。"}, {"text": "季節的", "is_correct": false, "explanation": "季節的は季節に関するさま。人脈の広さを表す文脈と合わない。"}], "explanations": {"人的": "「人的ネットワーク」で、人脈を指し、広いので相談先に困らないという文の意味に合う。", "地質的": "地質的は土地の成り立ちに関するさま。人脈を修飾しても意味が通らない。", "色彩的": "色彩的は色の配置や性質に関するさま。ネットワークに使うと意味が通らない。", "季節的": "季節的は季節に関するさま。人脈の広さを表す文脈と合わない。"}, "sentence_index": 0, "correct_answer": "人的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は人的に温かい人柄で、部下に慕われている。", "explanation": "ここは〈人間的〉の意味。人柄の温かさは人間的で、人的は人に関わるという意味なので人柄には合わない。"}, {"text": "この製品は人的な甘味料で味付けされている。", "explanation": "ここは〈人工的〉の意味。人の手で作られた甘味料は人工的で、人的は人に関する意味なので物質には合わない。"}, {"text": "彼女は人的な事情で会社を休んだ。", "explanation": "ここは〈個人的〉の意味。その人一人に関する事情は個人的で、人的は人全般に関わる意味なので事情には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52009, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人的", "is_correct": true, "explanation": "「人的ネットワークを持つ先輩」で、人脈を指し、紹介で仕事が決まったという文に合う。"}, {"text": "火山的", "is_correct": false, "explanation": "火山的は火山に関するさま。人脈を修飾しても意味が通らない。"}, {"text": "放射線的", "is_correct": false, "explanation": "放射線的は放射線に関するさま。ネットワークの説明として意味が通らない。"}, {"text": "熱帯的", "is_correct": false, "explanation": "熱帯的は熱帯の性質に関するさま。人脈を修飾する意味にはならない。"}], "explanations": {"人的": "「人的ネットワークを持つ先輩」で、人脈を指し、紹介で仕事が決まったという文に合う。", "火山的": "火山的は火山に関するさま。人脈を修飾しても意味が通らない。", "放射線的": "放射線的は放射線に関するさま。ネットワークの説明として意味が通らない。", "熱帯的": "熱帯的は熱帯の性質に関するさま。人脈を修飾する意味にはならない。"}, "sentence_index": 6, "correct_answer": "人的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場の人的な動きが止まった。", "explanation": "ここは〈機械的〉の意味。機械の動きは機械的で、人的は人に関する意味なので機械の動作には合わない。"}, {"text": "彼は人的な反応を見せず、落ち着いていた。", "explanation": "ここは〈感情的〉の意味。感情の動きに関する反応は感情的で、人的は人に関する意味なので反応には合わない。"}, {"text": "この問題は人的な証明で解けた。", "explanation": "ここは〈数学的〉の意味。論理や式による証明は数学的で、人的は人に関わるという意味なので証明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52009, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者たちは、人的ネットワークが広げることで、新しい共同研究を始めた。", "corrected_sentence": "研究者たちは、人的ネットワークを広げることで、新しい共同研究を始めた。", "error_description": "「広げる」の対象は「人的ネットワーク」で、「を」で示す。「が広げる」は主語になり、意味が通らない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "人的", "is_correct": true, "explanation": "「なつながり」の前に来る語幹の形。名詞を修飾する「な」の前に置くので正しい。"}, {"text": "人的に", "is_correct": false, "explanation": "連用形。「人的になつながり」となり、名詞を修飾できない。"}, {"text": "人的だ", "is_correct": false, "explanation": "終止形。言い切りの形なので「人的だなつながり」とはならず、名詞に続かない。"}, {"text": "人的で", "is_correct": false, "explanation": "連用形（で）。「人的でなつながり」となり、名詞を修飾する形として成り立たない。"}], "correct_form": "人的", "base_form": "人的だ", "form_label": "連体修飾（〜な）の語幹", "sentence_index": 1, "explanations": {"人的": "「なつながり」の前に来る語幹の形。名詞を修飾する「な」の前に置くので正しい。", "人的に": "連用形。「人的になつながり」となり、名詞を修飾できない。", "人的だ": "終止形。言い切りの形なので「人的だなつながり」とはならず、名詞に続かない。", "人的で": "連用形（で）。「人的でなつながり」となり、名詞を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52009, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究所の人的だ関係が、新しい研究を支えている。", "corrected_sentence": "研究所の人的な関係が、新しい研究を支えている。", "error_description": "名詞「関係」を修飾するには「人的な関係」と連体形（な）が必要。「人的だ関係」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "人的", "is_correct": true, "explanation": "「なつながり」の前に来る語幹の形。名詞を修飾する「な」の前に置くので正しい。"}, {"text": "人的だった", "is_correct": false, "explanation": "過去の断定の形。「人的だったなつながり」となり、名詞を修飾する語幹の形ではない。"}, {"text": "人的である", "is_correct": false, "explanation": "硬い断定の形。「人的であるなつながり」となり、名詞を修飾する語幹の形として成り立たない。"}, {"text": "人的なら", "is_correct": false, "explanation": "仮定の「なら」の形。「人的ならなつながり」と続かず、名詞を修飾できない。"}], "correct_form": "人的", "base_form": "人的だ", "form_label": "連体修飾（〜な）の語幹", "sentence_index": 7, "explanations": {"人的": "「なつながり」の前に来る語幹の形。名詞を修飾する「な」の前に置くので正しい。", "人的だった": "過去の断定の形。「人的だったなつながり」となり、名詞を修飾する語幹の形ではない。", "人的である": "硬い断定の形。「人的であるなつながり」となり、名詞を修飾する語幹の形として成り立たない。", "人的なら": "仮定の「なら」の形。「人的ならなつながり」と続かず、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52010, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "物的", "is_correct": true, "explanation": "「人的」の対義語。人に関することに対して、物に関すること。「人的資源」と「物的資源」の対になる関係。"}, {"text": "公的", "is_correct": false, "explanation": "公的は公に関するさま。人に関わるかどうかの対義語ではなく、この意味では対にならない。"}, {"text": "私的", "is_correct": false, "explanation": "私的は個人に関するさま。公的の反対語で、人的の対義語ではない。"}, {"text": "精神的", "is_correct": false, "explanation": "精神的は心に関するさま。物質的の反対語で、人的とは対にならない。"}], "correct_answer": "物的", "explanations": {"物的": "「人的」の対義語。人に関することに対して、物に関すること。「人的資源」と「物的資源」の対になる関係。", "公的": "公的は公に関するさま。人に関わるかどうかの対義語ではなく、この意味では対にならない。", "私的": "私的は個人に関するさま。公的の反対語で、人的の対義語ではない。", "精神的": "精神的は心に関するさま。物質的の反対語で、人的とは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52010, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "物的", "is_correct": true, "explanation": "「人的」の対義語。人に関することに対して、物に関すること。「人的資源」と「物的資源」の対になる関係。"}, {"text": "道徳的", "is_correct": false, "explanation": "道徳的は道徳に関するさま。人に関わるかどうかの対義語ではなく、この意味では対にならない。"}, {"text": "経済的", "is_correct": false, "explanation": "経済的はお金や景気に関するさま。人的の対義語とはならない。"}, {"text": "芸術的", "is_correct": false, "explanation": "芸術的は芸術の性質を持つさま。人的の対義語ではない。"}], "correct_answer": "物的", "explanations": {"物的": "「人的」の対義語。人に関することに対して、物に関すること。「人的資源」と「物的資源」の対になる関係。", "道徳的": "道徳的は道徳に関するさま。人に関わるかどうかの対義語ではなく、この意味では対にならない。", "経済的": "経済的はお金や景気に関するさま。人的の対義語とはならない。", "芸術的": "芸術的は芸術の性質を持つさま。人的の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52010, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "人に関係する、人を中心とした、という意味。特に「人的ネットワーク」で、人と人とのつながりや人脈を指す。", "primary_collocate": null, "pronunciation": "じんてき", "ipa": "dʑinteki", "syllable_count": 4, "sentences": [{"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "人的", "complexity_tier": "T3", "furigana": "資金[しきん]のみならず、経営[けいえい]の知見[ちけん]や人的[じんてき]ネットワークが注入[ちゅうにゅう]されることで、個々[ここ]の企業[きぎょう]の成長[せいちょう]が触発[しょくはつ]され、結果[けっか]として社会[しゃかい]実装[じっそう]を加速[かそく]させ、ひいては経済[けいざい]構造[こうぞう]の変革[へんかく]を促[うなが]す強力[きょうりょく]な原動力[げんどうりょく]となるのだ。", "sentence_source": "mined"}, {"text": "事故の原因は機械の故障ではなく、人的なミスだった。", "target_word": "人的", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]は機械[きかい]の故障[こしょう]ではなく、人的[じんてき]なミスだった。", "sentence_source": "generated"}, {"text": "この仕事は、人的ネットワークの広さが成果を左右する。", "target_word": "人的", "complexity_tier": "T3", "furigana": "この仕事[しごと]は、人的[じんてき]ネットワークの広[ひろ]さが成果[せいか]を左右[さゆう]する。", "sentence_source": "generated"}, {"text": "新しい事業は、設備より人的なつながりのほうが成功の鍵になる。", "target_word": "人的", "complexity_tier": "T3", "furigana": "新[あたら]しい事業[じぎょう]は、設備[せつび]より人的[じんてき]なつながりのほうが成功[せいこう]の鍵[かぎ]になる。", "sentence_source": "generated"}, {"text": "地域の人的ネットワークが、災害のときに住民を助けた。", "target_word": "人的", "complexity_tier": "T3", "furigana": "地域[ちいき]の人的[じんてき]ネットワークが、災害[さいがい]のときに住民[じゅうみん]を助[たす]けた。", "sentence_source": "generated"}, {"text": "彼は人的ネットワークを生かして、短い期間に取引先を増やした。", "target_word": "人的", "complexity_tier": "T3", "furigana": "彼[かれ]は人的[じんてき]ネットワークを生[い]かして、短[みじか]い期間[きかん]に取引先[とりひきさき]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "人的な交流が少ない部署では、情報が共有されにくい。", "target_word": "人的", "complexity_tier": "T3", "furigana": "人的[じんてき]な交流[こうりゅう]が少[すく]ない部署[ぶしょ]では、情報[じょうほう]が共有[きょうゆう]されにくい。", "sentence_source": "generated"}, {"text": "海外に進出するなら、現地の人的ネットワークを早めに作るべきだ。", "target_word": "人的", "complexity_tier": "T3", "furigana": "海外[かいがい]に進出[しんしゅつ]するなら、現地[げんち]の人的[じんてき]ネットワークを早[はや]めに作[つく]るべきだ。", "sentence_source": "generated"}, {"text": "工場で起きた事故は、確認の不足という人的な原因が大きかった。", "target_word": "人的", "complexity_tier": "T3", "furigana": "工場[こうじょう]で起[お]きた事故[じこ]は、確認[かくにん]の不足[ふそく]という人的[じんてき]な原因[げんいん]が大[おお]きかった。", "sentence_source": "generated"}, {"text": "大学の同窓会は、卒業生の人的ネットワークとして役立っている。", "target_word": "人的", "complexity_tier": "T3", "furigana": "大学[だいがく]の同窓会[どうそうかい]は、卒業生[そつぎょうせい]の人的[じんてき]ネットワークとして役立[やくだ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人的な", "label": "連体形（な）"}, {"form": "人的に", "label": "連用形（に）"}, {"form": "人的だ", "label": "終止形"}, {"form": "人的で", "label": "連用形（で）"}], "register": "書き言葉・やや硬い文体", "sense_fingerprint": "人に関わる、人を中心にしたという性質。人脈や人間関係、人の判断による原因などを表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e5ab70-def5-4471-8aae-314456eb3fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52010, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人的", "is_correct": true, "explanation": "「や人的ネットワーク」で、人と人とのつながりを指し、文の意味に合う。"}, {"text": "季節的", "is_correct": false, "explanation": "季節的は季節に関するさま。ネットワークを修飾しても人のつながりの意味にならない。"}, {"text": "瞬間的", "is_correct": false, "explanation": "瞬間的は一瞬に限るさま。長く続く人脈を表す文脈と合わない。"}, {"text": "懐古的", "is_correct": false, "explanation": "懐古的は昔をなつかしむさま。ネットワークの説明としては意味が通らない。"}], "explanations": {"人的": "「や人的ネットワーク」で、人と人とのつながりを指し、文の意味に合う。", "季節的": "季節的は季節に関するさま。ネットワークを修飾しても人のつながりの意味にならない。", "瞬間的": "瞬間的は一瞬に限るさま。長く続く人脈を表す文脈と合わない。", "懐古的": "懐古的は昔をなつかしむさま。ネットワークの説明としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "人的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は人的に温かく、誰にでも親切だ。", "explanation": "ここは〈人間的〉の意味。人柄の温かさは人間的で、人的は人に関わるという意味なので人柄には合わない。"}, {"text": "夜の店は人的な光で照らされ、明るい。", "explanation": "ここは〈人工的〉の意味。人の手で作られた光は人工的で、人的は人に関する意味なので光には合わない。"}, {"text": "彼は怒ると感情的になり、人的な発言を繰り返す。", "explanation": "ここは〈感情的〉の意味。感情に流された発言は感情的で、人的は人に関わる意味なので発言には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52010, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人的", "is_correct": true, "explanation": "「人的な交流」で、人と人との交わりを指し、交流が少ないという文の意味に合う。"}, {"text": "液体的", "is_correct": false, "explanation": "液体的は液体に関するさま。交流を修飾しても意味が通らない。"}, {"text": "光学的", "is_correct": false, "explanation": "光学的は光の性質に関するさま。交流を修飾する意味にはならない。"}, {"text": "熱帯的", "is_correct": false, "explanation": "熱帯的は熱帯の気候に関するさま。交流の文脈と合わず、意味が通らない。"}], "explanations": {"人的": "「人的な交流」で、人と人との交わりを指し、交流が少ないという文の意味に合う。", "液体的": "液体的は液体に関するさま。交流を修飾しても意味が通らない。", "光学的": "光学的は光の性質に関するさま。交流を修飾する意味にはならない。", "熱帯的": "熱帯的は熱帯の気候に関するさま。交流の文脈と合わず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "人的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は人的な悩みを友人に相談した。", "explanation": "ここは〈個人的〉の意味。その人一人に関する悩みは個人的で、人的は人全般に関わる意味なので悩みには合わない。"}, {"text": "彼は人的に返事をして、会話を終えた。", "explanation": "ここは〈機械的〉の意味。感情を交えず決まった型で行うのが機械的で、人的は人に関する意味なので返事の仕方には合わない。"}, {"text": "犯行は人的な計画に基づいていた。", "explanation": "ここは〈組織的〉の意味。組織だって計画されたことは組織的で、人的は人に関する意味なので計画の性質には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52010, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工場の事故は、確認不足という人的の原因で起きた。", "corrected_sentence": "工場の事故は、確認不足という人的な原因で起きた。", "error_description": "「人的」は名詞を修飾するとき「な」を付ける。「人的の原因」は誤りで、正しくは「人的な原因」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "人的", "is_correct": true, "explanation": "「なミス」の前に来る語幹の形。名詞を修飾する「な」の前に置くので正しい。"}, {"text": "人的に", "is_correct": false, "explanation": "連用形。「人的になミス」となり、名詞を修飾できない。"}, {"text": "人的だ", "is_correct": false, "explanation": "終止形。言い切りの形なので「人的だなミス」とはならず、名詞に続かない。"}, {"text": "人的で", "is_correct": false, "explanation": "連用形（で）。「人的でなミス」となり、名詞を修飾する形として成り立たない。"}], "correct_form": "人的", "base_form": "人的だ", "form_label": "連体修飾（〜な）の語幹", "sentence_index": 1, "explanations": {"人的": "「なミス」の前に来る語幹の形。名詞を修飾する「な」の前に置くので正しい。", "人的に": "連用形。「人的になミス」となり、名詞を修飾できない。", "人的だ": "終止形。言い切りの形なので「人的だなミス」とはならず、名詞に続かない。", "人的で": "連用形（で）。「人的でなミス」となり、名詞を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52010, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は人的だネットワークを築いて、新しい取引先を得た。", "corrected_sentence": "彼女は人的なネットワークを築いて、新しい取引先を得た。", "error_description": "「人的」は名詞を修飾するとき「な」が必要。「人的だネットワーク」は誤りで、正しくは「人的なネットワーク」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "人的", "is_correct": true, "explanation": "「人的ネットワーク」の前に来る語幹の形。名詞を直接修飾する形で、現地のネットワークを指す文に合う。"}, {"text": "人的だった", "is_correct": false, "explanation": "過去の形。「現地の人的だったネットワーク」と名詞に続かず、語幹の形ではない。"}, {"text": "人的として", "is_correct": false, "explanation": "資格や立場を表す「として」の形。「人的としてネットワーク」と続かず、名詞を修飾できない。"}, {"text": "人的では", "is_correct": false, "explanation": "「では」の形。「人的ではネットワーク」と続かず、名詞を修飾する形として成り立たない。"}], "correct_form": "人的", "base_form": "人的だ", "form_label": "連体修飾（〜な）の語幹", "sentence_index": 7, "explanations": {"人的": "「人的ネットワーク」の前に来る語幹の形。名詞を直接修飾する形で、現地のネットワークを指す文に合う。", "人的だった": "過去の形。「現地の人的だったネットワーク」と名詞に続かず、語幹の形ではない。", "人的として": "資格や立場を表す「として」の形。「人的としてネットワーク」と続かず、名詞を修飾できない。", "人的では": "「では」の形。「人的ではネットワーク」と続かず、名詞を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49765c2-488f-45e3-b26a-648e2e095348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52011, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「買い入れには」の「に」で、買い入れを話題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「をは」となり助詞が重なって成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「がは」となり助詞が重なって成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へは」となり助詞が重なって成り立たず、方向の意味も合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「買い入れには」の「に」で、買い入れを話題として示す。", "を": "「をは」となり助詞が重なって成り立たない。", "が": "「がは」となり助詞が重なって成り立たない。", "へ": "「へは」となり助詞が重なって成り立たず、方向の意味も合わない。"}, "error_tags": {"を": "助詞の重複（「をは」）", "が": "助詞の重複（「がは」）", "へ": "助詞の重複（「へは」）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52011, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「買い入れの量」で、量が買い入れに属することを示す。"}, {"text": "と", "is_correct": false, "explanation": "「買い入れと量が多いと」は並列になり、量の所属を表せないので意味が変わる。"}, {"text": "に", "is_correct": false, "explanation": "「買い入れに量が多いと」は場面を示すだけで、量の所属を表せず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「買い入れから量が多いと」は起点を示すが、量が買い入れに属する意味にならない。"}], "correct_answer": "の", "explanations": {"の": "正解。「買い入れの量」で、量が買い入れに属することを示す。", "と": "「買い入れと量が多いと」は並列になり、量の所属を表せないので意味が変わる。", "に": "「買い入れに量が多いと」は場面を示すだけで、量の所属を表せず不自然。", "から": "「買い入れから量が多いと」は起点を示すが、量が買い入れに属する意味にならない。"}, "error_tags": {"と": "並列（買い入れと量を並べる）", "に": "場面（所属を示せない）", "から": "起点（所属を示せない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52011, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "お金を出して、何かを手に入れることです。", "primary_collocate": null, "pronunciation": "かいいれ", "ipa": "kaiiɾe", "syllable_count": 4, "sentences": [{"text": "店は、野菜の買い入れを毎朝市場で行っている。", "target_word": "買い入れ", "complexity_tier": "T3", "furigana": "店[みせ]は、野菜[やさい]の買[か]い入[い]れを毎朝[まいあさ]市場[いちば]で行[おこな]っている。", "sentence_source": "generated"}, {"text": "新しい道具の買い入れには、お金がかかる。", "target_word": "買い入れ", "complexity_tier": "T3", "furigana": "新[あたら]しい道具[どうぐ]の買[か]い入[い]れには、お金[かね]がかかる。", "sentence_source": "generated"}, {"text": "米の買い入れが増えて、倉庫がいっぱいになった。", "target_word": "買い入れ", "complexity_tier": "T3", "furigana": "米[こめ]の買[か]い入[い]れが増[ふ]えて、倉庫[そうこ]がいっぱいになった。", "sentence_source": "generated"}, {"text": "買い入れが終わったら、品物を棚に並べる。", "target_word": "買い入れ", "complexity_tier": "T3", "furigana": "買[か]い入[い]れが終[お]わったら、品物[しなもの]を棚[たな]に並[なら]べる。", "sentence_source": "generated"}, {"text": "先生は、本の買い入れのために図書室の予算を使った。", "target_word": "買い入れ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、本[ほん]の買[か]い入[い]れのために図書室[としょしつ]の予算[よさん]を使[つか]った。", "sentence_source": "generated"}, {"text": "冬に向けて、灯油の買い入れを早めにすませた。", "target_word": "買い入れ", "complexity_tier": "T3", "furigana": "冬[ふゆ]に向[む]けて、灯油[とうゆ]の買[か]い入[い]れを早[はや]めにすませた。", "sentence_source": "generated"}, {"text": "パン屋は小麦の買い入れを、安い時期に行う。", "target_word": "買い入れ", "complexity_tier": "T3", "furigana": "パン屋[や]は小麦[こむぎ]の買[か]い入[い]れを、安[やす]い時期[じき]に行[おこな]う。", "sentence_source": "generated"}, {"text": "買い入れの量が多いと、値段を安くしてもらえる。", "target_word": "買い入れ", "complexity_tier": "T3", "furigana": "買[か]い入[い]れの量[りょう]が多[おお]いと、値段[ねだん]を安[やす]くしてもらえる。", "sentence_source": "generated"}, {"text": "学校は新しい机の買い入れを、予算が足りないので来月に延ばした。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "学校[がっこう]は新[あたら]しい机[つくえ]の買[か]い入[い]れを、予算[よさん]が足[た]りないので来月[らいげつ]に延[の]ばした。", "sentence_source": "generated"}, {"text": "店長は、人気の商品の買い入れを増やすと決めた。", "target_word": "買い入れ", "complexity_tier": "T3", "furigana": "店長[てんちょう]は、人気[にんき]の商品[しょうひん]の買[か]い入[い]れを増[ふ]やすと決[き]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "買い入れ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "お金を払って品物を手に入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52011, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "買い入れ", "is_correct": true, "explanation": "正解。代金を払って野菜を手に入れる行為で、「野菜の○○を毎朝市場で行う」に入る。"}, {"text": "読書", "is_correct": false, "explanation": "読書は本を読むことで、野菜を代金で手に入れる取引の文には合わない。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は楽器を弾くことで、野菜を扱う市場の文では成り立たない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことで、「行う」対象として野菜の取引と噛み合わない。"}], "explanations": {"買い入れ": "正解。代金を払って野菜を手に入れる行為で、「野菜の○○を毎朝市場で行う」に入る。", "読書": "読書は本を読むことで、野菜を代金で手に入れる取引の文には合わない。", "演奏": "演奏は楽器を弾くことで、野菜を扱う市場の文では成り立たない。", "散歩": "散歩は歩くことで、「行う」対象として野菜の取引と噛み合わない。"}, "sentence_index": 0, "correct_answer": "買い入れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店は銀行から運転資金の買い入れを受けた。", "explanation": "お金を借りる場面で、代金を払って品物を手に入れる買い入れは合わない。"}, {"text": "友達から誕生日に、腕時計の買い入れを贈られた。", "explanation": "プレゼントとして無償で受け取る場面で、代金を払って手に入れる買い入れは合わない。"}, {"text": "会社は新しい社員の買い入れを毎年行っている。", "explanation": "人を雇う場面で、品物を代金で手に入れる買い入れは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52011, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "買い入れ", "is_correct": true, "explanation": "正解。小麦を代金で手に入れる行為で、「小麦の○○を行う」に入る。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲をつくることで、小麦の取引には結びつかない。"}, {"text": "勉強", "is_correct": false, "explanation": "勉強は学ぶことで、小麦を対象にして「行う」とは言わない。"}, {"text": "演劇", "is_correct": false, "explanation": "演劇は劇を上演することで、小麦を扱うこの文には合わない。"}], "explanations": {"買い入れ": "正解。小麦を代金で手に入れる行為で、「小麦の○○を行う」に入る。", "作曲": "作曲は曲をつくることで、小麦の取引には結びつかない。", "勉強": "勉強は学ぶことで、小麦を対象にして「行う」とは言わない。", "演劇": "演劇は劇を上演することで、小麦を扱うこの文には合わない。"}, "sentence_index": 6, "correct_answer": "買い入れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農家は、畑の野菜を朝から買い入れている。", "explanation": "畑の作物を収穫する場面で、代金を払って手に入れる買い入れは合わない。"}, {"text": "営業マンは、新商品を取引先に買い入れて回った。", "explanation": "営業は売る側なので、代金を払って手に入れる買い入れとは向きが逆になる。"}, {"text": "工場は、取引先の注文を買い入れて、大量生産を始めた。", "explanation": "注文は受けるもので、代金を払って手に入れる買い入れとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52011, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅館は、春の宴会に向けて、酒の買い入れが増やした。", "corrected_sentence": "旅館は、春の宴会に向けて、酒の買い入れを増やした。", "error_description": "「増やす」は他動詞で目的語に「を」を取るので、「買い入れが」は誤り。正しくは「買い入れを増やした」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52011, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は、災害に備えて非常食の買い入れを増えた。", "corrected_sentence": "町は、災害に備えて非常食の買い入れを増やした。", "error_description": "「増える」は自動詞なので目的語の「を」とは結びつかず、他動詞「増やす」が正しい。正しくは「買い入れを増やした」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52012, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「買い入れが」が主語になり、「価格を安定させている」に続く。"}, {"text": "を", "is_correct": false, "explanation": "「買い入れを価格を」は目的語が二つ並んで不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、主語の位置には入らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するだけで、述語「安定させている」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。「買い入れが」が主語になり、「価格を安定させている」に続く。", "を": "「買い入れを価格を」は目的語が二つ並んで不自然になる。", "へ": "「へ」は方向を示すので、主語の位置には入らない。", "の": "「の」は名詞を修飾するだけで、述語「安定させている」の主語にはならない。"}, "error_tags": {"を": "目的語の格（目的語が二つになる）", "へ": "方向（主語を示さない）", "の": "連体修飾（主語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52012, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「買い入れに成功した」で、成功した内容（対象）を示す。"}, {"text": "から", "is_correct": false, "explanation": "「買い入れから成功した」は起点を示すので、成功の内容にならない。"}, {"text": "より", "is_correct": false, "explanation": "「買い入れより成功した」は比較の意味になり、比べる相手がないので不自然。"}, {"text": "と", "is_correct": false, "explanation": "「買い入れと成功した」は並列になり、成功の内容を示せない。"}], "correct_answer": "に", "explanations": {"に": "正解。「買い入れに成功した」で、成功した内容（対象）を示す。", "から": "「買い入れから成功した」は起点を示すので、成功の内容にならない。", "より": "「買い入れより成功した」は比較の意味になり、比べる相手がないので不自然。", "と": "「買い入れと成功した」は並列になり、成功の内容を示せない。"}, "error_tags": {"から": "起点（成功の内容を示さない）", "より": "比較（比べる相手がない）", "と": "並列（成功と並べる意味になる）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52012, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "商品や資産などを、代金を支払って自分のものにすること。", "primary_collocate": null, "pronunciation": "かいいれ", "ipa": "kaiiɾe", "syllable_count": 4, "sentences": [{"text": "会社は、工場の土地の買い入れを正式に決めた。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "会社[かいしゃ]は、工場[こうじょう]の土地[とち]の買[か]い入[い]れを正式[せいしき]に決[き]めた。", "sentence_source": "generated"}, {"text": "国による米の買い入れが、価格を安定させている。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "国[くに]による米[こめ]の買[か]い入[い]れが、価格[かかく]を安定[あんてい]させている。", "sentence_source": "generated"}, {"text": "株の買い入れは、値段が下がったときに行った。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "株[かぶ]の買[か]い入[い]れは、値段[ねだん]が下[さ]がったときに行[おこな]った。", "sentence_source": "generated"}, {"text": "銀行は、国債の買い入れを毎月続けている。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "銀行[ぎんこう]は、国債[こくさい]の買[か]い入[い]れを毎月[まいつき]続[つづ]けている。", "sentence_source": "generated"}, {"text": "買い入れの代金は、契約の翌日に支払われた。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "買[か]い入[い]れの代金[だいきん]は、契約[けいやく]の翌日[よくじつ]に支払[しはら]われた。", "sentence_source": "generated"}, {"text": "小売店は、メーカーから商品の買い入れを増やした。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "小売店[こうりてん]は、メーカーから商品[しょうひん]の買[か]い入[い]れを増[ふ]やした。", "sentence_source": "generated"}, {"text": "設備の買い入れには、銀行から借りたお金を使った。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "設備[せつび]の買[か]い入[い]れには、銀行[ぎんこう]から借[か]りたお金[かね]を使[つか]った。", "sentence_source": "generated"}, {"text": "美術館は、有名な絵画の買い入れに成功した。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "美術館[びじゅつかん]は、有名[ゆうめい]な絵画[かいが]の買[か]い入[い]れに成功[せいこう]した。", "sentence_source": "generated"}, {"text": "原料の買い入れに費用がかかり、製品の値段も上がった。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "原料[げんりょう]の買[か]い入[い]れに費用[ひよう]がかかり、製品[せいひん]の値段[ねだん]も上[あ]がった。", "sentence_source": "generated"}, {"text": "担当者は、材料の買い入れについて取引先と値段を交渉した。", "target_word": "買い入れ", "complexity_tier": "T4", "furigana": "担当者[たんとうしゃ]は、材料[ざいりょう]の買[か]い入[い]れについて取引先[とりひきさき]と値段[ねだん]を交渉[こうしょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "買い入れ", "label": "基本形"}], "register": "formal-business", "sense_fingerprint": "商品や資産を代金を払って自分のものにする取引", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52012, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "買い入れ", "is_correct": true, "explanation": "正解。土地を代金で自分のものにする取引で、「土地の○○を正式に決めた」に入る。"}, {"text": "読書", "is_correct": false, "explanation": "読書は本を読むことで、土地の取引を決める文には合わない。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は楽器を弾くことで、土地の決定とは結びつかない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことで、土地を正式に決める文の中では成り立たない。"}], "explanations": {"買い入れ": "正解。土地を代金で自分のものにする取引で、「土地の○○を正式に決めた」に入る。", "読書": "読書は本を読むことで、土地の取引を決める文には合わない。", "演奏": "演奏は楽器を弾くことで、土地の決定とは結びつかない。", "散歩": "散歩は歩くことで、土地を正式に決める文の中では成り立たない。"}, "sentence_index": 0, "correct_answer": "買い入れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は銀行から、工場建設の資金の買い入れを受けた。", "explanation": "資金を借りる場面で、代金を払って品物を手に入れる買い入れは合わない。"}, {"text": "会社は古いビルを買い入れて、資金を得た。", "explanation": "古いビルを手放して資金を得る話は、代金を払って手に入れる買い入れとは向きが逆になる。"}, {"text": "美術館は、寄贈された絵画を買い入れて展示した。", "explanation": "寄贈は無償なので、代金を払って手に入れる買い入れとは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52012, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "買い入れ", "is_correct": true, "explanation": "正解。設備を代金で手に入れる行為で、「設備の○○には」に入る。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲をつくることで、設備の話には結びつかない。"}, {"text": "勉強", "is_correct": false, "explanation": "勉強は学ぶことで、設備を対象にする文には合わない。"}, {"text": "演劇", "is_correct": false, "explanation": "演劇は劇を上演することで、設備とは関係がない。"}], "explanations": {"買い入れ": "正解。設備を代金で手に入れる行為で、「設備の○○には」に入る。", "作曲": "作曲は曲をつくることで、設備の話には結びつかない。", "勉強": "勉強は学ぶことで、設備を対象にする文には合わない。", "演劇": "演劇は劇を上演することで、設備とは関係がない。"}, "sentence_index": 6, "correct_answer": "買い入れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "取引先は、注文の件を担当者と買い入れた。", "explanation": "注文の件を話し合う場面で、代金を払って手に入れる買い入れとは合わない。"}, {"text": "お客さんは、傷のある商品を店に買い入れた。", "explanation": "返品は買った品を店に戻す行為で、買い入れとは向きが逆になる。"}, {"text": "担当者は、会議室を一日だけ買い入れる値段を取引先と交渉した。", "explanation": "買い入れは所有を代金で得ることなので、一日だけ使う話は借りる話になり、買い入れとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52012, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、古い図書館の建物の買い入れを結んだ。", "corrected_sentence": "市は、古い図書館の建物の買い入れを進めた。", "error_description": "「結ぶ」は契約などに使う動詞で、「買い入れを」とは組み合わない。正しくは「買い入れを進めた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52012, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "担当者は、古い機械の買い入れを来月に決まった。", "corrected_sentence": "担当者は、古い機械の買い入れを来月に決めた。", "error_description": "「決まる」は自動詞なので目的語の「を」とは結びつかず、他動詞「決める」が正しい。正しくは「買い入れを来月に決めた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52013, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "考える対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「オペレーションに考えます」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「考える」の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「オペレーションの考えます」は動詞に直接つながらず非文になる。"}], "correct_answer": "を", "explanations": {"を": "考える対象を示す「を」。", "に": "「オペレーションに考えます」は成り立たない。", "へ": "「へ」は方向を表し、「考える」の対象にならない。", "の": "「オペレーションの考えます」は動詞に直接つながらず非文になる。"}, "error_tags": {"に": "帰着点", "へ": "方向", "の": "連体修飾"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52013, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "受身文「行われた」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "受身文の「行われた」に「を」は付けられない。"}, {"text": "へ", "is_correct": false, "explanation": "「オペレーションへ行われた」は意味が通らず非文になる。"}, {"text": "の", "is_correct": false, "explanation": "「オペレーションの、夜通し行われた」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "受身文「行われた」の主語を示す「が」。", "を": "受身文の「行われた」に「を」は付けられない。", "へ": "「オペレーションへ行われた」は意味が通らず非文になる。", "の": "「オペレーションの、夜通し行われた」は文として成り立たない。"}, "error_tags": {"を": "対象格", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52013, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「オペレーション」は、何かをうまく動かすための計画や行いです。", "primary_collocate": null, "pronunciation": "おぺれーしょん", "ipa": "opeɾeːɕoɴ", "syllable_count": 6, "sentences": [{"text": "オペレーションを始めます。", "target_word": "オペレーション", "complexity_tier": "T2", "furigana": "オペレーションを始[はじ]めます。", "sentence_source": "generated"}, {"text": "このオペレーションは簡単です。", "target_word": "オペレーション", "complexity_tier": "T2", "furigana": "このオペレーションは簡単[かんたん]です。", "sentence_source": "generated"}, {"text": "店のオペレーションを考えます。", "target_word": "オペレーション", "complexity_tier": "T2", "furigana": "店[みせ]のオペレーションを考[かんが]えます。", "sentence_source": "generated"}, {"text": "毎日のオペレーションがうまくいっている。", "target_word": "オペレーション", "complexity_tier": "T3", "furigana": "毎日[まいにち]のオペレーションがうまくいっている。", "sentence_source": "generated"}, {"text": "工場のオペレーションを見直すことにした。", "target_word": "オペレーション", "complexity_tier": "T3", "furigana": "工場[こうじょう]のオペレーションを見直[みなお]すことにした。", "sentence_source": "generated"}, {"text": "計画どおりにオペレーションを進めた。", "target_word": "オペレーション", "complexity_tier": "T3", "furigana": "計画[けいかく]どおりにオペレーションを進[すす]めた。", "sentence_source": "generated"}, {"text": "このオペレーションが成功して、みんな喜んだ。", "target_word": "オペレーション", "complexity_tier": "T3", "furigana": "このオペレーションが成功[せいこう]して、みんな喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "救助のためのオペレーションが、夜通し行われた。", "target_word": "オペレーション", "complexity_tier": "T4", "furigana": "救助[きゅうじょ]のためのオペレーションが、夜通[よどお]し行[おこな]われた。", "sentence_source": "generated"}, {"text": "会社は、安全なオペレーションのために新しい規則を作った。", "target_word": "オペレーション", "complexity_tier": "T4", "furigana": "会社[かいしゃ]は、安全[あんぜん]なオペレーションのために新[あたら]しい規則[きそく]を作[つく]った。", "sentence_source": "generated"}, {"text": "細かい計画がなければ、大きなオペレーションは動かない。", "target_word": "オペレーション", "complexity_tier": "T4", "furigana": "細[こま]かい計画[けいかく]がなければ、大[おお]きなオペレーションは動[うご]かない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オペレーター", "label": "派生"}, {"form": "オペレート", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事を動かすための計画や行い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52013, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オペレーション", "is_correct": true, "explanation": "物事を動かす計画や行いを「始める」のは自然。"}, {"text": "ノート", "is_correct": false, "explanation": "形は合うが、「ノートを始める」は意味が合わない。"}, {"text": "バナナ", "is_correct": false, "explanation": "形は合うが、「バナナを始める」は意味が合わない。"}, {"text": "カーテン", "is_correct": false, "explanation": "形は合うが、「カーテンを始める」は意味が合わない。"}], "explanations": {"オペレーション": "物事を動かす計画や行いを「始める」のは自然。", "ノート": "形は合うが、「ノートを始める」は意味が合わない。", "バナナ": "形は合うが、「バナナを始める」は意味が合わない。", "カーテン": "形は合うが、「カーテンを始める」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "オペレーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "オペレーションをお茶に入れて飲んだ。", "explanation": "オペレーションは計画や行いで、飲み物に入れられる物ではない。"}, {"text": "私のオペレーションは赤くて丸い。", "explanation": "オペレーションは形や色を持つ物ではないので、この修飾は誤り。"}, {"text": "オペレーションが空を飛んで海へ行った。", "explanation": "オペレーションは飛ぶ物ではなく、動作の主体として誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52013, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オペレーション", "is_correct": true, "explanation": "計画や行いが成功してみんなが喜ぶのは自然。"}, {"text": "テーブル", "is_correct": false, "explanation": "形は合うが、「テーブルが成功する」は意味が合わない。"}, {"text": "ドア", "is_correct": false, "explanation": "形は合うが、「ドアが成功する」は意味が合わない。"}, {"text": "コップ", "is_correct": false, "explanation": "形は合うが、「コップが成功する」は意味が合わない。"}], "explanations": {"オペレーション": "計画や行いが成功してみんなが喜ぶのは自然。", "テーブル": "形は合うが、「テーブルが成功する」は意味が合わない。", "ドア": "形は合うが、「ドアが成功する」は意味が合わない。", "コップ": "形は合うが、「コップが成功する」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "オペレーション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝ご飯にオペレーションを食べました。", "explanation": "オペレーションは食べ物ではないので「食べる」の目的語にならない。"}, {"text": "オペレーションは犬のように庭で走っている。", "explanation": "オペレーションは動物ではなく、走るものとして使えない。"}, {"text": "オペレーションの上に座って休んだ。", "explanation": "オペレーションは座れる物ではなく、場所のようには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
