INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52014, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「オペレーションを行う」で、行う対象を示す。"}, {"text": "の", "is_correct": false, "explanation": "「オペレーションの行った」は動詞に直接つながらず非文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語「中央銀行が」がすでにあり、「オペレーションが行った」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「オペレーションと行った」は意味が通らず非文になる。"}], "correct_answer": "を", "explanations": {"を": "「オペレーションを行う」で、行う対象を示す。", "の": "「オペレーションの行った」は動詞に直接つながらず非文になる。", "が": "主語「中央銀行が」がすでにあり、「オペレーションが行った」は成り立たない。", "と": "「オペレーションと行った」は意味が通らず非文になる。"}, "error_tags": {"の": "連体修飾", "が": "主格", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52014, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「このオペレーションによって」で、原因・手段を表す。"}, {"text": "を", "is_correct": false, "explanation": "「をよって」とは言えず非文になる。"}, {"text": "が", "is_correct": false, "explanation": "「がよって」とは言えず非文になる。"}, {"text": "の", "is_correct": false, "explanation": "「のよって」とは言えず非文になる。"}], "correct_answer": "に", "explanations": {"に": "「このオペレーションによって」で、原因・手段を表す。", "を": "「をよって」とは言えず非文になる。", "が": "「がよって」とは言えず非文になる。", "の": "「のよって」とは言えず非文になる。"}, "error_tags": {"を": "対象格", "が": "主格", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52014, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あらかじめ計画された、組織的な活動や作業。特に、経済や金融の分野で、中央銀行などが市場に介入するための具体的な取引や政策手段を指す。", "primary_collocate": null, "pronunciation": "おぺれーしょん", "ipa": "opeɾeːɕoɴ", "syllable_count": 6, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "オペレーション", "complexity_tier": "T6", "furigana": "中央銀行[ちゅうおうぎんこう]による大規模[だいきぼ]な資産[しさん]買入[かいいれ]オペレーション、すなわち量的[りょうてき]緩和[かんわ]政策[せいさく]は、単[たん]なる流動性[りゅうどうせい]の供給[きょうきゅう]にとどまらず、国債[こくさい]市場[しじょう]における価格[かかく]発見[はっけん]機能[きのう]を歪曲[わいきょく]せしめる側面[そくめん]を孕[はら]んでいる。", "sentence_source": "mined"}, {"text": "中央銀行がオペレーションを行った。", "target_word": "オペレーション", "complexity_tier": "T3", "furigana": "中央銀行[ちゅうおうぎんこう]がオペレーションを行[おこな]った。", "sentence_source": "generated"}, {"text": "日銀はオペレーションを実施します。", "target_word": "オペレーション", "complexity_tier": "T2", "furigana": "日銀[にちぎん]はオペレーションを実施[じっし]します。", "sentence_source": "generated"}, {"text": "日銀のオペレーションの目的は何ですか。", "target_word": "オペレーション", "complexity_tier": "T2", "furigana": "日銀[にちぎん]のオペレーションの目的[もくてき]は何[なん]ですか。", "sentence_source": "generated"}, {"text": "市場にお金を出すオペレーションが続いている。", "target_word": "オペレーション", "complexity_tier": "T3", "furigana": "市場[しじょう]にお金[かね]を出[だ]すオペレーションが続[つづ]いている。", "sentence_source": "generated"}, {"text": "今日のオペレーションの結果が発表された。", "target_word": "オペレーション", "complexity_tier": "T4", "furigana": "今日[きょう]のオペレーションの結果[けっか]が発表[はっぴょう]された。", "sentence_source": "generated"}, {"text": "金利を下げるために、日銀は緊急のオペレーションを行った。", "target_word": "オペレーション", "complexity_tier": "T4", "furigana": "金利[きんり]を下[さ]げるために、日銀[にちぎん]は緊急[きんきゅう]のオペレーションを行[おこな]った。", "sentence_source": "generated"}, {"text": "このオペレーションによって、市場の不安は少しやわらいだ。", "target_word": "オペレーション", "complexity_tier": "T4", "furigana": "このオペレーションによって、市場[しじょう]の不安[ふあん]は少[すこ]しやわらいだ。", "sentence_source": "generated"}, {"text": "日銀が計画したオペレーションは、予定どおり三日間で終わった。", "target_word": "オペレーション", "complexity_tier": "T4", "furigana": "日銀[にちぎん]が計画[けいかく]したオペレーションは、予定[よてい]どおり三日間[みっかかん]で終[お]わった。", "sentence_source": "generated"}, {"text": "政府は為替を安定させるオペレーションを検討していると報じられた。", "target_word": "オペレーション", "complexity_tier": "T5", "furigana": "政府[せいふ]は為替[かわせ]を安定[あんてい]させるオペレーションを検討[けんとう]していると報[ほう]じられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オペレーター", "label": "派生"}, {"form": "オペレート", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 中央銀行などの市場介入の取引", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52014, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オペレーション", "is_correct": true, "explanation": "中央銀行の資産買入という市場介入の取引を指し、文脈に合う。"}, {"text": "ダイエット", "is_correct": false, "explanation": "形は合うが、資産買入や量的緩和とは意味が合わない。"}, {"text": "ボランティア", "is_correct": false, "explanation": "形は合うが、中央銀行の政策手段という意味が合わない。"}, {"text": "メンテナンス", "is_correct": false, "explanation": "形は合うが、市場介入の取引という意味が合わない。"}], "explanations": {"オペレーション": "中央銀行の資産買入という市場介入の取引を指し、文脈に合う。", "ダイエット": "形は合うが、資産買入や量的緩和とは意味が合わない。", "ボランティア": "形は合うが、中央銀行の政策手段という意味が合わない。", "メンテナンス": "形は合うが、市場介入の取引という意味が合わない。"}, "sentence_index": 0, "correct_answer": "オペレーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ご飯にオペレーションを食べました。", "explanation": "オペレーションは計画的な活動や取引で、食べ物ではないので「食べる」の目的語にならない。"}, {"text": "日銀のオペレーションは青くて冷たい。", "explanation": "オペレーションは活動・政策手段で、色や温度を表す形容詞では修飾できない。"}, {"text": "オペレーションに乗って学校へ行きました。", "explanation": "オペレーションは乗り物ではないので「乗る」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52014, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オペレーション", "is_correct": true, "explanation": "金利を下げる市場介入の取引を指し、文脈に合う。"}, {"text": "コンサート", "is_correct": false, "explanation": "形は合うが、金利を下げるための日銀の行為という意味が合わない。"}, {"text": "ファッション", "is_correct": false, "explanation": "形は合うが、金融政策の手段という意味が合わない。"}, {"text": "ダイエット", "is_correct": false, "explanation": "形は合うが、金利を下げる目的と意味が合わない。"}], "explanations": {"オペレーション": "金利を下げる市場介入の取引を指し、文脈に合う。", "コンサート": "形は合うが、金利を下げるための日銀の行為という意味が合わない。", "ファッション": "形は合うが、金融政策の手段という意味が合わない。", "ダイエット": "形は合うが、金利を下げる目的と意味が合わない。"}, "sentence_index": 6, "correct_answer": "オペレーション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公園でオペレーションを三つ拾って帰った。", "explanation": "オペレーションは数えて拾える物ではなく、活動を指す語なので使い方が誤り。"}, {"text": "オペレーションは犬のように庭を走っている。", "explanation": "オペレーションは動物ではなく、走るものとして使えない。"}, {"text": "彼はオペレーションを着て会議に出た。", "explanation": "オペレーションは衣服ではなく、「着る」の目的語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
