INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52015, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「量的」は、「量（りょう）」についての、という意味です。", "primary_collocate": null, "pronunciation": "りょうてき", "ipa": "ɾʲoːteki", "syllable_count": 4, "sentences": [{"text": "これは質ではなく、量的な話だ。", "target_word": "量的な", "complexity_tier": "T2", "furigana": "これは質[しつ]ではなく、量的[りょうてき]な話[はなし]だ。", "sentence_source": "generated"}, {"text": "量的に多いです。", "target_word": "量的に", "complexity_tier": "T2", "furigana": "量的[りょうてき]に多[おお]いです。", "sentence_source": "generated"}, {"text": "この問題は量的です。", "target_word": "量的", "complexity_tier": "T2", "furigana": "この問題[もんだい]は量的[りょうてき]です。", "sentence_source": "generated"}, {"text": "差は量的でした。", "target_word": "量的", "complexity_tier": "T2", "furigana": "差[さ]は量的[りょうてき]でした。", "sentence_source": "generated"}, {"text": "量的な面では問題ありません。", "target_word": "量的な", "complexity_tier": "T2", "furigana": "量的[りょうてき]な面[めん]では問題[もんだい]ありません。", "sentence_source": "generated"}, {"text": "量的には足りている。", "target_word": "量的には", "complexity_tier": "T3", "furigana": "量的[りょうてき]には足[た]りている。", "sentence_source": "generated"}, {"text": "勉強は、量的にも質的にも大切だ。", "target_word": "量的にも", "complexity_tier": "T3", "furigana": "勉強[べんきょう]は、量的[りょうてき]にも質的[しつてき]にも大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "量的に見ると、今年の雨は去年よりずっと多かった。", "target_word": "量的に", "complexity_tier": "T4", "furigana": "量的[りょうてき]に見[み]ると、今年[ことし]の雨[あめ]は去年[きょねん]よりずっと多[おお]かった。", "sentence_source": "generated"}, {"text": "量的な比較だけでは、本当の価値は分からない。", "target_word": "量的な", "complexity_tier": "T4", "furigana": "量的[りょうてき]な比較[ひかく]だけでは、本当[ほんとう]の価値[かち]は分[わ]からない。", "sentence_source": "generated"}, {"text": "この調査は量的なデータを中心にまとめた。", "target_word": "量的な", "complexity_tier": "T4", "furigana": "この調査[ちょうさ]は量的[りょうてき]なデータを中心[ちゅうしん]にまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "量的な", "label": "活用"}, {"form": "量的に", "label": "活用"}, {"form": "量的だ", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | 量についてのという意味の語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52015, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "量的な", "is_correct": true, "explanation": "「質ではなく」と対比され、量についての話という意味で自然。"}, {"text": "爆発的な", "is_correct": false, "explanation": "形は合うが、量についての話という意味が合わない。"}, {"text": "瞬間的な", "is_correct": false, "explanation": "形は合うが、量についての話という意味が合わない。"}, {"text": "圧倒的な", "is_correct": false, "explanation": "形は合うが、量についての話という意味が合わない。"}], "explanations": {"量的な": "「質ではなく」と対比され、量についての話という意味で自然。", "爆発的な": "形は合うが、量についての話という意味が合わない。", "瞬間的な": "形は合うが、量についての話という意味が合わない。", "圧倒的な": "形は合うが、量についての話という意味が合わない。"}, "sentence_index": 0, "correct_answer": "量的な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の性格は量的で、とても明るい。", "explanation": "量的は量に関する語で、性格を表す語ではない。"}, {"text": "量的な色の服を着ている。", "explanation": "色の様子は量的では表せず、意味が合わない。"}, {"text": "山道を量的に歩いて、足が痛くなった。", "explanation": "量的には歩き方を表す意味はなく、使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52015, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "量的にも", "is_correct": true, "explanation": "「質的にも」と対になり、量の面でも大切という意味で自然。"}, {"text": "感情的にも", "is_correct": false, "explanation": "形は合うが、「質的にも」と対になる意味が合わない。"}, {"text": "劇的にも", "is_correct": false, "explanation": "形は合うが、勉強が大切という文脈に意味が合わない。"}, {"text": "偶発的にも", "is_correct": false, "explanation": "形は合うが、勉強が大切という文脈に意味が合わない。"}], "explanations": {"量的にも": "「質的にも」と対になり、量の面でも大切という意味で自然。", "感情的にも": "形は合うが、「質的にも」と対になる意味が合わない。", "劇的にも": "形は合うが、勉強が大切という文脈に意味が合わない。", "偶発的にも": "形は合うが、勉強が大切という文脈に意味が合わない。"}, "sentence_index": 6, "correct_answer": "量的にも"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "量的な声で歌を歌った。", "explanation": "量的は量に関する語で、声の質を表す語ではない。"}, {"text": "量的に笑って、友達に挨拶した。", "explanation": "量的には笑い方を表す意味はなく、使い方が誤り。"}, {"text": "あの人は量的で、みんなに好かれている。", "explanation": "量的は人柄を表す語ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52015, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この問題は量的なです。", "corrected_sentence": "この問題は量的です。", "error_description": "「です」の前では「量的な」ではなく「量的」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "量的に", "is_correct": true, "explanation": "「多い」を修飾する連用形で、スロットに合う。"}, {"text": "量的な", "is_correct": false, "explanation": "連体形なので、形容詞「多い」の前には置けない。"}, {"text": "量的だ", "is_correct": false, "explanation": "終止形なので、後ろに「多いです」を続けられない。"}, {"text": "量的だった", "is_correct": false, "explanation": "過去形の終止形なので、このスロットには合わない。"}], "correct_form": "量的に", "base_form": "量的", "form_label": "連用形", "sentence_index": 1, "explanations": {"量的に": "「多い」を修飾する連用形で、スロットに合う。", "量的な": "連体形なので、形容詞「多い」の前には置けない。", "量的だ": "終止形なので、後ろに「多いです」を続けられない。", "量的だった": "過去形の終止形なので、このスロットには合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52015, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "量的で見ると、今年の雨は去年より多かった。", "corrected_sentence": "量的に見ると、今年の雨は去年より多かった。", "error_description": "「見る」を修飾する形は「量的で」ではなく「量的に」である。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "量的に", "is_correct": true, "explanation": "「見ると」を修飾する連用形で、スロットに合う。"}, {"text": "量的な", "is_correct": false, "explanation": "連体形なので、動詞「見る」の前には置けない。"}, {"text": "量的で", "is_correct": false, "explanation": "「量的で見ると」は動詞を修飾できず、不自然になる。"}, {"text": "量的だろう", "is_correct": false, "explanation": "推量形なので、後ろに「見ると」を続けられない。"}], "correct_form": "量的に", "base_form": "量的", "form_label": "連用形", "sentence_index": 7, "explanations": {"量的に": "「見ると」を修飾する連用形で、スロットに合う。", "量的な": "連体形なので、動詞「見る」の前には置けない。", "量的で": "「量的で見ると」は動詞を修飾できず、不自然になる。", "量的だろう": "推量形なので、後ろに「見ると」を続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52016, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "質的", "is_correct": true, "explanation": "量に対して質に関することを表す対義語。"}, {"text": "具体的", "is_correct": false, "explanation": "具体的は量的の対義語ではない。"}, {"text": "基本的", "is_correct": false, "explanation": "基本的は量的の対義語ではない。"}, {"text": "個人的", "is_correct": false, "explanation": "個人的は量的の対義語ではない。"}], "correct_answer": "質的", "explanations": {"質的": "量に対して質に関することを表す対義語。", "具体的": "具体的は量的の対義語ではない。", "基本的": "基本的は量的の対義語ではない。", "個人的": "個人的は量的の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52016, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "質的な", "is_correct": true, "explanation": "量的に対して質に関することを表す対義語。"}, {"text": "社会的な", "is_correct": false, "explanation": "社会的は量的の対義語ではない。"}, {"text": "国際的な", "is_correct": false, "explanation": "国際的は量的の対義語ではない。"}, {"text": "長期的な", "is_correct": false, "explanation": "長期的は量的の対義語ではない。"}], "correct_answer": "質的な", "explanations": {"質的な": "量的に対して質に関することを表す対義語。", "社会的な": "社会的は量的の対義語ではない。", "国際的な": "国際的は量的の対義語ではない。", "長期的な": "長期的は量的の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52016, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「量的」は、数量や量に関することを表す形容動詞の語幹です。特に経済学では、金融政策の手段として、通貨の供給量を直接的に増減させることを指します。", "primary_collocate": null, "pronunciation": "りょうてき", "ipa": "ɾʲoːteki", "syllable_count": 4, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "量的", "complexity_tier": "T6", "furigana": "中央銀行[ちゅうおうぎんこう]による大規模[だいきぼ]な資産[しさん]買入[かいいれ]オペレーション、すなわち量的[りょうてき]緩和[かんわ]政策[せいさく]は、単[たん]なる流動性[りゅうどうせい]の供給[きょうきゅう]にとどまらず、国債[こくさい]市場[しじょう]における価格[かかく]発見[はっけん]機能[きのう]を歪曲[わいきょく]せしめる側面[そくめん]を孕[はら]んでいる。", "sentence_source": "mined"}, {"text": "量的な差は小さい。", "target_word": "量的な", "complexity_tier": "T1", "furigana": "量的[りょうてき]な差[さ]は小[ちい]さい。", "sentence_source": "generated"}, {"text": "量的に十分です。", "target_word": "量的に", "complexity_tier": "T2", "furigana": "量的[りょうてき]に十分[じゅうぶん]です。", "sentence_source": "generated"}, {"text": "この違いは量的です。", "target_word": "量的", "complexity_tier": "T2", "furigana": "この違[ちが]いは量的[りょうてき]です。", "sentence_source": "generated"}, {"text": "この調査は量的に行われた。", "target_word": "量的に", "complexity_tier": "T3", "furigana": "この調査[ちょうさ]は量的[りょうてき]に行[おこな]われた。", "sentence_source": "generated"}, {"text": "量的な拡大が続いている。", "target_word": "量的な", "complexity_tier": "T3", "furigana": "量的[りょうてき]な拡大[かくだい]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "量的な緩和で、市場のお金が増えた。", "target_word": "量的な", "complexity_tier": "T3", "furigana": "量的[りょうてき]な緩和[かんわ]で、市場[しじょう]のお金[かね]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "売り上げは量的には増えたが、利益は減った。", "target_word": "量的には", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げは量的[りょうてき]には増[ふ]えたが、利益[りえき]は減[へ]った。", "sentence_source": "generated"}, {"text": "質的な変化ではなく、量的な変化にすぎない。", "target_word": "量的な", "complexity_tier": "T4", "furigana": "質的[しつてき]な変化[へんか]ではなく、量的[りょうてき]な変化[へんか]にすぎない。", "sentence_source": "generated"}, {"text": "中央銀行は量的な金融緩和を続けるかどうか議論している。", "target_word": "量的な", "complexity_tier": "T4", "furigana": "中央銀行[ちゅうおうぎんこう]は量的[りょうてき]な金融緩和[きんゆうかんわ]を続[つづ]けるかどうか議論[ぎろん]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "量的な", "label": "活用"}, {"form": "量的に", "label": "活用"}, {"form": "量的だ", "label": "活用"}, {"form": "量的緩和", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 数量や量に関することを表す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52016, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "量的", "is_correct": true, "explanation": "通貨供給量を増やす「量的緩和」という語になり、文脈に合う。"}, {"text": "個人的", "is_correct": false, "explanation": "形は合うが、「個人的緩和政策」は意味が合わない。"}, {"text": "感情的", "is_correct": false, "explanation": "形は合うが、「感情的緩和政策」は意味が合わない。"}, {"text": "国際的", "is_correct": false, "explanation": "形は合うが、量的緩和の意味とは合わない。"}], "explanations": {"量的": "通貨供給量を増やす「量的緩和」という語になり、文脈に合う。", "個人的": "形は合うが、「個人的緩和政策」は意味が合わない。", "感情的": "形は合うが、「感情的緩和政策」は意味が合わない。", "国際的": "形は合うが、量的緩和の意味とは合わない。"}, "sentence_index": 0, "correct_answer": "量的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は量的な人で、いつも優しく笑う。", "explanation": "量的は数量に関することで、人の性格を表す語ではない。"}, {"text": "このスープは量的で、とても辛い。", "explanation": "量的は味の性質ではなく、数量に関する語なので誤り。"}, {"text": "量的な空が広がっている。", "explanation": "空の様子は量的とは言わず、数量に関する意味と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52016, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "量的な", "is_correct": true, "explanation": "お金の量を増やす「量的な緩和」で、文脈に合う。"}, {"text": "感情的な", "is_correct": false, "explanation": "形は合うが、「感情的な緩和」では市場のお金が増える意味が合わない。"}, {"text": "個人的な", "is_correct": false, "explanation": "形は合うが、お金が増えた理由として意味が合わない。"}, {"text": "芸術的な", "is_correct": false, "explanation": "形は合うが、「芸術的な緩和」では市場のお金が増える理由として意味が合わない。"}], "explanations": {"量的な": "お金の量を増やす「量的な緩和」で、文脈に合う。", "感情的な": "形は合うが、「感情的な緩和」では市場のお金が増える意味が合わない。", "個人的な": "形は合うが、お金が増えた理由として意味が合わない。", "芸術的な": "形は合うが、「芸術的な緩和」では市場のお金が増える理由として意味が合わない。"}, "sentence_index": 6, "correct_answer": "量的な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "量的な歌手が舞台で歌った。", "explanation": "量的は数量に関する語で、人の特徴を表す語ではない。"}, {"text": "朝から量的に走って学校へ行った。", "explanation": "量的には走る様子を表す意味はなく、使い方が誤り。"}, {"text": "この音楽は量的で、とても悲しい。", "explanation": "量的は感情の性質を表す語ではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52016, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "量的の差は小さい。", "corrected_sentence": "量的な差は小さい。", "error_description": "名詞を修飾するときは「量的の」ではなく「量的な」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "量的な", "is_correct": true, "explanation": "名詞「差」を修飾する連体形で、スロットに合う。"}, {"text": "量的だ", "is_correct": false, "explanation": "終止形なので、名詞「差」を修飾できない。"}, {"text": "量的です", "is_correct": false, "explanation": "丁寧な終止形なので、名詞の前には置けない。"}, {"text": "量的だった", "is_correct": false, "explanation": "過去形の終止形なので、名詞の前には置けない。"}], "correct_form": "量的な", "base_form": "量的", "form_label": "連体形", "sentence_index": 1, "explanations": {"量的な": "名詞「差」を修飾する連体形で、スロットに合う。", "量的だ": "終止形なので、名詞「差」を修飾できない。", "量的です": "丁寧な終止形なので、名詞の前には置けない。", "量的だった": "過去形の終止形なので、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52016, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "売り上げは量的が増えたが、利益は減った。", "corrected_sentence": "売り上げは量的には増えたが、利益は減った。", "error_description": "「量的」は形状詞なので「が」を付けて主語にできない。量の面を表すには「量的には」（または「量的に」）とする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "量的には", "is_correct": true, "explanation": "量の面では、と限定して対比する形で、後ろの「が」に合う。"}, {"text": "量的だ", "is_correct": false, "explanation": "終止形なので、「増えたが」の前には置けない。"}, {"text": "量的です", "is_correct": false, "explanation": "丁寧な終止形なので、このスロットには合わない。"}, {"text": "量的な", "is_correct": false, "explanation": "連体形なので、動詞「増えた」の前には置けない。"}], "correct_form": "量的には", "base_form": "量的", "form_label": "連用形+は", "sentence_index": 7, "explanations": {"量的には": "量の面では、と限定して対比する形で、後ろの「が」に合う。", "量的だ": "終止形なので、「増えたが」の前には置けない。", "量的です": "丁寧な終止形なので、このスロットには合わない。", "量的な": "連体形なので、動詞「増えた」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
