INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52018, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お金の預金や貸し付け、為替取引などを行う金融機関。", "primary_collocate": null, "pronunciation": "ぎんこう", "ipa": "ɡiŋkoː", "syllable_count": 4, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "銀行", "complexity_tier": "T6", "furigana": "ちゅうおうぎんこうによるだいきぼなしさんかいいれオペレーション、すなわちりょうてきかんわせいさくは、たんなるりゅうどうせいのきょうきゅうにとどまらず、こくさいしじょうにおけるかかくはっけんきのうをわいきょくせしめるそくめんをはらんでいる。", "sentence_source": "mined"}, {"text": "銀行に行く。", "target_word": "銀行", "complexity_tier": "T1", "furigana": "ぎんこうにいく。", "sentence_source": "generated"}, {"text": "銀行は九時に開きます。", "target_word": "銀行", "complexity_tier": "T2", "furigana": "ぎんこうはくじにあきます。", "sentence_source": "generated"}, {"text": "母は銀行で働いています。", "target_word": "銀行", "complexity_tier": "T3", "furigana": "はははぎんこうではたらいています。", "sentence_source": "generated"}, {"text": "銀行からお金を借りて、家を買った。", "target_word": "銀行", "complexity_tier": "T3", "furigana": "ぎんこうからおかねをかりて、いえをかった。", "sentence_source": "generated"}, {"text": "駅の前に新しい銀行ができました。", "target_word": "銀行", "complexity_tier": "T2", "furigana": "えきのまえにあたらしいぎんこうができました。", "sentence_source": "generated"}, {"text": "この銀行の口座を開きたい。", "target_word": "銀行", "complexity_tier": "T3", "furigana": "このぎんこうのこうざをひらきたい。", "sentence_source": "generated"}, {"text": "銀行が金利を引き上げたため、住宅ローンの返済額が増えた。", "target_word": "銀行", "complexity_tier": "T4", "furigana": "ぎんこうがきんりをひきあげたため、じゅうたくローンのへんさいがくがふえた。", "sentence_source": "generated"}, {"text": "銀行に預けたお金は、安全に守られている。", "target_word": "銀行", "complexity_tier": "T4", "furigana": "ぎんこうにあずけたおかねは、あんぜんにまもられている。", "sentence_source": "generated"}, {"text": "彼は銀行と交渉して、融資を受けることができた。", "target_word": "銀行", "complexity_tier": "T4", "furigana": "かれはぎんこうとこうしょうして、ゆうしをうけることができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "銀行員", "label": "派生"}, {"form": "銀行口座", "label": "派生"}, {"form": "銀行家", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 預金や貸付を行う金融機関", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: せしめる (Zipf 2.46)']::text[], '78030f87-aae1-459b-9e77-753f1c3b3c04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52018, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "銀行", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "金鉱", "is_correct": false, "explanation": "きんこう。最初の音が「ぎ」ではなく「き」です。"}, {"text": "人口", "is_correct": false, "explanation": "じんこう。最初の音が「ぎ」ではなく「じ」です。"}, {"text": "進行", "is_correct": false, "explanation": "しんこう。最初の音が「ぎ」ではなく「し」です。"}, {"text": "咽喉", "is_correct": false, "explanation": "いんこう。最初の音が「ぎ」ではなく「い」です。"}], "explanations": {"銀行": "見出し語そのものです。", "金鉱": "きんこう。最初の音が「ぎ」ではなく「き」です。", "人口": "じんこう。最初の音が「ぎ」ではなく「じ」です。", "進行": "しんこう。最初の音が「ぎ」ではなく「し」です。", "咽喉": "いんこう。最初の音が「ぎ」ではなく「い」です。"}, "sentence_index": null, "correct_answer": "銀行"}, "level_3": {"options": [{"text": "銀行", "is_correct": true, "explanation": "中央銀行は量的緩和を行う機関なので文脈に合います。"}, {"text": "図書館", "is_correct": false, "explanation": "形は合うが意味が合わない。図書館は資産買入を行いません。"}, {"text": "郵便局", "is_correct": false, "explanation": "形は合うが意味が合わない。「中央郵便局」は量的緩和政策の主体ではありません。"}, {"text": "動物園", "is_correct": false, "explanation": "形は合うが意味が合わない。動物園は金融政策と無関係です。"}], "explanations": {"銀行": "中央銀行は量的緩和を行う機関なので文脈に合います。", "図書館": "形は合うが意味が合わない。図書館は資産買入を行いません。", "郵便局": "形は合うが意味が合わない。「中央郵便局」は量的緩和政策の主体ではありません。", "動物園": "形は合うが意味が合わない。動物園は金融政策と無関係です。"}, "sentence_index": 0, "correct_answer": "銀行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "銀行で新鮮な野菜と魚を買って、夕食を作った。", "explanation": "銀行は金融機関で、野菜や魚を売る店ではありません。"}, {"text": "毎朝、銀行に乗って学校へ行く。", "explanation": "銀行は乗り物ではないので「乗る」と合いません。"}, {"text": "銀行の先生が、教室で算数を教えてくれた。", "explanation": "銀行は学校ではないので、先生が教室で算数を教える場所ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCL