INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52018, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "銀行", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "品行", "is_correct": false, "explanation": "ひんこう。最初の音が「ぎ」ではなく「ひ」です。"}, {"text": "燐光", "is_correct": false, "explanation": "りんこう。最初の音が「ぎ」ではなく「り」です。"}, {"text": "沈降", "is_correct": false, "explanation": "ちんこう。最初の音が「ぎ」ではなく「ち」です。"}, {"text": "鈍行", "is_correct": false, "explanation": "どんこう。最初の音が「ぎ」ではなく「ど」です。"}], "explanations": {"銀行": "見出し語そのものです。", "品行": "ひんこう。最初の音が「ぎ」ではなく「ひ」です。", "燐光": "りんこう。最初の音が「ぎ」ではなく「り」です。", "沈降": "ちんこう。最初の音が「ぎ」ではなく「ち」です。", "鈍行": "どんこう。最初の音が「ぎ」ではなく「ど」です。"}, "sentence_index": null, "correct_answer": "銀行"}, "level_3": {"options": [{"text": "銀行", "is_correct": true, "explanation": "口座を開くのは銀行なので意味が合います。"}, {"text": "公園", "is_correct": false, "explanation": "形は合うが意味が合わない。公園の口座を開くことはできません。"}, {"text": "病院", "is_correct": false, "explanation": "形は合うが意味が合わない。病院で口座を開く意味にはなりません。"}, {"text": "図書館", "is_correct": false, "explanation": "形は合うが意味が合わない。図書館の口座とは言いません。"}], "explanations": {"銀行": "口座を開くのは銀行なので意味が合います。", "公園": "形は合うが意味が合わない。公園の口座を開くことはできません。", "病院": "形は合うが意味が合わない。病院で口座を開く意味にはなりません。", "図書館": "形は合うが意味が合わない。図書館の口座とは言いません。"}, "sentence_index": 6, "correct_answer": "銀行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "銀行に切手を貼って手紙を送った。", "explanation": "銀行は手紙ではないので、切手を貼って送ることはできません。"}, {"text": "銀行の上を歩いて、海を渡った。", "explanation": "銀行は橋や道ではないので、その上を歩いて海を渡ることはできません。"}, {"text": "銀行でカレーとサラダを注文した。", "explanation": "銀行は金融機関で、料理を注文する飲食店ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_err