INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52019, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「お金」はせしめる対象で、目的語の「を」が入ります。"}, {"text": "に", "is_correct": false, "explanation": "「お金にせしめた」とは言えません。"}, {"text": "へ", "is_correct": false, "explanation": "「お金へせしめた」とは言えません。"}, {"text": "と", "is_correct": false, "explanation": "「お金とせしめた」とは言えません。"}], "correct_answer": "を", "explanations": {"を": "「お金」はせしめる対象で、目的語の「を」が入ります。", "に": "「お金にせしめた」とは言えません。", "へ": "「お金へせしめた」とは言えません。", "と": "「お金とせしめた」とは言えません。"}, "error_tags": {"に": "target_marker", "へ": "direction", "と": "companion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贈る", "is_correct": true, "explanation": "相手に物をあげる「贈る」は、手に入れる「せしめる」と反対の関係です。"}, {"text": "盗む", "is_correct": false, "explanation": "人の物を不正に取る意味で、類義語です。反対ではありません。"}, {"text": "奪う", "is_correct": false, "explanation": "力ずくで取る意味で、類義語です。反対ではありません。"}, {"text": "騙す", "is_correct": false, "explanation": "うそで人を信じさせる意味で、反対の関係ではありません。"}], "correct_answer": "贈る", "explanations": {"贈る": "相手に物をあげる「贈る」は、手に入れる「せしめる」と反対の関係です。", "盗む": "人の物を不正に取る意味で、類義語です。反対ではありません。", "奪う": "力ずくで取る意味で、類義語です。反対ではありません。", "騙す": "うそで人を信じさせる意味で、反対の関係ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
