INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52019, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「せしめる」は、悪い方法で何かを手に入れることです。", "primary_collocate": null, "pronunciation": "せしめる", "ipa": "seɕimeɾɯ", "syllable_count": 4, "sentences": [{"text": "彼は私の本をせしめた。", "target_word": "せしめた", "complexity_tier": "T3", "furigana": "かれはわたしのほんをせしめた。", "sentence_source": "generated"}, {"text": "悪い人が、お金をせしめた。", "target_word": "せしめた", "complexity_tier": "T3", "furigana": "わるいひとが、おかねをせしめた。", "sentence_source": "generated"}, {"text": "弟は兄からゲームをせしめた。", "target_word": "せしめた", "complexity_tier": "T3", "furigana": "おとうとはあにからゲームをせしめた。", "sentence_source": "generated"}, {"text": "あの人は、うそをついてお金をせしめます。", "target_word": "せしめます", "complexity_tier": "T3", "furigana": "あのひとは、うそをついておかねをせしめます。", "sentence_source": "generated"}, {"text": "友達にお菓子をせしめられた。", "target_word": "せしめられた", "complexity_tier": "T4", "furigana": "ともだちにおかしをせしめられた。", "sentence_source": "generated"}, {"text": "彼はただで食事をせしめようとした。", "target_word": "せしめよう", "complexity_tier": "T4", "furigana": "かれはただでしょくじをせしめようとした。", "sentence_source": "generated"}, {"text": "せしめたお金で、車を買ったらしい。", "target_word": "せしめた", "complexity_tier": "T3", "furigana": "せしめたおかねで、くるまをかったらしい。", "sentence_source": "generated"}, {"text": "先輩から昼ご飯をせしめて、得をした。", "target_word": "せしめて", "complexity_tier": "T3", "furigana": "せんぱいからひるごはんをせしめて、とくをした。", "sentence_source": "generated"}, {"text": "彼女は上手に客から金をせしめている。", "target_word": "せしめて", "complexity_tier": "T3", "furigana": "かのじょはじょうずにきゃくからかねをせしめている。", "sentence_source": "generated"}, {"text": "人の物をせしめるのは、悪いことです。", "target_word": "せしめる", "complexity_tier": "T3", "furigana": "ひとのものをせしめるのは、わるいことです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "せしめた", "label": "活用"}, {"form": "せしめて", "label": "活用"}, {"form": "せしめない", "label": "活用"}, {"form": "せしめられる", "