INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52019, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "せしめた", "is_correct": true, "explanation": "悪い方法で私の本を手に入れたという意味が合います。"}, {"text": "割った", "is_correct": false, "explanation": "形は合うが意味が合わない。本を割るとは言いません。"}, {"text": "飲んだ", "is_correct": false, "explanation": "形は合うが意味が合わない。本は飲むものではありません。"}, {"text": "着た", "is_correct": false, "explanation": "形は合うが意味が合わない。本は着るものではありません。"}], "explanations": {"せしめた": "悪い方法で私の本を手に入れたという意味が合います。", "割った": "形は合うが意味が合わない。本を割るとは言いません。", "飲んだ": "形は合うが意味が合わない。本は飲むものではありません。", "着た": "形は合うが意味が合わない。本は着るものではありません。"}, "sentence_index": 0, "correct_answer": "せしめた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎晩、ベッドでぐっすり眠りをせしめます。", "explanation": "「せしめる」は悪い方法で物を得る意味で、眠りには使えません。"}, {"text": "友達の誕生日に、心をこめて花をせしめた。", "explanation": "「せしめる」は贈る意味ではありません。"}, {"text": "先生が黒板に字をせしめた。", "explanation": "「せしめる」は書く意味ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52019, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "せしめた", "is_correct": true, "explanation": "悪い方法で得たお金で車を買った、という意味が合います。"}, {"text": "落とした", "is_correct": false, "explanation": "形は合うが意味が合わない。落としたお金で車を買う流れになりません。"}, {"text": "燃やした", "is_correct": false, "explanation": "形は合うが意味が合わない。燃やしたお金では車を買えません。"}, {"text": "忘れた", "is_correct": false, "explanation": "形は合うが意味が合わない。忘れたお金で車を買う流れになりません。"}], "explanations": {"せしめた": "悪い方法で得たお金で車を買った、という意味が合います。", "落とした": "形は合うが意味が合わない。落としたお金で車を買う流れになりません。", "燃やした": "形は合うが意味が合わない。燃やしたお金では車を買えません。", "忘れた": "形は合うが意味が合わない。忘れたお金で車を買う流れになりません。"}, "sentence_index": 6, "correct_answer": "せしめた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "歌をせしめるのは、楽しいことです。", "explanation": "「せしめる」は歌う意味ではありません。"}, {"text": "友達と映画をせしめるのは、楽しいことです。", "explanation": "「せしめる」は映画を見る意味ではありません。"}, {"text": "宿題をせしめるのは、大切なことです。", "explanation": "「せしめる」は宿題をする意味ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52019, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "悪い人が、お金にせしめた。", "corrected_sentence": "悪い人が、お金をせしめた。", "error_description": "「せしめる」の目的語は「お金を」で表します。「に」は誤りです。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "せしめた", "is_correct": true, "explanation": "文末の過去形で、この文に合います。"}, {"text": "せしめて", "is_correct": false, "explanation": "て形では文が終わらず、続きが必要です。"}, {"text": "せしめれば", "is_correct": false, "explanation": "仮定形では文が終わらず、過去の出来事を述べる文に合いません。"}, {"text": "せしめろ", "is_correct": false, "explanation": "命令形では、悪い人がしたことを述べる文になりません。"}], "correct_form": "せしめた", "base_form": "せしめる", "form_label": "過去形", "sentence_index": 1, "explanations": {"せしめた": "文末の過去形で、この文に合います。", "せしめて": "て形では文が終わらず、続きが必要です。", "せしめれば": "仮定形では文が終わらず、過去の出来事を述べる文に合いません。", "せしめろ": "命令形では、悪い人がしたことを述べる文になりません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
