INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52020, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「せしめる」は、不正な手段や強引な方法で、金品や利益などを自分のものにすることを意味する動詞です。", "primary_collocate": null, "pronunciation": "せしめる", "ipa": "seɕimeɾɯ", "syllable_count": 4, "sentences": [{"text": "あいつ、うまいこと言って先輩から昼飯代をせしめたらしい。", "target_word": "せしめた", "complexity_tier": "T4", "furigana": "あいつ、うまいこといってせんぱいからひるめしだいをせしめたらしい。", "sentence_source": "generated"}, {"text": "彼は友人から大金をせしめた。", "target_word": "せしめた", "complexity_tier": "T3", "furigana": "かれはゆうじんからたいきんをせしめた。", "sentence_source": "generated"}, {"text": "詐欺師は老人からお金をせしめた。", "target_word": "せしめた", "complexity_tier": "T3", "furigana": "さぎしはろうじんからおかねをせしめた。", "sentence_source": "generated"}, {"text": "兄は父をうまく言いくるめて、小遣いをせしめた。", "target_word": "せしめた", "complexity_tier": "T4", "furigana": "あにはちちをうまくいいくるめて、こづかいをせしめた。", "sentence_source": "generated"}, {"text": "彼は取引先から多額の謝礼をせしめようとした。", "target_word": "せしめよう", "complexity_tier": "T4", "furigana": "かれはとりひきさきからたがくのしゃれいをせしめようとした。", "sentence_source": "generated"}, {"text": "あの男は、うまい話で人の金をせしめる。", "target_word": "せしめる", "complexity_tier": "T3", "furigana": "あのおとこは、うまいはなしでひとのかねをせしめる。", "sentence_source": "generated"}, {"text": "彼女は元夫から慰謝料をせしめたそうだ。", "target_word": "せしめた", "complexity_tier": "T4", "furigana": "かのじょはもとおっとからいしゃりょうをせしめたそうだ。", "sentence_source": "generated"}, {"text": "弟にジュースをせしめられた。", "target_word": "せしめられた", "complexity_tier": "T4", "furigana": "おとうとにジュースをせしめられた。", "sentence_source": "generated"}, {"text": "彼は会社の金をせしめて、姿を消した。", "target_word": "せしめて", "complexity_tier": "T3", "furigana": "かれはかいしゃのかねをせしめて、すがたをけした。", "sentence_source": "generated"}, {"text": "せしめたお金は、すぐに使い果たしてしまった。", "target_word": "せしめた", "complexity_tier": "T3", "furigana": "せしめたおかねは、すぐにつかいはたしてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "せしめた", "label": "活用"}, {"form": "せしめて", "label": "活用"}, {"form": "せしめない", "label": "活用"}, {"form": "せしめられる", "label": "活用"}], "register": "casual", "sense_fingerprint": "動詞 | 不正や強引な手で金品を得る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78030f87-aae1-459b-9e77-753f1c3b3c04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52020, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "せしめた", "is_correct": true, "explanation": "うまいことを言って先輩から昼飯代をずるく手に入れた、という意味で文に合います。"}, {"text": "払った", "is_correct": false, "explanation": "形は合うが意味が合わない。「先輩から〜を払った」ではお金の向きが逆です。"}, {"text": "貸した", "is_correct": false, "explanation": "形は合うが意味が合わない。「先輩から〜を貸した」ではお金の向きが逆です。"}, {"text": "捨てた", "is_correct": false, "explanation": "形は合うが意味が合わない。「うまいこと言って先輩から昼飯代を捨てた」は意味が通りません。"}], "explanations": {"せしめた": "うまいことを言って先輩から昼飯代をずるく手に入れた、という意味で文に合います。", "払った": "形は合うが意味が合わない。「先輩から〜を払った」ではお金の向きが逆です。", "貸した": "形は合うが意味が合わない。「先輩から〜を貸した」ではお金の向きが逆です。", "捨てた": "形は合うが意味が合わない。「うまいこと言って先輩から昼飯代を捨てた」は意味が通りません。"}, "sentence_index": 0, "correct_answer": "せしめた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の中で傘をせしめて、道を歩いた。", "explanation": "「せしめる」は金品を不正に得る意味で、傘を差す意味では使えません。"}, {"text": "母が料理をせしめて、家族に出した。", "explanation": "「せしめる」は料理を作る意味ではありません。"}, {"text": "先生は生徒に漢字をせしめた。", "explanation": "「せしめる」は教える意味ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52020, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "せしめた", "is_correct": true, "explanation": "元夫から慰謝料を強引に得た、という意味が合います。"}, {"text": "払った", "is_correct": false, "explanation": "形は合うが意味が合わない。「元夫から慰謝料を払った」では支払いの向きが合いません。"}, {"text": "断った", "is_correct": false, "explanation": "形は合うが意味が合わない。「元夫から慰謝料を断った」は不自然です。"}, {"text": "数えた", "is_correct": false, "explanation": "形は合うが意味が合わない。「元夫から」と数える動作が結びつきません。"}], "explanations": {"せしめた": "元夫から慰謝料を強引に得た、という意味が合います。", "払った": "形は合うが意味が合わない。「元夫から慰謝料を払った」では支払いの向きが合いません。", "断った": "形は合うが意味が合わない。「元夫から慰謝料を断った」は不自然です。", "数えた": "形は合うが意味が合わない。「元夫から」と数える動作が結びつきません。"}, "sentence_index": 6, "correct_answer": "せしめた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は窓をせしめて、部屋の空気を入れ替えた。", "explanation": "「せしめる」は金品を得る意味で、窓を開ける意味では使えません。"}, {"text": "毎朝、庭の花をせしめて、水をあげている。", "explanation": "「せしめる」は世話をする意味ではありません。"}, {"text": "彼は新しいシャツをせしめて、出かけた。", "explanation": "「せしめる」は着る意味ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52020, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "詐欺師は老人からお金へせしめた。", "corrected_sentence": "詐欺師は老人からお金をせしめた。", "error_description": "「せしめる」の目的語は「お金を」で表します。「へ」は誤りです。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "せしめた", "is_correct": true, "explanation": "文末の過去形で、この文に合います。"}, {"text": "せしめて", "is_correct": false, "explanation": "て形では文が終わらず、続きが必要です。"}, {"text": "せしめれば", "is_correct": false, "explanation": "仮定形では文が終わらず、過去の出来事を述べる文に合いません。"}, {"text": "せしめたら", "is_correct": false, "explanation": "条件形では後に続く文がなく、過去の出来事を述べる文として終われません。"}], "correct_form": "せしめた", "base_form": "せしめる", "form_label": "過去形", "sentence_index": 1, "explanations": {"せしめた": "文末の過去形で、この文に合います。", "せしめて": "て形では文が終わらず、続きが必要です。", "せしめれば": "仮定形では文が終わらず、過去の出来事を述べる文に合いません。", "せしめたら": "条件形では後に続く文がなく、過去の出来事を述べる文として終われません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52020, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの男は、うまい話で人の金がせしめる。", "corrected_sentence": "あの男は、うまい話で人の金をせしめる。", "error_description": "「せしめる」の目的語は「金を」で表します。「が」は誤りです。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "せしめられた", "is_correct": true, "explanation": "弟にジュースを取られたという受身の過去形です。"}, {"text": "せしめて", "is_correct": false, "explanation": "て形では文が終わらず、続きが必要です。"}, {"text": "せしめれば", "is_correct": false, "explanation": "仮定形では文が終わらず、被害を述べる文に合いません。"}, {"text": "せしめよう", "is_correct": false, "explanation": "意向形では「弟に〜られた」という被害の文になりません。"}], "correct_form": "せしめられた", "base_form": "せしめる", "form_label": "受身の過去形", "sentence_index": 7, "explanations": {"せしめられた": "弟にジュースを取られたという受身の過去形です。", "せしめて": "て形では文が終わらず、続きが必要です。", "せしめれば": "仮定形では文が終わらず、被害を述べる文に合いません。", "せしめよう": "意向形では「弟に〜られた」という被害の文になりません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52022, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "歪曲する対象「事実」を示す「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「事実に歪曲する」では対象を表せず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、歪曲の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」では歪曲の対象を示せず、文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "歪曲する対象「事実」を示す「を」が正しい。", "に": "「事実に歪曲する」では対象を表せず、文として成り立たない。", "へ": "「へ」は方向を表すので、歪曲の対象を示せない。", "と": "「と」では歪曲の対象を示せず、文として成り立たない。"}, "error_tags": {"に": "wrong_case_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52022, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「事実の歪曲」と、名詞「歪曲」の内容を示す「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "名詞「歪曲」の前に「事実を」を置くと、「だ」で終わる文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「事実に歪曲だ」では意味がつながらず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、名詞同士をつなげない。"}], "correct_answer": "の", "explanations": {"の": "「事実の歪曲」と、名詞「歪曲」の内容を示す「の」が正しい。", "を": "名詞「歪曲」の前に「事実を」を置くと、「だ」で終わる文として成り立たない。", "に": "「事実に歪曲だ」では意味がつながらず、文として成り立たない。", "へ": "「へ」は方向を表すので、名詞同士をつなげない。"}, "error_tags": {"を": "wrong_case_marker", "に": "wrong_case_marker", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52022, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本来の形や事実をゆがめて、正しくないものにすること。", "primary_collocate": null, "pronunciation": "わいきょく", "ipa": "waikʲokɯ", "syllable_count": 4, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "歪曲", "complexity_tier": "T6", "furigana": "ちゅうおうぎんこうによるだいきぼなしさんかいいれオペレーション、すなわちりょうてきかんわせいさくは、たんなるりゅうどうせいのきょうきゅうにとどまらず、こくさいしじょうにおけるかかくはっけんきのうをわいきょくせしめるそくめんをはらんでいる。", "sentence_source": "mined"}, {"text": "事実を歪曲してはいけない。", "target_word": "歪曲", "complexity_tier": "T3", "furigana": "じじつをわいきょくしてはいけない。", "sentence_source": "generated"}, {"text": "その記事は歴史を歪曲している。", "target_word": "歪曲", "complexity_tier": "T3", "furigana": "そのきじはれきしをわいきょくしている。", "sentence_source": "generated"}, {"text": "発言が歪曲されて伝わった。", "target_word": "歪曲", "complexity_tier": "T4", "furigana": "はつげんがわいきょくされてつたわった。", "sentence_source": "generated"}, {"text": "彼は証拠を歪曲して、自分に有利な話を作った。", "target_word": "歪曲", "complexity_tier": "T4", "furigana": "かれはしょうこをわいきょくして、じぶんにゆうりなはなしをつくった。", "sentence_source": "generated"}, {"text": "政府は統計の歪曲を否定した。", "target_word": "歪曲", "complexity_tier": "T3", "furigana": "せいふはとうけいのわいきょくをひていした。", "sentence_source": "generated"}, {"text": "歪曲された情報を信じてしまった。", "target_word": "歪曲", "complexity_tier": "T4", "furigana": "わいきょくされたじょうほうをしんじてしまった。", "sentence_source": "generated"}, {"text": "これは明らかな事実の歪曲だ。", "target_word": "歪曲", "complexity_tier": "T3", "furigana": "これはあきらかなじじつのわいきょくだ。", "sentence_source": "generated"}, {"text": "報道が真実を歪曲していると、彼女は批判した。", "target_word": "歪曲", "complexity_tier": "T4", "furigana": "ほうどうがしんじつをわいきょくしていると、かのじょはひはんした。", "sentence_source": "generated"}, {"text": "私の意見を歪曲しないでください。", "target_word": "歪曲", "complexity_tier": "T3", "furigana": "わたしのいけんをわいきょくしないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歪曲する", "label": "活用"}, {"form": "歪曲された", "label": "活用"}, {"form": "歪曲して", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 事実や形をゆがめて偽ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78030f87-aae1-459b-9e77-753f1c3b3c04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52022, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歪曲", "is_correct": true, "explanation": "聞こえた語そのもの「わいきょく」で、正解。"}, {"text": "開局", "is_correct": false, "explanation": "「かいきょく」で、最初の音が「わ」ではなく「か」。"}, {"text": "政局", "is_correct": false, "explanation": "「せいきょく」で、最初の音が「わ」ではなく「せ」。"}, {"text": "対局", "is_correct": false, "explanation": "「たいきょく」で、最初の音が「わ」ではなく「た」。"}, {"text": "湾曲", "is_correct": false, "explanation": "「わんきょく」で、二番目の音が「い」ではなく「ん」。"}], "explanations": {"歪曲": "聞こえた語そのもの「わいきょく」で、正解。", "開局": "「かいきょく」で、最初の音が「わ」ではなく「か」。", "政局": "「せいきょく」で、最初の音が「わ」ではなく「せ」。", "対局": "「たいきょく」で、最初の音が「わ」ではなく「た」。", "湾曲": "「わんきょく」で、二番目の音が「い」ではなく「ん」。"}, "sentence_index": null, "correct_answer": "歪曲"}, "level_3": {"options": [{"text": "歪曲", "is_correct": true, "explanation": "価格発見機能を本来の形からゆがめるという意味で、文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。機能を散歩させることはできない。"}, {"text": "乗車", "is_correct": false, "explanation": "形は合うが意味が合わない。市場の機能が乗車することはない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが意味が合わない。機能を卒業させるという意味は文脈に合わない。"}], "explanations": {"歪曲": "価格発見機能を本来の形からゆがめるという意味で、文脈に合う。", "散歩": "形は合うが意味が合わない。機能を散歩させることはできない。", "乗車": "形は合うが意味が合わない。市場の機能が乗車することはない。", "卒業": "形は合うが意味が合わない。機能を卒業させるという意味は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "歪曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強い風で、看板が歪曲してしまった。", "explanation": "この「歪曲」は事実や内容をゆがめて偽る意味なので、物が曲がる意味では使えない。"}, {"text": "記者は事実をありのままに歪曲して伝えた。", "explanation": "「歪曲」は事実をゆがめることなので、「ありのまま」とは意味が矛盾する。"}, {"text": "私は毎朝七時に歪曲して学校へ行く。", "explanation": "「歪曲」に移動する意味はなく、「行く」の動作を表す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52022, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "歪曲", "is_correct": true, "explanation": "聞こえた語そのもの「わいきょく」で、正解。"}, {"text": "大局", "is_correct": false, "explanation": "「たいきょく」で、最初の音が「わ」ではなく「た」。"}, {"text": "内局", "is_correct": false, "explanation": "「ないきょく」で、最初の音が「わ」ではなく「な」。"}, {"text": "湾曲", "is_correct": false, "explanation": "「わんきょく」で、二番目の音が「い」ではなく「ん」。"}], "explanations": {"歪曲": "聞こえた語そのもの「わいきょく」で、正解。", "大局": "「たいきょく」で、最初の音が「わ」ではなく「た」。", "内局": "「ないきょく」で、最初の音が「わ」ではなく「な」。", "湾曲": "「わんきょく」で、二番目の音が「い」ではなく「ん」。"}, "sentence_index": null, "correct_answer": "歪曲"}, "level_3": {"options": [{"text": "歪曲", "is_correct": true, "explanation": "情報が本来の事実をゆがめられたという意味で、文脈に合う。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが意味が合わない。情報が結婚されることはない。"}, {"text": "乗車", "is_correct": false, "explanation": "形は合うが意味が合わない。情報が乗車されるという意味は成り立たない。"}, {"text": "入浴", "is_correct": false, "explanation": "形は合うが意味が合わない。情報が入浴されるという意味は成り立たない。"}], "explanations": {"歪曲": "情報が本来の事実をゆがめられたという意味で、文脈に合う。", "結婚": "形は合うが意味が合わない。情報が結婚されることはない。", "乗車": "形は合うが意味が合わない。情報が乗車されるという意味は成り立たない。", "入浴": "形は合うが意味が合わない。情報が入浴されるという意味は成り立たない。"}, "sentence_index": 6, "correct_answer": "歪曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この小説は、実際にあった出来事を忠実に歪曲した作品だ。", "explanation": "「歪曲」は事実を不正確にゆがめることなので、「忠実に」とは意味が矛盾する。"}, {"text": "弟は階段で転んで、足を歪曲した。", "explanation": "「歪曲」は事実や内容をゆがめる意味で、ケガをする意味では使えない。"}, {"text": "お昼に歪曲を食べてから、午後の授業に出た。", "explanation": "「歪曲」は食べ物ではないので、「食べる」の目的語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.valida