INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52023, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国が、お金を借りるための証書です。", "primary_collocate": null, "pronunciation": "こくさい", "ipa": "kokɯsai", "syllable_count": 4, "sentences": [{"text": "国は国債を出しました。", "target_word": "国債", "complexity_tier": "T2", "furigana": "くにはこくさいをだしました。", "sentence_source": "generated"}, {"text": "国債とは、国の借金の証書です。", "target_word": "国債", "complexity_tier": "T2", "furigana": "こくさいとは、くにのしゃっきんのしょうしょです。", "sentence_source": "generated"}, {"text": "父は国債を買った。", "target_word": "国債", "complexity_tier": "T1", "furigana": "ちちはこくさいをかった。", "sentence_source": "generated"}, {"text": "国債の利子を受け取る。", "target_word": "国債", "complexity_tier": "T1", "furigana": "こくさいのりしをうけとる。", "sentence_source": "generated"}, {"text": "国債は安全だと言われます。", "target_word": "国債", "complexity_tier": "T4", "furigana": "こくさいはあんぜんだといわれます。", "sentence_source": "generated"}, {"text": "国債を売って、お金を作った。", "target_word": "国債", "complexity_tier": "T3", "furigana": "こくさいをうって、おかねをつくった。", "sentence_source": "generated"}, {"text": "国債で集めたお金を、学校に使う。", "target_word": "国債", "complexity_tier": "T3", "furigana": "こくさいであつめたおかねを、がっこうにつかう。", "sentence_source": "generated"}, {"text": "銀行も国債を持っています。", "target_word": "国債", "complexity_tier": "T2", "furigana": "ぎんこうもこくさいをもっています。", "sentence_source": "generated"}, {"text": "国債が増えすぎて、心配です。", "target_word": "国債", "complexity_tier": "T2", "furigana": "こくさいがふえすぎて、しんぱいです。", "sentence_source": "generated"}, {"text": "来年も新しい国債が出る予定だ。", "target_word": "国債", "complexity_tier": "T3", "furigana": "らいねんもあたらしいこくさいがでるよていだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国債市場", "label": "派生"}, {"form": "国債費", "label": "派生"}, {"form": "国債残高", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 国がお金を借りる証書", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78030f87-aae1-459b-9e77-753f1c3b3c04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52023, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国債", "is_correct": true, "explanation": "「こくさい」。聞こえた語そのものです。"}, {"text": "国内", "is_correct": false, "explanation": "「こくない」。「さ」が「な」に変わるだけの別の語です。"}, {"text": "国外", "is_correct": false, "explanation": "「こくがい」。「さ」が「が」に変わるだけの別の語です。"}, {"text": "国勢", "is_correct": false, "explanation": "「こくせい」。「さ」が「せ」に変わるだけの別の語です。"}, {"text": "交際", "is_correct": false, "explanation": "「こうさい」。「く」が「う」に変わるだけの別の語です。"}], "explanations": {"国債": "「こくさい」。聞こえた語そのものです。", "国内": "「こくない」。「さ」が「な」に変わるだけの別の語です。", "国外": "「こくがい」。「さ」が「が」に変わるだけの別の語です。", "国勢": "「こくせい」。「さ」が「せ」に変わるだけの別の語です。", "交際": "「こうさい」。「く」が「う」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "国債"}, "level_3": {"options": [{"text": "国債", "is_correct": true, "explanation": "国が借金のために出す証書なので、「出しました」に合います。"}, {"text": "風邪", "is_correct": false, "explanation": "形は合うが意味が合わない。国が風邪を出すとは言いません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。国が季節を出すとは言いません。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが意味が合わない。国が野菜を出すという文脈ではありません。"}], "explanations": {"国債": "国が借金のために出す証書なので、「出しました」に合います。", "風邪": "形は合うが意味が合わない。国が風邪を出すとは言いません。", "季節": "形は合うが意味が合わない。国が季節を出すとは言いません。", "野菜": "形は合うが意味が合わない。国が野菜を出すという文脈ではありません。"}, "sentence_index": 0, "correct_answer": "国債"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国債を食べて、元気になった。", "explanation": "国債は証書であり、食べ物ではないので「食べる」は合いません。"}, {"text": "国債は、国民が国に払う税金のことです。", "explanation": "国債は国がお金を借りるための証書で、税金ではありません。意味の使い方が違います。"}, {"text": "毎朝、国債に乗って学校へ行く。", "explanation": "国債は乗り物ではないので「乗る」は合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version 