INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52023, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "国債", "is_correct": true, "explanation": "「こくさい」。聞こえた語そのものです。"}, {"text": "国産", "is_correct": false, "explanation": "「こくさん」。最後の「い」が「ん」に変わるだけの別の語です。"}, {"text": "国策", "is_correct": false, "explanation": "「こくさく」。最後の「い」が「く」に変わるだけの別の語です。"}, {"text": "虹彩", "is_correct": false, "explanation": "「こうさい」。「く」が「う」に変わるだけの別の語です。"}], "explanations": {"国債": "「こくさい」。聞こえた語そのものです。", "国産": "「こくさん」。最後の「い」が「ん」に変わるだけの別の語です。", "国策": "「こくさく」。最後の「い」が「く」に変わるだけの別の語です。", "虹彩": "「こうさい」。「く」が「う」に変わるだけの別の語です。"}, "sentence_index": null, "correct_answer": "国債"}, "level_3": {"options": [{"text": "国債", "is_correct": true, "explanation": "国債を売り出して集めたお金を学校に使う、という意味で合います。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが意味が合わない。辞書でお金を集めることはできません。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気でお金を集めるとは言いません。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが意味が合わない。地震でお金を集めて学校に使うという文脈ではありません。"}], "explanations": {"国債": "国債を売り出して集めたお金を学校に使う、という意味で合います。", "辞書": "形は合うが意味が合わない。辞書でお金を集めることはできません。", "天気": "形は合うが意味が合わない。天気でお金を集めるとは言いません。", "地震": "形は合うが意味が合わない。地震でお金を集めて学校に使うという文脈ではありません。"}, "sentence_index": 6, "correct_answer": "国債"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国債をたくさん洗って、きれいにした。", "explanation": "国債は証書で、洗って掃除する物ではないので「洗う」は合いません。"}, {"text": "国債の天気は今日は晴れです。", "explanation": "国債は天気を持つ場所ではないので、使い方が間違いです。"}, {"text": "私は国債に住んでいて、庭が広い。", "explanation": "国債は住む場所ではないので「住む」は合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
