INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52024, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "発行する対象「国債」を示す「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「国債に発行した」では対象を表せず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、発行の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「国債と発行した」では対象を表せず、文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "発行する対象「国債」を示す「を」が正しい。", "に": "「国債に発行した」では対象を表せず、文として成り立たない。", "へ": "「へ」は方向を表すので、発行の対象を示せない。", "と": "「国債と発行した」では対象を表せず、文として成り立たない。"}, "error_tags": {"に": "wrong_case_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52024, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "資金を集める手段「国債」を示す「で」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、手段を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「国債に集めた資金」では手段を表せず、文として成り立たない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は後ろに否定が必要なので、「国債しか集めた資金は…使われる」は文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "資金を集める手段「国債」を示す「で」が正しい。", "へ": "「へ」は方向を表すので、手段を示せない。", "に": "「国債に集めた資金」では手段を表せず、文として成り立たない。", "しか": "「しか」は後ろに否定が必要なので、「国債しか集めた資金は…使われる」は文として成り立たない。"}, "error_tags": {"へ": "direction", "に": "wrong_case_marker", "しか": "negative_polarity"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52024, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "政府が、資金を調達するために発行する債券のこと。国が返済を約束する借用証書で、投資家が購入することで国の財政を支える役割を果たす。", "primary_collocate": null, "pronunciation": "こくさい", "ipa": "kokɯsai", "syllable_count": 4, "sentences": [{"text": "国債の発行が増えると、国の借金も増える。", "target_word": "国債", "complexity_tier": "T4", "furigana": "こくさいのはっこうがふえると、くにのしゃっきんもふえる。", "sentence_source": "generated"}, {"text": "政府は国債を発行した。", "target_word": "国債", "complexity_tier": "T3", "furigana": "せいふはこくさいをはっこうした。", "sentence_source": "generated"}, {"text": "国債の金利が上がった。", "target_word": "国債", "complexity_tier": "T3", "furigana": "こくさいのきんりがあがった。", "sentence_source": "generated"}, {"text": "銀行は多くの国債を保有している。", "target_word": "国債", "complexity_tier": "T3", "furigana": "ぎんこうはおおくのこくさいをほゆうしている。", "sentence_source": "generated"}, {"text": "国債を買う投資家が増えている。", "target_word": "国債", "complexity_tier": "T3", "furigana": "こくさいをかうとうしかがふえている。", "sentence_source": "generated"}, {"text": "国債は国の借金の一つだ。", "target_word": "国債", "complexity_tier": "T3", "furigana": "こくさいはくにのしゃっきんのひとつだ。", "sentence_source": "generated"}, {"text": "日本の国債は、安全な投資先と考えられている。", "target_word": "国債", "complexity_tier": "T4", "furigana": "にほんのこくさいは、あんぜんなとうしさきとかんがえられている。", "sentence_source": "generated"}, {"text": "国債で集めた資金は、道路の整備に使われる。", "target_word": "国債", "complexity_tier": "T4", "furigana": "こくさいであつめたしきんは、どうろのせいびにつかわれる。", "sentence_source": "generated"}, {"text": "日銀が国債を買い入れて、市場にお金を供給した。", "target_word": "国債", "complexity_tier": "T4", "furigana": "にちぎんがこくさいをかいいれて、しじょうにおかねをきょうきゅうした。", "sentence_source": "generated"}, {"text": "国債の価格が下がると、利回りは上昇する。", "target_word": "国債", "complexity_tier": "T4", "furigana": "こくさいのかかくがさがると、りまわりはじょうしょうする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国債市場", "label": "派生"}, {"form": "国債費", "label": "派生"}, {"form": "国債残高", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 政府が資金調達で出す債券", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78030f87-aae1-459b-9e77-753f1c3b3c04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52024, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国債", "is_correct": true, "explanation": "聞こえた語そのもの「こくさい」で、正解。"}, {"text": "国内", "is_correct": false, "explanation": "「こくない」で、三番目の音が「さ」ではなく「な」。"}, {"text": "国政", "is_correct": false, "explanation": "「こくせい」で、三番目の音が「さ」ではなく「せ」。"}, {"text": "国策", "is_correct": false, "explanation": "「こくさく」で、最後の音が「い」ではなく「く」。"}], "explanations": {"国債": "聞こえた語そのもの「こくさい」で、正解。", "国内": "「こくない」で、三番目の音が「さ」ではなく「な」。", "国政": "「こくせい」で、三番目の音が「さ」ではなく「せ」。", "国策": "「こくさく」で、最後の音が「い」ではなく「く」。"}, "sentence_index": null, "correct_answer": "国債"}, "level_3": {"options": [{"text": "国債", "is_correct": true, "explanation": "国債は国の借金の証書なので、発行が増えると国の借金も増える。文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は発行するものではない。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが意味が合わない。宿題を発行しても国の借金は増えない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。散歩は発行するものではない。"}], "explanations": {"国債": "国債は国の借金の証書なので、発行が増えると国の借金も増える。文脈に合う。", "天気": "形は合うが意味が合わない。天気は発行するものではない。", "宿題": "形は合うが意味が合わない。宿題を発行しても国の借金は増えない。", "散歩": "形は合うが意味が合わない。散歩は発行するものではない。"}, "sentence_index": 0, "correct_answer": "国債"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国債は、会社が株主に利益を分けるために発行する証書だ。", "explanation": "国債は政府が資金を借りるために出す債券で、会社が株主に出すものではない。"}, {"text": "私は毎朝、国債に乗って会社へ通っている。", "explanation": "国債は債券であり、乗り物ではないので「乗る」の対象にならない。"}, {"text": "国債とは、政府が国民から無料でもらうお金のことだ。", "explanation": "国債は返済を約束して借りる借用証書で、無料でもらうお金ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52024, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "国債", "is_correct": true, "explanation": "聞こえた語そのもの「こくさい」で、正解。"}, {"text": "国外", "is_correct": false, "explanation": "「こくがい」で、三番目の音が「さ」ではなく「が」。"}, {"text": "交際", "is_correct": false, "explanation": "「こうさい」で、二番目の音が「く」ではなく「う」。"}, {"text": "国産", "is_correct": false, "explanation": "「こくさん」で、最後の音が「い」ではなく「ん」。"}], "explanations": {"国債": "聞こえた語そのもの「こくさい」で、正解。", "国外": "「こくがい」で、三番目の音が「さ」ではなく「が」。", "交際": "「こうさい」で、二番目の音が「く」ではなく「う」。", "国産": "「こくさん」で、最後の音が「い」ではなく「ん」。"}, "sentence_index": null, "correct_answer": "国債"}, "level_3": {"options": [{"text": "国債", "is_correct": true, "explanation": "日本の国債が安全な投資先とされるという意味で、文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は投資先として考えられない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが意味が合わない。地震は投資先として考えられない。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが意味が合わない。宿題は投資先として考えられない。"}], "explanations": {"国債": "日本の国債が安全な投資先とされるという意味で、文脈に合う。", "天気": "形は合うが意味が合わない。天気は投資先として考えられない。", "地震": "形は合うが意味が合わない。地震は投資先として考えられない。", "宿題": "形は合うが意味が合わない。宿題は投資先として考えられない。"}, "sentence_index": 6, "correct_answer": "国債"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国債は、地方の市町村が資金を集めるために発行する債券だ。", "explanation": "市町村が発行するのは地方債で、国債は国が発行する債券。"}, {"text": "国債は国が発行するので、政府は返済する必要がまったくない。", "explanation": "国債は国が返済を約束する借用証書なので、返済が不要という説明は誤り。"}, {"text": "国債を歌いながら、みんなで運動場を走った。", "explanation": "国債は債券であり歌ではないので、「歌う」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52024, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府は資金を集めるために、国債に発行した。", "corrected_sentence": "政府は資金を集めるために、国債を発行した。", "error_description": "発行する対象は「を」で示す。「国債に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
