INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52025, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「預金のイールド」で、イールドの対象を表します。"}, {"text": "を", "is_correct": false, "explanation": "「預金をイールドは低い」は文として成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「預金にイールドは低い」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「預金へイールドは低い」は文として成り立ちません。"}], "correct_answer": "の", "explanations": {"の": "「預金のイールド」で、イールドの対象を表します。", "を": "「預金をイールドは低い」は文として成り立ちません。", "に": "「預金にイールドは低い」は文として成り立ちません。", "へ": "「預金へイールドは低い」は文として成り立ちません。"}, "error_tags": {"を": "object_marker_misuse", "に": "target_marker_misuse", "へ": "direction_marker_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
