INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52025, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "銀行に預けたり人に貸したりしたお金に対して、受け取る利子の割合のこと。利回り。", "primary_collocate": null, "pronunciation": "いーるど", "ipa": "iːɾɯdo", "syllable_count": 4, "sentences": [{"text": "イールドは利回りのことです。", "target_word": "イールド", "complexity_tier": "T2", "furigana": "イールドはりまわりのことです。", "sentence_source": "generated"}, {"text": "預金のイールドは低い。", "target_word": "イールド", "complexity_tier": "T1", "furigana": "よきんのイールドはひくい。", "sentence_source": "generated"}, {"text": "高いイールドの商品を探す。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "たかいイールドのしょうひんをさがす。", "sentence_source": "generated"}, {"text": "この債券のイールドは三パーセントだ。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "このさいけんのイールドはさんパーセントだ。", "sentence_source": "generated"}, {"text": "イールドが高いほど、リスクも大きい。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "イールドがたかいほど、リスクもおおきい。", "sentence_source": "generated"}, {"text": "彼はイールドを見て、国債を選んだ。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "かれはイールドをみて、こくさいをえらんだ。", "sentence_source": "generated"}, {"text": "イールドが下がって、がっかりした。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "イールドがさがって、がっかりした。", "sentence_source": "generated"}, {"text": "イールドの計算は、難しくない。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "イールドのけいさんは、むずかしくない。", "sentence_source": "generated"}, {"text": "母はイールドの良い投資を勧められた。", "target_word": "イールド", "complexity_tier": "T4", "furigana": "はははイールドのよいとうしをすすめられた。", "sentence_source": "generated"}, {"text": "銀行によって、イールドは違います。", "target_word": "イールド", "complexity_tier": "T2", "furigana": "ぎんこうによって、イールドはちがいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "イールドカーブ", "label": "派生"}, {"form": "ハイイールド", "label": "派生"}, {"form": "イールドギャップ", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 貸したお金に付く利子の割合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78030f87-aae1-459b-9e77-753f1c3b3c04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52025, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "イールド", "is_correct": true, "explanation": "聞こえた語そのもの「いーるど」で、正解。"}, {"text": "シールド", "is_correct": false, "explanation": "「しーるど」で、最初の音が「い」ではなく「し」。"}, {"text": "フィールド", "is_correct": false, "explanation": "「ふぃーるど」で、最初の音が「い」ではなく「ふぃ」。"}, {"text": "ゴールド", "is_correct": false, "explanation": "「ごーるど」で、最初の音が「い」ではなく「ご」。"}, {"text": "ホールド", "is_correct": false, "explanation": "「ほーるど」で、最初の音が「い」ではなく「ほ」。"}], "explanations": {"イールド": "聞こえた語そのもの「いーるど」で、正解。", "シールド": "「しーるど」で、最初の音が「い」ではなく「し」。", "フィールド": "「ふぃーるど」で、最初の音が「い」ではなく「ふぃ」。", "ゴールド": "「ごーるど」で、最初の音が「い」ではなく「ご」。", "ホールド": "「ほーるど」で、最初の音が「い」ではなく「ほ」。"}, "sentence_index": null, "correct_answer": "イールド"}, "level_3": {"options": [{"text": "イールド", "is_correct": true, "explanation": "「利回りのこと」と説明される語なので合います。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。机は利回りのことではありません。"}, {"text": "犬", "is_correct": false, "explanation": "形は合うが意味が合わない。犬は利回りのことではありません。"}, {"text": "郵便", "is_correct": false, "explanation": "形は合うが意味が合わない。郵便は利回りのことではありません。"}], "explanations": {"イールド": "「利回りのこと」と説明される語なので合います。", "机": "形は合うが意味が合わない。机は利回りのことではありません。", "犬": "形は合うが意味が合わない。犬は利回りのことではありません。", "郵便": "形は合うが意味が合わない。郵便は利回りのことではありません。"}, "sentence_index": 0, "correct_answer": "イールド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎日、イールドを食べて朝ごはんにする。", "explanation": "イールドは利子の割合を表す語で、食べ物ではありません。"}, {"text": "この部屋のイールドは三メートルあります。", "explanation": "イールドは部屋の長さを表す語ではありません。"}, {"text": "イールドに乗って、駅まで行った。", "explanation": "イールドは乗り物ではないので「乗る」は合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52025, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "イールド", "is_correct": true, "explanation": "利回りが下がってがっかりした、という意味で合います。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。机が下がってがっかりする文脈ではありません。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが意味が合わない。地図が下がるとは言いません。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが意味が合わない。靴が下がってがっかりするという文脈ではありません。"}], "explanations": {"イールド": "利回りが下がってがっかりした、という意味で合います。", "机": "形は合うが意味が合わない。机が下がってがっかりする文脈ではありません。", "地図": "形は合うが意味が合わない。地図が下がるとは言いません。", "靴": "形は合うが意味が合わない。靴が下がってがっかりするという文脈ではありません。"}, "sentence_index": 6, "correct_answer": "イールド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "イールドは、庭に咲く赤い花です。", "explanation": "イールドは利子の割合を表す語で、花の名前ではありません。"}, {"text": "銀行のイールドを開けて、中に入った。", "explanation": "イールドは扉や建物ではないので「開ける」は合いません。"}, {"text": "イールドを洗って、きれいに干した。", "explanation": "イールドは物ではないので「洗って干す」は合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
