INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52026, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "投資した金額に対して、どれだけの利益が得られるかを示す割合のこと。特に債券などの金融商品で使われる。", "primary_collocate": null, "pronunciation": "いーるど", "ipa": "iːɾɯdo", "syllable_count": 4, "sentences": [{"text": "社債のイールドは、国債よりも高いことが多い。", "target_word": "イールド", "complexity_tier": "T4", "furigana": "しゃさいのイールドは、こくさいよりもたかいことがおおい。", "sentence_source": "generated"}, {"text": "債券のイールドが上がった。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "さいけんのイールドがあがった。", "sentence_source": "generated"}, {"text": "このファンドはイールドが高い。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "このファンドはイールドがたかい。", "sentence_source": "generated"}, {"text": "投資家はイールドを重視する。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "とうしかはイールドをじゅうしする。", "sentence_source": "generated"}, {"text": "国債のイールドは、金利に応じて動く。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "こくさいのイールドは、きんりにおうじてうごく。", "sentence_source": "generated"}, {"text": "低いイールドでは、利益は期待できない。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "ひくいイールドでは、りえきはきたいできない。", "sentence_source": "generated"}, {"text": "イールドを比べてから、商品を選びました。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "イールドをくらべてから、しょうひんをえらびました。", "sentence_source": "generated"}, {"text": "物価が上がると、長期のイールドも上昇しやすい。", "target_word": "イールド", "complexity_tier": "T4", "furigana": "ぶっかがあがると、ちょうきのイールドもじょうしょうしやすい。", "sentence_source": "generated"}, {"text": "銀行は、より高いイールドを求めて外債を買った。", "target_word": "イールド", "complexity_tier": "T4", "furigana": "ぎんこうは、よりたかいイールドをもとめてがいさいをかった。", "sentence_source": "generated"}, {"text": "株式のイールドは、債券ほど安定していない。", "target_word": "イールド", "complexity_tier": "T3", "furigana": "かぶしきのイールドは、さいけんほどあんていしていない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "イールドカーブ", "label": "派生"}, {"form": "ハイイールド", "label": "派生"}, {"form": "イールドギャップ", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 投資額に対する利益の割合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78030f87-aae1-459b-9e77-753f1c3b3c04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52026, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "イールド", "is_correct": true, "explanation": "聞こえた語そのもの「いーるど」で、正解。"}, {"text": "シールド", "is_correct": false, "explanation": "「しーるど」で、最初の音が「い」ではなく「し」。"}, {"text": "フィールド", "is_correct": false, "explanation": "「ふぃーるど」で、最初の音が「い」ではなく「ふぃ」。"}, {"text": "ゴールド", "is_correct": false, "explanation": "「ごーるど」で、最初の音が「い」ではなく「ご」。"}, {"text": "ホールド", "is_correct": false, "explanation": "「ほーるど」で、最初の音が「い」ではなく「ほ」。"}], "explanations": {"イールド": "聞こえた語そのもの「いーるど」で、正解。", "シールド": "「しーるど」で、最初の音が「い」ではなく「し」。", "フィールド": "「ふぃーるど」で、最初の音が「い」ではなく「ふぃ」。", "ゴールド": "「ごーるど」で、最初の音が「い」ではなく「ご」。", "ホールド": "「ほーるど」で、最初の音が「い」ではなく「ほ」。"}, "sentence_index": null, "correct_answer": "イールド"}, "level_3": {"options": [{"text": "イールド", "is_correct": true, "explanation": "社債から得られる利益の割合が国債より高い、という意味で文脈に合います。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。社債に机はありません。"}, {"text": "犬", "is_correct": false, "explanation": "形は合うが意味が合わない。社債と犬は関係ありません。"}, {"text": "夕焼け", "is_correct": false, "explanation": "形は合うが意味が合わない。社債の夕焼けとは言いません。"}], "explanations": {"イールド": "社債から得られる利益の割合が国債より高い、という意味で文脈に合います。", "机": "形は合うが意味が合わない。社債に机はありません。", "犬": "形は合うが意味が合わない。社債と犬は関係ありません。", "夕焼け": "形は合うが意味が合わない。社債の夕焼けとは言いません。"}, "sentence_index": 0, "correct_answer": "イールド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "イールドは、毎朝飲む温かいお茶の種類です。", "explanation": "イールドは利益の割合を表す語で、お茶の種類ではありません。"}, {"text": "このビルのイールドは二十階まであります。", "explanation": "イールドは建物の高さや階数を表す語ではありません。"}, {"text": "投資家はイールドを走らせて、遠くへ行った。", "explanation": "イールドは割合であり、走らせる乗り物ではないので使い方が違います。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52026, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "イールド", "is_correct": true, "explanation": "金融商品の利益の割合を比べて選ぶ、という意味で合います。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが意味が合わない。地震を比べて商品を選ぶことはありません。"}, {"text": "夕焼け", "is_correct": false, "explanation": "形は合うが意味が合わない。夕焼けを比べて商品を選ぶという文脈ではありません。"}, {"text": "悲しみ", "is_correct": false, "explanation": "形は合うが意味が合わない。悲しみを比べて商品を選ぶとは言いません。"}], "explanations": {"イールド": "金融商品の利益の割合を比べて選ぶ、という意味で合います。", "地震": "形は合うが意味が合わない。地震を比べて商品を選ぶことはありません。", "夕焼け": "形は合うが意味が合わない。夕焼けを比べて商品を選ぶという文脈ではありません。", "悲しみ": "形は合うが意味が合わない。悲しみを比べて商品を選ぶとは言いません。"}, "sentence_index": 6, "correct_answer": "イールド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "イールドを着て、寒い冬の外を歩いた。", "explanation": "イールドは服ではないので「着る」は合いません。"}, {"text": "昨日、公園でイールドと遊んで楽しかった。", "explanation": "イールドは割合を表す語で、一緒に遊ぶ相手ではありません。"}, {"text": "この川のイールドは、とても深くて長い。", "explanation": "イールドは川の深さや長さを表す語ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5565bce-284d-44c9-b74e-bf8928672917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
