INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52027, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "グラフなどにかかれた、曲がりながら変化を表す線（曲線）のことです。", "primary_collocate": null, "pronunciation": "かーぶ", "ipa": "kaːbɯ", "syllable_count": 3, "sentences": [{"text": "グラフに赤いカーブがあります。", "target_word": "カーブ", "complexity_tier": "T2", "furigana": "グラフに赤[あか]いカーブがあります。", "sentence_source": "generated"}, {"text": "売り上げのカーブを見てください。", "target_word": "カーブ", "complexity_tier": "T2", "furigana": "売[う]り上[あ]げのカーブを見[み]てください。", "sentence_source": "generated"}, {"text": "先生は黒板にカーブを書いた。", "target_word": "カーブ", "complexity_tier": "T2", "furigana": "先生[せんせい]は黒板[こくばん]にカーブを書[か]いた。", "sentence_source": "generated"}, {"text": "このカーブは右に上がっている。", "target_word": "カーブ", "complexity_tier": "T3", "furigana": "このカーブは右[みぎ]に上[あ]がっている。", "sentence_source": "generated"}, {"text": "線のカーブは下に向かっている。", "target_word": "カーブ", "complexity_tier": "T3", "furigana": "線[せん]のカーブは下[した]に向[む]かっている。", "sentence_source": "generated"}, {"text": "右上がりのカーブは、成長を表している。", "target_word": "カーブ", "complexity_tier": "T3", "furigana": "右上[みぎうえ]がりのカーブは、成長[せいちょう]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "カーブがゆるやかなほど、変化は小さい。", "target_word": "カーブ", "complexity_tier": "T3", "furigana": "カーブがゆるやかなほど、変化[へんか]は小[ちい]さい。", "sentence_source": "generated"}, {"text": "カーブが急になると、数字が大きく変わる。", "target_word": "カーブ", "complexity_tier": "T4", "furigana": "カーブが急[きゅう]になると、数字[すうじ]が大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "結果をカーブにまとめると、傾きの違いが分かる。", "target_word": "カーブ", "complexity_tier": "T4", "furigana": "結果[けっか]をカーブにまとめると、傾[かたむ]きの違[ちが]いが分[わ]かる。", "sentence_source": "generated"}, {"text": "二つのカーブが交わる点を、図の中から探しなさい。", "target_word": "カーブ", "complexity_tier": "T4", "furigana": "二[ふた]つのカーブが交[まじ]わる点[てん]を、図[ず]の中[なか]から探[さが]しなさい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カーブする", "label": "派生"}, {"form": "カーブした", "label": "活用"}, {"form": "カーブして", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | かたむきを持つ曲がった線", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61f01209-a5ab-450f-a9fd-dfc8a97e8f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
