INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52028, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "曲線。まっすぐではない、ゆるやかに曲がった線。", "primary_collocate": null, "pronunciation": "かーぶ", "ipa": "kaːbɯ", "syllable_count": 3, "sentences": [{"text": "紙にかいた線が、ゆるやかなカーブになった。", "target_word": "カーブ", "complexity_tier": "T2", "furigana": "紙[かみ]にかいた線[せん]が、ゆるやかなカーブになった。", "sentence_source": "generated"}, {"text": "グラフのカーブがゆるやかになった。", "target_word": "カーブ", "complexity_tier": "T2", "furigana": "グラフのカーブがゆるやかになった。", "sentence_source": "generated"}, {"text": "この道は大きなカーブがある。", "target_word": "カーブ", "complexity_tier": "T2", "furigana": "この道[みち]は大[おお]きなカーブがある。", "sentence_source": "generated"}, {"text": "カーブの先に小さな駅が見えます。", "target_word": "カーブ", "complexity_tier": "T2", "furigana": "カーブの先[さき]に小[ちい]さな駅[えき]が見[み]えます。", "sentence_source": "generated"}, {"text": "川が美しいカーブを描いている。", "target_word": "カーブ", "complexity_tier": "T3", "furigana": "川[かわ]が美[うつく]しいカーブを描[えが]いている。", "sentence_source": "generated"}, {"text": "線がカーブしているので、定規では引けない。", "target_word": "カーブ", "complexity_tier": "T3", "furigana": "線[せん]がカーブしているので、定規[じょうぎ]では引[ひ]けない。", "sentence_source": "generated"}, {"text": "山道はカーブが続くので、ゆっくり走る。", "target_word": "カーブ", "complexity_tier": "T3", "furigana": "山道[やまみち]はカーブが続[つづ]くので、ゆっくり走[はし]る。", "sentence_source": "generated"}, {"text": "気温の変化をカーブで示すと、上がり方がよく分かる。", "target_word": "カーブ", "complexity_tier": "T4", "furigana": "気温[きおん]の変化[へんか]をカーブで示[しめ]すと、上[あ]がり方[かた]がよく分[わ]かる。", "sentence_source": "generated"}, {"text": "設計者はなめらかなカーブになるように線を修正した。", "target_word": "カーブ", "complexity_tier": "T4", "furigana": "設計者[せっけいしゃ]はなめらかなカーブになるように線[せん]を修正[しゅうせい]した。", "sentence_source": "generated"}, {"text": "急なカーブを曲がるとき、車は速度を落とさなければならない。", "target_word": "カーブ", "complexity_tier": "T4", "furigana": "急[きゅう]なカーブを曲[ま]がるとき、車[くるま]は速度[そくど]を落[お]とさなければならない。", "sentence_sour