INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52028, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "カーブ", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "カート", "is_correct": false, "explanation": "最後の音が「ブ」から「ト」に変わる別の語。"}, {"text": "カーキ", "is_correct": false, "explanation": "最後の音が「ブ」から「キ」に変わる別の語。"}, {"text": "カーフ", "is_correct": false, "explanation": "濁音「ブ」が清音「フ」に変わる別の語。"}], "explanations": {"カーブ": "見出し語そのもの。", "カート": "最後の音が「ブ」から「ト」に変わる別の語。", "カーキ": "最後の音が「ブ」から「キ」に変わる別の語。", "カーフ": "濁音「ブ」が清音「フ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "カーブ"}, "level_3": {"options": [{"text": "カーブ", "is_correct": true, "explanation": "山道に曲がった道が続くので、ゆっくり走る理由になる。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが、山道に宿題が続いても走る速度の理由にならず意味が合わない。"}, {"text": "夢", "is_correct": false, "explanation": "形は合うが、山道に夢が続くという意味になり合わない。"}, {"text": "笑顔", "is_correct": false, "explanation": "形は合うが、山道に笑顔が続くという意味になり合わない。"}], "explanations": {"カーブ": "山道に曲がった道が続くので、ゆっくり走る理由になる。", "宿題": "形は合うが、山道に宿題が続いても走る速度の理由にならず意味が合わない。", "夢": "形は合うが、山道に夢が続くという意味になり合わない。", "笑顔": "形は合うが、山道に笑顔が続くという意味になり合わない。"}, "sentence_index": 6, "correct_answer": "カーブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は毎日、カーブを飲みながら本を読む。", "explanation": "カーブは曲線で、飲み物ではないので「飲む」の対象にならない。"}, {"text": "道がまっすぐなので、大きなカーブが何度も続く。", "explanation": "まっすぐな道にはカーブがないので、カーブの意味と矛盾する。"}, {"text": "カーブは来月から新しい駅で働く予定だ。", "explanation": "カーブは線の形で、人のように働くことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_i