INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52029, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「債務がある」と、存在するものを示します。"}, {"text": "を", "is_correct": false, "explanation": "「債務をあります」は文法的に誤りです。"}, {"text": "へ", "is_correct": false, "explanation": "「債務へあります」は成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「債務とあります」はこの文では成り立ちません。"}], "correct_answer": "が", "explanations": {"が": "「債務がある」と、存在するものを示します。", "を": "「債務をあります」は文法的に誤りです。", "へ": "「債務へあります」は成り立ちません。", "と": "「債務とあります」はこの文では成り立ちません。"}, "error_tags": {"を": "object", "へ": "direction", "と": "companion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "債権", "is_correct": true, "explanation": "お金を返してもらう権利で、債務の反対の関係です。"}, {"text": "借金", "is_correct": false, "explanation": "債務と近い意味の類義語です。"}, {"text": "利子", "is_correct": false, "explanation": "借りたお金に付くもので、反対語ではありません。"}, {"text": "返済", "is_correct": false, "explanation": "借りたお金を返す行為で、反対語ではありません。"}], "correct_answer": "債権", "explanations": {"債権": "お金を返してもらう権利で、債務の反対の関係です。", "借金": "債務と近い意味の類義語です。", "利子": "借りたお金に付くもので、反対語ではありません。", "返済": "借りたお金を返す行為で、反対語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
