INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52029, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "債務", "is_correct": true, "explanation": "「さいむ」で、聞こえた語そのものです。"}, {"text": "財務", "is_correct": false, "explanation": "「ざいむ」で、最初の音が濁音になっています。"}, {"text": "財布", "is_correct": false, "explanation": "「さいふ」で、最後の音が違います。"}, {"text": "細工", "is_correct": false, "explanation": "「さいく」で、最後の音が違います。"}, {"text": "皆無", "is_correct": false, "explanation": "「かいむ」で、最初の音が違います。"}], "explanations": {"債務": "「さいむ」で、聞こえた語そのものです。", "財務": "「ざいむ」で、最初の音が濁音になっています。", "財布": "「さいふ」で、最後の音が違います。", "細工": "「さいく」で、最後の音が違います。", "皆無": "「かいむ」で、最初の音が違います。"}, "sentence_index": null, "correct_answer": "債務"}, "level_3": {"options": [{"text": "債務", "is_correct": true, "explanation": "「借りたお金のこと」と説明される語として合います。"}, {"text": "旅行", "is_correct": false, "explanation": "形は合うが、旅行は借りたお金のことではなく意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節は借りたお金のことではなく意味が合わない。"}, {"text": "友達", "is_correct": false, "explanation": "形は合うが、友達は借りたお金のことではなく意味が合わない。"}], "explanations": {"債務": "「借りたお金のこと」と説明される語として合います。", "旅行": "形は合うが、旅行は借りたお金のことではなく意味が合わない。", "季節": "形は合うが、季節は借りたお金のことではなく意味が合わない。", "友達": "形は合うが、友達は借りたお金のことではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "債務"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は債務を高い山の上に建てた。", "explanation": "債務は建物ではなく借金のことなので「建てる」と使えません。"}, {"text": "債務をかばんに入れて、公園へ持って行った。", "explanation": "債務は返す義務のあるお金のことで、物ではないので、かばんに入れて持ち運ぶことはできません。"}, {"text": "朝ごはんに債務を食べて、学校へ行った。", "explanation": "債務は食べ物ではないので「食べる」と使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_er