INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52029, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "債務", "is_correct": true, "explanation": "「さいむ」で、聞こえた語そのものです。"}, {"text": "税務", "is_correct": false, "explanation": "「ぜいむ」で、最初の音が違います。"}, {"text": "サイト", "is_correct": false, "explanation": "「さいと」で、最後の音が違います。"}, {"text": "サイズ", "is_correct": false, "explanation": "「さいず」で、最後の音が違います。"}, {"text": "サイン", "is_correct": false, "explanation": "「さいん」で、最後の音が違います。"}], "explanations": {"債務": "「さいむ」で、聞こえた語そのものです。", "税務": "「ぜいむ」で、最初の音が違います。", "サイト": "「さいと」で、最後の音が違います。", "サイズ": "「さいず」で、最後の音が違います。", "サイン": "「さいん」で、最後の音が違います。"}, "sentence_index": null, "correct_answer": "債務"}, "level_3": {"options": [{"text": "債務", "is_correct": true, "explanation": "銀行の人に相談する内容として自然に合います。"}, {"text": "星座", "is_correct": false, "explanation": "形は合うが、銀行の人に星座を相談する場面は考えにくく意味が合わない。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、銀行の人に台風を相談するのは不自然で意味が合わない。"}, {"text": "虫歯", "is_correct": false, "explanation": "形は合うが、虫歯は銀行の人でなく歯医者に相談することで意味が合わない。"}], "explanations": {"債務": "銀行の人に相談する内容として自然に合います。", "星座": "形は合うが、銀行の人に星座を相談する場面は考えにくく意味が合わない。", "台風": "形は合うが、銀行の人に台風を相談するのは不自然で意味が合わない。", "虫歯": "形は合うが、虫歯は銀行の人でなく歯医者に相談することで意味が合わない。"}, "sentence_index": 6, "correct_answer": "債務"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "債務を庭に植えたら、赤い花が咲いた。", "explanation": "債務は借金のことで、植物ではないので「植える」と使えません。"}, {"text": "債務はとても甘くて、子どもに人気がある。", "explanation": "債務はお金の義務で、味はないので「甘い」と言えません。"}, {"text": "毎晩、債務を聞きながら寝ている。", "explanation": "債務は音楽や音ではないので「聞く」と使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_er