INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52030, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「債務を抱える」と、抱える対象を示す助詞です。"}, {"text": "に", "is_correct": false, "explanation": "「債務に抱える」とは言えません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、抱える対象には使えません。"}, {"text": "と", "is_correct": false, "explanation": "「債務と抱える」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「債務を抱える」と、抱える対象を示す助詞です。", "に": "「債務に抱える」とは言えません。", "へ": "「へ」は方向を表すので、抱える対象には使えません。", "と": "「債務と抱える」は文として成り立ちません。"}, "error_tags": {"に": "target_location", "へ": "direction", "と": "companion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "債権", "is_correct": true, "explanation": "お金を返してもらう権利で、債務の反対の関係です。"}, {"text": "借金", "is_correct": false, "explanation": "債務とほぼ同じ意味の類義語です。"}, {"text": "負債", "is_correct": false, "explanation": "債務に近い意味で、反対ではありません。"}, {"text": "利息", "is_correct": false, "explanation": "借金に付く費用で、反対語ではありません。"}], "correct_answer": "債権", "explanations": {"債権": "お金を返してもらう権利で、債務の反対の関係です。", "借金": "債務とほぼ同じ意味の類義語です。", "負債": "債務に近い意味で、反対ではありません。", "利息": "借金に付く費用で、反対語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52030, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「債務を負う」と、負う対象を示します。"}, {"text": "へ", "is_correct": false, "explanation": "「債務へ負う」とは言えません。"}, {"text": "と", "is_correct": false, "explanation": "「債務と負う」は文として成り立ちません。"}, {"text": "より", "is_correct": false, "explanation": "「債務より負う」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「債務を負う」と、負う対象を示します。", "へ": "「債務へ負う」とは言えません。", "と": "「債務と負う」は文として成り立ちません。", "より": "「債務より負う」は文として成り立ちません。"}, "error_tags": {"へ": "direction", "と": "companion", "より": "comparison"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "債権", "is_correct": true, "explanation": "返してもらう側の権利で、債務と反対の関係です。"}, {"text": "借入", "is_correct": false, "explanation": "お金を借りることで、債務と近い意味です。"}, {"text": "返済", "is_correct": false, "explanation": "債務を返す行為で、反対の語ではありません。"}, {"text": "赤字", "is_correct": false, "explanation": "収支の状態で、債務の反対語ではありません。"}], "correct_answer": "債権", "explanations": {"債権": "返してもらう側の権利で、債務と反対の関係です。", "借入": "お金を借りることで、債務と近い意味です。", "返済": "債務を返す行為で、反対の語ではありません。", "赤字": "収支の状態で、債務の反対語ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52030, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "借りたお金や、支払わなければならない義務のある金額のこと。", "primary_collocate": null, "pronunciation": "さいむ", "ipa": "saimɯ", "syllable_count": 3, "sentences": [{"text": "債務の返済期限は、来年の三月である。", "target_word": "債務", "complexity_tier": "T3", "furigana": "債務[さいむ]の返済[へんさい]期限[きげん]は、来年[らいねん]の三月[さんがつ]である。", "sentence_source": "generated"}, {"text": "会社は多くの債務を抱えている。", "target_word": "債務", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は多[おお]くの債務[さいむ]を抱[かか]えている。", "sentence_source": "generated"}, {"text": "債務を返すのは簡単ではない。", "target_word": "債務", "complexity_tier": "T3", "furigana": "債務[さいむ]を返[かえ]すのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "彼の債務は去年より増えました。", "target_word": "債務", "complexity_tier": "T2", "furigana": "彼[かれ]の債務[さいむ]は去年[きょねん]より増[ふ]えました。", "sentence_source": "generated"}, {"text": "国の債務が大きくなっている。", "target_word": "債務", "complexity_tier": "T3", "furigana": "国[くに]の債務[さいむ]が大[おお]きくなっている。", "sentence_source": "generated"}, {"text": "毎月少しずつ債務を返します。", "target_word": "債務", "complexity_tier": "T2", "furigana": "毎月[まいつき]少[すこ]しずつ債務[さいむ]を返[かえ]します。", "sentence_source": "generated"}, {"text": "債務がある人は、新しい借金を断られることがある。", "target_word": "債務", "complexity_tier": "T4", "furigana": "債務[さいむ]がある人[ひと]は、新[あたら]しい借金[しゃっきん]を断[ことわ]られることがある。", "sentence_source": "generated"}, {"text": "事業が失敗したため、社長は債務を負うことになった。", "target_word": "債務", "complexity_tier": "T4", "furigana": "事業[じぎょう]が失敗[しっぱい]したため、社長[しゃちょう]は債務[さいむ]を負[お]うことになった。", "sentence_source": "generated"}, {"text": "債務の返済が遅れると、利息が増えてしまう。", "target_word": "債務", "complexity_tier": "T4", "furigana": "債務[さいむ]の返済[へんさい]が遅[おく]れると、利息[りそく]が増[ふ]えてしまう。", "sentence_source": "generated"}, {"text": "政府は債務を減らすために、予算を見直すと発表した。", "target_word": "債務", "complexity_tier": "T4", "furigana": "政府[せいふ]は債務[さいむ]を減[へ]らすために、予算[よさん]を見直[みなお]すと発表[はっぴょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "債務者", "label": "派生"}, {"form": "債務超過", "label": "派生"}, {"form": "債務不履行", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 返す義務のあるお金や借金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61f01209-a5ab-450f-a9fd-dfc8a97e8f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52030, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "債務", "is_correct": true, "explanation": "「さいむ」で、聞こえた語そのものです。"}, {"text": "財務", "is_correct": false, "explanation": "「ざいむ」で、最初の音が濁音になっている別の語です。"}, {"text": "財布", "is_correct": false, "explanation": "「さいふ」で、最後の音が「む」ではなく「ふ」です。"}, {"text": "細工", "is_correct": false, "explanation": "「さいく」で、最後の音が「む」ではなく「く」です。"}, {"text": "最後", "is_correct": false, "explanation": "「さいご」で、最後の音が「む」ではなく「ご」です。"}, {"text": "皆無", "is_correct": false, "explanation": "「かいむ」で、最初の音が「さ」ではなく「か」です。"}], "explanations": {"債務": "「さいむ」で、聞こえた語そのものです。", "財務": "「ざいむ」で、最初の音が濁音になっている別の語です。", "財布": "「さいふ」で、最後の音が「む」ではなく「ふ」です。", "細工": "「さいく」で、最後の音が「む」ではなく「く」です。", "最後": "「さいご」で、最後の音が「む」ではなく「ご」です。", "皆無": "「かいむ」で、最初の音が「さ」ではなく「か」です。"}, "sentence_index": null, "correct_answer": "債務"}, "level_3": {"options": [{"text": "債務", "is_correct": true, "explanation": "返す義務のあるお金なので、返済期限があるという文脈に合います。"}, {"text": "天候", "is_correct": false, "explanation": "形は合うが、天候は返すものではなく返済期限がないので意味が合わない。"}, {"text": "感情", "is_correct": false, "explanation": "形は合うが、感情は返済するものではなく意味が合わない。"}, {"text": "習慣", "is_correct": false, "explanation": "形は合うが、習慣に返済期限はなく意味が合わない。"}], "explanations": {"債務": "返す義務のあるお金なので、返済期限があるという文脈に合います。", "天候": "形は合うが、天候は返すものではなく返済期限がないので意味が合わない。", "感情": "形は合うが、感情は返済するものではなく意味が合わない。", "習慣": "形は合うが、習慣に返済期限はなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "債務"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は債務をたくさん貯めて、銀行に預けた。", "explanation": "債務は返す義務のある借金なので、「貯めて預ける」対象にはならず、語の意味を誤用しています。"}, {"text": "昨日、おいしい債務を食べて、お腹がいっぱいになった。", "explanation": "債務はお金に関する義務で、食べ物ではないので「食べる」と使えません。"}, {"text": "債務は雨の日に空から降ってくる。", "explanation": "債務は自然現象ではなく、借金のことなので「降ってくる」と使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52030, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "債務", "is_correct": true, "explanation": "「さいむ」で、聞こえた語そのものです。"}, {"text": "税務", "is_correct": false, "explanation": "「ぜいむ」で、最初の音が「さ」ではなく「ぜ」です。"}, {"text": "サイト", "is_correct": false, "explanation": "「さいと」で、最後の音が「む」ではなく「と」です。"}, {"text": "サイズ", "is_correct": false, "explanation": "「さいず」で、最後の音が「む」ではなく「ず」です。"}, {"text": "サイン", "is_correct": false, "explanation": "「さいん」で、最後の音が「む」ではなく「ん」です。"}], "explanations": {"債務": "「さいむ」で、聞こえた語そのものです。", "税務": "「ぜいむ」で、最初の音が「さ」ではなく「ぜ」です。", "サイト": "「さいと」で、最後の音が「む」ではなく「と」です。", "サイズ": "「さいず」で、最後の音が「む」ではなく「ず」です。", "サイン": "「さいん」で、最後の音が「む」ではなく「ん」です。"}, "sentence_index": null, "correct_answer": "債務"}, "level_3": {"options": [{"text": "債務", "is_correct": true, "explanation": "債務がある人は借金を断られることがある、という流れに合います。"}, {"text": "才能", "is_correct": false, "explanation": "形は合うが、才能がある人が借金を断られる理由にならず意味が合わない。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが、趣味と借金を断られることは結びつかず意味が合わない。"}, {"text": "身長", "is_correct": false, "explanation": "形は合うが、身長は借金の審査と関係がなく意味が合わない。"}], "explanations": {"債務": "債務がある人は借金を断られることがある、という流れに合います。", "才能": "形は合うが、才能がある人が借金を断られる理由にならず意味が合わない。", "趣味": "形は合うが、趣味と借金を断られることは結びつかず意味が合わない。", "身長": "形は合うが、身長は借金の審査と関係がなく意味が合わない。"}, "sentence_index": 6, "correct_answer": "債務"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "債務は天気が悪い日に食べるとおいしい。", "explanation": "債務は借金のことなので、食べ物として「おいしい」とは言えません。"}, {"text": "彼は債務を高く飛ばして、空に消えた。", "explanation": "債務は返す義務のあるお金で、「飛ばす」ことはできません。"}, {"text": "新しい債務を着て、パーティーに出かけた。", "explanation": "債務は服ではないので「着る」と使えず、語の意味の誤用です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52030, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は債務を毎月少しずつ食べている。", "corrected_sentence": "彼女は債務を毎月少しずつ返している。", "error_description": "債務に合う動詞は「返す」で、「食べる」は意味が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52030, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は債務を泳ぐために、家を売ることにした。", "corrected_sentence": "彼は債務を返すために、家を売ることにした。", "error_description": "債務に合う動詞は「返す」で、「泳ぐ」は意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52031, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「懸念は一つだけです」で、話題として取り上げます。"}, {"text": "を", "is_correct": false, "explanation": "「です」の文では目的語の「を」は使えません。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、この位置では意味が通りません。"}, {"text": "で", "is_correct": false, "explanation": "「懸念で一つだけです」では文が成立しません。"}], "correct_answer": "は", "explanations": {"は": "「懸念は一つだけです」で、話題として取り上げます。", "を": "「です」の文では目的語の「を」は使えません。", "へ": "方向を表す「へ」は、この位置では意味が通りません。", "で": "「懸念で一つだけです」では文が成立しません。"}, "error_tags": {"を": "object_marker", "へ": "direction", "で": "location_or_means"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安心", "is_correct": true, "explanation": "心配がなく落ち着いた状態で、「懸念」の反対です。"}, {"text": "心配", "is_correct": false, "explanation": "気にかけることで、「懸念」の類義語です。"}, {"text": "不安", "is_correct": false, "explanation": "落ち着かない気持ちで、「懸念」に近い意味です。"}, {"text": "疑問", "is_correct": false, "explanation": "分からないことで、反対の意味ではありません。"}], "correct_answer": "安心", "explanations": {"安心": "心配がなく落ち着いた状態で、「懸念」の反対です。", "心配": "気にかけることで、「懸念」の類義語です。", "不安": "落ち着かない気持ちで、「懸念」に近い意味です。", "疑問": "分からないことで、反対の意味ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52031, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「影響が懸念される」で、心配される内容を示します。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、心配される内容を示せません。"}, {"text": "と", "is_correct": false, "explanation": "「影響と懸念される」では文が成り立ちません。"}, {"text": "や", "is_correct": false, "explanation": "「影響や懸念される」では並べる相手がなく、文が成立しません。"}], "correct_answer": "が", "explanations": {"が": "「影響が懸念される」で、心配される内容を示します。", "へ": "方向を表す「へ」は、心配される内容を示せません。", "と": "「影響と懸念される」では文が成り立ちません。", "や": "「影響や懸念される」では並べる相手がなく、文が成立しません。"}, "error_tags": {"へ": "direction", "と": "quotation_or_partner", "や": "listing"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安堵", "is_correct": true, "explanation": "心配が消えてほっとすることで、「懸念」の反対です。"}, {"text": "危惧", "is_correct": false, "explanation": "悪い結果を心配することで、「懸念」の類義語です。"}, {"text": "不安", "is_correct": false, "explanation": "落ち着かない気持ちで、「懸念」に近い意味です。"}, {"text": "困惑", "is_correct": false, "explanation": "どうしてよいか分からない状態で、反対の意味ではありません。"}], "correct_answer": "安堵", "explanations": {"安堵": "心配が消えてほっとすることで、「懸念」の反対です。", "危惧": "悪い結果を心配することで、「懸念」の類義語です。", "不安": "落ち着かない気持ちで、「懸念」に近い意味です。", "困惑": "どうしてよいか分からない状態で、反対の意味ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52031, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心配なこと。", "primary_collocate": null, "pronunciation": "けねん", "ipa": "keneɴ", "syllable_count": 3, "sentences": [{"text": "一番の懸念は、彼の遅刻だ。", "target_word": "懸念", "complexity_tier": "T2", "furigana": "一番[いちばん]の懸念[けねん]は、彼[かれ]の遅刻[ちこく]だ。", "sentence_source": "generated"}, {"text": "懸念は一つだけです。", "target_word": "懸念", "complexity_tier": "T2", "furigana": "懸念[けねん]は一[ひと]つだけです。", "sentence_source": "generated"}, {"text": "私には少し懸念があります。", "target_word": "懸念", "complexity_tier": "T2", "furigana": "私[わたし]には少[すこ]し懸念[けねん]があります。", "sentence_source": "generated"}, {"text": "話を聞いて、懸念が消えた。", "target_word": "懸念", "complexity_tier": "T2", "furigana": "話[はなし]を聞[き]いて、懸念[けねん]が消[き]えた。", "sentence_source": "generated"}, {"text": "試験の結果に懸念を持っている。", "target_word": "懸念", "complexity_tier": "T3", "furigana": "試験[しけん]の結果[けっか]に懸念[けねん]を持[も]っている。", "sentence_source": "generated"}, {"text": "母は雨の日の運転を懸念している。", "target_word": "懸念", "complexity_tier": "T3", "furigana": "母[はは]は雨[あめ]の日[ひ]の運転[うんてん]を懸念[けねん]している。", "sentence_source": "generated"}, {"text": "懸念していたことは起こらなかった。", "target_word": "懸念", "complexity_tier": "T3", "furigana": "懸念[けねん]していたことは起[お]こらなかった。", "sentence_source": "generated"}, {"text": "台風が近づいているので、旅行への影響が懸念される。", "target_word": "懸念", "complexity_tier": "T4", "furigana": "台風[たいふう]が近[ちか]づいているので、旅行[りょこう]への影響[えいきょう]が懸念[けねん]される。", "sentence_source": "generated"}, {"text": "子どもの安全について、親は常に懸念を抱いている。", "target_word": "懸念", "complexity_tier": "T4", "furigana": "子[こ]どもの安全[あんぜん]について、親[おや]は常[つね]に懸念[けねん]を抱[いだ]いている。", "sentence_source": "generated"}, {"text": "懸念があるなら、先に先生に相談しておいたほうがいい。", "target_word": "懸念", "complexity_tier": "T4", "furigana": "懸念[けねん]があるなら、先[さき]に先生[せんせい]に相談[そうだん]しておいたほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "懸念する", "label": "派生"}, {"form": "懸念される", "label": "派生"}, {"form": "懸念材料", "label": "派生"}, {"form": "懸念事項", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 心配に思うことや気がかり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61f01209-a5ab-450f-a9fd-dfc8a97e8f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52031, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "懸念", "is_correct": true, "explanation": "見出し語の「けねん」そのものです。"}, {"text": "疑念", "is_correct": false, "explanation": "「ぎねん」は最初の一音だけが違う別の語です。"}, {"text": "理念", "is_correct": false, "explanation": "「りねん」は最初の一音だけが違う別の語です。"}, {"text": "無念", "is_correct": false, "explanation": "「むねん」は最初の一音だけが違う別の語です。"}, {"text": "外連", "is_correct": false, "explanation": "「けれん」は二音目だけが違う別の語です。"}], "explanations": {"懸念": "見出し語の「けねん」そのものです。", "疑念": "「ぎねん」は最初の一音だけが違う別の語です。", "理念": "「りねん」は最初の一音だけが違う別の語です。", "無念": "「むねん」は最初の一音だけが違う別の語です。", "外連": "「けれん」は二音目だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "懸念"}, "level_3": {"options": [{"text": "懸念", "is_correct": true, "explanation": "遅刻が心配なことだという意味で自然です。"}, {"text": "楽しみ", "is_correct": false, "explanation": "形は合うが意味が合わない。遅刻を楽しみにするのは不自然です。"}, {"text": "感謝", "is_correct": false, "explanation": "形は合うが意味が合わない。遅刻が感謝の対象という意味になってしまいます。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが意味が合わない。遅刻が趣味というのは文脈に合いません。"}], "explanations": {"懸念": "遅刻が心配なことだという意味で自然です。", "楽しみ": "形は合うが意味が合わない。遅刻を楽しみにするのは不自然です。", "感謝": "形は合うが意味が合わない。遅刻が感謝の対象という意味になってしまいます。", "趣味": "形は合うが意味が合わない。遅刻が趣味というのは文脈に合いません。"}, "sentence_index": 0, "correct_answer": "懸念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達と旅行に行くのが楽しみで、毎日懸念している。", "explanation": "「懸念」は心配を表し、楽しみな気持ちには使えません。"}, {"text": "おいしいケーキを食べて、懸念な気持ちになった。", "explanation": "「懸念」は満足や喜びを表さず、意味が合いません。"}, {"text": "昨日の試合の結果を懸念して、とても嬉しかった。", "explanation": "「懸念」は心配なことで、嬉しい気持ちとは結びつきません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52031, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "懸念", "is_correct": true, "explanation": "見出し語の「けねん」そのものです。"}, {"text": "余念", "is_correct": false, "explanation": "「よねん」は最初の一音だけが違う別の語です。"}, {"text": "去年", "is_correct": false, "explanation": "「きょねん」は最初の一音だけが違う別の語です。"}, {"text": "邪念", "is_correct": false, "explanation": "「じゃねん」は最初の一音だけが違う別の語です。"}], "explanations": {"懸念": "見出し語の「けねん」そのものです。", "余念": "「よねん」は最初の一音だけが違う別の語です。", "去年": "「きょねん」は最初の一音だけが違う別の語です。", "邪念": "「じゃねん」は最初の一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "懸念"}, "level_3": {"options": [{"text": "懸念", "is_correct": true, "explanation": "心配していたことが起こらなかったという意味で自然です。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。散歩していたことが「起こる」という内容は不自然です。"}, {"text": "掃除", "is_correct": false, "explanation": "形は合うが意味が合わない。掃除していたことが「起こらなかった」は不自然です。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが意味が合わない。運転していたことが「起こらなかった」は不自然です。"}], "explanations": {"懸念": "心配していたことが起こらなかったという意味で自然です。", "散歩": "形は合うが意味が合わない。散歩していたことが「起こる」という内容は不自然です。", "掃除": "形は合うが意味が合わない。掃除していたことが「起こらなかった」は不自然です。", "運転": "形は合うが意味が合わない。運転していたことが「起こらなかった」は不自然です。"}, "sentence_index": 6, "correct_answer": "懸念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "懸念が大きいので、安心して旅行に出かけた。", "explanation": "懸念が大きければ安心できず、意味が矛盾します。"}, {"text": "彼は懸念を食べて、元気になった。", "explanation": "「懸念」は食べるものではありません。"}, {"text": "このカバンは懸念が軽くて、使いやすい。", "explanation": "「懸念」は物の軽さではなく心配な気持ちを表します。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warni