INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52032, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「懸念が大きくなった」で、変化する主語を表します。"}, {"text": "を", "is_correct": false, "explanation": "「大きくなる」は自動詞なので、目的語の「を」は使えません。"}, {"text": "に", "is_correct": false, "explanation": "「懸念に大きくなった」では主語がなくなり、文が成立しません。"}, {"text": "と", "is_correct": false, "explanation": "「懸念と大きくなった」では意味が通りません。"}], "correct_answer": "が", "explanations": {"が": "「懸念が大きくなった」で、変化する主語を表します。", "を": "「大きくなる」は自動詞なので、目的語の「を」は使えません。", "に": "「懸念に大きくなった」では主語がなくなり、文が成立しません。", "と": "「懸念と大きくなった」では意味が通りません。"}, "error_tags": {"を": "object_marker", "に": "target_marker", "と": "quotation_or_partner"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安心", "is_correct": true, "explanation": "不安がなく落ち着いた状態で、「懸念」の反対です。"}, {"text": "憂慮", "is_correct": false, "explanation": "悪い成り行きを心配することで、「懸念」の類義語です。"}, {"text": "気がかり", "is_correct": false, "explanation": "心配に思うことで、「懸念」に近い意味です。"}, {"text": "恐怖", "is_correct": false, "explanation": "強いおそれで、反対の意味ではありません。"}], "correct_answer": "安心", "explanations": {"安心": "不安がなく落ち着いた状態で、「懸念」の反対です。", "憂慮": "悪い成り行きを心配することで、「懸念」の類義語です。", "気がかり": "心配に思うことで、「懸念」に近い意味です。", "恐怖": "強いおそれで、反対の意味ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
