INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52032, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "将来、良くないことが起こるのではないかという不安。", "primary_collocate": null, "pronunciation": "けねん", "ipa": "keneɴ", "syllable_count": 3, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "懸念", "complexity_tier": "T6", "furigana": "イールドカーブ・コントロールの下[もと]では、市場[しじょう]メカニズムを通[つう]じた適正[てきせい]なリスクプレミアムの形成[けいせい]が阻害[そがい]され、結果[けっか]として財政[ざいせい]の持続[じぞく]可能性[かのうせい]を担保[たんぽ]するべき債務[さいむ]の価格的[かかくてき]シグナルが鈍磨[どんま]する懸念[けねん]が拭[ぬぐ]えない。", "sentence_source": "mined"}, {"text": "将来への懸念が大きくなった。", "target_word": "懸念", "complexity_tier": "T2", "furigana": "将来[しょうらい]への懸念[けねん]が大[おお]きくなった。", "sentence_source": "generated"}, {"text": "事故の懸念はありません。", "target_word": "懸念", "complexity_tier": "T2", "furigana": "事故[じこ]の懸念[けねん]はありません。", "sentence_source": "generated"}, {"text": "母は私の健康を懸念している。", "target_word": "懸念", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の健康[けんこう]を懸念[けねん]している。", "sentence_source": "generated"}, {"text": "新しい法律に懸念を示す人もいる。", "target_word": "懸念", "complexity_tier": "T3", "furigana": "新[あたら]しい法律[ほうりつ]に懸念[けねん]を示[しめ]す人[ひと]もいる。", "sentence_source": "generated"}, {"text": "懸念が現実になってしまった。", "target_word": "懸念", "complexity_tier": "T3", "furigana": "懸念[けねん]が現実[げんじつ]になってしまった。", "sentence_source": "generated"}, {"text": "専門家は物価の上昇に懸念を表明した。", "target_word": "懸念", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は物価[ぶっか]の上昇[じょうしょう]に懸念[けねん]を表明[ひょうめい]した。", "sentence_source": "generated"}, {"text": "失敗するのではないかという懸念から、彼は何度も確認した。", "target_word": "懸念", "complexity_tier": "T4", "furigana": "失敗[しっぱい]するのではないかという懸念[けねん]から、彼[かれ]は何度[なんど]も確認[かくにん]した。", "sentence_source": "generated"}, {"text": "環境への影響が懸念されるため、工事は一時止められた。", "target_word": "懸念", "complexity_tier": "T4", "furigana": "環境[かんきょう]への影響[えいきょう]が懸念[けねん]されるため、工事[こうじ]は一時[いちじ]止[と]められた。", "sentence_source": "generated"}, {"text": "懸念を取り除くには、まず正確な情報を集めることが大切だ。", "target_word": "懸念", "complexity_tier": "T4", "furigana": "懸念[けねん]を取[と]り除[のぞ]くには、まず正確[せいかく]な情報[じょうほう]を集[あつ]めることが大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "懸念する", "label": "派生"}, {"form": "懸念される", "label": "派生"}, {"form": "懸念材料", "label": "派生"}, {"form": "懸念事項", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 将来への悪い予想に対する不安", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61f01209-a5ab-450f-a9fd-dfc8a97e8f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52032, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "懸念", "is_correct": true, "explanation": "見出し語の「けねん」そのものです。"}, {"text": "疑念", "is_correct": false, "explanation": "「ぎねん」は最初の一音だけが違う別の語です。"}, {"text": "理念", "is_correct": false, "explanation": "「りねん」は最初の一音だけが違う別の語です。"}, {"text": "無念", "is_correct": false, "explanation": "「むねん」は最初の一音だけが違う別の語です。"}, {"text": "外連", "is_correct": false, "explanation": "「けれん」は二音目だけが違う別の語です。"}], "explanations": {"懸念": "見出し語の「けねん」そのものです。", "疑念": "「ぎねん」は最初の一音だけが違う別の語です。", "理念": "「りねん」は最初の一音だけが違う別の語です。", "無念": "「むねん」は最初の一音だけが違う別の語です。", "外連": "「けれん」は二音目だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "懸念"}, "level_3": {"options": [{"text": "懸念", "is_correct": true, "explanation": "将来への悪い予想に対する不安を表し、「拭えない」と自然に結びつきます。"}, {"text": "期待", "is_correct": false, "explanation": "形は合うが意味が合わない。「期待」は良い予想で、「拭えない」とは結びつきません。"}, {"text": "満足", "is_correct": false, "explanation": "形は合うが意味が合わない。「満足」が鈍磨することや拭えないことを表す文脈ではありません。"}, {"text": "自信", "is_correct": false, "explanation": "形は合うが意味が合わない。「自信が拭えない」とは言いません。"}], "explanations": {"懸念": "将来への悪い予想に対する不安を表し、「拭えない」と自然に結びつきます。", "期待": "形は合うが意味が合わない。「期待」は良い予想で、「拭えない」とは結びつきません。", "満足": "形は合うが意味が合わない。「満足」が鈍磨することや拭えないことを表す文脈ではありません。", "自信": "形は合うが意味が合わない。「自信が拭えない」とは言いません。"}, "sentence_index": 0, "correct_answer": "懸念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は私の誕生日を懸念して、大きなケーキを買った。", "explanation": "「懸念」は悪いことへの不安で、楽しみにする気持ちには使えません。"}, {"text": "試験に合格したと聞いて、彼は大きな懸念を感じて喜んだ。", "explanation": "「懸念」は良い知らせへの喜びではなく、悪い予想への不安を表します。"}, {"text": "彼は昨日の食事を懸念して、とてもおいしかったと言った。", "explanation": "「懸念」は将来への不安で、過去の出来事の感想には使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52032, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "懸念", "is_correct": true, "explanation": "見出し語の「けねん」そのものです。"}, {"text": "余念", "is_correct": false, "explanation": "「よねん」は最初の一音だけが違う別の語です。"}, {"text": "去年", "is_correct": false, "explanation": "「きょねん」は最初の一音だけが違う別の語です。"}, {"text": "邪念", "is_correct": false, "explanation": "「じゃねん」は最初の一音だけが違う別の語です。"}], "explanations": {"懸念": "見出し語の「けねん」そのものです。", "余念": "「よねん」は最初の一音だけが違う別の語です。", "去年": "「きょねん」は最初の一音だけが違う別の語です。", "邪念": "「じゃねん」は最初の一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "懸念"}, "level_3": {"options": [{"text": "懸念", "is_correct": true, "explanation": "物価上昇への不安を示す「懸念を表明する」という表現です。"}, {"text": "感謝", "is_correct": false, "explanation": "形は合うが意味が合わない。物価上昇に感謝を表明するのは不自然です。"}, {"text": "祝福", "is_correct": false, "explanation": "形は合うが意味が合わない。物価上昇を祝福する文脈ではありません。"}, {"text": "謝罪", "is_correct": false, "explanation": "形は合うが意味が合わない。専門家が物価上昇に謝罪するのは不自然です。"}], "explanations": {"懸念": "物価上昇への不安を示す「懸念を表明する」という表現です。", "感謝": "形は合うが意味が合わない。物価上昇に感謝を表明するのは不自然です。", "祝福": "形は合うが意味が合わない。物価上昇を祝福する文脈ではありません。", "謝罪": "形は合うが意味が合わない。専門家が物価上昇に謝罪するのは不自然です。"}, "sentence_index": 6, "correct_answer": "懸念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は友人の結婚を心から懸念し、盛大に祝った。", "explanation": "「懸念」は不安を表し、祝う気持ちには使えません。"}, {"text": "遅れてしまい、先生に懸念をかけてしまった。", "explanation": "「心配をかける」とは言いますが、「懸念をかける」は誤用です。"}, {"text": "この料理は懸念がよくて、毎日食べたくなる。", "explanation": "「懸念」は味の良さではなく不安を表します。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52032, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい制度の導入に、住民は大きな懸念を喜んだ。", "corrected_sentence": "新しい制度の導入に、住民は大きな懸念を示した。", "error_description": "「懸念」は不安なので「喜ぶ」とは結びつかず、「懸念を示す」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52032, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風の接近が懸念するため、試合は中止された。", "corrected_sentence": "台風の接近が懸念されるため、試合は中止された。", "error_description": "「接近が」が主語なので、受身の「懸念される」にするべき。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f253fac-b463-490d-880c-dfb43e853640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52033, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "原因を表し、「インフレで物が高くなる」と使う。"}, {"text": "を", "is_correct": false, "explanation": "「物が高くなる」の前では目的語にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、原因を表せない。"}, {"text": "まで", "is_correct": false, "explanation": "範囲の助詞で、この文では不自然。"}], "correct_answer": "で", "explanations": {"で": "原因を表し、「インフレで物が高くなる」と使う。", "を": "「物が高くなる」の前では目的語にならず不自然。", "へ": "方向の助詞で、原因を表せない。", "まで": "範囲の助詞で、この文では不自然。"}, "error_tags": {"を": "object", "へ": "direction", "まで": "limit"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "デフレ", "is_correct": true, "explanation": "物の値段が下がり続けることで、インフレの対義語。"}, {"text": "貯金", "is_correct": false, "explanation": "お金をためることで、対義の関係ではない。"}, {"text": "給料", "is_correct": false, "explanation": "働いてもらうお金で、対義の関係ではない。"}, {"text": "値段", "is_correct": false, "explanation": "物の価格のことで、対義の関係ではない。"}], "correct_answer": "デフレ", "explanations": {"デフレ": "物の値段が下がり続けることで、インフレの対義語。", "貯金": "お金をためることで、対義の関係ではない。", "給料": "働いてもらうお金で、対義の関係ではない。", "値段": "物の価格のことで、対義の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52033, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「インフレが続く」で主語を表す。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞で、目的語を取らない。"}, {"text": "と", "is_correct": false, "explanation": "「インフレと続けば」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「インフレが続く」で主語を表す。", "を": "「続く」は自動詞で、目的語を取らない。", "と": "「インフレと続けば」では意味が通らない。", "へ": "方向の助詞で、主語にならない。"}, "error_tags": {"を": "object", "と": "comitative", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "デフレ", "is_correct": true, "explanation": "物の値段が下がり続けることで、インフレの対義語。"}, {"text": "パン", "is_correct": false, "explanation": "食べ物で、対義の関係ではない。"}, {"text": "生活", "is_correct": false, "explanation": "暮らしのことで、対義の関係ではない。"}, {"text": "心配", "is_correct": false, "explanation": "気がかりのことで、対義の関係ではない。"}], "correct_answer": "デフレ", "explanations": {"デフレ": "物の値段が下がり続けることで、インフレの対義語。", "パン": "食べ物で、対義の関係ではない。", "生活": "暮らしのことで、対義の関係ではない。", "心配": "気がかりのことで、対義の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52033, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金の価値がだんだん下がって、物の値段が上がっていくこと。", "primary_collocate": null, "pronunciation": "いんふれ", "ipa": "iɴɸɯɾe", "syllable_count": 4, "sentences": [{"text": "今はインフレだ。", "target_word": "インフレ", "complexity_tier": "T1", "furigana": "今[いま]はインフレだ。", "sentence_source": "generated"}, {"text": "インフレは怖い。", "target_word": "インフレ", "complexity_tier": "T1", "furigana": "インフレは怖[こわ]い。", "sentence_source": "generated"}, {"text": "インフレで物が高くなった。", "target_word": "インフレ", "complexity_tier": "T2", "furigana": "インフレで物[もの]が高[たか]くなった。", "sentence_source": "generated"}, {"text": "日本でもインフレが始まった。", "target_word": "インフレ", "complexity_tier": "T2", "furigana": "日本[にほん]でもインフレが始[はじ]まった。", "sentence_source": "generated"}, {"text": "インフレになると、お金の力が弱くなる。", "target_word": "インフレ", "complexity_tier": "T3", "furigana": "インフレになると、お金[かね]の力[ちから]が弱[よわ]くなる。", "sentence_source": "generated"}, {"text": "父はインフレの話をしている。", "target_word": "インフレ", "complexity_tier": "T3", "furigana": "父[ちち]はインフレの話[はなし]をしている。", "sentence_source": "generated"}, {"text": "インフレが止まらなくて、みんな困っている。", "target_word": "インフレ", "complexity_tier": "T3", "furigana": "インフレが止[と]まらなくて、みんな困[こま]っている。", "sentence_source": "generated"}, {"text": "インフレが続けば、パンの値段も上がるだろう。", "target_word": "インフレ", "complexity_tier": "T4", "furigana": "インフレが続[つづ]けば、パンの値段[ねだん]も上[あ]がるだろう。", "sentence_source": "generated"}, {"text": "インフレを心配して、貯金を減らす人もいる。", "target_word": "インフレ", "complexity_tier": "T4", "furigana": "インフレを心配[しんぱい]して、貯金[ちょきん]を減[へ]らす人[ひと]もいる。", "sentence_source": "generated"}, {"text": "インフレのとき、給料が増えないと生活が苦しくなってしまう。", "target_word": "インフレ", "complexity_tier": "T5", "furigana": "インフレのとき、給料[きゅうりょう]が増[ふ]えないと生活[せいかつ]が苦[くる]しくなってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インフレーション", "label": "派生"}, {"form": "インフレ率", "label": "派生"}, {"form": "インフレ期待", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物の値段が上がり続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52033, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インフレ", "is_correct": true, "explanation": "「今は物価が上がる状態だ」という意味で合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、「今は鉛筆だ」では意味が合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、「今は辞書だ」では意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、「今は靴だ」では意味が合わない。"}], "explanations": {"インフレ": "「今は物価が上がる状態だ」という意味で合う。", "鉛筆": "形は合うが、「今は鉛筆だ」では意味が合わない。", "辞書": "形は合うが、「今は辞書だ」では意味が合わない。", "靴": "形は合うが、「今は靴だ」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "インフレ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "インフレで、お店の物がどんどん安くなりました。", "explanation": "インフレは物の値段が上がることで、安くなる意味ではない。"}, {"text": "インフレを食べて、元気になった。", "explanation": "インフレは食べ物ではなく、食べる対象にならない。"}, {"text": "インフレは、雨がたくさん降ることだ。", "explanation": "インフレは天気ではなく、値段が上がる現象を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52033, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インフレ", "is_correct": true, "explanation": "止まらず人々を困らせる経済の現象として合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、「机が止まらない」では意味が合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、「帽子が止まらない」では意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、「地図が止まらない」では意味が合わない。"}], "explanations": {"インフレ": "止まらず人々を困らせる経済の現象として合う。", "机": "形は合うが、「机が止まらない」では意味が合わない。", "帽子": "形は合うが、「帽子が止まらない」では意味が合わない。", "地図": "形は合うが、「地図が止まらない」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "インフレ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "インフレのとき、物の値段が下がって、お金で買える物が増える。", "explanation": "物の値段が下がるのはインフレではなく、意味が逆。"}, {"text": "インフレは、友だちに会う約束のことです。", "explanation": "インフレは経済の現象で、約束を指す語ではない。"}, {"text": "インフレの先生が、教室で話している。", "explanation": "インフレは人の職業や種類を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52033, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "インフレで野菜の値段が安くなりました。", "corrected_sentence": "インフレで野菜の値段が高くなりました。", "error_description": "インフレでは値段が上がる。「安くなりました」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52033, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "インフレのとき、貯金の価値は少しずつ上がっていく。", "corrected_sentence": "インフレのとき、貯金の価値は少しずつ下がっていく。", "error_description": "インフレではお金の価値が下がる。「上がっていく」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52034, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「インフレが…目減りさせ」で動作の主体を表す。"}, {"text": "を", "is_correct": false, "explanation": "後に「価値を」があり、目的語が重なって非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、動作の主体を表せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の助詞で、「目減りさせ」の主体がなくなり不自然。"}], "correct_answer": "が", "explanations": {"が": "「インフレが…目減りさせ」で動作の主体を表す。", "を": "後に「価値を」があり、目的語が重なって非文になる。", "へ": "方向の助詞で、動作の主体を表せない。", "から": "起点の助詞で、「目減りさせ」の主体がなくなり不自然。"}, "error_tags": {"を": "object", "へ": "direction", "から": "origin"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "デフレ", "is_correct": true, "explanation": "物価が持続的に下がる現象で、インフレの対義語。"}, {"text": "スタグフレーション", "is_correct": false, "explanation": "不況下の物価上昇で、インフレと反対ではない。"}, {"text": "増税", "is_correct": false, "explanation": "税を増やすことで、対義の関係ではない。"}, {"text": "円安", "is_correct": false, "explanation": "為替の動きで、対義の関係ではない。"}], "correct_answer": "デフレ", "explanations": {"デフレ": "物価が持続的に下がる現象で、インフレの対義語。", "スタグフレーション": "不況下の物価上昇で、インフレと反対ではない。", "増税": "税を増やすことで、対義の関係ではない。", "円安": "為替の動きで、対義の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52034, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「インフレが続く」で主語を表す。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞で、目的語を取らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「続けば」の主語を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「インフレが続く」で主語を表す。", "を": "「続く」は自動詞で、目的語を取らない。", "より": "比較の助詞で、「続けば」の主語を表せない。", "へ": "方向の助詞で、主語にならない。"}, "error_tags": {"を": "object", "より": "comparison", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "デフレ", "is_correct": true, "explanation": "物価が下がり続ける現象で、インフレの対義語。"}, {"text": "物価", "is_correct": false, "explanation": "インフレが起こす対象で、対義語ではない。"}, {"text": "景気", "is_correct": false, "explanation": "経済の状態を指す語で、対義の関係ではない。"}, {"text": "賃金", "is_correct": false, "explanation": "給料のことで、対義の関係ではない。"}], "correct_answer": "デフレ", "explanations": {"デフレ": "物価が下がり続ける現象で、インフレの対義語。", "物価": "インフレが起こす対象で、対義語ではない。", "景気": "経済の状態を指す語で、対義の関係ではない。", "賃金": "給料のことで、対義の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52034, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物価が全体的に持続的に上昇する経済現象。お金の価値が下がり、同じ金額で買える物が減ること。", "primary_collocate": null, "pronunciation": "いんふれ", "ipa": "iɴɸɯɾe", "syllable_count": 4, "sentences": [{"text": "原材料費の高騰に端を発した急激なインフレが、家計の預金の実質的な価値を大きく目減りさせ、消費の冷え込みを招いている。", "target_word": "インフレ", "complexity_tier": "T6", "furigana": "原材料費[げんざいりょうひ]の高騰[こうとう]に端[たん]を発[はっ]した急激[きゅうげき]なインフレが、家計[かけい]の預金[よきん]の実質的[じっしつてき]な価値[かち]を大[おお]きく目減[めべ]りさせ、消費[しょうひ]の冷[ひ]え込[こ]みを招[まね]いている。", "sentence_source": "generated"}, {"text": "インフレが続く。", "target_word": "インフレ", "complexity_tier": "T1", "furigana": "インフレが続[つづ]く。", "sentence_source": "generated"}, {"text": "今年はインフレが進みました。", "target_word": "インフレ", "complexity_tier": "T2", "furigana": "今年[ことし]はインフレが進[すす]みました。", "sentence_source": "generated"}, {"text": "インフレは家計に影響します。", "target_word": "インフレ", "complexity_tier": "T2", "furigana": "インフレは家計[かけい]に影響[えいきょう]します。", "sentence_source": "generated"}, {"text": "中央銀行はインフレを抑えようとしている。", "target_word": "インフレ", "complexity_tier": "T3", "furigana": "中央銀行[ちゅうおうぎんこう]はインフレを抑[おさ]えようとしている。", "sentence_source": "generated"}, {"text": "インフレで貯金の価値が下がっている。", "target_word": "インフレ", "complexity_tier": "T3", "furigana": "インフレで貯金[ちょきん]の価値[かち]が下[さ]がっている。", "sentence_source": "generated"}, {"text": "インフレのせいで、輸入品が高くなった。", "target_word": "インフレ", "complexity_tier": "T3", "furigana": "インフレのせいで、輸入品[ゆにゅうひん]が高[たか]くなった。", "sentence_source": "generated"}, {"text": "インフレが続けば、賃金も上げざるを得ない。", "target_word": "インフレ", "complexity_tier": "T4", "furigana": "インフレが続[つづ]けば、賃金[ちんぎん]も上[あ]げざるを得[え]ない。", "sentence_source": "generated"}, {"text": "政府は急激なインフレを防ぐために金利を上げた。", "target_word": "インフレ", "complexity_tier": "T4", "furigana": "政府[せいふ]は急激[きゅうげき]なインフレを防[ふせ]ぐために金利[きんり]を上[あ]げた。", "sentence_source": "generated"}, {"text": "長引くインフレは、年金生活者の暮らしを静かに圧迫する。", "target_word": "インフレ", "complexity_tier": "T5", "furigana": "長引[ながび]くインフレは、年金生活者[ねんきんせいかつしゃ]の暮[く]らしを静[しず]かに圧迫[あっぱく]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インフレーション", "label": "派生"}, {"form": "インフレ率", "label": "派生"}, {"form": "インフレ期待", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物価が持続的に上がる経済現象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52034, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インフレ", "is_correct": true, "explanation": "物価の高騰が預金の価値を減らすという因果に合う。"}, {"text": "少子化", "is_correct": false, "explanation": "形は合うが、原材料費の高騰から少子化は生じず意味が合わない。"}, {"text": "豊作", "is_correct": false, "explanation": "形は合うが、豊作は預金の価値を減らす原因にならない。"}, {"text": "噴火", "is_correct": false, "explanation": "形は合うが、原材料費の高騰から噴火は起こらない。"}], "explanations": {"インフレ": "物価の高騰が預金の価値を減らすという因果に合う。", "少子化": "形は合うが、原材料費の高騰から少子化は生じず意味が合わない。", "豊作": "形は合うが、豊作は預金の価値を減らす原因にならない。", "噴火": "形は合うが、原材料費の高騰から噴火は起こらない。"}, "sentence_index": 0, "correct_answer": "インフレ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夕食はインフレがおいしかった。", "explanation": "インフレは経済現象で、食べ物の味を表す語ではない。"}, {"text": "インフレのせいで、物の値段が全体的に下がり続けている。", "explanation": "物価が下がるのはデフレで、インフレの意味に反する。"}, {"text": "インフレの日は、傘を持って出かけたほうがいい。", "explanation": "インフレは天気を表さず、特定の日を指す語でもない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52034, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インフレ", "is_correct": true, "explanation": "物価上昇で輸入品が高くなるという因果に合う。"}, {"text": "円高", "is_correct": false, "explanation": "形は合うが、円高なら輸入品は安くなるので意味が合わない。"}, {"text": "デフレ", "is_correct": false, "explanation": "形は合うが、デフレは物価下落で意味が合わない。"}, {"text": "豊作", "is_correct": false, "explanation": "形は合うが、輸入品の値段との因果に意味が合わない。"}], "explanations": {"インフレ": "物価上昇で輸入品が高くなるという因果に合う。", "円高": "形は合うが、円高なら輸入品は安くなるので意味が合わない。", "デフレ": "形は合うが、デフレは物価下落で意味が合わない。", "豊作": "形は合うが、輸入品の値段との因果に意味が合わない。"}, "sentence_index": 6, "correct_answer": "インフレ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "インフレで、毎年お金の価値がどんどん上がっていく。", "explanation": "インフレはお金の価値が下がる現象で、意味が逆。"}, {"text": "インフレは友達と一緒に公園で遊ぶことだ。", "explanation": "インフレは経済現象で、遊びの行為ではない。"}, {"text": "彼はインフレの電車に乗って学校へ行った。", "explanation": "インフレは電車の種類を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52034, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "インフレが進むと、お金の価値が下がり、同じ金額で買える物が増える。", "corrected_sentence": "インフレが進むと、お金の価値が下がり、同じ金額で買える物が減る。", "error_description": "インフレでは買える物が増えるのではなく減る。「増える」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52034, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "中央銀行は物価が下がり続けるインフレを抑えるため、金利を上げた。", "corrected_sentence": "中央銀行は物価が上がり続けるインフレを抑えるため、金利を上げた。", "error_description": "インフレは物価が上がる現象。「下がり続ける」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52035, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「心が鈍磨する」で主語を表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、主語を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「心に鈍磨しました」では主語がなく不自然。"}, {"text": "と", "is_correct": false, "explanation": "「心と鈍磨しました」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「心が鈍磨する」で主語を表す。", "へ": "方向の助詞で、主語を表せない。", "に": "「心に鈍磨しました」では主語がなく不自然。", "と": "「心と鈍磨しました」では意味が通らない。"}, "error_tags": {"へ": "direction", "に": "target", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "鋭敏", "is_correct": true, "explanation": "感覚が鋭くはっきりしていることで、鈍磨の対義語。"}, {"text": "麻痺", "is_correct": false, "explanation": "感覚がなくなることで、鈍磨に近く対義ではない。"}, {"text": "疲労", "is_correct": false, "explanation": "疲れることで、対義の関係ではない。"}, {"text": "寒冷", "is_correct": false, "explanation": "寒いことで、対義の関係ではない。"}], "correct_answer": "鋭敏", "explanations": {"鋭敏": "感覚が鋭くはっきりしていることで、鈍磨の対義語。", "麻痺": "感覚がなくなることで、鈍磨に近く対義ではない。", "疲労": "疲れることで、対義の関係ではない。", "寒冷": "寒いことで、対義の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52035, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「鈍磨を防ぐ」で防ぐ対象を表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、「防ぐ」の目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「鈍磨と防ぐ」では意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「鈍磨に防ぐ」では「防ぐ」と結びつかず不自然。"}], "correct_answer": "を", "explanations": {"を": "「鈍磨を防ぐ」で防ぐ対象を表す。", "へ": "方向の助詞で、「防ぐ」の目的語にならない。", "と": "「鈍磨と防ぐ」では意味が通らない。", "に": "「鈍磨に防ぐ」では「防ぐ」と結びつかず不自然。"}, "error_tags": {"へ": "direction", "と": "comitative", "に": "target"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "敏感", "is_correct": true, "explanation": "感覚が鋭く働くことで、鈍磨と反対の状態。"}, {"text": "鈍感", "is_correct": false, "explanation": "感覚が鈍いことで、鈍磨に近く対義ではない。"}, {"text": "挑戦", "is_correct": false, "explanation": "新しいことに取り組むことで、対義の関係ではない。"}, {"text": "危険", "is_correct": false, "explanation": "あぶないことで、対義の関係ではない。"}], "correct_answer": "敏感", "explanations": {"敏感": "感覚が鋭く働くことで、鈍磨と反対の状態。", "鈍感": "感覚が鈍いことで、鈍磨に近く対義ではない。", "挑戦": "新しいことに取り組むことで、対義の関係ではない。", "危険": "あぶないことで、対義の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52035, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "感覚や心の働きがにぶくなり、物事を鋭く感じ取れなくなること。", "primary_collocate": null, "pronunciation": "どんま", "ipa": "doɴma", "syllable_count": 3, "sentences": [{"text": "心が鈍磨する。", "target_word": "鈍磨", "complexity_tier": "T1", "furigana": "心[こころ]が鈍磨[どんま]する。", "sentence_source": "generated"}, {"text": "毎日の仕事で心が鈍磨しました。", "target_word": "鈍磨", "complexity_tier": "T2", "furigana": "毎日[まいにち]の仕事[しごと]で心[こころ]が鈍磨[どんま]しました。", "sentence_source": "generated"}, {"text": "感覚の鈍磨が心配です。", "target_word": "鈍磨", "complexity_tier": "T2", "furigana": "感覚[かんかく]の鈍磨[どんま]が心配[しんぱい]です。", "sentence_source": "generated"}, {"text": "単調な生活が続いて、感覚が鈍磨している。", "target_word": "鈍磨", "complexity_tier": "T3", "furigana": "単調[たんちょう]な生活[せいかつ]が続[つづ]いて、感覚[かんかく]が鈍磨[どんま]している。", "sentence_source": "generated"}, {"text": "疲れがたまると、判断力が鈍磨してしまう。", "target_word": "鈍磨", "complexity_tier": "T3", "furigana": "疲[つか]れがたまると、判断力[はんだんりょく]が鈍磨[どんま]してしまう。", "sentence_source": "generated"}, {"text": "年をとると、感覚の鈍磨が進む。", "target_word": "鈍磨", "complexity_tier": "T3", "furigana": "年[とし]をとると、感覚[かんかく]の鈍磨[どんま]が進[すす]む。", "sentence_source": "generated"}, {"text": "毎日同じ音を聞いていると、耳が鈍磨するそうだ。", "target_word": "鈍磨", "complexity_tier": "T4", "furigana": "毎日[まいにち]同[おな]じ音[おと]を聞[き]いていると、耳[みみ]が鈍磨[どんま]するそうだ。", "sentence_source": "generated"}, {"text": "鈍磨を防ぐために、新しいことに挑戦している。", "target_word": "鈍磨", "complexity_tier": "T4", "furigana": "鈍磨[どんま]を防[ふせ]ぐために、新[あたら]しいことに挑戦[ちょうせん]している。", "sentence_source": "generated"}, {"text": "感覚が鈍磨したせいで、危険に気づかなかった。", "target_word": "鈍磨", "complexity_tier": "T4", "furigana": "感覚[かんかく]が鈍磨[どんま]したせいで、危険[きけん]に気[き]づかなかった。", "sentence_source": "generated"}, {"text": "長い間無理を続けた結果、体も心も鈍磨してしまったようだ。", "target_word": "鈍磨", "complexity_tier": "T5", "furigana": "長[なが]い間[あいだ]無理[むり]を続[つづ]けた結果[けっか]、体[からだ]も心[こころ]も鈍磨[どんま]してしまったようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鈍磨する", "label": "活用"}, {"form": "鈍磨した", "label": "活用"}, {"form": "鈍磨している", "label": "活用"}, {"form": "鈍磨させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 感覚・心の働きがにぶくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52035, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鈍磨", "is_correct": true, "explanation": "心がはっきり働かなくなる意味で合う。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが、「心が出発する」では意味が合わない。"}, {"text": "乗車", "is_correct": false, "explanation": "形は合うが、「心が乗車する」では意味が合わない。"}, {"text": "開店", "is_correct": false, "explanation": "形は合うが、「心が開店する」では意味が合わない。"}], "explanations": {"鈍磨": "心がはっきり働かなくなる意味で合う。", "出発": "形は合うが、「心が出発する」では意味が合わない。", "乗車": "形は合うが、「心が乗車する」では意味が合わない。", "開店": "形は合うが、「心が開店する」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "鈍磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝コーヒーを飲んだら、頭が鈍磨してはっきり冴えた。", "explanation": "鈍磨ははっきりしなくなることで、冴える意味ではない。"}, {"text": "鈍磨をテーブルの上に置いた。", "explanation": "鈍磨は物ではなく、置く対象にならない。"}, {"text": "駅まで鈍磨で走って行った。", "explanation": "鈍磨は移動の手段を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52035, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鈍磨", "is_correct": true, "explanation": "同じ音を聞き続けて耳の感覚が鈍る意味で合う。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、「耳が結婚する」では意味が合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、「耳が卒業する」では意味が合わない。"}, {"text": "入院", "is_correct": false, "explanation": "形は合うが、「耳が入院する」では意味が合わない。"}], "explanations": {"鈍磨": "同じ音を聞き続けて耳の感覚が鈍る意味で合う。", "結婚": "形は合うが、「耳が結婚する」では意味が合わない。", "卒業": "形は合うが、「耳が卒業する」では意味が合わない。", "入院": "形は合うが、「耳が入院する」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "鈍磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "練習を重ねて、耳が鈍磨したので、小さな音もよく聞こえる。", "explanation": "鈍磨は感覚が鈍ることで、よく聞こえる意味ではない。"}, {"text": "鈍磨が空を飛んでいる。", "explanation": "鈍磨は生き物ではなく、飛ぶ主語にならない。"}, {"text": "弟は鈍磨が好きで、毎日三つ食べる。", "explanation": "鈍磨は食べ物ではなく、食べる対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
