INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52036, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「感受性が鈍磨する」で主語を表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、主語を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「感受性に鈍磨しやすい」では主語がなく不自然。"}, {"text": "と", "is_correct": false, "explanation": "「感受性と鈍磨しやすい」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「感受性が鈍磨する」で主語を表す。", "へ": "方向の助詞で、主語を表せない。", "に": "「感受性に鈍磨しやすい」では主語がなく不自然。", "と": "「感受性と鈍磨しやすい」では意味が通らない。"}, "error_tags": {"へ": "direction", "に": "target", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "敏感", "is_correct": true, "explanation": "感覚が鋭く反応することで、鈍磨と反対の状態。"}, {"text": "鈍感", "is_correct": false, "explanation": "感覚が鈍いことで、鈍磨に近く対義ではない。"}, {"text": "停滞", "is_correct": false, "explanation": "進まないことで、対義の関係ではない。"}, {"text": "習慣", "is_correct": false, "explanation": "いつもの行いのことで、対義の関係ではない。"}], "correct_answer": "敏感", "explanations": {"敏感": "感覚が鋭く反応することで、鈍磨と反対の状態。", "鈍感": "感覚が鈍いことで、鈍磨に近く対義ではない。", "停滞": "進まないことで、対義の関係ではない。", "習慣": "いつもの行いのことで、対義の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52036, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の切れ味や感覚がにぶくなること。また、能力や機能が低下して、はっきりと働かなくなること。", "primary_collocate": null, "pronunciation": "どんま", "ipa": "doɴma", "syllable_count": 3, "sentences": [{"text": "長期にわたる金融緩和の下では、市場の価格シグナルが鈍磨し、財政規律への警戒感も薄れかねないという指摘がある。", "target_word": "鈍磨", "complexity_tier": "T6", "furigana": "長期[ちょうき]にわたる金融緩和[きんゆうかんわ]の下[もと]では、市場[しじょう]の価格[かかく]シグナルが鈍磨[どんま]し、財政規律[ざいせいきりつ]への警戒感[けいかいかん]も薄[うす]れかねないという指摘[してき]がある。", "sentence_source": "generated"}, {"text": "感覚が鈍磨する。", "target_word": "鈍磨", "complexity_tier": "T1", "furigana": "感覚[かんかく]が鈍磨[どんま]する。", "sentence_source": "generated"}, {"text": "感覚が鈍磨しました。", "target_word": "鈍磨", "complexity_tier": "T2", "furigana": "感覚[かんかく]が鈍磨[どんま]しました。", "sentence_source": "generated"}, {"text": "長年の習慣で、判断力が鈍磨している。", "target_word": "鈍磨", "complexity_tier": "T3", "furigana": "長年[ながねん]の習慣[しゅうかん]で、判断力[はんだんりょく]が鈍磨[どんま]している。", "sentence_source": "generated"}, {"text": "刃物の切れ味が鈍磨してしまった。", "target_word": "鈍磨", "complexity_tier": "T3", "furigana": "刃物[はもの]の切[き]れ味[あじ]が鈍磨[どんま]してしまった。", "sentence_source": "generated"}, {"text": "鈍磨は少しずつ進んでいく。", "target_word": "鈍磨", "complexity_tier": "T3", "furigana": "鈍磨[どんま]は少[すこ]しずつ進[すす]んでいく。", "sentence_source": "generated"}, {"text": "危機感が鈍磨すれば、対応は遅れるだろう。", "target_word": "鈍磨", "complexity_tier": "T4", "furigana": "危機感[ききかん]が鈍磨[どんま]すれば、対応[たいおう]は遅[おく]れるだろう。", "sentence_source": "generated"}, {"text": "同じ刺激に慣れると、感受性が鈍磨しやすい。", "target_word": "鈍磨", "complexity_tier": "T4", "furigana": "同[おな]じ刺激[しげき]に慣[な]れると、感受性[かんじゅせい]が鈍磨[どんま]しやすい。", "sentence_source": "generated"}, {"text": "長時間の単調な作業は注意力の鈍磨を招く。", "target_word": "鈍磨", "complexity_tier": "T4", "furigana": "長時間[ちょうじかん]の単調[たんちょう]な作業[さぎょう]は注意力[ちゅういりょく]の鈍磨[どんま]を招[まね]く。", "sentence_source": "generated"}, {"text": "情報があふれる社会では、人々の痛みへの感覚が鈍磨しかねない。", "target_word": "鈍磨", "complexity_tier": "T5", "furigana": "情報[じょうほう]があふれる社会[しゃかい]では、人々[ひとびと]の痛[いた]みへの感覚[かんかく]が鈍磨[どんま]しかねない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鈍磨する", "label": "活用"}, {"form": "鈍磨した", "label": "活用"}, {"form": "鈍磨している", "label": "活用"}, {"form": "鈍磨させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 感覚や機能が鈍って低下すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52036, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鈍磨", "is_correct": true, "explanation": "価格シグナルの機能が低下する意味で合う。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、「シグナルが結婚する」では意味が合わない。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが、「シグナルが出発する」では意味が合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、「シグナルが卒業する」では意味が合わない。"}], "explanations": {"鈍磨": "価格シグナルの機能が低下する意味で合う。", "結婚": "形は合うが、「シグナルが結婚する」では意味が合わない。", "出発": "形は合うが、「シグナルが出発する」では意味が合わない。", "卒業": "形は合うが、「シグナルが卒業する」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "鈍磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "刃物の切れ味が鈍磨して、驚くほど鋭くなった。", "explanation": "鈍磨は鈍くなることで、鋭くなる意味ではない。"}, {"text": "彼は鈍磨に歩いて駅へ向かった。", "explanation": "鈍磨は歩き方を表す副詞的な語ではない。"}, {"text": "この料理は鈍磨で、とても甘い。", "explanation": "鈍磨は味を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52036, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鈍磨", "is_correct": true, "explanation": "危機感が弱まり対応が遅れるという流れに合う。"}, {"text": "入院", "is_correct": false, "explanation": "形は合うが、「危機感が入院する」では意味が合わない。"}, {"text": "乗車", "is_correct": false, "explanation": "形は合うが、「危機感が乗車する」では意味が合わない。"}, {"text": "開店", "is_correct": false, "explanation": "形は合うが、「危機感が開店する」では意味が合わない。"}], "explanations": {"鈍磨": "危機感が弱まり対応が遅れるという流れに合う。", "入院": "形は合うが、「危機感が入院する」では意味が合わない。", "乗車": "形は合うが、「危機感が乗車する」では意味が合わない。", "開店": "形は合うが、「危機感が開店する」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "鈍磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "運動を続けたら、感覚が鈍磨して、細かい違いまでよく分かるようになった。", "explanation": "鈍磨は感覚が鈍ることで、よく分かるようになる意味ではない。"}, {"text": "鈍磨を二つ買って、冷蔵庫に入れた。", "explanation": "鈍磨は物の名前ではなく、買って数える対象ではない。"}, {"text": "窓の鈍磨を開けて、空気を入れ替えた。", "explanation": "鈍磨は窓の部分を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52036, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刃物の切れ味が鈍磨して、よく切れるようになった。", "corrected_sentence": "刃物の切れ味が鈍磨して、よく切れなくなった。", "error_description": "鈍磨は切れ味が鈍る意味なので、「よく切れるようになった」が矛盾する。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52036, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鈍磨が進むと、感覚はますます鋭くなる。", "corrected_sentence": "鈍磨が進むと、感覚はますます鈍くなる。", "error_description": "鈍磨が進めば感覚は鈍くなる。「鋭くなる」が矛盾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52037, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「下ろす」の目的語を示す。"}, {"text": "の", "is_correct": false, "explanation": "「アンカーの下ろしました」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「アンカーへ下ろしました」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「アンカーと下ろしました」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「下ろす」の目的語を示す。", "の": "「アンカーの下ろしました」は文法的に成り立たない。", "へ": "「アンカーへ下ろしました」は文法的に成り立たない。", "と": "「アンカーと下ろしました」は文法的に成り立たない。"}, "error_tags": {"の": "possessive", "へ": "direction", "と": "quotative_or_comitative"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
