INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52037, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物をしっかりと固定するための道具。船を止めるための錨や、壁などに取り付けて物を固定する金具のこと。", "primary_collocate": null, "pronunciation": "あんかー", "ipa": "aɴkaː", "syllable_count": 4, "sentences": [{"text": "アンカーを下ろす。", "target_word": "アンカー", "complexity_tier": "T1", "furigana": "アンカーを下[お]ろす。", "sentence_source": "generated"}, {"text": "船がアンカーを下ろしました。", "target_word": "アンカー", "complexity_tier": "T2", "furigana": "船[ふね]がアンカーを下[お]ろしました。", "sentence_source": "generated"}, {"text": "壁のアンカーが緩みました。", "target_word": "アンカー", "complexity_tier": "T2", "furigana": "壁[かべ]のアンカーが緩[ゆる]みました。", "sentence_source": "generated"}, {"text": "アンカーが外れて、棚が落ちた。", "target_word": "アンカー", "complexity_tier": "T3", "furigana": "アンカーが外[はず]れて、棚[たな]が落[お]ちた。", "sentence_source": "generated"}, {"text": "強い風でアンカーが動いている。", "target_word": "アンカー", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]でアンカーが動[うご]いている。", "sentence_source": "generated"}, {"text": "工事の人が壁にアンカーを打ち込んだ。", "target_word": "アンカー", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が壁[かべ]にアンカーを打[う]ち込[こ]んだ。", "sentence_source": "generated"}, {"text": "アンカーが弱ければ、棚は危ない。", "target_word": "アンカー", "complexity_tier": "T4", "furigana": "アンカーが弱[よわ]ければ、棚[たな]は危[あぶ]ない。", "sentence_source": "generated"}, {"text": "この太い金具が、重い棚を支えるアンカーになる。", "target_word": "アンカー", "complexity_tier": "T4", "furigana": "この太[ふと]い金具[かなぐ]が、重[おも]い棚[たな]を支[ささ]えるアンカーになる。", "sentence_source": "generated"}, {"text": "重いアンカーのおかげで、船は流されなかった。", "target_word": "アンカー", "complexity_tier": "T4", "furigana": "重[おも]いアンカーのおかげで、船[ふね]は流[なが]されなかった。", "sentence_source": "generated"}, {"text": "嵐の夜、船長は大きなアンカーを海に投げ入れるよう命じた。", "target_word": "アンカー", "complexity_tier": "T5", "furigana": "嵐[あらし]の夜[よる]、船長[せんちょう]は大[おお]きなアンカーを海[うみ]に投[な]げ入[い]れるよう命[めい]じた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 船の錨や物を固定する金具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52037, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "アンカー", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "アンダー", "is_correct": false, "explanation": "「アンダー」は「か」が「だ」に変わった別の語。"}, {"text": "アンサー", "is_correct": false, "explanation": "「アンサー」は「か」が「さ」に変わった別の語。"}, {"text": "アンバー", "is_correct": false, "explanation": "「アンバー」は「か」が「ば」に変わった別の語。"}], "explanations": {"アンカー": "見出し語そのもの。", "アンダー": "「アンダー」は「か」が「だ」に変わった別の語。", "アンサー": "「アンサー」は「か」が「さ」に変わった別の語。", "アンバー": "「アンバー」は「か」が「ば」に変わった別の語。"}, "sentence_index": null, "correct_answer": "アンカー"}, "level_3": {"options": [{"text": "アンカー", "is_correct": true, "explanation": "船を固定する道具で「下ろす」に合う。"}, {"text": "ニュース", "is_correct": false, "explanation": "形は合うが、「下ろす」と結びつく意味ではない。"}, {"text": "ルール", "is_correct": false, "explanation": "形は合うが、「下ろす」とは意味が合わない。"}, {"text": "メロディー", "is_correct": false, "explanation": "形は合うが、「下ろす」とは意味が合わない。"}], "explanations": {"アンカー": "船を固定する道具で「下ろす」に合う。", "ニュース": "形は合うが、「下ろす」と結びつく意味ではない。", "ルール": "形は合うが、「下ろす」とは意味が合わない。", "メロディー": "形は合うが、「下ろす」とは意味が合わない。"}, "sentence_index": 0, "correct_answer": "アンカー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アンカーを飲んで、体が温まった。", "explanation": "アンカーは固定する道具や支えで、飲み物ではないので誤り。"}, {"text": "アンカーを冷蔵庫で冷やして、ジュースにした。", "explanation": "アンカーは物を固定する道具で、ジュースにする飲み物の材料ではないので誤り。"}, {"text": "アンカーを着て、雨の中を歩いた。", "explanation": "アンカーは衣服ではないので「着る」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52037, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "アンカー", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "ランカー", "is_correct": false, "explanation": "「ランカー」は「あ」が「ら」に変わった別の語。"}, {"text": "バンカー", "is_correct": false, "explanation": "「バンカー」は「あ」が「ば」に変わった別の語。"}, {"text": "タンカー", "is_correct": false, "explanation": "「タンカー」は「あ」が「た」に変わった別の語。"}, {"text": "リンカー", "is_correct": false, "explanation": "「リンカー」は「あ」が「り」に変わった別の語。"}], "explanations": {"アンカー": "見出し語そのもの。", "ランカー": "「ランカー」は「あ」が「ら」に変わった別の語。", "バンカー": "「バンカー」は「あ」が「ば」に変わった別の語。", "タンカー": "「タンカー」は「あ」が「た」に変わった別の語。", "リンカー": "「リンカー」は「あ」が「り」に変わった別の語。"}, "sentence_index": null, "correct_answer": "アンカー"}, "level_3": {"options": [{"text": "アンカー", "is_correct": true, "explanation": "固定する道具が弱いと棚が危ないという意味で合う。"}, {"text": "ニュース", "is_correct": false, "explanation": "形は合うが、「弱ければ棚が危ない」という意味が合わない。"}, {"text": "スープ", "is_correct": false, "explanation": "形は合うが、棚の安全とは意味が合わない。"}, {"text": "カレンダー", "is_correct": false, "explanation": "形は合うが、「弱い」と棚が危ない関係にならない。"}], "explanations": {"アンカー": "固定する道具が弱いと棚が危ないという意味で合う。", "ニュース": "形は合うが、「弱ければ棚が危ない」という意味が合わない。", "スープ": "形は合うが、棚の安全とは意味が合わない。", "カレンダー": "形は合うが、「弱い」と棚が危ない関係にならない。"}, "sentence_index": 6, "correct_answer": "アンカー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きなアンカーは甘くて、おやつに食べた。", "explanation": "アンカーは船を止める道具で、食べ物ではないので誤り。"}, {"text": "嵐の夜、船長は大きなアンカーを鍋で煮て食べた。", "explanation": "アンカーは船を止める金属の道具で、煮て食べるものではない。"}, {"text": "船長は大きなアンカーを机の上で読んだ。", "explanation": "アンカーは読む対象ではないので「読む」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_val