INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52038, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や物事を安定した状態に保つための基準や支え。金融の分野では、人々が将来の物価や経済の見通しを考えるときの基準となるもの。", "primary_collocate": null, "pronunciation": "あんかー", "ipa": "aɴkaː", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "アンカー", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融政策[きんゆうせいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体経済[じったいけいざい]における物価上昇圧力[ぶっかじょうしょうあつりょく]と相乗効果[そうじょうこうか]を生[う]み、予期[よき]せぬスタグフレーションや財政主導[ざいせいしゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "経済にはアンカーが要る。", "target_word": "アンカー", "complexity_tier": "T1", "furigana": "経済[けいざい]にはアンカーが要[い]る。", "sentence_source": "generated"}, {"text": "金利はアンカーになります。", "target_word": "アンカー", "complexity_tier": "T2", "furigana": "金利[きんり]はアンカーになります。", "sentence_source": "generated"}, {"text": "期待のアンカーが揺らぎました。", "target_word": "アンカー", "complexity_tier": "T2", "furigana": "期待[きたい]のアンカーが揺[ゆ]らぎました。", "sentence_source": "generated"}, {"text": "人々の期待のアンカーが必要だ。", "target_word": "アンカー", "complexity_tier": "T3", "furigana": "人々[ひとびと]の期待[きたい]のアンカーが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "中央銀行は物価目標をアンカーにしている。", "target_word": "アンカー", "complexity_tier": "T3", "furigana": "中央銀行[ちゅうおうぎんこう]は物価目標[ぶっかもくひょう]をアンカーにしている。", "sentence_source": "generated"}, {"text": "市場はそのアンカーを信じている。", "target_word": "アンカー", "complexity_tier": "T3", "furigana": "市場[しじょう]はそのアンカーを信[しん]じている。", "sentence_source": "generated"}, {"text": "アンカーが失われると、期待は不安定になりやすい。", "target_word": "アンカー", "complexity_tier": "T4", "furigana": "アンカーが失[うしな]われると、期待[きたい]は不安定[ふあんてい]になりやすい。", "sentence_source": "generated"}, {"text": "明確な目標がアンカーとして働けば、物価は安定する。", "target_word": "アンカー", "complexity_tier": "T4", "furigana": "明確[めいかく]な目標[もくひょう]がアンカーとして働[はたら]けば、物価[ぶっか]は安定[あんてい]する。", "sentence_source": "generated"}, {"text": "賃金交渉の場でも、前年の物価上昇率が一つのアンカーになっている。", "target_word": "アンカー", "complexity_tier": "T5", "furigana": "賃金交渉[ちんぎんこうしょう]の場[ば]でも、前年[ぜんねん]の物価上昇率[ぶっかじょうしょうりつ]が一[ひと]つのアンカーになっている。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 経済の見通しの基準となる支え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52038, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "アンカー", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "アンダー", "is_correct": false, "explanation": "「アンダー」は「か」が「だ」に変わった別の語。"}, {"text": "アンサー", "is_correct": false, "explanation": "「アンサー」は「か」が「さ」に変わった別の語。"}, {"text": "アンバー", "is_correct": false, "explanation": "「アンバー」は「か」が「ば」に変わった別の語。"}], "explanations": {"アンカー": "見出し語そのもの。", "アンダー": "「アンダー」は「か」が「だ」に変わった別の語。", "アンサー": "「アンサー」は「か」が「さ」に変わった別の語。", "アンバー": "「アンバー」は「か」が「ば」に変わった別の語。"}, "sentence_index": null, "correct_answer": "アンカー"}, "level_3": {"options": [{"text": "アンカー", "is_correct": true, "explanation": "インフレ期待の基準となる支えという意味で文脈に合う。"}, {"text": "カーテン", "is_correct": false, "explanation": "形は合うが、金融政策の文脈では意味が合わない。"}, {"text": "ボタン", "is_correct": false, "explanation": "形は合うが、期待の基準という意味にならない。"}, {"text": "メロディー", "is_correct": false, "explanation": "形は合うが、物価の見通しの支えという意味が合わない。"}], "explanations": {"アンカー": "インフレ期待の基準となる支えという意味で文脈に合う。", "カーテン": "形は合うが、金融政策の文脈では意味が合わない。", "ボタン": "形は合うが、期待の基準という意味にならない。", "メロディー": "形は合うが、物価の見通しの支えという意味が合わない。"}, "sentence_index": 0, "correct_answer": "アンカー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "金利のアンカーを朝ごはんに食べました。", "explanation": "アンカーは基準や支えであり、食べるものではないので用法が誤り。"}, {"text": "アンカーをコップに入れて、ジュースと一緒に飲んだ。", "explanation": "アンカーは基準や支えであり、飲み物ではないので誤り。"}, {"text": "彼はアンカーを着て出かけた。", "explanation": "アンカーは衣服ではないので「着る」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52038, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "アンカー", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "ランカー", "is_correct": false, "explanation": "「ランカー」は「あ」が「ら」に変わった別の語。"}, {"text": "バンカー", "is_correct": false, "explanation": "「バンカー」は「あ」が「ば」に変わった別の語。"}, {"text": "タンカー", "is_correct": false, "explanation": "「タンカー」は「あ」が「た」に変わった別の語。"}, {"text": "リンカー", "is_correct": false, "explanation": "「リンカー」は「あ」が「り」に変わった別の語。"}], "explanations": {"アンカー": "見出し語そのもの。", "ランカー": "「ランカー」は「あ」が「ら」に変わった別の語。", "バンカー": "「バンカー」は「あ」が「ば」に変わった別の語。", "タンカー": "「タンカー」は「あ」が「た」に変わった別の語。", "リンカー": "「リンカー」は「あ」が「り」に変わった別の語。"}, "sentence_index": null, "correct_answer": "アンカー"}, "level_3": {"options": [{"text": "アンカー", "is_correct": true, "explanation": "市場が信じる基準という意味で合う。"}, {"text": "ストロー", "is_correct": false, "explanation": "形は合うが、市場が信じる対象という意味が合わない。"}, {"text": "カーテン", "is_correct": false, "explanation": "形は合うが、市場が信じる基準という意味が合わない。"}, {"text": "スリッパ", "is_correct": false, "explanation": "形は合うが、経済の文脈では意味が合わない。"}], "explanations": {"アンカー": "市場が信じる基準という意味で合う。", "ストロー": "形は合うが、市場が信じる対象という意味が合わない。", "カーテン": "形は合うが、市場が信じる基準という意味が合わない。", "スリッパ": "形は合うが、経済の文脈では意味が合わない。"}, "sentence_index": 6, "correct_answer": "アンカー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このアンカーは甘くて、とてもおいしい。", "explanation": "アンカーは基準であり、味を持つ食べ物ではないので誤り。"}, {"text": "物価のアンカーを鍋で煮て、夕ご飯にした。", "explanation": "アンカーは抽象的な基準で、料理の材料ではないので誤り。"}, {"text": "アンカーを履いて学校へ行った。", "explanation": "アンカーは履き物ではないので「履く」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52038, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "物価目標がアンカーを食べて、期待が安定した。", "corrected_sentence": "物価目標がアンカーとなって、期待が安定した。", "error_description": "アンカーは食べるものではなく、「アンカーとなる」で基準になるという意味を表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52038, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "インフレ期待のアンカーが食べられると、市場は動揺する。", "corrected_sentence": "インフレ期待のアンカーが失われると、市場は動揺する。", "error_description": "基準としてのアンカーは「食べられる」ものではなく、「失われる」と言う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52039, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見た」の対象を示すので「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示す格で、「見た」の目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や引用を示すので、見る対象を表すことはできない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す格で、見る対象の名詞には付かない。"}], "correct_answer": "を", "explanations": {"を": "「見た」の対象を示すので「を」が正しい。", "に": "「に」は場所や相手を示す格で、「見た」の目的語にはならない。", "と": "「と」は共同や引用を示すので、見る対象を表すことはできない。", "へ": "「へ」は方向を示す格で、見る対象の名詞には付かない。"}, "error_tags": {"に": "相手・場所を示す格", "と": "共同・引用を示す格", "へ": "方向を示す格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52039, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52039, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本当に存在するものや、実際にあること。", "primary_collocate": null, "pronunciation": "じったい", "ipa": "dʑittai", "syllable_count": 4, "sentences": [{"text": "その会社は名前だけで、実体がないことが後で分かった。", "target_word": "実体", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は名前[なまえ]だけで、実体[じったい]がないことが後[あと]で分[わ]かった。", "sentence_source": "generated"}, {"text": "幽霊の話は多いが、実体を見た人はいない。", "target_word": "実体", "complexity_tier": "T3", "furigana": "幽霊[ゆうれい]の話[はなし]は多[おお]いが、実体[じったい]を見[み]た人[ひと]はいない。", "sentence_source": "generated"}, {"text": "影は動いているが、実体はどこにも見えない。", "target_word": "実体", "complexity_tier": "T3", "furigana": "影[かげ]は動[うご]いているが、実体[じったい]はどこにも見[み]えない。", "sentence_source": "generated"}, {"text": "鏡に映った姿は本物ではなく、実体のない像にすぎない。", "target_word": "実体", "complexity_tier": "T3", "furigana": "鏡[かがみ]に映[うつ]った姿[すがた]は本物[ほんもの]ではなく、実体[じったい]のない像[ぞう]にすぎない。", "sentence_source": "generated"}, {"text": "夢の中の人物には、実体がない。", "target_word": "実体", "complexity_tier": "T3", "furigana": "夢[ゆめ]の中[なか]の人物[じんぶつ]には、実体[じったい]がない。", "sentence_source": "generated"}, {"text": "彼は実体のあるものしか信じない人だ。", "target_word": "実体", "complexity_tier": "T3", "furigana": "彼[かれ]は実体[じったい]のあるものしか信[しん]じない人[ひと]だ。", "sentence_source": "generated"}, {"text": "噂だけが広がって、その店に実体があるのかさえ誰も知らなかった。", "target_word": "実体", "complexity_tier": "T3", "furigana": "噂[うわさ]だけが広[ひろ]がって、その店[みせ]に実体[じったい]があるのかさえ誰[だれ]も知[し]らなかった。", "sentence_source": "generated"}, {"text": "夜空に現れた未確認の物体の実体は、のちに飛行機だと分かった。", "target_word": "実体", "complexity_tier": "T3", "furigana": "夜空[よぞら]に現[あらわ]れた未確認[みかくにん]の物体[ぶったい]の実体[じったい]は、のちに飛行機[ひこうき]だと分[わ]かった。", "sentence_source": "generated"}, {"text": "立体映像は見えるが、手を伸ばしても実体には触れられない。", "target_word": "実体", "complexity_tier": "T3", "furigana": "立体映像[りったいえいぞう]は見[み]えるが、手[て]を伸[の]ばしても実体[じったい]には触[ふ]れられない。", "sentence_source": "generated"}, {"text": "名前ばかりの組織に実体を持たせるには、人とお金が要る。", "target_word": "実体", "complexity_tier": "T3", "furigana": "名前[なまえ]ばかりの組織[そしき]に実体[じったい]を持[も]たせるには、人[ひと]とお金[かね]が要[い]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実体", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "見かけや名前ではなく、実際に存在する本体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52039, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実体", "is_correct": true, "explanation": "「実体がない」は存在するものの中身がないことを表し、名前だけの会社だったという文脈に合う。"}, {"text": "面影", "is_correct": false, "explanation": "「面影」は昔の姿の名残を指すので、名前だけの会社に「面影がない」とは言えない。"}, {"text": "名残", "is_correct": false, "explanation": "「名残がない」は以前にあったものの痕跡が消えたことを表すため、初めから何もなかった会社の話には合わない。"}, {"text": "余韻", "is_correct": false, "explanation": "「余韻」は音や出来事が後に残る響きを指すので、会社の存在の有無には使えない。"}], "explanations": {"実体": "「実体がない」は存在するものの中身がないことを表し、名前だけの会社だったという文脈に合う。", "面影": "「面影」は昔の姿の名残を指すので、名前だけの会社に「面影がない」とは言えない。", "名残": "「名残がない」は以前にあったものの痕跡が消えたことを表すため、初めから何もなかった会社の話には合わない。", "余韻": "「余韻」は音や出来事が後に残る響きを指すので、会社の存在の有無には使えない。"}, "sentence_index": 0, "correct_answer": "実体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パソコンの実体が壊れたので、モニターだけ新しく買った。", "explanation": "ここは〈本体〉の意味。機械の中心部分は本体と言う。実体は実際に存在することを指すので、この文脈では使えない。"}, {"text": "その作家は実体の人物をもとに、小説を書いた。", "explanation": "ここは〈実在〉の意味。人物について実際にいたことを言うときは実在と言うので、実体の人物とは言わない。"}, {"text": "展示会では、実体の車に乗ることができた。", "explanation": "ここは〈実物〉の意味。展示された本物の品物は実物と言う。実体は存在の本体を指すので、車には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52039, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実体", "is_correct": true, "explanation": "「実体があるのか」は店が実際に存在するかを問う文になり、噂の内容と対応する。"}, {"text": "余韻", "is_correct": false, "explanation": "「余韻」は音や感情が残る響きを指すので、店の存在を問う文には合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "「色彩」は色の具合や雰囲気を指すので、店が実在するかという問いには合わない。"}, {"text": "雑音", "is_correct": false, "explanation": "「雑音」は耳に入る不要な音を指すので、店の有無を問う文脈では意味が成り立たない。"}], "explanations": {"実体": "「実体があるのか」は店が実際に存在するかを問う文になり、噂の内容と対応する。", "余韻": "「余韻」は音や感情が残る響きを指すので、店の存在を問う文には合わない。", "色彩": "「色彩」は色の具合や雰囲気を指すので、店が実在するかという問いには合わない。", "雑音": "「雑音」は耳に入る不要な音を指すので、店の有無を問う文脈では意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "実体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議では、誰も実体を言わなかった。", "explanation": "ここは〈本音〉の意味。本音は口に出して言うものだが、実体は存在そのものを指すので「言う」とは結びつかない。"}, {"text": "この箱の実体は、割れ物だと書いてある。", "explanation": "ここは〈中身〉の意味。箱に入っているものは中身と言う。実体は存在の本体を指すので、箱の中身の説明には合わない。"}, {"text": "研修は実体で行うのが一番だ。", "explanation": "ここは〈実地〉の意味（現場で実際に行う）。実体は存在そのものを指すので、現場で行う研修の意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52039, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その噂の実体に確かめるため、現地に行った。", "corrected_sentence": "その噂の実体を確かめるため、現地に行った。", "error_description": "「確かめる」は目的語に「を」を取る。「実体に」は誤りで、正しくは「実体を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52039, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その店は実体がいるのか、ずっと疑われていた。", "corrected_sentence": "その店は実体があるのか、ずっと疑われていた。", "error_description": "「実体」は存在する物事について「ある」と言う。「いる」は人や動物に使うので、「実体がいる」は誤り。正しくは「実体がある」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52041, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「物価の安い国」で主語を示す連体修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「物価を安い国」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「物価へ安い国」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「物価と安い国」は文法的に成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「物価の安い国」で主語を示す連体修飾の「の」。", "を": "「物価を安い国」は文法的に成り立たない。", "へ": "「物価へ安い国」は文法的に成り立たない。", "と": "「物価と安い国」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "quotative_or_comitative"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
