INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52041, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お店で売っているものの値段のこと。", "primary_collocate": null, "pronunciation": "ぶっか", "ipa": "bɯkka", "syllable_count": 3, "sentences": [{"text": "物価が高い。", "target_word": "物価", "complexity_tier": "T1", "furigana": "物価[ぶっか]が高[たか]い。", "sentence_source": "generated"}, {"text": "物価の安い国に住みたい。", "target_word": "物価", "complexity_tier": "T2", "furigana": "物価[ぶっか]の安[やす]い国[くに]に住[す]みたい。", "sentence_source": "generated"}, {"text": "今日は物価の話をしました。", "target_word": "物価", "complexity_tier": "T2", "furigana": "今日[きょう]は物価[ぶっか]の話[はなし]をしました。", "sentence_source": "generated"}, {"text": "この町の物価は安いです。", "target_word": "物価", "complexity_tier": "T2", "furigana": "この町[まち]の物価[ぶっか]は安[やす]いです。", "sentence_source": "generated"}, {"text": "高い物価のせいで、おかしを買えない。", "target_word": "物価", "complexity_tier": "T3", "furigana": "高[たか]い物価[ぶっか]のせいで、おかしを買[か]えない。", "sentence_source": "generated"}, {"text": "母は物価を気にしている。", "target_word": "物価", "complexity_tier": "T3", "furigana": "母[はは]は物価[ぶっか]を気[き]にしている。", "sentence_source": "generated"}, {"text": "旅行先の物価を調べておいた。", "target_word": "物価", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]の物価[ぶっか]を調[しら]べておいた。", "sentence_source": "generated"}, {"text": "物価が下がったら、もっと買い物ができるのに。", "target_word": "物価", "complexity_tier": "T4", "furigana": "物価[ぶっか]が下[さ]がったら、もっと買[か]い物[もの]ができるのに。", "sentence_source": "generated"}, {"text": "物価が上がるにつれて、お小遣いが足りなくなった。", "target_word": "物価", "complexity_tier": "T4", "furigana": "物価[ぶっか]が上[あ]がるにつれて、お小遣[こづか]いが足[た]りなくなった。", "sentence_source": "generated"}, {"text": "ニュースによると、来月は物価も少し上がるそうだ。", "target_word": "物価", "complexity_tier": "T5", "furigana": "ニュースによると、来月[らいげつ]は物価[ぶっか]も少[すこ]し上[あ]がるそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物価高", "label": "派生"}, {"form": "物価安", "label": "派生"}, {"form": "物価上昇", "label": "派生"}, {"form": "物価指数", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | お店で売る物の値段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52041, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物価", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "国家", "is_correct": false, "explanation": "「こっか」は「ぶ」が「こ」に変わった別の語。"}, {"text": "実家", "is_correct": false, "explanation": "「じっか」は「ぶ」が「じ」に変わった別の語。"}, {"text": "作家", "is_correct": false, "explanation": "「さっか」は「ぶ」が「さ」に変わった別の語。"}, {"text": "落下", "is_correct": false, "explanation": "「らっか」は「ぶ」が「ら」に変わった別の語。"}], "explanations": {"物価": "見出し語そのもの。", "国家": "「こっか」は「ぶ」が「こ」に変わった別の語。", "実家": "「じっか」は「ぶ」が「じ」に変わった別の語。", "作家": "「さっか」は「ぶ」が「さ」に変わった別の語。", "落下": "「らっか」は「ぶ」が「ら」に変わった別の語。"}, "sentence_index": null, "correct_answer": "物価"}, "level_3": {"options": [{"text": "物価", "is_correct": true, "explanation": "お店の値段が高いという意味で合う。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、「重さが高い」とは言わず意味が合わない。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが、「時間が高い」とは言わず意味が合わない。"}, {"text": "数量", "is_correct": false, "explanation": "形は合うが、「数量が高い」とは言わず意味が合わない。"}], "explanations": {"物価": "お店の値段が高いという意味で合う。", "重さ": "形は合うが、「重さが高い」とは言わず意味が合わない。", "時間": "形は合うが、「時間が高い」とは言わず意味が合わない。", "数量": "形は合うが、「数量が高い」とは言わず意味が合わない。"}, "sentence_index": 0, "correct_answer": "物価"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町の物価は赤いです。", "explanation": "物価は値段の水準であり、色を表す形容詞とは結びつかない。"}, {"text": "物価を食べました。", "explanation": "物価は食べ物ではないので「食べる」と結びつかない。"}, {"text": "物価は歩いて学校へ行きました。", "explanation": "物価は値段の水準で、歩く主体にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52041, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物価", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "日課", "is_correct": false, "explanation": "「にっか」は「ぶ」が「に」に変わった別の語。"}, {"text": "真っ赤", "is_correct": false, "explanation": "「まっか」は「ぶ」が「ま」に変わった別の語。"}, {"text": "薄荷", "is_correct": false, "explanation": "「はっか」は「ぶ」が「は」に変わった別の語。"}, {"text": "菊花", "is_correct": false, "explanation": "「きっか」は「ぶ」が「き」に変わった別の語。"}], "explanations": {"物価": "見出し語そのもの。", "日課": "「にっか」は「ぶ」が「に」に変わった別の語。", "真っ赤": "「まっか」は「ぶ」が「ま」に変わった別の語。", "薄荷": "「はっか」は「ぶ」が「は」に変わった別の語。", "菊花": "「きっか」は「ぶ」が「き」に変わった別の語。"}, "sentence_index": null, "correct_answer": "物価"}, "level_3": {"options": [{"text": "物価", "is_correct": true, "explanation": "旅行先の値段を調べるという意味で合う。"}, {"text": "歯", "is_correct": false, "explanation": "形は合うが、旅行先を調べる対象として意味が合わない。"}, {"text": "ズボン", "is_correct": false, "explanation": "形は合うが、「旅行先の」と調べる意味が合わない。"}, {"text": "あくび", "is_correct": false, "explanation": "形は合うが、旅行先で調べる対象として意味が合わない。"}], "explanations": {"物価": "旅行先の値段を調べるという意味で合う。", "歯": "形は合うが、旅行先を調べる対象として意味が合わない。", "ズボン": "形は合うが、「旅行先の」と調べる意味が合わない。", "あくび": "形は合うが、旅行先で調べる対象として意味が合わない。"}, "sentence_index": 6, "correct_answer": "物価"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ニュースによると、来月は物価も少し笑うそうだ。", "explanation": "物価は値段の水準で、「笑う」の主語にはならない。"}, {"text": "物価を履いて出かけた。", "explanation": "物価は履き物ではないので「履く」と結びつかない。"}, {"text": "来月は物価が大きく走るそうだ。", "explanation": "物価は走る主体ではなく、「走る」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warni