INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52042, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「〜と相乗効果を生む」で、一緒に効果を生む相手を表す。"}, {"text": "を", "is_correct": false, "explanation": "「圧力を相乗効果を」は「を」が重なり文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「圧力へ相乗効果を」は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「圧力に相乗効果を生み」は文法的に成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「〜と相乗効果を生む」で、一緒に効果を生む相手を表す。", "を": "「圧力を相乗効果を」は「を」が重なり文法的に成り立たない。", "へ": "「圧力へ相乗効果を」は文として成り立たない。", "に": "「圧力に相乗効果を生み」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "に": "target_or_location"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
