INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52042, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "商品やサービスの価格。一般的に、物価が上がると生活費が高くなる。", "primary_collocate": null, "pronunciation": "ぶっか", "ipa": "bɯkka", "syllable_count": 3, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "物価", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融政策[きんゆうせいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体経済[じったいけいざい]における物価上昇圧力[ぶっかじょうしょうあつりょく]と相乗効果[そうじょうこうか]を生[う]み、予期[よき]せぬスタグフレーションや財政主導[ざいせいしゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "物価が上がる。", "target_word": "物価", "complexity_tier": "T1", "furigana": "物価[ぶっか]が上[あ]がる。", "sentence_source": "generated"}, {"text": "物価は高いです。", "target_word": "物価", "complexity_tier": "T2", "furigana": "物価[ぶっか]は高[たか]いです。", "sentence_source": "generated"}, {"text": "最近は物価が下がりません。", "target_word": "物価", "complexity_tier": "T2", "furigana": "最近[さいきん]は物価[ぶっか]が下[さ]がりません。", "sentence_source": "generated"}, {"text": "物価の上昇で生活が苦しくなった。", "target_word": "物価", "complexity_tier": "T3", "furigana": "物価[ぶっか]の上昇[じょうしょう]で生活[せいかつ]が苦[くる]しくなった。", "sentence_source": "generated"}, {"text": "政府は物価を安定させようとしている。", "target_word": "物価", "complexity_tier": "T3", "furigana": "政府[せいふ]は物価[ぶっか]を安定[あんてい]させようとしている。", "sentence_source": "generated"}, {"text": "都市は地方より物価が高い。", "target_word": "物価", "complexity_tier": "T3", "furigana": "都市[とし]は地方[ちほう]より物価[ぶっか]が高[たか]い。", "sentence_source": "generated"}, {"text": "物価が上がれば、給料も上がるとは限らない。", "target_word": "物価", "complexity_tier": "T4", "furigana": "物価[ぶっか]が上[あ]がれば、給料[きゅうりょう]も上[あ]がるとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "海外から来た人は、日本の物価が安いと驚く。", "target_word": "物価", "complexity_tier": "T4", "furigana": "海外[かいがい]から来[き]た人[ひと]は、日本[にほん]の物価[ぶっか]が安[やす]いと驚[おどろ]く。", "sentence_source": "generated"}, {"text": "物価の変動を正しく測るために、専門家は多くの商品の値段を調べている。", "target_word": "物価", "complexity_tier": "T5", "furigana": "物価[ぶっか]の変動[へんどう]を正[ただ]しく測[はか]るために、専門家[せんもんか]は多[おお]くの商品[しょうひん]の値段[ねだん]を調[しら]べている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物価高", "label": "派生"}, {"form": "物価安", "label": "派生"}, {"form": "物価上昇", "label": "派生"}, {"form": "物価指数", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 商品やサービスの価格の全体的な水準", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: スタグフレーション (Zipf 1.93)']::text[], 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52042, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物価", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "国家", "is_correct": false, "explanation": "「こっか」は「ぶ」が「こ」に変わった別の語。"}, {"text": "実家", "is_correct": false, "explanation": "「じっか」は「ぶ」が「じ」に変わった別の語。"}, {"text": "作家", "is_correct": false, "explanation": "「さっか」は「ぶ」が「さ」に変わった別の語。"}, {"text": "落下", "is_correct": false, "explanation": "「らっか」は「ぶ」が「ら」に変わった別の語。"}], "explanations": {"物価": "見出し語そのもの。", "国家": "「こっか」は「ぶ」が「こ」に変わった別の語。", "実家": "「じっか」は「ぶ」が「じ」に変わった別の語。", "作家": "「さっか」は「ぶ」が「さ」に変わった別の語。", "落下": "「らっか」は「ぶ」が「ら」に変わった別の語。"}, "sentence_index": null, "correct_answer": "物価"}, "level_3": {"options": [{"text": "物価", "is_correct": true, "explanation": "「物価上昇圧力」という経済用語として文脈に合う。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、金融政策の文脈では意味が合わない。"}, {"text": "体重", "is_correct": false, "explanation": "形は合うが、実体経済の圧力という意味が合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、「上昇圧力」の経済的な意味が合わない。"}], "explanations": {"物価": "「物価上昇圧力」という経済用語として文脈に合う。", "気温": "形は合うが、金融政策の文脈では意味が合わない。", "体重": "形は合うが、実体経済の圧力という意味が合わない。", "湿度": "形は合うが、「上昇圧力」の経済的な意味が合わない。"}, "sentence_index": 0, "correct_answer": "物価"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は物価を食べて、元気になった。", "explanation": "物価は値段の水準であり、食べ物ではないので誤り。"}, {"text": "昨日、友だちが物価に乗って学校へ行った。", "explanation": "物価は乗り物ではないので「乗る」と結びつかない。"}, {"text": "この店の物価は赤くて、とても大きい。", "explanation": "物価は値段の水準で、色や大きさを持つ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52042, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物価", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "日課", "is_correct": false, "explanation": "「にっか」は「ぶ」が「に」に変わった別の語。"}, {"text": "真っ赤", "is_correct": false, "explanation": "「まっか」は「ぶ」が「ま」に変わった別の語。"}, {"text": "薄荷", "is_correct": false, "explanation": "「はっか」は「ぶ」が「は」に変わった別の語。"}, {"text": "菊花", "is_correct": false, "explanation": "「きっか」は「ぶ」が「き」に変わった別の語。"}], "explanations": {"物価": "見出し語そのもの。", "日課": "「にっか」は「ぶ」が「に」に変わった別の語。", "真っ赤": "「まっか」は「ぶ」が「ま」に変わった別の語。", "薄荷": "「はっか」は「ぶ」が「は」に変わった別の語。", "菊花": "「きっか」は「ぶ」が「き」に変わった別の語。"}, "sentence_index": null, "correct_answer": "物価"}, "level_3": {"options": [{"text": "物価", "is_correct": true, "explanation": "都市と地方の値段の水準を比べる文脈に合う。"}, {"text": "面積", "is_correct": false, "explanation": "形は合うが、「高い」とは意味が合わない。"}, {"text": "歴史", "is_correct": false, "explanation": "形は合うが、「歴史が高い」とは言わず意味が合わない。"}, {"text": "体重", "is_correct": false, "explanation": "形は合うが、「体重が高い」とは言わず意味が合わない。"}], "explanations": {"物価": "都市と地方の値段の水準を比べる文脈に合う。", "面積": "形は合うが、「高い」とは意味が合わない。", "歴史": "形は合うが、「歴史が高い」とは言わず意味が合わない。", "体重": "形は合うが、「体重が高い」とは言わず意味が合わない。"}, "sentence_index": 6, "correct_answer": "物価"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "専門家は物価の味を調べて、おいしいと言った。", "explanation": "物価は値段の水準で、味を調べる対象ではないので誤り。"}, {"text": "物価を着て出かけると、寒くない。", "explanation": "物価は衣服ではないので「着る」と結びつかない。"}, {"text": "物価が昨日、私に電話をかけてきた。", "explanation": "物価は抽象的な水準で、電話をかける主体にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_war