INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52043, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金の値打ちが上がったり下がったりして、モノの値段が上がるのと、仕事が減ってみんながこまるのが、いっしょにおこること。", "primary_collocate": null, "pronunciation": "すたぐふれーしょん", "ipa": "sɯtaɡɯɸɯɾeːɕoɴ", "syllable_count": 8, "sentences": [{"text": "スタグフレーションが怖い。", "target_word": "スタグフレーション", "complexity_tier": "T2", "furigana": "スタグフレーションが怖[こわ]い。", "sentence_source": "generated"}, {"text": "スタグフレーションは大変です。", "target_word": "スタグフレーション", "complexity_tier": "T2", "furigana": "スタグフレーションは大変[たいへん]です。", "sentence_source": "generated"}, {"text": "スタグフレーションが起きました。", "target_word": "スタグフレーション", "complexity_tier": "T2", "furigana": "スタグフレーションが起[お]きました。", "sentence_source": "generated"}, {"text": "スタグフレーションで仕事が減っている。", "target_word": "スタグフレーション", "complexity_tier": "T3", "furigana": "スタグフレーションで仕事[しごと]が減[へ]っている。", "sentence_source": "generated"}, {"text": "先生がスタグフレーションを説明した。", "target_word": "スタグフレーション", "complexity_tier": "T3", "furigana": "先生[せんせい]がスタグフレーションを説明[せつめい]した。", "sentence_source": "generated"}, {"text": "スタグフレーションの話はむずかしい。", "target_word": "スタグフレーション", "complexity_tier": "T3", "furigana": "スタグフレーションの話[はなし]はむずかしい。", "sentence_source": "generated"}, {"text": "スタグフレーションになると、物の値段が上がる。", "target_word": "スタグフレーション", "complexity_tier": "T4", "furigana": "スタグフレーションになると、物[もの]の値段[ねだん]が上[あ]がる。", "sentence_source": "generated"}, {"text": "スタグフレーションが起きたら、みんなが困るだろう。", "target_word": "スタグフレーション", "complexity_tier": "T4", "furigana": "スタグフレーションが起[お]きたら、みんなが困[こま]るだろう。", "sentence_source": "generated"}, {"text": "スタグフレーションのせいで、給料は増えないのに、物は高くなった。", "target_word": "スタグフレーション", "complexity_tier": "T5", "furigana": "スタグフレーションのせいで、給料[きゅうりょう]は増[ふ]えないのに、物[もの]は高[たか]くなった。", "sentence_source": "generated"}, {"text": "昔、石油が高くなって、世界がスタグフレーションになったと習った。", "target_word": "スタグフレーション", "complexity_tier": "T5", "furigana": "昔[むかし]、石油[せきゆ]が高[たか]くなって、世界[せかい]がスタグフレーションになったと習[なら]った。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 物価高と不況が一緒に起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52043, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スタグフレーション", "is_correct": true, "explanation": "物価高と不況が一緒に起こることで、「怖い」に合う。"}, {"text": "貯金", "is_correct": false, "explanation": "形は合うが意味が合わない。貯金は怖がる対象として不自然。"}, {"text": "黒字", "is_correct": false, "explanation": "形は合うが意味が合わない。黒字を怖いと言う文脈ではない。"}, {"text": "割引", "is_correct": false, "explanation": "形は合うが意味が合わない。割引が怖いという意味は通らない。"}], "explanations": {"スタグフレーション": "物価高と不況が一緒に起こることで、「怖い」に合う。", "貯金": "形は合うが意味が合わない。貯金は怖がる対象として不自然。", "黒字": "形は合うが意味が合わない。黒字を怖いと言う文脈ではない。", "割引": "形は合うが意味が合わない。割引が怖いという意味は通らない。"}, "sentence_index": 0, "correct_answer": "スタグフレーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スタグフレーションで物の値段が下がり、みんなが喜んでいる。", "explanation": "スタグフレーションは値段が上がって困ることなので、値段が下がって喜ぶは誤り。"}, {"text": "スタグフレーションは、おいしいパンの名前です。", "explanation": "経済の出来事を食べ物の名前として使っており、意味が誤り。"}, {"text": "スタグフレーションを開けて、中に入った。", "explanation": "出来事であり開ける物ではないので、「開ける」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52043, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スタグフレーション", "is_correct": true, "explanation": "物価高と不況が一緒に起こる状態で、値段が上がる結果に合う。"}, {"text": "デフレ", "is_correct": false, "explanation": "形は合うが意味が合わない。デフレでは値段が下がる。"}, {"text": "豊作", "is_correct": false, "explanation": "形は合うが意味が合わない。豊作では普通、値段が下がる。"}, {"text": "値下げ", "is_correct": false, "explanation": "形は合うが意味が合わない。値下げは値段が下がることで矛盾する。"}], "explanations": {"スタグフレーション": "物価高と不況が一緒に起こる状態で、値段が上がる結果に合う。", "デフレ": "形は合うが意味が合わない。デフレでは値段が下がる。", "豊作": "形は合うが意味が合わない。豊作では普通、値段が下がる。", "値下げ": "形は合うが意味が合わない。値下げは値段が下がることで矛盾する。"}, "sentence_index": 6, "correct_answer": "スタグフレーション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スタグフレーションは、きれいな花がたくさん咲くことだ。", "explanation": "経済の出来事を花が咲くことの意味で使っており、誤り。"}, {"text": "昔、世界がスタグフレーションを飲んだと習った。", "explanation": "抽象的な出来事は飲むものではないので、「飲む」との組み合わせは誤り。"}, {"text": "スタグフレーションのおかげで、給料が増えて、みんなが喜んだ。", "explanation": "スタグフレーションは物価が上がり景気が悪くなって困ることなので、給料が増えて喜ぶ原因にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
