INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52044, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物価が上昇するインフレと、経済活動が停滞する不況が同時に発生する状態。", "primary_collocate": null, "pronunciation": "すたぐふれーしょん", "ipa": "sɯtaɡɯɸɯɾeːɕoɴ", "syllable_count": 8, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "スタグフレーション", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融政策[きんゆうせいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体経済[じったいけいざい]における物価上昇圧力[ぶっかじょうしょうあつりょく]と相乗効果[そうじょうこうか]を生[う]み、予期[よき]せぬスタグフレーションや財政主導[ざいせいしゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "スタグフレーションが心配です。", "target_word": "スタグフレーション", "complexity_tier": "T2", "furigana": "スタグフレーションが心配[しんぱい]です。", "sentence_source": "generated"}, {"text": "スタグフレーションが懸念されます。", "target_word": "スタグフレーション", "complexity_tier": "T2", "furigana": "スタグフレーションが懸念[けねん]されます。", "sentence_source": "generated"}, {"text": "スタグフレーションの影響を受けている。", "target_word": "スタグフレーション", "complexity_tier": "T3", "furigana": "スタグフレーションの影響[えいきょう]を受[う]けている。", "sentence_source": "generated"}, {"text": "スタグフレーションで失業が増えている。", "target_word": "スタグフレーション", "complexity_tier": "T3", "furigana": "スタグフレーションで失業[しつぎょう]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "石油危機はスタグフレーションを招いた。", "target_word": "スタグフレーション", "complexity_tier": "T3", "furigana": "石油危機[せきゆきき]はスタグフレーションを招[まね]いた。", "sentence_source": "generated"}, {"text": "景気が悪いのに物価が上がるのは、スタグフレーションだ。", "target_word": "スタグフレーション", "complexity_tier": "T4", "furigana": "景気[けいき]が悪[わる]いのに物価[ぶっか]が上[あ]がるのは、スタグフレーションだ。", "sentence_source": "generated"}, {"text": "スタグフレーションが長引けば、家計は苦しくなるだろう。", "target_word": "スタグフレーション", "complexity_tier": "T4", "furigana": "スタグフレーションが長引[ながび]けば、家計[かけい]は苦[くる]しくなるだろう。", "sentence_source": "generated"}, {"text": "一九七〇年代には、多くの国がスタグフレーションに苦しんだ。", "target_word": "スタグフレーション", "complexity_tier": "T5", "furigana": "一九七〇年代[せんきゅうひゃくななじゅうねんだい]には、多[おお]くの国[くに]がスタグフレーションに苦[くる]しんだ。", "sentence_source": "generated"}, {"text": "政府はスタグフレーションを避けるため、慎重に金利を調整している。", "target_word": "スタグフレーション", "complexity_tier": "T5", "furigana": "政府[せいふ]はスタグフレーションを避[さ]けるため、慎重[しんちょう]に金利[きんり]を調整[ちょうせい]している。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 物価高と不況が同時に起こる状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52044, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スタグフレーション", "is_correct": true, "explanation": "物価上昇と不況が同時に起こる状態で、文脈に合う。"}, {"text": "アンカー", "is_correct": false, "explanation": "形は合うが意味が合わない。「予期せぬアンカー」ではリスクの帰結にならない。"}, {"text": "プレミアム", "is_correct": false, "explanation": "形は合うが意味が合わない。「予期せぬプレミアム」がシナリオへ帰結するリスクは文意に合わない。"}, {"text": "メカニズム", "is_correct": false, "explanation": "形は合うが意味が合わない。仕組みが予期せぬ経済状態を表すことはない。"}], "explanations": {"スタグフレーション": "物価上昇と不況が同時に起こる状態で、文脈に合う。", "アンカー": "形は合うが意味が合わない。「予期せぬアンカー」ではリスクの帰結にならない。", "プレミアム": "形は合うが意味が合わない。「予期せぬプレミアム」がシナリオへ帰結するリスクは文意に合わない。", "メカニズム": "形は合うが意味が合わない。仕組みが予期せぬ経済状態を表すことはない。"}, "sentence_index": 0, "correct_answer": "スタグフレーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スタグフレーションは、物価が下がり続ける状態のことだ。", "explanation": "スタグフレーションは物価上昇を伴う状態で、物価が下がるという意味の使い方は誤り。"}, {"text": "スタグフレーションを食べて、昼ご飯にした。", "explanation": "スタグフレーションは経済状態を表す抽象名詞で、食べる対象にはならない。"}, {"text": "私はスタグフレーションに乗って、駅まで行った。", "explanation": "経済状態であり乗り物ではないので、「乗る」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52044, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スタグフレーション", "is_correct": true, "explanation": "不況なのに物価が上がる状態を指し、文に合う。"}, {"text": "デフレ", "is_correct": false, "explanation": "形は合うが意味が合わない。デフレは物価が下がる状態。"}, {"text": "好景気", "is_correct": false, "explanation": "形は合うが意味が合わない。景気が悪い状況と矛盾する。"}, {"text": "黒字", "is_correct": false, "explanation": "形は合うが意味が合わない。物価上昇を説明する語ではない。"}], "explanations": {"スタグフレーション": "不況なのに物価が上がる状態を指し、文に合う。", "デフレ": "形は合うが意味が合わない。デフレは物価が下がる状態。", "好景気": "形は合うが意味が合わない。景気が悪い状況と矛盾する。", "黒字": "形は合うが意味が合わない。物価上昇を説明する語ではない。"}, "sentence_index": 6, "correct_answer": "スタグフレーション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "デフレで物価が下がる現象を、スタグフレーションと呼ぶ。", "explanation": "スタグフレーションは物価上昇と不況の併発で、物価下落の現象ではない。"}, {"text": "スタグフレーションは、とても長い橋の名前だ。", "explanation": "経済用語を橋の名前として使っており、意味が誤り。"}, {"text": "彼はスタグフレーションを着て、会議に出た。", "explanation": "抽象的な経済状態は着るものではないので、「着る」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52044, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "七〇年代の日本はスタグフレーションを苦しんだ。", "corrected_sentence": "七〇年代の日本はスタグフレーションに苦しんだ。", "error_description": "「苦しむ」は苦しみの原因を「に」で示すので、「スタグフレーションに苦しんだ」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52044, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "景気が良いのに物価が上がる状態を、スタグフレーションと呼ぶ。", "corrected_sentence": "景気が悪いのに物価が上がる状態を、スタグフレーションと呼ぶ。", "error_description": "スタグフレーションは不況下の物価上昇なので、「景気が良い」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52045, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「出す」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「シグナルに出しました」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「出す」の目的語を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「先生が」と重なり、「シグナルが出しました」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「出す」の目的語を示す。", "に": "「シグナルに出しました」は文として成り立たない。", "へ": "方向の「へ」は「出す」の目的語を示せない。", "が": "「先生が」と重なり、「シグナルが出しました」は文として成り立たない。"}, "error_tags": {"に": "target_marker", "へ": "direction", "が": "subject_marker"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52045, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「病気のシグナル」で、何を知らせる合図かを示す。"}, {"text": "を", "is_correct": false, "explanation": "「病気をシグナルかもしれない」は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「病気にシグナルかもしれない」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「病気がシグナルかもしれない」は「〜のは」と合わず、文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「病気のシグナル」で、何を知らせる合図かを示す。", "を": "「病気をシグナルかもしれない」は文として成り立たない。", "に": "「病気にシグナルかもしれない」は文として成り立たない。", "が": "「病気がシグナルかもしれない」は「〜のは」と合わず、文として成り立たない。"}, "error_tags": {"を": "object_marker", "に": "target_marker", "が": "subject_marker"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52045, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起きることを知らせる合図。", "primary_collocate": null, "pronunciation": "しぐなる", "ipa": "ɕiɡɯnaɾɯ", "syllable_count": 4, "sentences": [{"text": "シグナルを送る。", "target_word": "シグナル", "complexity_tier": "T1", "furigana": "シグナルを送[おく]る。", "sentence_source": "generated"}, {"text": "シグナルが来た。", "target_word": "シグナル", "complexity_tier": "T1", "furigana": "シグナルが来[き]た。", "sentence_source": "generated"}, {"text": "先生がシグナルを出しました。", "target_word": "シグナル", "complexity_tier": "T2", "furigana": "先生[せんせい]がシグナルを出[だ]しました。", "sentence_source": "generated"}, {"text": "光はシグナルです。", "target_word": "シグナル", "complexity_tier": "T2", "furigana": "光[ひかり]はシグナルです。", "sentence_source": "generated"}, {"text": "犬のしっぽは気持ちのシグナルだ。", "target_word": "シグナル", "complexity_tier": "T3", "furigana": "犬[いぬ]のしっぽは気持[きも]ちのシグナルだ。", "sentence_source": "generated"}, {"text": "赤いランプが危険のシグナルになる。", "target_word": "シグナル", "complexity_tier": "T3", "furigana": "赤[あか]いランプが危険[きけん]のシグナルになる。", "sentence_source": "generated"}, {"text": "体のシグナルを無視してはいけない。", "target_word": "シグナル", "complexity_tier": "T3", "furigana": "体[からだ]のシグナルを無視[むし]してはいけない。", "sentence_source": "generated"}, {"text": "咳が止まらないのは、病気のシグナルかもしれない。", "target_word": "シグナル", "complexity_tier": "T4", "furigana": "咳[せき]が止[と]まらないのは、病気[びょうき]のシグナルかもしれない。", "sentence_source": "generated"}, {"text": "シグナルに気づいたら、すぐに連絡してください。", "target_word": "シグナル", "complexity_tier": "T4", "furigana": "シグナルに気[き]づいたら、すぐに連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "山の上から見張りが煙でシグナルを送ると、村の人たちは集まった。", "target_word": "シグナル", "complexity_tier": "T5", "furigana": "山[やま]の上[うえ]から見張[みは]りが煙[けむり]でシグナルを送[おく]ると、村[むら]の人[ひと]たちは集[あつ]まった。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 何かが起きると知らせる合図", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52045, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シグナル", "is_correct": true, "explanation": "何かを知らせる合図で、「送る」と自然に結びつく。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は送るものではない。"}, {"text": "背中", "is_correct": false, "explanation": "形は合うが意味が合わない。背中を送るとは言わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "形は合うが意味が合わない。昼寝は送るものではない。"}], "explanations": {"シグナル": "何かを知らせる合図で、「送る」と自然に結びつく。", "天気": "形は合うが意味が合わない。天気は送るものではない。", "背中": "形は合うが意味が合わない。背中を送るとは言わない。", "昼寝": "形は合うが意味が合わない。昼寝は送るものではない。"}, "sentence_index": 0, "correct_answer": "シグナル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "シグナルは、冷たくておいしい飲み物です。", "explanation": "シグナルは合図で、飲み物ではない。"}, {"text": "私はシグナルを着て学校へ行きます。", "explanation": "合図は着るものではないので、「着る」との組み合わせは誤り。"}, {"text": "シグナルを植えたら、きれいな花が咲いた。", "explanation": "合図は植えるものではないので、「植える」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52045, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シグナル", "is_correct": true, "explanation": "体が発する知らせの意味で、「無視する」に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。体の机は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。体の天気という言い方は通らない。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが意味が合わない。体の帽子は意味が通らない。"}], "explanations": {"シグナル": "体が発する知らせの意味で、「無視する」に合う。", "机": "形は合うが意味が合わない。体の机は意味が通らない。", "天気": "形は合うが意味が合わない。体の天気という言い方は通らない。", "帽子": "形は合うが意味が合わない。体の帽子は意味が通らない。"}, "sentence_index": 6, "correct_answer": "シグナル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山の上から見張りが煙でシグナルを食べると、村の人たちは集まった。", "explanation": "合図は食べるものではないので、「食べる」との組み合わせは誤り。"}, {"text": "山の上から見張りが煙でシグナルを植えると、村の人たちは集まった。", "explanation": "合図は植えるものではないので、「植える」との組み合わせは誤り。"}, {"text": "見張りが煙でシグナルを着ると、村の人たちは集まった。", "explanation": "合図は着るものではないので、「着る」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52045, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生が教室でシグナルに出しました。", "corrected_sentence": "先生が教室でシグナルを出しました。", "error_description": "「出す」の対象はシグナルなので、「に」ではなく「を」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
