INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52046, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "情報や指示を伝えるための合図や兆し。特に、経済や金融の分野で、将来の動きを示す手がかり。", "primary_collocate": null, "pronunciation": "しぐなる", "ipa": "ɕiɡɯnaɾɯ", "syllable_count": 4, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "シグナル", "complexity_tier": "T6", "furigana": "イールドカーブ・コントロールの下[もと]では、市場[しじょう]メカニズムを通[つう]じた適正[てきせい]なリスクプレミアムの形成[けいせい]が阻害[そがい]され、結果[けっか]として財政[ざいせい]の持続可能性[じぞくかのうせい]を担保[たんぽ]するべき債務[さいむ]の価格的[かかくてき]シグナルが鈍磨[どんま]する懸念[けねん]が拭[ぬぐ]えない。", "sentence_source": "mined"}, {"text": "シグナルが出た。", "target_word": "シグナル", "complexity_tier": "T1", "furigana": "シグナルが出[で]た。", "sentence_source": "generated"}, {"text": "これは良いシグナルです。", "target_word": "シグナル", "complexity_tier": "T2", "furigana": "これは良[よ]いシグナルです。", "sentence_source": "generated"}, {"text": "市場にシグナルを送りました。", "target_word": "シグナル", "complexity_tier": "T2", "furigana": "市場[しじょう]にシグナルを送[おく]りました。", "sentence_source": "generated"}, {"text": "金利の動きは重要なシグナルだ。", "target_word": "シグナル", "complexity_tier": "T3", "furigana": "金利[きんり]の動[うご]きは重要[じゅうよう]なシグナルだ。", "sentence_source": "generated"}, {"text": "投資家はそのシグナルを読み取った。", "target_word": "シグナル", "complexity_tier": "T3", "furigana": "投資家[とうしか]はそのシグナルを読[よ]み取[と]った。", "sentence_source": "generated"}, {"text": "シグナルは必ずしも正しくない。", "target_word": "シグナル", "complexity_tier": "T3", "furigana": "シグナルは必[かなら]ずしも正[ただ]しくない。", "sentence_source": "generated"}, {"text": "中央銀行の発言が、利上げのシグナルとして受け取られた。", "target_word": "シグナル", "complexity_tier": "T4", "furigana": "中央銀行[ちゅうおうぎんこう]の発言[はつげん]が、利上[りあ]げのシグナルとして受[う]け取[と]られた。", "sentence_source": "generated"}, {"text": "弱いシグナルを見逃すと、判断を誤りかねない。", "target_word": "シグナル", "complexity_tier": "T4", "furigana": "弱[よわ]いシグナルを見逃[みのが]すと、判断[はんだん]を誤[あやま]りかねない。", "sentence_source": "generated"}, {"text": "景気後退のシグナルが複数そろったため、企業は投資を慎重に見直し始めた。", "target_word": "シグナル", "complexity_tier": "T5", "furigana": "景気後退[けいきこうたい]のシグナルが複数[ふくすう]そろったため、企業[きぎょう]は投資[とうし]を慎重[しんちょう]に見直[みなお]し始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 将来の動きを示す合図や兆し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bceace8b-1bcf-4089-a741-bd92f5882128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52046, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シグナル", "is_correct": true, "explanation": "将来の動きを示す兆しの意味で、価格的な指標として文に合う。"}, {"text": "ブランド", "is_correct": false, "explanation": "形は合うが意味が合わない。債務の価格的ブランドが鈍磨するとは言えない。"}, {"text": "エネルギー", "is_correct": false, "explanation": "形は合うが意味が合わない。価格の情報を伝える意味にならない。"}, {"text": "ユーモア", "is_correct": false, "explanation": "形は合うが意味が合わない。金融の文脈に合わない。"}], "explanations": {"シグナル": "将来の動きを示す兆しの意味で、価格的な指標として文に合う。", "ブランド": "形は合うが意味が合わない。債務の価格的ブランドが鈍磨するとは言えない。", "エネルギー": "形は合うが意味が合わない。価格の情報を伝える意味にならない。", "ユーモア": "形は合うが意味が合わない。金融の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "シグナル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "投資家はシグナルを食べました。", "explanation": "シグナルは合図や兆しで、食べるものではない。"}, {"text": "シグナルを塗って、壁をきれいにした。", "explanation": "シグナルは塗料のような物ではなく、「塗る」との組み合わせは誤り。"}, {"text": "彼はシグナルに座って昼食を取った。", "explanation": "シグナルは座る場所を表さない。抽象的な合図の意味から外れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52046, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シグナル", "is_correct": true, "explanation": "兆しや合図は必ずしも正確でないので、文に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。机が正しくないとは言わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は正しい・正しくないで評価しない。"}, {"text": "傘", "is_correct": false, "explanation": "形は合うが意味が合わない。傘が正しくないとは通常言わない。"}], "explanations": {"シグナル": "兆しや合図は必ずしも正確でないので、文に合う。", "机": "形は合うが意味が合わない。机が正しくないとは言わない。", "天気": "形は合うが意味が合わない。天気は正しい・正しくないで評価しない。", "傘": "形は合うが意味が合わない。傘が正しくないとは通常言わない。"}, "sentence_index": 6, "correct_answer": "シグナル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "シグナルは、銀行の建物の高さを表す単位だ。", "explanation": "シグナルは兆しや合図で、長さや高さの単位ではない。"}, {"text": "景気後退のシグナルを洗ったので、きれいになった。", "explanation": "抽象的な兆しは洗えないので、「洗う」との組み合わせは誤り。"}, {"text": "企業は景気後退のシグナルをかぶって、会議に出た。", "explanation": "兆しは身につける物ではないので、「かぶる」との組み合わせは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77b1bc88-cc20-42f9-8586-1e187fd539fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
