INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52047, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「物語」と「シナリオ」を結ぶ連体の助詞。"}, {"text": "を", "is_correct": false, "explanation": "「この物語をシナリオは」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「この物語へシナリオは」は成り立たない。"}, {"text": "ので", "is_correct": false, "explanation": "理由の「ので」は名詞どうしを結べない。"}], "correct_answer": "の", "explanations": {"の": "「物語」と「シナリオ」を結ぶ連体の助詞。", "を": "「この物語をシナリオは」は成り立たない。", "へ": "「この物語へシナリオは」は成り立たない。", "ので": "理由の「ので」は名詞どうしを結べない。"}, "error_tags": {"を": "wrong_case", "へ": "direction", "ので": "reason"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52047, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "映画・劇・ゲームなどの筋書きを書いたもの。台本。", "primary_collocate": null, "pronunciation": "しなりお", "ipa": "ɕinaɾio", "syllable_count": 4, "sentences": [{"text": "シナリオを読みます。", "target_word": "シナリオ", "complexity_tier": "T2", "furigana": "シナリオを読[よ]みます。", "sentence_source": "generated"}, {"text": "このシナリオはおもしろいです。", "target_word": "シナリオ", "complexity_tier": "T2", "furigana": "このシナリオはおもしろいです。", "sentence_source": "generated"}, {"text": "映画のシナリオを書いた。", "target_word": "シナリオ", "complexity_tier": "T2", "furigana": "映画[えいが]のシナリオを書[か]いた。", "sentence_source": "generated"}, {"text": "シナリオが長すぎて、覚えられない。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "シナリオが長[なが]すぎて、覚[おぼ]えられない。", "sentence_source": "generated"}, {"text": "先生は劇のシナリオを作っている。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "先生[せんせい]は劇[げき]のシナリオを作[つく]っている。", "sentence_source": "generated"}, {"text": "友だちとシナリオを考えて、ゲームを作った。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "友[とも]だちとシナリオを考[かんが]えて、ゲームを作[つく]った。", "sentence_source": "generated"}, {"text": "話の終わりがシナリオと違っていた。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "話[はなし]の終[お]わりがシナリオと違[ちが]っていた。", "sentence_source": "generated"}, {"text": "この物語のシナリオは、誰が書いたのですか。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "この物語[ものがたり]のシナリオは、誰[だれ]が書[か]いたのですか。", "sentence_source": "generated"}, {"text": "シナリオを変えれば、結末も変わるだろう。", "target_word": "シナリオ", "complexity_tier": "T4", "furigana": "シナリオを変[か]えれば、結末[けつまつ]も変[か]わるだろう。", "sentence_source": "generated"}, {"text": "もしシナリオが悪ければ、客は来ない。", "target_word": "シナリオ", "complexity_tier": "T4", "furigana": "もしシナリオが悪[わる]ければ、客[きゃく]は来[こ]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シナリオ通り", "label": "派生"}, {"form": "シナリオライター", "label": "派生"}, {"form": "シナリオ作家", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 映画や劇の脚本・台本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52047, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シナリオ", "is_correct": true, "explanation": "読む対象としての筋書きで意味が合う。"}, {"text": "雨", "is_correct": false, "explanation": "形は合うが、雨を読むとは意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、靴を読むとは意味が合わない。"}, {"text": "窓", "is_correct": false, "explanation": "形は合うが、窓を読むとは意味が合わない。"}], "explanations": {"シナリオ": "読む対象としての筋書きで意味が合う。", "雨": "形は合うが、雨を読むとは意味が合わない。", "靴": "形は合うが、靴を読むとは意味が合わない。", "窓": "形は合うが、窓を読むとは意味が合わない。"}, "sentence_index": 0, "correct_answer": "シナリオ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "シナリオを飲んだら、のどが痛くなった。", "explanation": "シナリオは話の筋書きで、飲む物ではない。"}, {"text": "シナリオは五月に東京へ引っ越した。", "explanation": "シナリオは人ではないので、引っ越しの主体にならない。"}, {"text": "このシナリオはとても熱いので、手でさわれない。", "explanation": "シナリオは話の流れで、温度を持つ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
