INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52048, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "将来の出来事や状況についての、予想される展開や筋書き。", "primary_collocate": null, "pronunciation": "しなりお", "ipa": "ɕinaɾio", "syllable_count": 4, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "シナリオ", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融[きんゆう]政策[せいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体[じったい]経済[けいざい]における物価[ぶっか]上昇[じょうしょう]圧力[あつりょく]と相乗[そうじょう]効果[こうか]を生[う]み、予期[よき]せぬスタグフレーションや財政[ざいせい]主導[しゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "最悪のシナリオを考えます。", "target_word": "シナリオ", "complexity_tier": "T2", "furigana": "最悪[さいあく]のシナリオを考[かんが]えます。", "sentence_source": "generated"}, {"text": "シナリオが変わるかもしれない。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "シナリオが変[か]わるかもしれない。", "sentence_source": "generated"}, {"text": "その会社は三つのシナリオを用意した。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は三[みっ]つのシナリオを用意[ようい]した。", "sentence_source": "generated"}, {"text": "このシナリオでは、物価は下がる。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "このシナリオでは、物価[ぶっか]は下[さ]がる。", "sentence_source": "generated"}, {"text": "専門家は最悪のシナリオを恐れている。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は最悪[さいあく]のシナリオを恐[おそ]れている。", "sentence_source": "generated"}, {"text": "シナリオの違いで、結果は大きく変わる。", "target_word": "シナリオ", "complexity_tier": "T3", "furigana": "シナリオの違[ちが]いで、結果[けっか]は大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "政府は楽観的なシナリオに基づいて予算を組んだ。", "target_word": "シナリオ", "complexity_tier": "T4", "furigana": "政府[せいふ]は楽観的[らっかんてき]なシナリオに基[もと]づいて予算[よさん]を組[く]んだ。", "sentence_source": "generated"}, {"text": "景気が回復するシナリオが現実になった。", "target_word": "シナリオ", "complexity_tier": "T4", "furigana": "景気[けいき]が回復[かいふく]するシナリオが現実[げんじつ]になった。", "sentence_source": "generated"}, {"text": "もし金利が急に上がれば、別のシナリオが必要になる。", "target_word": "シナリオ", "complexity_tier": "T4", "furigana": "もし金利[きんり]が急[きゅう]に上[あ]がれば、別[べつ]のシナリオが必要[ひつよう]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シナリオ通り", "label": "派生"}, {"form": "シナリオ分析", "label": "派生"}, {"form": "シナリオ作成", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 将来の展開を予想した筋書き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: スタグフレーション (Zipf 1.93)']::text[], '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52048, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シナリオ", "is_correct": true, "explanation": "財政主導の筋書きへ帰結するという意味で文脈に合う。"}, {"text": "野菜", "is_correct": false, "explanation": "名詞だが、「財政主導の野菜へと帰結する」は意味が合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、金融政策の帰結として意味が合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、リスクの帰結先として意味が合わない。"}], "explanations": {"シナリオ": "財政主導の筋書きへ帰結するという意味で文脈に合う。", "野菜": "名詞だが、「財政主導の野菜へと帰結する」は意味が合わない。", "帽子": "形は合うが、金融政策の帰結として意味が合わない。", "鉛筆": "形は合うが、リスクの帰結先として意味が合わない。"}, "sentence_index": 0, "correct_answer": "シナリオ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "シナリオは東京から大阪まで新幹線で二時間かかる。", "explanation": "シナリオは筋書きで、移動して時間がかかるものではない。"}, {"text": "彼は朝ごはんにシナリオを食べて、元気になった。", "explanation": "シナリオは抽象的な筋書きなので、食べるものとして使えない。"}, {"text": "きれいなシナリオが空に浮かんでいる。", "explanation": "シナリオは予想される展開で、空に浮かぶ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52048, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シナリオ", "is_correct": true, "explanation": "想定の違いで結果が変わるという意味に合う。"}, {"text": "窓", "is_correct": false, "explanation": "形は合うが、窓の違いで結果が大きく変わるとは意味が合わない。"}, {"text": "卵", "is_correct": false, "explanation": "形は合うが、結果を左右する想定として意味が合わない。"}, {"text": "星", "is_correct": false, "explanation": "形は合うが、文脈に意味が合わない。"}], "explanations": {"シナリオ": "想定の違いで結果が変わるという意味に合う。", "窓": "形は合うが、窓の違いで結果が大きく変わるとは意味が合わない。", "卵": "形は合うが、結果を左右する想定として意味が合わない。", "星": "形は合うが、文脈に意味が合わない。"}, "sentence_index": 6, "correct_answer": "シナリオ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "シナリオを洗って、庭に干した。", "explanation": "シナリオは抽象的な筋書きで、洗って干す物ではない。"}, {"text": "金利のシナリオが学校へ走って行った。", "explanation": "シナリオは展開の予想で、走る主体にならない。"}, {"text": "このシナリオは三階建てで、広い庭がある。", "explanation": "シナリオは建物ではないので、階数や庭を持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52048, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その会社は来年のシナリオを食べた。", "corrected_sentence": "その会社は来年のシナリオを描いた。", "error_description": "シナリオは「食べる」の目的語にならない。「描く」「用意する」などが自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52048, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "専門家は景気が悪くなるシナリオが備えている。", "corrected_sentence": "専門家は景気が悪くなるシナリオに備えている。", "error_description": "「備える」の対象は「に」で示す。「シナリオが」ではシナリオが備える主体になり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
