INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52049, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても冷たい気持ちで、感情に流されずに考えること。", "primary_collocate": null, "pronunciation": "れいてつ", "ipa": "ɾeːtetsɯ", "syllable_count": 4, "sentences": [{"text": "社長は冷徹な判断で、赤字の店を閉めることにした。", "target_word": "冷徹な", "complexity_tier": "T4", "furigana": "社長[しゃちょう]は冷徹[れいてつ]な判断[はんだん]で、赤字[あかじ]の店[みせ]を閉[し]めることにした。", "sentence_source": "generated"}, {"text": "彼女は冷徹な目で、状況を見つめていた。", "target_word": "冷徹な", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は冷徹[れいてつ]な目[め]で、状況[じょうきょう]を見[み]つめていた。", "sentence_source": "generated"}, {"text": "医者は感情を出さず、冷徹に病状を説明した。", "target_word": "冷徹に", "complexity_tier": "T4", "furigana": "医者[いしゃ]は感情[かんじょう]を出[だ]さず、冷徹[れいてつ]に病状[びょうじょう]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "冷徹な人だと言われるが、本当は優しい面もある。", "target_word": "冷徹な", "complexity_tier": "T3", "furigana": "冷徹[れいてつ]な人[ひと]だと言[い]われるが、本当[ほんとう]は優[やさ]しい面[めん]もある。", "sentence_source": "generated"}, {"text": "勝負の世界では、冷徹な考え方が必要なときもある。", "target_word": "冷徹な", "complexity_tier": "T4", "furigana": "勝負[しょうぶ]の世界[せかい]では、冷徹[れいてつ]な考[かんが]え方[かた]が必要[ひつよう]なときもある。", "sentence_source": "generated"}, {"text": "彼は仲間が泣いても、冷徹な態度をくずさなかった。", "target_word": "冷徹な", "complexity_tier": "T4", "furigana": "彼[かれ]は仲間[なかま]が泣[な]いても、冷徹[れいてつ]な態度[たいど]をくずさなかった。", "sentence_source": "generated"}, {"text": "刑事は冷徹に事実だけを集め、犯人を追いつめた。", "target_word": "冷徹に", "complexity_tier": "T4", "furigana": "刑事[けいじ]は冷徹[れいてつ]に事実[じじつ]だけを集[あつ]め、犯人[はんにん]を追[お]いつめた。", "sentence_source": "generated"}, {"text": "冷徹な計算の結果、計画は中止になった。", "target_word": "冷徹な", "complexity_tier": "T4", "furigana": "冷徹[れいてつ]な計算[けいさん]の結果[けっか]、計画[けいかく]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "その将軍は冷徹で、味方の犠牲にも心を動かさなかった。", "target_word": "冷徹で", "complexity_tier": "T4", "furigana": "その将軍[しょうぐん]は冷徹[れいてつ]で、味方[みかた]の犠牲[ぎせい]にも心[こころ]を動[うご]かさなかった。", "sentence_source": "generated"}, {"text": "彼の冷徹な言葉に、会議室は静まり返った。", "target_word": "冷徹な", "complexity_tier": "T4", "furigana": "彼[かれ]の冷徹[れいてつ]な言葉[ことば]に、会議室[かいぎしつ]は静[しず]まり返[かえ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷徹な", "label": "連体形"}, {"form": "冷徹に", "label": "連用形"}, {"form": "冷徹で", "label": "て形"}, {"form": "冷徹だ", "label": "終止形"}], "register": "neutral-written", "sense_fingerprint": "感情に流されず冷ややかに物事を見て判断するさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52049, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷徹な", "is_correct": true, "explanation": "正解。「判断」を修飾する連体形で、感情を交えない判断を表す。"}, {"text": "冷徹に", "is_correct": false, "explanation": "連用形は名詞の前に置けないため、「判断で」に続かない。"}, {"text": "冷徹だ", "is_correct": false, "explanation": "終止形は名詞を修飾できないので、「判断」に続けると文が成り立たない。"}, {"text": "冷徹で", "is_correct": false, "explanation": "て形は名詞を修飾できず、「判断で」の位置には入らない。"}], "explanations": {"冷徹な": "正解。「判断」を修飾する連体形で、感情を交えない判断を表す。", "冷徹に": "連用形は名詞の前に置けないため、「判断で」に続かない。", "冷徹だ": "終止形は名詞を修飾できないので、「判断」に続けると文が成り立たない。", "冷徹で": "て形は名詞を修飾できず、「判断で」の位置には入らない。"}, "sentence_index": 0, "correct_answer": "冷徹な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北風が冷徹な風となって、窓から吹き込んできた。", "explanation": "冷徹は判断や態度に使う語で、風の冷たさには使わない。"}, {"text": "彼は、長年の友人との再会に、冷徹な喜びを感じた。", "explanation": "冷徹は感情を交えない態度を表すので、胸が熱くなる感激の場面には合わない。"}, {"text": "彼女は冷徹な愛情で、子どもを抱きしめた。", "explanation": "冷徹は感情を交えない態度を表すので、温かい愛情の場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52049, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷徹に", "is_correct": true, "explanation": "正解。動詞「集め」を修飾する連用形。"}, {"text": "冷徹だった", "is_correct": false, "explanation": "過去の終止形で、「事実」を修飾できず文が成り立たない。"}, {"text": "冷徹さ", "is_correct": false, "explanation": "名詞形で、「事実だけを集め」の修飾にはならない。"}, {"text": "冷徹では", "is_correct": false, "explanation": "「では」の形で、「事実だけを集め」を修飾する形にはならない。"}], "explanations": {"冷徹に": "正解。動詞「集め」を修飾する連用形。", "冷徹だった": "過去の終止形で、「事実」を修飾できず文が成り立たない。", "冷徹さ": "名詞形で、「事実だけを集め」の修飾にはならない。", "冷徹では": "「では」の形で、「事実だけを集め」を修飾する形にはならない。"}, "sentence_index": 6, "correct_answer": "冷徹に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は恋人との別れに、冷徹に泣き崩れた。", "explanation": "冷徹は感情を交えない態度なので、感情があふれて泣き崩れる場面には合わない。"}, {"text": "この冷徹な池の水は、夏でも冷えきっていた。", "explanation": "冷徹は判断や態度について使い、水の冷たさには使わない。"}, {"text": "彼は冷徹な思い出を、楽しそうに語った。", "explanation": "冷徹は感情を交えない態度を指すので、懐かしさを楽しそうに語る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52049, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部長は冷徹に判断で、新人を解雇した。", "corrected_sentence": "部長は冷徹な判断で、新人を解雇した。", "error_description": "名詞「判断」を修飾するには連体形「冷徹な」が必要で、連用形「冷徹に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "冷徹な", "is_correct": true, "explanation": "正解。「目」を修飾する連体形。"}, {"text": "冷徹に", "is_correct": false, "explanation": "連用形で、名詞「目」を修飾できない。"}, {"text": "冷徹で", "is_correct": false, "explanation": "て形で、名詞を修飾する形ではない。"}, {"text": "冷徹だ", "is_correct": false, "explanation": "終止形で、名詞の前には置けない。"}], "correct_form": "冷徹な", "base_form": "冷徹", "form_label": "連体形", "sentence_index": 1, "explanations": {"冷徹な": "正解。「目」を修飾する連体形。", "冷徹に": "連用形で、名詞「目」を修飾できない。", "冷徹で": "て形で、名詞を修飾する形ではない。", "冷徹だ": "終止形で、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52049, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その監督の冷徹が、チームを勝利に導いた。", "corrected_sentence": "その監督の冷徹さが、チームを勝利に導いた。", "error_description": "「冷徹」は形容動詞なので、名詞として主語にするときは「冷徹さ」と名詞化する必要がある。「冷徹が」は誤り。正しくは「冷徹さが」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "冷徹な", "is_correct": true, "explanation": "正解。「計算」を修飾する連体形。"}, {"text": "冷徹だった", "is_correct": false, "explanation": "過去の終止形で、名詞の前には置けない。"}, {"text": "冷徹さ", "is_correct": false, "explanation": "名詞化した形で、「計算」を直接修飾できない。"}, {"text": "冷徹では", "is_correct": false, "explanation": "「では」の形で、名詞修飾の形ではない。"}], "correct_form": "冷徹な", "base_form": "冷徹", "form_label": "連体形", "sentence_index": 7, "explanations": {"冷徹な": "正解。「計算」を修飾する連体形。", "冷徹だった": "過去の終止形で、名詞の前には置けない。", "冷徹さ": "名詞化した形で、「計算」を直接修飾できない。", "冷徹では": "「では」の形で、名詞修飾の形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52051, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "予期する対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「雨が予期して」では雨が主語になり、意味が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「雨で予期して」は対象を表せず、成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「雨の予期して」は活用語に続かず、成り立たない。"}], "correct_answer": "を", "explanations": {"を": "予期する対象を表す。", "が": "「雨が予期して」では雨が主語になり、意味が成り立たない。", "で": "「雨で予期して」は対象を表せず、成り立たない。", "の": "「雨の予期して」は活用語に続かず、成り立たない。"}, "error_tags": {"が": "subject", "で": "means", "の": "possessive"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52051, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「予期に反して」で、予期と違う結果になったことを表す決まった形。"}, {"text": "を", "is_correct": false, "explanation": "「反する」は「〜に反する」と言い、「を」はとらない。"}, {"text": "が", "is_correct": false, "explanation": "「予期が反して」では予期が主語になり、成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「反する」の相手は「で」で表せず、成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「予期に反して」で、予期と違う結果になったことを表す決まった形。", "を": "「反する」は「〜に反する」と言い、「を」はとらない。", "が": "「予期が反して」では予期が主語になり、成り立たない。", "で": "「反する」の相手は「で」で表せず、成り立たない。"}, "error_tags": {"を": "object", "が": "subject", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52051, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "まだ起きていないことについて、心の中でそうなるだろうと思うこと。", "primary_collocate": null, "pronunciation": "よき", "ipa": "jokʲi", "syllable_count": 2, "sentences": [{"text": "雨を予期して、かさを持った。", "target_word": "予期", "complexity_tier": "T2", "furigana": "雨[あめ]を予期[よき]して、かさを持[も]った。", "sentence_source": "generated"}, {"text": "予期しないことが起きました。", "target_word": "予期", "complexity_tier": "T2", "furigana": "予期[よき]しないことが起[お]きました。", "sentence_source": "generated"}, {"text": "予期していたより、人が多かった。", "target_word": "予期", "complexity_tier": "T3", "furigana": "予期[よき]していたより、人[ひと]が多[おお]かった。", "sentence_source": "generated"}, {"text": "テストの難しさは予期できた。", "target_word": "予期", "complexity_tier": "T3", "furigana": "テストの難[むずか]しさは予期[よき]できた。", "sentence_source": "generated"}, {"text": "彼が来るとは予期しなかった。", "target_word": "予期", "complexity_tier": "T3", "furigana": "彼[かれ]が来[く]るとは予期[よき]しなかった。", "sentence_source": "generated"}, {"text": "予期せぬプレゼントに、とてもうれしくなった。", "target_word": "予期", "complexity_tier": "T3", "furigana": "予期[よき]せぬプレゼントに、とてもうれしくなった。", "sentence_source": "generated"}, {"text": "悪いことを予期すると、心配になる。", "target_word": "予期", "complexity_tier": "T3", "furigana": "悪[わる]いことを予期[よき]すると、心配[しんぱい]になる。", "sentence_source": "generated"}, {"text": "予期に反して、天気は晴れだった。", "target_word": "予期", "complexity_tier": "T3", "furigana": "予期[よき]に反[はん]して、天気[てんき]は晴[は]れだった。", "sentence_source": "generated"}, {"text": "この結果は、私が予期した通りだ。", "target_word": "予期", "complexity_tier": "T3", "furigana": "この結果[けっか]は、私[わたし]が予期[よき]した通[とお]りだ。", "sentence_source": "generated"}, {"text": "先生は、生徒が質問することを予期していた。", "target_word": "予期", "complexity_tier": "T4", "furigana": "先生[せんせい]は、生徒[せいと]が質問[しつもん]することを予期[よき]していた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "予期する", "label": "活用"}, {"form": "予期しない", "label": "活用"}, {"form": "予期せぬ", "label": "活用"}, {"form": "予期できる", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 起きる前に心でそう思うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52051, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "予期", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "余暇", "is_correct": false, "explanation": "よか。「き」が「か」に変わった別の語です。"}, {"text": "雪", "is_correct": false, "explanation": "ゆき。「よ」が「ゆ」に変わった別の語です。"}, {"text": "駅", "is_correct": false, "explanation": "えき。「よ」が「え」に変わった別の語です。"}, {"text": "横", "is_correct": false, "explanation": "よこ。「き」が「こ」に変わった別の語です。"}], "explanations": {"予期": "見出し語そのものです。", "余暇": "よか。「き」が「か」に変わった別の語です。", "雪": "ゆき。「よ」が「ゆ」に変わった別の語です。", "駅": "えき。「よ」が「え」に変わった別の語です。", "横": "よこ。「き」が「こ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "予期"}, "level_3": {"options": [{"text": "予期", "is_correct": true, "explanation": "雨になると思って、かさを持ったという意味で合う。"}, {"text": "無視", "is_correct": false, "explanation": "形は合うが、雨を無視してかさを持つのは意味が合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "形は合うが、雨は掃除するものではなく、意味が合わない。"}, {"text": "感謝", "is_correct": false, "explanation": "形は合うが、感謝してかさを持つのは理由として合わない。"}], "explanations": {"予期": "雨になると思って、かさを持ったという意味で合う。", "無視": "形は合うが、雨を無視してかさを持つのは意味が合わない。", "掃除": "形は合うが、雨は掃除するものではなく、意味が合わない。", "感謝": "形は合うが、感謝してかさを持つのは理由として合わない。"}, "sentence_index": 0, "correct_answer": "予期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "すでに起きた失敗を予期して、反省した。", "explanation": "予期はまだ起きていないことを思う語で、すでに起きた失敗には使えない。"}, {"text": "母に予期を頼まれて、スーパーへ買い物に行った。", "explanation": "予期は心の中で思うことで、人に頼まれてする用事ではない。「用事」との混同による誤用。"}, {"text": "彼のやさしさに予期して、お礼を言った。", "explanation": "予期は感謝する意味ではない。「感謝」との混同による誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52051, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "予期", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "予備", "is_correct": false, "explanation": "よび。「き」が「び」に変わった別の語です。"}, {"text": "余地", "is_correct": false, "explanation": "よち。「き」が「ち」に変わった別の語です。"}, {"text": "欲", "is_correct": false, "explanation": "よく。「き」が「く」に変わった別の語です。"}, {"text": "酔い", "is_correct": false, "explanation": "よい。「き」が「い」に変わった別の語です。"}], "explanations": {"予期": "見出し語そのものです。", "予備": "よび。「き」が「び」に変わった別の語です。", "余地": "よち。「き」が「ち」に変わった別の語です。", "欲": "よく。「き」が「く」に変わった別の語です。", "酔い": "よい。「き」が「い」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "予期"}, "level_3": {"options": [{"text": "予期", "is_correct": true, "explanation": "悪いことが起きると思うと心配になる、という意味で合う。"}, {"text": "禁止", "is_correct": false, "explanation": "形は合うが、禁止すると心配になるという因果は意味が合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "形は合うが、悪いことは掃除するものではなく、意味が合わない。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが、悪いことを運転するという意味は成り立たない。"}], "explanations": {"予期": "悪いことが起きると思うと心配になる、という意味で合う。", "禁止": "形は合うが、禁止すると心配になるという因果は意味が合わない。", "掃除": "形は合うが、悪いことは掃除するものではなく、意味が合わない。", "運転": "形は合うが、悪いことを運転するという意味は成り立たない。"}, "sentence_index": 6, "correct_answer": "予期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日見た映画の内容を予期して、友達に話した。", "explanation": "予期は未来のことを思う語で、すでに見た内容には使えない。"}, {"text": "レストランを予期したので、席が空いていた。", "explanation": "予期は席を取る意味ではない。「予約」との混同による誤用。"}, {"text": "予期をたくさん食べて、おなかがいっぱいになった。", "explanation": "予期は心の中で思うことで、食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
