INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52052, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "未来の事柄をあらかじめ推測して、予想すること。", "primary_collocate": null, "pronunciation": "よき", "ipa": "jokʲi", "syllable_count": 2, "sentences": [{"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "予期", "complexity_tier": "T6", "furigana": "さらに、こうした非伝統的[ひでんとうてき]な金融[きんゆう]政策[せいさく]がインフレ期待[きたい]のアンカーとして機能[きのう]し得[う]る一方[いっぽう]で、過剰[かじょう]な流動性[りゅうどうせい]が実体[じったい]経済[けいざい]における物価[ぶっか]上昇[じょうしょう]圧力[あつりょく]と相乗[そうじょう]効果[こうか]を生[う]み、予期[よき]せぬスタグフレーションや財政[ざいせい]主導[しゅどう]のシナリオへと帰結[きけつ]するリスクを常[つね]に内包[ないほう]していることを、我々[われわれ]は冷徹[れいてつ]に認識[にんしき]する責務[せきむ]を負[お]っている。", "sentence_source": "mined"}, {"text": "予期せぬ事故が起きた。", "target_word": "予期", "complexity_tier": "T2", "furigana": "予期[よき]せぬ事故[じこ]が起[お]きた。", "sentence_source": "generated"}, {"text": "結果は予期した通りだった。", "target_word": "予期", "complexity_tier": "T3", "furigana": "結果[けっか]は予期[よき]した通[とお]りだった。", "sentence_source": "generated"}, {"text": "彼の反応は予期していなかった。", "target_word": "予期", "complexity_tier": "T3", "furigana": "彼[かれ]の反応[はんのう]は予期[よき]していなかった。", "sentence_source": "generated"}, {"text": "予期に反して、売り上げは伸びた。", "target_word": "予期", "complexity_tier": "T3", "furigana": "予期[よき]に反[はん]して、売[う]り上[あ]げは伸[の]びた。", "sentence_source": "generated"}, {"text": "社長は予期していた問題に備えていた。", "target_word": "予期", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は予期[よき]していた問題[もんだい]に備[そな]えていた。", "sentence_source": "generated"}, {"text": "この事態を予期できた人はいなかった。", "target_word": "予期", "complexity_tier": "T3", "furigana": "この事態[じたい]を予期[よき]できた人[ひと]はいなかった。", "sentence_source": "generated"}, {"text": "予期できない変化が、市場に混乱を与えた。", "target_word": "予期", "complexity_tier": "T4", "furigana": "予期[よき]できない変化[へんか]が、市場[しじょう]に混乱[こんらん]を与[あた]えた。", "sentence_source": "generated"}, {"text": "失敗を予期して、彼は別の計画を用意した。", "target_word": "予期", "complexity_tier": "T4", "furigana": "失敗[しっぱい]を予期[よき]して、彼[かれ]は別[べつ]の計画[けいかく]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "予期された結果とはいえ、やはり残念だ。", "target_word": "予期", "complexity_tier": "T4", "furigana": "予期[よき]された結果[けっか]とはいえ、やはり残念[ざんねん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "予期する", "label": "活用"}, {"form": "予期した", "label": "活用"}, {"form": "予期せぬ", "label": "活用"}, {"form": "予期しない", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 未来を前もって推測すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04fdc735-03d9-474b-95d7-448c4529ef13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52052, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "予期", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "余暇", "is_correct": false, "explanation": "よか。「き」が「か」に変わった別の語です。"}, {"text": "雪", "is_correct": false, "explanation": "ゆき。「よ」が「ゆ」に変わった別の語です。"}, {"text": "駅", "is_correct": false, "explanation": "えき。「よ」が「え」に変わった別の語です。"}, {"text": "横", "is_correct": false, "explanation": "よこ。「き」が「こ」に変わった別の語です。"}], "explanations": {"予期": "見出し語そのものです。", "余暇": "よか。「き」が「か」に変わった別の語です。", "雪": "ゆき。「よ」が「ゆ」に変わった別の語です。", "駅": "えき。「よ」が「え」に変わった別の語です。", "横": "よこ。「き」が「こ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "予期"}, "level_3": {"options": [{"text": "予期", "is_correct": true, "explanation": "「予期せぬスタグフレーション」で、前もって推測していなかった事態を表し、文意に合う。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが、スタグフレーションが出発するという意味は成り立たない。"}, {"text": "納得", "is_correct": false, "explanation": "形は合うが、「納得せぬ」では受け入れないという意味になり、意味が合わない。"}, {"text": "安心", "is_correct": false, "explanation": "形は合うが、「安心せぬ」では不安という意味になり、リスクの説明に合わない。"}], "explanations": {"予期": "「予期せぬスタグフレーション」で、前もって推測していなかった事態を表し、文意に合う。", "出発": "形は合うが、スタグフレーションが出発するという意味は成り立たない。", "納得": "形は合うが、「納得せぬ」では受け入れないという意味になり、意味が合わない。", "安心": "形は合うが、「安心せぬ」では不安という意味になり、リスクの説明に合わない。"}, "sentence_index": 0, "correct_answer": "予期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "過去の歴史を予期して、年表を作った。", "explanation": "予期は未来の事柄を前もって推測することなので、過去の歴史には使えない。"}, {"text": "彼は予期を電車に忘れてきた。", "explanation": "予期は心の中で推測する行為で、物のように忘れ物にはならない。"}, {"text": "会議の予期を三時に変更した。", "explanation": "予期は日時の取り決めではない。「予定」と混同した誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '973d70d1-217e-4815-b7ed-fa2c2a2f118b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
